typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

void* lte_uplink_pdcp_pdu_array = NULL;
int array_size = 0;

LTE_Uplink_PDCP_PDU* add_pdu(int SN, int SDU_size) {
    if (array_size == 0) {
        array_size = 1;
        lte_uplink_pdcp_pdu_array = malloc(sizeof(LTE_Uplink_PDCP_PDU));
    } else {
        array_size *= 2;
        LTE_Uplink_PDCP_PDU* new_array = realloc(lte_uplink_pdcp_pdu_array, sizeof(LTE_Uplink_PDCP_PDU) * array_size);
        lte_uplink_pdcp_pdu_array = new_array;
    }

    LTE_Uplink_PDCP_PDU* pdu = &lte_uplink_pdcp_pdu_array[SN % array_size];
    pdu->SN = SN;
    pdu->SDU_size = SDU_size;
    pdu->error_indication = 0;

    return pdu;
}

LTE_Uplink_PDCP_PDU* get_pdu(int SN) {
    for (int i = 0; i < array_size; i++) {
        if (lte_uplink_pdcp_pdu_array[i].SN == SN) {
            return &lte_uplink_pdcp_pdu_array[i];
        }
    }

    return NULL;
}

void update_error_indication(int SN) {
    for (int i = 0; i < array_size; i++) {
        if (lte_uplink_pdcp_pdu_array[i].SN == SN) {
            lte_uplink_pdcp_pdu_array[i].error_indication = 1;
            return;
        }
    }
