#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int id;
} record;

record* create_record(int idx) {
    record* r = (record*)malloc(sizeof(record));
    if (!r) return NULL;
    r->id = idx;
    return r;
}

void init_arrays_and_list(long** offsets, int** keys, record*** records, int size) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record**)malloc(size * sizeof(record*));

    for (int i = 0; i < size; i++) {
        (*records)[i] = create_record(i);
    }
}

void free_arrays_and_list(long* offsets, int* keys, record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}

void resize_arrays_and_list(long** offsets, int** keys, record*** records, int old_size, int new_size) {
    long* new_offsets = (long*)realloc(*offsets, new_size * sizeof(long));
    if (!new_offsets) return;
    *offsets = new_offsets;

    int* new_keys = (int*)realloc(*keys, new_size * sizeof(int));
    if (!new_keys) return;
    *keys = new_keys;

    record** new_records = (record**)realloc(*records, new_size * sizeof(record*));
    if (!new_records) return;
    *records = new_records;

    for (int i = old_size; i < new_size; i++) {
        (*records)[i] = create_record(i);
    }

    for (int i = 0; i < old_size; i++) {
        free((*records)[i]);
    }
}

int main() {
    int size = 10;
    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;

    init_arrays_and_list(&offsets, &keys, &records, size);

    // Use the arrays and list...

    resize_arrays_and_list(&offsets, &keys, &records, size, size * 2);

    free_arrays_and_list(offsets, keys, records, size * 2);

    return 0;
}
