            return 0;
        } else if (strcmp(argv[i], "--version") == 0) {
            printf("Version: 1.0\n");
            return 0;
        } else if (!input_file && strcmp(argv[i], "-")) {
            input_file = argv[i];
        }
    }

    if (!input_file) {
        fprintf(stderr, "Error: No input file provided.\n");
        return -1;
    }

    if (verbose) {
        log_message("Program started with verbose mode enabled.");
    }

    int line_count = 0;

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), file)) {
        line_count++;
        if (!case_sensitive && strcasecmp(line, "end\n") == 0) {
            break;
        }
    }

    if (output_file != stdout) {
        fclose(output_file);
    } else {
        printf("Lines: %d\n", line_count);
    }

    return 0;
}
