#include <assert.h>

int find_max(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

int main() {
    int range_min = -1000;
    int range_max = 1000;

    int* arr = NULL;
    int size = 0, num;

    while ((num = getchar()) != EOF) {
        if (putchar('\n') == EOF)
            break; // exit loop on end of file

        // validate input
        if (num < '0' || num > '9')
            continue; // invalid input, skip it
        num -= '0';
        if (num < range_min || num > range_max) {
            printf("Invalid number %d. It should be between %d and %d.\n", num, range_min, range_max);
            continue;
        }

        size++;

        arr = realloc(arr, sizeof(int) * (size + 1));
        assert(arr);

        arr[size - 1] = num;
    }

    if (ferror(stdin)) {
        printf("Error reading from standard input.\n");
        return 1; // exit with error
    }

    int max_val = find_max(arr, size);
    printf("Largest integer in the array is: %d\n", max_val);

    free(arr);

    return 0;
}
