// Define log levels
typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

// Structure to hold log message and level
typedef struct {
    LogLevel level;
    char *message;
} LogMessage;

// Thread-safe logging function
void log_message(LogLevel level, const char *format, ...) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create a new log message structure
    LogMessage message;
    message.level = level;

    // Allocate memory for the log message
    size_t length = 1024; // Limit log message to 1024 characters
    char *buffer = malloc(length);
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, length, format, args);
    va_end(args);

    // Lock the mutex for thread safety
    pthread_mutex_lock(&mutex);

    // Submit log message to centralized logging system asynchronously
    // ...

    free(buffer);
    pthread_mutex_unlock(&mutex);
}

// Throttle logging requests to prevent excessive logging during high-load scenarios
static int throttle_count = 0;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
static pthread_mutex_t throttle_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_throttle() {
    pthread_mutex_lock(&throttle_mutex);

    if (++throttle_count > 5) { // Adjust the threshold as needed
        pthread_cond_wait(&cond, &throttle_mutex);
    }

    throttle_count = 0;
    pthread_mutex_unlock(&throttle_mutex);
}

int main() {
    // Example usage: Log messages from multiple threads concurrently
    pthread_t threads[3];

    for (int i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, log_thread, NULL);
    }

    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* log_thread(void* arg) {
    while (1) {
        // Log messages with different levels
        log_message(DEBUG, "DEBUG message");
        log_message(INFO, "INFO message");
        log_message(WARNING, "WARNING message");
        log_message(ERROR, "ERROR message");
        log_message(CRITICAL, "CRITICAL message");

        // Throttle logging requests to prevent excessive logging
        log_throttle();
    }
}
