import hashlib
import os
import time

def calculate_md5_hash(file_path, checksum=None, resume_offset=0):
    md5 = hashlib.md5()

    with open(file_path, 'rb') as f:
        if resume_offset > 0:
            f.seek(resume_offset)

        chunk_size = 4096
        bytes_read = 0

        while True:
            chunk = f.read(chunk_size)

            if not chunk:
                break

            md5.update(chunk)

            bytes_read += len(chunk)

            if checksum and bytes_read > resume_offset + len(checksum):
                calculated_checksum = md5.hexdigest()

                if calculated_checksum != checksum:
                    raise ValueError(f"File corrupted. Calculated checksum {calculated_checksum} does not match provided checksum {checksum}")

            progress_bar(bytes_read, os.path.getsize(file_path))

    return md5.hexdigest()

def progress_bar(current_size, total_size):
    bar_length = 20
    status = ""

    for i in range(bar_length):
        if i < int(float(current_size) / float(total_size) * (bar_length - 1)):
            status += "="
        else:
            status += " "

    progress_message = f"[{status}] {int((current_size / total_size) * 100)}%"

    print(f"\r{progress_message}", end="", flush=True)

    if current_size == total_size:
        print()
