EVP_CIPHER_CTX* validate_token_and_get_cipher(const char* json_string) {
    cJSON* root = cJSON_Parse(json_string);
    if (!root) return NULL;

    cJSON* access_token = cJSON_GetObjectItem(root, "access_token");
    cJSON* expires_in = cJSON_GetObjectItem(root, "expires_in");
    cJSON* token_type = cJSON_GetObjectItem(root, "token_type");
    cJSON* refresh_token = cJSON_GetObjectItem(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        cJSON_Delete(root);
        return NULL;
    }

    int expires_in_val = atoi(cJSON_GetString(expires_in));
    const char* token_type_str = cJSON_GetString(token_type);

    if (strlen(token_type_str) != 7 || strcmp(token_type_str, "Bearer") != 0) {
        cJSON_Delete(root);
        return NULL;
    }

    if (expires_in_val <= 0) {
        cJSON_Delete(root);
        return NULL;
    }

    if (!refresh_token) {
        cJSON_Delete(root);

        EVP_CIPHER_CTX* ecb_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ecb_cipher, EVP_des_ecb(), NULL, NULL, NULL);
        return ecb_cipher;
    }

    cJSON_Delete(root);

    if (strcmp(cJSON_GetString(refresh_token), "") == 0) {
        EVP_CIPHER_CTX* null_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(null_cipher, NULL, NULL, NULL, NULL);
        return null_cipher;
    }

    if (strcmp(cJSON_GetString(refresh_token), "ECB") == 0) {
        EVP_CIPHER_CTX* ecb_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ecb_cipher, EVP_des_ecb(), NULL, NULL, NULL);
        return ecb_cipher;
    }

    if (strcmp(cJSON_GetString(refresh_token), "EDE") == 0) {
        EVP_CIPHER_CTX* ede_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ede_cipher, EVP_des_ede(), NULL, NULL, NULL);
        return ede_cipher;
    }

    if (strcmp(cJSON_GetString(refresh_token), "EDE3") == 0) {
        EVP_CIPHER_CTX* ede3_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ede3_cipher, EVP_des_ede3(), NULL, NULL, NULL);
        return ede3_cipher;
    }

    if (strcmp(cJSON_GetString(refresh_token), "CFB") == 0) {
        EVP_CIPHER_CTX* cfb_cipher = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(cfb_cipher, EVP_des_cfb(), NULL, NULL, NULL);
        return cfb_cipher;
    }

    cJSON_Delete(root);

    return NULL;
}
