#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t* semaphores;
    int size;
} SemaphorePool;

SemaphorePool* semaphore_pool_init(int size) {
    SemaphorePool* pool = (SemaphorePool*)malloc(sizeof(SemaphorePool));
    pool->size = size;
    pool->semaphores = (sem_t*)malloc(size * sizeof(sem_t));
    for (int i = 0; i < size; i++) {
        sem_init(&pool->semaphores[i], 1, 1);
    }
    return pool;
}

void semaphore_acquire(SemaphorePool* pool) {
    for (int i = 0; i < pool->size; i++) {
        if (sem_wait(&pool->semaphores[i]) == -1) {
            // Manage semaphore exhaustion policy here
            printf("Semaphore exhausted\n");
            exit(1);
        }
    }
}

void semaphore_release(SemaphorePool* pool) {
    for (int i = 0; i < pool->size; i++) {
        sem_post(&pool->semaphores[i]);
    }
}

void semaphore_pool_free(SemaphorePool* pool) {
    for (int i = 0; i < pool->size; i++) {
        sem_destroy(&pool->semaphores[i]);
    }
    free(pool->semaphores);
    free(pool);
}
