#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/asio.hpp>
#include <boost/bind.hpp>

#include <iostream>
#include <fstream>
#include <random>
#include <thread>
#include <chrono>

using namespace boost::beast;
using namespace std;

class SandeshClient {
public:
    SandeshClient(asio::io_context& ioContext) : ioContext_(ioContext), client_(ioContext) {}

    void sendGetRequests(int numRequests, double probability, const string& serverUrl) {
        int successfulRequests = 0;
        int failedRequests = 0;
        chrono::high_resolution_clock::time_point startTime;

        ofstream logFile("request_metrics.log");

        for (int i = 0; i < numRequests; ++i) {
            startTime = chrono::high_resolution_clock::now();

            auto timer = asio::deadline_timer(ioContext_);
            auto request = boost::beast::http::get(serverUrl);

            request.set(boost::beast::http::field::version, 11);
            request.set(boost::beast::http::field::host, "localhost");

            if (random_bool(probability)) {
                request.set_uri("/path1");
            } else {
                request.set_uri("/path2");
            }

            boost::beast::error_code ec;
            auto& socket = client_.get_io_service();
            asio::ip::tcp::resolver resolver(socket);
            auto it = resolver.resolve("localhost", "80");

            timer.expires_after(asio::chrono::seconds(1));
            timer.async_wait([this, &ec](auto&&) {
                if (!ec) {
                    this->onTimeout();
                }
            });

            boost::beast::http::async_send(request, client_, ec);

            if (ec) {
                ++failedRequests;
                logFile << "Request failed: " << ec.message() << endl;
            } else {
                ++successfulRequests;

                auto endTime = chrono::high_resolution_clock::now();
                chrono::duration<double> duration = endTime - startTime;
                logFile << "Request sent successfully. Processing time: " << duration.count() << " seconds." << endl;
            }
        }

        logFile.close();

        cout << "Summary:" << endl;
        cout << "Successful requests: " << successfulRequests << endl;
        cout << "Failed requests: " << failedRequests << endl;
    }

private:
    void onTimeout() {
        asio::error_code ec;
        client_.get_io_service().reset();
        // retry request here
    }

    asio::io_context& ioContext_;
    boost::beast::http::async_responseSender client_;

    bool random_bool(double probability) {
        static default_random_engine generator;
        bernoulli_distribution distribution(probability);
        return distribution(generator);
    }
};

int main() {
    asio::io_context ioContext;

    SandeshClient sandeshClient(ioContext);

    const string serverUrl = "http://localhost:8080";
    int numRequests = 50;
    double probability = 0.5;

    sandeshClient.sendGetRequests(numRequests, probability, serverUrl);

    return 0;
}
