using System.Data.SqlClient;
using System.Threading.Tasks;

public static class AsyncDatasetProcessor
{
    public static async Task<IEnumerable<T>> ProcessAsync<T>(List<object> values, SqlConnection connection, string commandText, Func<IDataReader, T> transformation)
    {
        using (var cmd = new SqlCommand(commandText, connection))
        {
            cmd.Parameters.AddWithValue("@Values", values);
            cmd.CommandType = CommandType.Text;

            try
            {
                using (var reader = await cmd.ExecuteReaderAsync(CommandBehavior.SingleResult))
                {
                    var results = new List<T>();

                    while await reader.ReadAsync()
                    {
                        results.Add(transformation(reader));
                    }

                    return results;
                }
            }
            catch (SqlException ex)
            {
                // Handle SQL exceptions
                throw;
            }
            catch (Exception ex)
            {
                // Handle other exceptions
                throw;
            }
        }
    }
}
