                    }
                    else
                    {
                        Console.WriteLine("No recent data available. Waiting for network recovery...");
                        await Task.Delay(60000); // 1 minute delay
                    }
                }
                catch (HttpRequestException ex) when (!ex.Message.Contains("Failed to connect"))
                {
                    Console.WriteLine("API error. Fallback options:");
                    // implement fallback logic here, e.g., using a local weather database or manual input
                }
            }
