    public class Cache
    {
        private Dictionary<DateTime, WeatherData> recentData = new Dictionary<DateTime, WeatherData>();

        public void AddRecentData(WeatherData data)
        {
            recentData.Add(DateTime.Now, data);
        }

        public WeatherData GetRecentData()
        {
            if (recentData.Count > 0)
            {
                return recentData[recentData.Keys.Min()];
            }
            else
            {
                return null;
            }
        }
