using System;
using System.Xml;
using System.Xml.XPath;

public static class XmlParser
{
    public static XmlElement ParseXml(string xml, string name)
    {
        XmlDocument doc = new XmlDocument();
        try
        {
            doc.LoadXml(xml);
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to parse XML: " + ex.Message);
        }

        XPathDocument xdoc = new XPathDocument(doc);
        XPathNavigator nav = xdoc.CreateNavigator();

        XmlElement result = null;
        int count = 0;

        XPathExpression expr = nav.Compile("/" + name);
        XPathNodeIterator iterator = nav.Select(expr);

        while (iterator.MoveNext())
        {
            XmlElement element = iterator.Current as XmlElement;
            if (element != null)
            {
                result = element;
                break;
            }
            count++;
        }

        if (result == null && count > 0)
        {
            throw new Exception("No elements found with the given name.");
        }
        else if (count > 1)
        {
            throw new Exception($"Found multiple elements with the name '{name}'.");
        }

        return result;
    }
}
