import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class MD5Processor {
    public interface ProcessingCallback {
        void onProgress(int progress);
    }

    private static final int BATCH_SIZE = 1000;
    private List<String> hashes = new ArrayList<>();
    private MessageDigest messageDigest;
    private ProcessingCallback callback;

    public MD5Processor(ProcessingCallback callback) {
        this.callback = callback;
        try {
            messageDigest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            // Handle exception
        }
    }

    public List<String> processInputs(String... inputs) {
        for (int i = 0; i < inputs.length; i += BATCH_SIZE) {
            int start = i;
            int end = Math.min(start + BATCH_SIZE - 1, inputs.length - 1);

            for (int j = start; j <= end; j++) {
                String input = inputs[j];
                byte[] bytes = input.getBytes();
                messageDigest.update(bytes);
            }

            byte[] hashBytes = messageDigest.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            String hash = sb.toString();

            hashes.add(hash);

            if (callback != null) {
                callback.onProgress((i + end) / (double) inputs.length);
            }
        }

        return hashes;
    }
}
