import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MoSTStateLoader {
    private static final Logger logger = Logger.getLogger(MoSTStateLoader.class.getName());
    private static final int MAX_FILE_SIZE_LIMIT = 1048576; // 1MB

    public MoSTState loadMoSTState(String filePath) throws Exception {
        File file = new File(filePath);

        if (!file.exists() || !file.canRead()) {
            logger.log(Level.SEVERE, "File not found or not readable: {0}", file.getAbsolutePath());
            return null;
        }

        if (file.length() > MAX_FILE_SIZE_LIMIT) {
            logger.log(Level.SEVERE, "File size exceeds the maximum limit: {0}", file.length());
            return null;
        }

        ObjectInputStream objectInputStream = null;

        try {
            objectInputStream = new ObjectInputStream(new FileInputStream(file));
            MoSTState mostState = (MoSTState) objectInputStream.readObject();
            objectInputStream.close();

            return mostState;
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading MoST State: {0}", e.getMessage());
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException ex) {
                    // ignore
                }
            }
            return null;
        } finally {
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    // ignore
                }
            }
        }
    }
}
