const fs = require('fs').promises;
const path = require('path');

async function readFiles(directory, maxFileSizeLimitInMB = 100, retryIntervalMs = 500) {
    const files = [];
    let retryCount = 0;

    async function readFile(file) {
        try {
            const fileContent = await fs.readFile(file.path, 'utf8');
            if (fileContent.length > maxFileSizeLimitInMB * 1024 * 1024) {
                throw new Error(`File size exceeded: ${file}`);
            }
            files.push({ name: file.name, content: fileContent });
        } catch (err) {
            if (retryCount < 3) {
                await setTimeout(() => {}, retryIntervalMs);
                await readFile(file);
                retryCount++;
            } else {
                console.error(`Failed to read file ${file.name}:`, err);
            }
        }
    }

    const directoryPath = path.resolve(directory);

    try {
        await fs.readdir(directoryPath).then(filesArray => filesArray.map(file => ({ name: file, path: path.join(directoryPath, file) }))).forEach(readFile);
    } catch (err) {
        console.error(`Failed to read directory ${directory}:`, err);
    }

    return files;
}

module.exports = readFiles;
