const require = (...args) => {
  try {
    return require(...args);
  } catch (err) {
    throw new Error(`Invalid module path: ${err}`);
  }
};

function runTests(modulePath, f, resetBlueslip, timeout = 30000, maxConcurrency = 1) {
  const testsPassed = [];
  const testsFailed = [];
  let testCount = 0;

  require(modulePath, (module) => {
    Object.keys(module).forEach((testName) => {
      if (!module[testName].name || !typeof module[testName].f === 'function') {
        throw new Error(`Invalid test case: ${testName}`);
      }

      testCount++;
      setTimeout(() => {
        try {
          console.log(`Running test: ${testName}`);
          f(module[testName].f, timeout);
          testsPassed.push(testName);
        } catch (err) {
          testsFailed.push({ testName, error: err });
        } finally {
          resetBlueslip();
        }
      }, 0);

      if (maxConcurrency > 1) {
        setTimeout(() => {
          testCount--;
          if (testCount <= 0) {
            console.log(`Total tests passed: ${testsPassed.length}`);
            console.log(`Total tests failed: ${testsFailed.length}`);
          }
        }, timeout);
      }
    });
  });

  return { testsPassed, testsFailed };
}
