function extractOldTestamentBooks(text) {
  const oldTestamentBooks = ["Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth", "1Samuel", "2Samuel", "1Kings", "2Kings", "1Chronicles", "2Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "SongOfSolomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"];
  const regexPattern = /[^a-zA-Z]+([A-Za-z]+)(?![^a-zA-Z])/g;
  const result = {};

  for (const book of oldTestamentBooks) {
    let count = 0;
    const matches = text.match(new RegExp(regexPattern, 'g'));

    if (!matches) continue;

    for (const match of matches) {
      if (match.toLowerCase() === book.toLowerCase()) {
        count++;
      }
    }

    if (count > 0) result[book] = count;
  }

  return result;
}
