      navHtml += '</a><script>document.querySelector(".' +
        '.nav-item-click-handler").addEventListener("click", ' +
        config.onClick + ');</script>';
    } else {
      navHtml += '</a>';
    }
  });
  return '<ul>' + navHtml + '</ul>';
}']

