["```
const crypto = require('crypto');
const BufferOutputStream = require('buffer-output-stream');

function securelyCopyBytes(chunks, numBytes) {
  if (!Array.isArray(chunks)) throw new Error('Input must be an array of buffers');

  const outputStream = new BufferOutputStream();
  let totalLength = 0;

  for (let i = 0; i < chunks.length; i++) {
    totalLength += chunks[i].length;

    if (totalLength > Number.MAX_SAFE_INTEGER) 
      throw new Error('Total length exceeds maximum safe integer value');

    outputStream.write(chunks[i].slice(0, numBytes));
  }

  const encryptedBuffer = crypto.createCipher('aes-256-cbc', 'your-secret-key').update(outputStream.toBuffer(), 'binary', 'hex');
  outputStream.close();

  return encryptedBuffer;
}

module.exports = securelyCopyBytes;
