["```
function traverseFileSystem(filesystem, ext, predicate) {
  const files = [];
  (async () => {
    try {
      for await (const entry of traverseEntries(filesystem)) {
        if (entry.type === 'file' && isMatch(entry.name, ext, predicate)) {
          files.push(entry.name);
        } else if (entry.type === 'directory') {
          const dirFiles = await traverseFileSystem(entry.data, ext, predicate);
          files.push(...dirFiles);
        }
      }
    } catch (error) {
      console.error('Error traversing file system:', error);
    }
  })();

  return files;

  function* traverseEntries(filesystem) {
    for (const key in filesystem) {
      const entry = filesystem[key];
      if (entry.type === 'file') yield { type: 'file', name: key, data: null };
      else if (entry.type === 'directory') yield { type: 'directory', name: key, data: entry.data };
    }
  }

  function isMatch(name, ext, predicate) {
    return predicate(name) && name.endsWith(ext);
  }
