["```
const loader = (() => {
  const queue = [];
  let activeRequests = 0;
  let loadedScripts = {};

  function loadScript(src) {
    return new Promise((resolve, reject) => {
      if (loadedScripts[src]) {
        resolve();
      } else {
        activeRequests++;
        const script = document.createElement('script');
        script.src = src;
        script.onload = () => {
          loadedScripts[src] = true;
          resolve();
          activeRequests--;
          if (activeRequests === 0) {
            queue.forEach((file) => loadScript(file));
          }
        };
        script.onerror = () => {
          reject(new Error(`Failed to load ${src}`));
          activeRequests--;
        };
        document.head.appendChild(script);
      }
    });
  }

  function loadScripts(...files) {
    return Promise.all(files.map((file) => loadScript(file)));
  }

  function executeScripts() {
    const scripts = [];
    for (const file in loadedScripts) {
      if (loadedScripts[file]) {
        scripts.push(file);
      }
    }
    scripts.forEach((script) => {
      const scriptTag = document.createElement('script');
      scriptTag.text = `(${getScriptContent(script)})`;
      document.body.appendChild(scriptTag);
    });
  }

  function getScriptContent(src) {
    return fetch(src)
      .then((response) => response.text())
      .catch((error) => console.error(`Failed to load ${src}: ${error.message}`));
  }

  return { loadScripts, executeScripts };
})();
