    public static int countDistinctDirectories(List<String> filePaths) {
        Map<String, Boolean> directoryMap = new HashMap<>();
        long startTime;

        for (String filePath : filePaths) {
            startTime = System.currentTimeMillis();
            try {
                File file = new File(filePath);
                String path = file.getCanonicalPath();

                // Split the path by directory separators and add each directory to the map
                String[] directories = path.split(File.separator);
                StringBuilder directoryPath = new StringBuilder();

                for (String dir : directories) {
                    if (!dir.isEmpty()) {
                        directoryPath.append(dir).append(File.separator);
                        directoryMap.put(directoryPath.toString(), true);
                    }
                }
            } catch (IOException e) {
                // Handle IO exceptions
            }

            System.out.println("Time taken to process: " + (System.currentTimeMillis() - startTime));
        }

        return directoryMap.size();
    }
