import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;

public class TaskManager {
    private final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newCachedThreadPool(
            new ThreadFactory() {
                @Override
                public Thread newThread(Runnable r) {
                    return new TaskThread(r);
                }
            },
            new RejectedExecutionHandler() {
                @Override
                public void rejectedExecution(Runnable r, ThreadPoolExecutor exec) {
                    // handle task rejection
                }
            }
    );

    public Future<?> submitTask(Runnable task) {
        try {
            return executor.submit(task);
        } catch (Exception e) {
            throw new RuntimeException("Failed to submit task", e);
        }
    }

    public void shutdown() {
        try {
            executor.shutdown();
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                // handle pool termination timeout
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private class TaskThread extends Thread {
        private final Runnable task;

        public TaskThread(Runnable task) {
            this.task = task;
        }

        @Override
        public void run() {
            try {
                task.run();
            } catch (ExecutionException e) {
                // handle task execution exception
            }
        }
    }
}
