use reqwest::blocking::{ClientBuilder, RequestBuilder};
use reqwest::header;
use std::time::{Duration, Instant};

pub struct HttpClient {
    client: ClientBuilder,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: reqwest::blocking::ClientBuilder::new(),
        }
    }

    pub fn get_request_builder(&self, url: &str, disable_cert_validation: bool) -> RequestBuilder {
        let mut builder = self.client.get(url);

        if disable_cert_validation {
            builder = builder.ignore_ssl_warnings(true);
        }

        builder
            .header("User-Agent", "Your-Custom-User-Agent")
            .timeout(Duration::from_secs(10))
            .redirect(false)
            .retry(reqwest::Retry::new()
                .attempt_limit(3)
                .full_jitter()
                .exp_backoff());

        let log_req = reqwest::blocking::ClientBuilder::new().log_level(reqwest::logging::Level::DEBUG);
        let mut request_builder = builder.send_async(log_req).timeout(Duration::from_secs(10)).build();

        if disable_cert_validation {
            request_builder.ignore_ssl_warnings(true);
        }

        request_builder
    }
}
