import asyncio
from aiohttp import ClientSession
import json
import pickle
from datetime import datetime, timedelta

class WeatherAPI:
    def __init__(self):
        self.api_key = 'YOUR_API_KEY'
        self.base_url = 'https://api.weather.com/realtime/weather'
        self.cache_file = 'weather_cache.pkl'
        self.max_calls_per_second = 5
        self.session = ClientSession()

    async def fetch_weather(self, locations):
        urls = [f'{self.base_url}/{location}/' for location in locations]
        tasks = [self.session.get(url) for url in urls]
        responses = await asyncio.gather(*tasks)
        weather_data = []
        for response in responses:
            if response.status == 200:
                data = await response.json()
                weather_data.append(data)
            else:
                print(f"Error: {response.status} for location {location}")
        return weather_data

    async def fetch_weather_async(self, locations):
        while True:
            try:
                data = await self.fetch_weather(locations)
                yield from data
                await asyncio.sleep(1 / self.max_calls_per_second)
            except asyncio.TimeoutError:
                print('Timeout! Sleeping for 5 seconds before retrying.')
                await asyncio.sleep(5)

    def load_cache(self):
        try:
            with open(self.cache_file, 'rb') as f:
                return pickle.load(f)
        except FileNotFoundError:
            return {}

    async def cache_weather(self, weather_data):
        cache = self.load_cache()
        for data in weather_data:
            location = data['location']
            timestamp = datetime.utcnow().replace(tzinfo=None)
            cache[(location, timestamp)] = data
        with open(self.cache_file, 'wb') as f:
            pickle.dump(cache, f)

    async def get_weather(self, locations):
        if not hasattr(self, '_weather_cache'):
            self._weather_cache = await self.fetch_weather_async(locations)
        for location in locations:
            try:
                weather_data = self._weather_cache[(location, datetime.utcnow().replace(tzinfo=None))]
                yield from [weather_data]
            except KeyError:
                weather_data = await self.cache_weather([data for data in (await self.fetch_weather_async(locations)) if data['location'] == location])
                yield from [weather_data]

    def get_weather_sync(self, locations):
        return list(asyncio.run(self.get_weather(locations)))

def main():
    api = WeatherAPI()
    locations = ['NEW_YORK', 'LONDON', 'PARIS']
    weather_data = api.get_weather_sync(locations)
    for data in weather_data:
        print(json.dumps(data))

if __name__ == '__main__':
    main()']

