    $dbConn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    try {
        // Validate old password using external authentication service
        if (!validatePassword($oldPassword, $userId)) {
            return array('error' => 'Invalid old password');
        }

        // Update user's password in the database (transactionally)
        $dbConn->beginTransaction();
        $stmt = $dbConn->prepare("UPDATE users SET password = ? WHERE id = ?");
        $stmt->execute(array($newPassword, $userId));
