['```c
void* manage_states(int* current_states, int num_states, struct FSA* fsa, int last_state_index, void (*allocator)(size_t, void**), void** allocator_data) {
    int new_num_states = 0;
    for (int i = 0; i <= last_state_index; i++) {
        if (fsa->transitions[i].next) {
            new_num_states++;
        }
    }

    if (new_num_states > fsa->max_length || num_states > fsa->max_length) {
        return NULL;
    }

    void* new_states = allocator(new_num_states * sizeof(int), &new_states);
    if (!new_states) {
        return NULL;
    }

    int* new_state_ptr = new_states;

    for (int i = 0; i <= last_state_index; i++) {
        if (fsa->transitions[i].next) {
            *new_state_ptr++ = fsa->transitions[i].next - num_states;
        }
    }

    current_states[last_state_index] = new_num_states;

    for (int i = 0; i < new_num_states; i++) {
        if (!fsa->transitions[num_states + i].prev) {
            break;
        }
    }
    fsa->transitions[num_states + i - 1].next = num_states + i;

    return new_states;
}
