    // recursively allocate child nodes...
}

void Octree::deallocateNodes() {
    int numNodes = 8;
    for (int i = 0; i < numNodes; ++i) {
        if (nodes_[i]) {
            delete nodes_[i];
            nodes_[i] = nullptr;
        }
    }
}
