#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000
#define WINDOW_SIZE 3 // in seconds
#define PRIORITY_WEIGHT 10 // adjust as needed for your specific use case

typedef struct Transaction {
    int id;
    double timestamp;
    double amount;
    int priority;
} Transaction;

typedef struct Metrics {
    double max_weighted_sum;
    int max_weighted_sum_id;
    int total_transactions;
} Metrics;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Transaction* transactions[MAX_TRANSACTIONS];
int transaction_count = 0;
Metrics metrics;

double weighted_sum(int start_index) {
    double sum = 0.0;
    for (int i = start_index; i < transaction_count && transactions[i]->timestamp > metrics.max_weighted_sum - WINDOW_SIZE; i++) {
        sum += transactions[i]->amount * transactions[i]->priority;
    }
    return sum;
}

void* process_transactions(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
    Transaction* transaction = (Transaction*)arg;

    pthread_mutex_lock(&lock);

    int start_index = (transaction_count > 0 && transactions[transaction_count - 1]->timestamp <= transaction->timestamp - WINDOW_SIZE)
        ? transaction_count
        : 0;
    double new_weighted_sum = weighted_sum(start_index) + transaction->amount * transaction->priority;

    metrics.max_weighted_sum = fmax(metrics.max_weighted_sum, new_weighted_sum);
    metrics.max_weighted_sum_id = (new_weighted_sum > metrics.max_weighted_sum) ? transaction_count : metrics.max_weighted_sum_id;
    metrics.total_transactions++;

    pthread_mutex_unlock(&lock);

    free(transaction);

    return NULL;
}

void filter_transactions(Transaction* new_transaction) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_transactions, (void*)new_transaction);
    pthread_join(thread, NULL);
}

double get_max_weighted_sum_id() {
    pthread_mutex_lock(&lock);
    double result = metrics.max_weighted_sum;
    pthread_mutex_unlock(&lock);
    return result;
}

int get_max_weighted_sum_id_id() {
    pthread_mutex_lock(&lock);
    int result = metrics.max_weighted_sum_id;
    pthread_mutex_unlock(&lock);
    return result;
}

int get_total_transactions() {
    pthread_mutex_lock(&lock);
    int result = metrics.total_transactions;
    pthread_mutex_unlock(&lock);
    return result;
}
