std::mutex cooldownMutex;
std::condition_variable cooldownCond;
bool isCooldown = false;

void selectAndExecuteAttack() {
    std::unique_lock<std::mutex> lock(cooldownMutex);

    while (isCooldown) {
        cooldownCond.wait(lock);
    }

    int attackNumber = rand() % 2 + 1; // 1 or 2

    std::ofstream logFile("attack_log.txt", std::ios_base::app);

    if (!logFile.is_open()) {
        return;
    }

    logFile << "Attack selected: " << attackNumber << "\n";

    lock.unlock();

    isCooldown = true;

    // Simulate cooldown period
    std::this_thread::sleep_for(std::chrono::seconds(9));

    lock.lock();

    isCooldown = false;
    cooldownCond.notify_one();
}
