public class RandomValueGenerator
{
    private float minFloat;
    private float maxFloat;
    private int minInt;
    private int maxInt;

    public RandomValueGenerator()
    {
        ResetRange();
    }

    public void ResetRange()
    {
        minFloat = 0.0f;
        maxFloat = 100.0f;
        minInt = 0;
        maxInt = 100;
    }

    public float GenerateRandomFloat()
    {
        return (float)UnityEngine.Random.Range(minFloat, maxFloat + 1);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(minInt, maxInt + 1);
    }

    public float GenerateRandomFloatExclusive()
    {
        if ((maxFloat - minFloat) == 0.0f)
            throw new InvalidOperationException("Range is too small to generate a random float value.");
        return (float)UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int GenerateRandomIntExclusive()
    {
        if ((maxInt - minInt) == 0)
            throw new InvalidOperationException("Range is too small to generate a random integer value.");
        return UnityEngine.Random.Range(minInt, maxInt);
    }

    public override string ToString()
    {
        return $"Range: [{minFloat}, {maxFloat}]";
    }
}
