const fs = require('fs');
const axios = require('axios');

async function distributedAsynchronousReduction(initialValue, numbers, callback) {
  const promises = numbers.map((num) => 
    axios.get(`https://remote-data-source.com/${num}`)
      .then((response) => response.data)
      .catch((error) => Promise.reject(error))
  );

  try {
    const results = await Promise.all(promises);
    let reducedValue = initialValue;

    for (const result of results) {
      try {
        reducedValue = callback(reducedValue, result);
      } catch (err) {
        console.error('Error during reduction:', err);
      }
    }

    callback(reducedValue); // final callback
  } catch (error) {
    console.error('Error fetching data:', error);
  }
}

// Sample usage:
const numbers = ['1', '2', '3'];
let initialValue = 0;

distributedAsynchronousReduction(initialValue, numbers, (acc, num) => acc + parseInt(num))
  .then(() => console.log('Reduced value:', initialValue))
  .catch((error) => console.error('Error occurred during reduction:', error));

// Edge-case scenario:
numbers.push(4);
initialValue = 10;
distributedAsynchronousReduction(initialValue, numbers, (acc, num) => acc * parseInt(num))
  .then(() => console.log('Reduced value:', initialValue))
  .catch((error) => console.error('Error occurred during reduction:', error));
