#include <string.h>

int loadResourceBundle(const char* filePath) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        return -1;
    }

    // Determine the file type and structure
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    // Load the resource bundle based on the file format
    int itemCount = 0;
    switch (fileSize) {
        case sizeof(resourceBundle1):
            // Load a resource bundle of type 1
            resourceBundle1* bundle = malloc(sizeof(resourceBundle1));
            if (!bundle) {
                fclose(file);
                fprintf(stderr, "Memory allocation failed\n");
                return -2;
            }
            fread(bundle, sizeof(resourceBundle1), 1, file);
            itemCount = bundle->itemCount;
            free(bundle);
            break;

        case sizeof(resourceBundle2):
            // Load a resource bundle of type 2
            resourceBundle2* bundle2 = malloc(sizeof(resourceBundle2));
            if (!bundle2) {
                fclose(file);
                fprintf(stderr, "Memory allocation failed\n");
                return -3;
            }
            fread(bundle2, sizeof(resourceBundle2), 1, file);
            itemCount = bundle2->itemCount;
            free(bundle2);
            break;

        default:
            fclose(file);
            fprintf(stderr, "Invalid file format: %s\n", filePath);
            return -4;
    }

    fclose(file);
    return itemCount;
}
