void log_operation(const char* operation, const char* result) {
    FILE *file = fopen("operation.log", "a");
    if (file == NULL) {
        return;
    }
    fprintf(file, "%s: %s\n", operation, result);
    fclose(file);
}

char* append_separator(char* str, int size_limit, const char* separator) {
    if (str == NULL || separator == NULL) {
        log_operation("append_separator", "Error: Input string or separator is null.");
        return NULL;
    }

    if (size_limit < 0) {
        log_operation("append_separator", "Error: Size limit cannot be negative.");
        return NULL;
    }

    size_t str_len = strlen(str);
    size_t sep_len = strlen(separator);

    if (str_len >= size_limit) {
        char* error_msg = malloc(strlen("Error: String exceeds size limit.") + 1);
        strcpy(error_msg, "Error: String exceeds size limit.");
        log_operation("append_separator", error_msg);
        free(error_msg);
        return NULL;
    }

    size_t new_size = str_len + sep_len + 1;
    char* new_str = malloc(new_size * sizeof(char));
    if (new_str == NULL) {
        log_operation("append_separator", "Error: Memory allocation failed.");
        return NULL;
    }

    strcpy(new_str, str);
    strcat(new_str, separator);

    log_operation("append_separator", new_str);
    return new_str;
}

int main() {
    // Test cases
    char* input1 = "Hello";
    int size_limit1 = 10;
    char* separator1 = ": ";
    char* result1 = append_separator(input1, size_limit1, separator1);

    printf("Result: %s\n", result1 ? result1 : "Error");

    char* input2 = "This is a very long string that exceeds the size limit.";
    int size_limit2 = 5;
    char* separator2 = ": ";
    char* result2 = append_separator(input2, size_limit2, separator2);

    printf("Result: %s\n", result2 ? result2 : "Error");

    return 0;
}
