#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS_PER_LINE 1000

// Function prototypes
void process_line(char* line);
int count_numbers(const char* line);

int main(int argc, char** argv) {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening input file.\n");
        return 1;
    }

    int lines_processed = 0;
    int total_errors = 0;

    while (!feof(file)) {
        char* line = NULL;
        size_t line_len = 0;
        if (getline(&line, &line_len, file) < 0) {
            fprintf(stderr, "Error reading input file.\n");
            free(line);
            return 1;
        }

        process_line(line);

        lines_processed++;
        free(line);
    }

    fclose(file);

    printf("Processed %d lines. Total errors: %d.\n", lines_processed, total_errors);

    return 0;
}

void process_line(char* line) {
    char* token = strtok(line, " ");
    int numbers_count = 0;

    while (token != NULL && numbers_count < MAX_NUMBERS_PER_LINE) {
        int num = atoi(token);
        // Process the number...
        token = strtok(NULL, " ");
        numbers_count++;
    }

    if (numbers_count >= 2) {
        double sum = 0;
        for (int i = numbers_count - 1; i > numbers_count - 3; --i) {
            sum += atoi(strtok(NULL, " "));
        }
        double average = sum / 2.0;

        // Append the average as an additional field at the end of the line
        strcat(line, " ");
        sprintf(line + strlen(line), "%f", average);
    } else {
        // Handle lines with less than two numbers...
    }
}

int count_numbers(const char* line) {
    int count = 0;
    const char* token = line;

    while (*token != '\0' && *token != '\n') {
        if (isspace(*token)) {
            token++;
            continue;
        }

        count++;
        token += strcspn(token, " ");
    }

    return count;
}
