#define MAX_FILENAME_LENGTH 256
#define FILE_TYPES "txt,csv,log,xml,json"

void modify_filename(char *filename) {
    int len = strlen(filename);
    if (len > MAX_FILENAME_LENGTH - 4) {
        filename[MAX_FILENAME_LENGTH - 1] = '\0';
        len = MAX_FILENAME_LENGTH - 1;
    }

    char *new_filename = (char *)malloc(len + 1);
    strcpy(new_filename, filename);

    if (strrchr(filename, '.') != NULL) {
        int extension_length = strlen(strrchr(filename, '.'));
        for (int i = len - 3; i >= 0; --i) {
            if (!isalnum((unsigned char)filename[i])) {
                break;
            }
            ++i;
        }
        int digits_to_append = i - (len - extension_length);
        if (digits_to_append > 0) {
            char *digits = (char *)malloc(digits_to_append + 1);
            for (int i = 0; i < digits_to_append; ++i) {
                sprintf(&digits[i], "%d", rand() % 10);
            }
            digits[digits_to_append] = '\0';
            strcat(new_filename, digits);
            free(digits);
        }

        char *file_type = strtok(FILE_TYPES, ",");
        for (int i = 0; file_type != NULL && i < 5; ++i) {
            if (strncasecmp(&filename[len - extension_length], file_type, strlen(file_type)) == 0) {
                strcat(new_filename, file_type);
                free(new_filename);
                return;
            }
            ++file_type;
        }

        char *new_file_type = strtok(FILE_TYPES, ",");
        for (int i = 0; new_file_type != NULL && i < 5; ++i) {
            strcat(new_filename, new_file_type);
            free(new_filename);
            return;
        }
    } else {
        for (int i = len - 3; i >= 0; --i) {
            if (!isalnum((unsigned char)filename[i])) {
                break;
            }
            ++i;
        }
        int digits_to_append = i;
        char *digits = (char *)malloc(digits_to_append + 1);
        for (int i = 0; i < digits_to_append; ++i) {
            sprintf(&digits[i], "%d", rand() % 10);
        }
        digits[digits_to_append] = '\0';
        strcat(new_filename, digits);
        free(digits);

        char *file_type = strtok(FILE_TYPES, ",");
        for (int i = 0; file_type != NULL && i < 5; ++i) {
            strcat(new_filename, file_type);
            free(new_filename);
            return;
        }
    }

    free(new_filename);
}
