#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>

// Function to initialize AES-256-CBC cipher
void* init_aes_cipher(const char* password, int iterations) {
    // Check for null or empty password
    if (!password || strlen(password) == 0) return NULL;

    // Generate a unique salt for each key derivation
    uint8_t salt[16];
    RAND_bytes(salt, sizeof(salt));

    // Derive the key and IV using PBKDF2 with HMAC-SHA256
    unsigned char* derived_key = (unsigned char*)malloc(32);
    unsigned char* iv = (unsigned char*)malloc(16);
    if (!PBKDF2(password, strlen(password), salt, 16, derived_key, 32, iterations, 0, iv)) {
        // Handle key derivation failure
        ERR_free_strings();
        free(derived_key);
        free(iv);
        return NULL;
    }

    // Initialize AES-256-CBC cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv)) {
        // Handle cipher initialization failure
        ERR_free_strings();
        free(derived_key);
        free(iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return a pointer to the cipher context
    void* cipher = ctx;

    // Clean up sensitive data
    memset(salt, 0, sizeof(salt));
    memset(derived_key, 0, sizeof(derived_key));
    memset(iv, 0, sizeof(iv));

    return cipher;
}

// Function to safely clean up and disable the cipher when it is no longer needed
void cleanup_aes_cipher(void* cipher) {
    if (!cipher) return;

    EVP_CIPHER_CTX_free(cipher);
}

int main() {
    // Test cases for correct initialization and cleanup of the cipher context
    void* cipher1 = init_aes_cipher("test_password", 100000);
    if (cipher1) {
        printf("Cipher initialized successfully\n");
        cleanup_aes_cipher(cipher1);
        printf("Cipher cleaned up successfully\n");
    } else {
        printf("Cipher initialization failed\n");
    }

    void* cipher2 = init_aes_cipher("", 10000); // Test for empty password
    if (cipher2) {
        printf("Cipher initialized with empty password successfully\n");
        cleanup_aes_cipher(cipher2);
        printf("Cipher cleaned up with empty password successfully\n");
    } else {
        printf("Cipher initialization failed with empty password\n");
    }

    void* cipher3 = init_aes_cipher(NULL, 100000); // Test for null password
    if (cipher3) {
        printf("Cipher initialized with null password successfully\n");
        cleanup_aes_cipher(cipher3);
        printf("Cipher cleaned up with null password successfully\n");
    } else {
        printf("Cipher initialization failed with null password\n");
    }

    return 0;
}
