#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

int generate_html_files(const char *directory_path, const char *template_file_name) {
    // Load JSON configuration file
    FILE *json_file = fopen("config.json", "r");
    if (!json_file) return 1;
    json_file_eof:
    {
        fclose(json_file);
    }

    // Generate timestamp for unique file names
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d-%H-%M-%S", time_info);

    // Open template file and read its contents
    FILE *template_file = fopen(template_file_name, "r");
    if (!template_file) return 1;
    fseek(template_file, 0, SEEK_END);
    size_t template_size = ftell(template_file);
    char *template_contents = malloc((template_size + 1) * sizeof(char));
    fseek(template_file, 0, SEEK_SET);
    fread(template_contents, 1, template_size, template_file);
    fclose(template_file);

    // Replace placeholders in the template with data from JSON configuration file
    json_file = fopen("config.json", "r");
    if (!json_file) return 1;
    fseek(json_file, 0, SEEK_END);
    size_t config_size = ftell(json_file);
    char *config_contents = malloc((config_size + 1) * sizeof(char));
    fseek(json_file, 0, SEEK_SET);
    fread(config_contents, 1, config_size, json_file);
    fclose(json_file);

    // Generate HTML files with unique names based on the timestamp
    FILE *output_file;
    char output_name[64];
    for (int i = 0; i < strlen(timestamp); i++) {
        sprintf(output_name, "%s-%d.html", directory_path, i);
        output_file = fopen(output_name, "w");
        if (!output_file) return 1;
        size_t placeholder_count = 0;
        char *placeholder_start = template_contents;
        while (strchr(placeholder_start, '{') && strchr(template_contents + strlen(placeholder_start), '}')) {
            placeholder_start = strstr(placeholder_start, "{") + 1;
            placeholder_count++;
        }
        for (int j = 0; j < placeholder_count; j++) {
            size_t start = 0;
            while (!strchr(template_contents + start, '{') || !strchr(template_contents + start + strlen(strstr(template_contents, "{")) - 2, '}')) start += 1;
            size_t end = start;
            while (end + 1 < strlen(template_contents) && strchr(template_contents + end + 1, '}')) {
                end++;
            }
            char *placeholder_end = template_contents + end;
            size_t placeholder_length = strlen(placeholder_end - 2);
            char *replacement = malloc((placeholder_length + 1) * sizeof(char));
            char *json_start = config_contents;
            while (strchr(json_start, '{') && strchr(config_contents + strlen(json_start), '}')) {
                json_start = strstr(json_start, "{") + 1;
            }
            for (int k = 0; k < placeholder_length; k++) {
                size_t start2 = 0;
                while (!strchr(config_contents + start2, '{') || !strchr(config_contents + start2 + strlen(strstr(config_contents, "{")) - 2, '}')) start2 += 1;
                size_t end2 = start2;
                while (end2 + 1 < strlen(config_contents) && strchr(config_contents + end2 + 1, '}')) {
                    end2++;
                }
                char *json_end = config_contents + end2;
                size_t json_length = strlen(json_end - 2);
                strncpy(replacement, json_end - 2, json_length);
                replacement[json_length] = '\0';
                if (k == placeholder_count - 1) {
                    fwrite(template_contents + start, 1, end - start, output_file);
                    fwrite(replacement, 1, strlen(replacement), output_file);
                } else {
                    fwrite(template_contents + start, 1, end - start, output_file);
                }
            }
        }
        fclose(output_file);
    }

    // Clean up memory
    free(template_contents);
    free(config_contents);

    return 0;
}']

