    int status;
    int running = 0;

    if (signal(SIGINT, SIG_IGN) == SIG_ERR)
        return 0;

    for (i = 0; i < max_concurrent; i++) {
        pid = fork();

        if (pid < 0) {
            perror("Fork failed");
            return 0;
        }

        if (!pid) { // Child process
            if (execlp(cmd, cmd, NULL) == -1) {
                perror("Cmd execution failed");
                _exit(1);
            }
        } else { // Parent process
            running++;
            wait(&status);

            if (WIFEXITED(status)) {
                printf("%s: %d: %s completed with exit code %d\n", log_file, getpid(), cmd, WEXITSTATUS(status));
                fflush(stdout);
            }

            if (WIFSIGNALED(status) && status == SIGINT)
                printf("%s: %d: %s interrupted by signal\n", log_file, getpid(), cmd);

            running--;
        }
    }

    while (running > 0) {
        wait(&status);
        running--;

        if (WIFEXITED(status)) {
            printf("%s: %d: %s completed with exit code %d\n", log_file, getpid(), cmd, WEXITSTATUS(status));
            fflush(stdout);
        }

        if (WIFSIGNALED(status) && status == SIGINT)
            printf("%s: %d: %s interrupted by signal\n", log_file, getpid(), cmd);
    }
}']

