import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final int MAX_RETRIES = 3;
    private static final int TIMEOUT_MILLISECONDS = 30000; // 30 seconds
    private static final String LOG_FILE_NAME = "command_log.txt";

    public void executeCommand(String filePath, String[] command) throws IOException {
        Path file = Paths.get(filePath);
        if (!Files.exists(file)) {
            System.out.println("File not found: " + filePath);
            return;
        }

        // Delete the file if it exists
        Files.deleteIfExists(file);

        try (BufferedReader outputReader = getOutputReader(command[0], command[1], file);
             BufferedReader errorReader = getErrorReader(command[0], command[1], file)) {

            String line;
            while ((line = outputReader.readLine()) != null) {
                System.out.println(line);
                logOutput(line);
            }

            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
                logError(line);
            }
        } catch (IOException e) {
            throw new IOException("Failed to execute command", e);
        }
    }

    private BufferedReader getOutputReader(String command, String... args) throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(command, args);
        return newOutputReader(processBuilder.start());
    }

    private BufferedReader getErrorReader(String command, String... args) throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(command, args);
        return newErrorReader(processBuilder.redirectErrorStream(true).start());
    }

    private BufferedReader newOutputReader(Process process) throws IOException {
        return new BufferedReader(new InputStreamReader(process.getInputStream()));
    }

    private BufferedReader newErrorReader(Process process) throws IOException {
        return new BufferedReader(new InputStreamReader(process.getErrorStream()));
    }

    private void logOutput(String output) {
        try (PrintWriter writer = new PrintWriter(new BufferedWriter(new FileWriter(LOG_FILE_NAME, true)))) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            Date date = new Date();
            writer.println(dateFormat.format(date) + ": " + output);
        } catch (IOException e) {
            System.err.println("Failed to log output: " + e.getMessage());
        }
    }

    private void logError(String error) {
        try (PrintWriter writer = new PrintWriter(new BufferedWriter(new FileWriter(LOG_FILE_NAME, true)))) {
            SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            Date date = new Date();
            writer.println(dateFormat.format(date) + ": " + error);
        } catch (IOException e) {
            System.err.println("Failed to log error: " + e.getMessage());
        }
    }

    public static void main(String[] args) throws IOException {
        CommandExecutor executor = new CommandExecutor();
        String filePath = "/path/to/file";
        String[] command = {"command", "args"};
        executor.executeCommand(filePath, command);
    }
}
