int json_valid(const char *json_string) {
    json_object *jobj = json_object_from_json_string(json_string);
    if (!jobj) return 0; // invalid JSON structure, return false

    int has_access_token = json_object_object_exists(jobj, "access_token");
    int has_expires_in = json_object_object_exists(jobj, "expires_in");
    int has_token_type = json_object_object_exists(jobj, "token_type");
    int has_refresh_token = json_object_object_exists(jobj, "refresh_token");

    if (!has_access_token || !has_expires_in || !has_token_type) return 0; // missing required fields

    char *access_token = json_object_get_string(jobj, "access_token");
    int expires_in = json_object_get_int(jobj, "expires_in");
    char *token_type = json_object_get_string(jobj, "token_type");

    if (!access_token || strlen(access_token) == 0 || 
        (expires_in <= 0) || 
        (strcmp(token_type, "Bearer") != 0)) return 0; // invalid values

    if (has_refresh_token) {
        char *refresh_token = json_object_get_string(jobj, "refresh_token");
        if (!refresh_token || strlen(refresh_token) == 0) return 0; // invalid refresh token
    }

    if (json_object_object_exists(jobj, "scope")) {
        char *scope = json_object_get_string(jobj, "scope");
        if (!scope || strlen(scope) == 0) return 0; // invalid scope
    }

    return 1; // valid OAuth2 token response
}
