using System;
using System.Security.Cryptography;

public class SemaphorePool
{
    private readonly int _initialPoolSize;
    private readonly int _maxPoolSize;
    private readonly object _syncLock = new object();
    private readonly Semaphore[] _semaphorePool;

    public SemaphorePool(int initialPoolSize, int maxPoolSize)
    {
        _initialPoolSize = initialPoolSize;
        _maxPoolSize = maxPoolSize;
        _semaphorePool = new Semaphore[initialPoolSize];
        for (int i = 0; i < initialPoolSize; i++)
        {
            _semaphorePool[i] = new Semaphore(1, 1);
        }
    }

    public string DecryptMessage(string encryptedMessage)
    {
        try
        {
            byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
            using (TripleDESCryptoServiceProvider cryptoProvider = new TripleDESCryptoServiceProvider())
            {
                cryptoProvider.Key = Encoding.ASCII.GetBytes("YourSecretKey");
                cryptoProvider.IV = Encoding.ASCII.GetBytes("YourInitializationVector");
                using (MemoryStream memoryStream = new MemoryStream())
                {
                    CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoProvider.CreateDecryptor(), CryptoStreamMode.Write);
                    cryptoStream.Write(encryptedBytes, 0, encryptedBytes.Length);
                    cryptoStream.FlushFinalBlock();
                    byte[] decryptedBytes = memoryStream.ToArray();
                    return Encoding.UTF8.GetString(decryptedBytes);
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions
        }

        return null;
    }

    public void ReleaseSemaphore(int semaphoreIndex)
    {
        if (semaphoreIndex >= 0 && semaphoreIndex < _semaphorePool.Length)
        {
            _semaphorePool[semaphoreIndex].Release();
        }
    }

    public void AcquireSemaphore(int semaphoreIndex)
    {
        if (semaphoreIndex >= 0 && semaphoreIndex < _semaphorePool.Length)
        {
            _semaphorePool[semaphoreIndex].WaitOne();
        }
    }

    public void DeleteSemaphore(int semaphoreIndex)
    {
        if (_semaphorePool != null && semaphoreIndex >= 0 && semaphoreIndex < _semaphorePool.Length)
        {
            _semaphorePool[semaphoreIndex].Dispose();
        }
    }
}']

