public class FileHasher
{
    private readonly ILog _logger = LogManager.GetLogger(typeof(FileHasher));

    public string ComputeMd5Hash(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hash = md5.ComputeHash(stream);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
        }
    }

    public bool VerifyMd5Hash(string filePath, string expectedHash)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                using (var stream = File.OpenRead(filePath))
                {
                    var hash = md5.ComputeHash(stream);
                    return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant() == expectedHash;
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Error("Error verifying MD5 hash: " + ex.Message);
            return false;
        }
    }

    public void ComputeMd5HashAsync(string filePath, Action<string> onComplete)
    {
        Task.Run(() =>
        {
            try
            {
                using (var md5 = MD5.Create())
                {
                    using (var stream = File.OpenRead(filePath))
                    {
                        var hash = md5.ComputeHash(stream);
                        _logger.Info("Computed MD5 hash: " + BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant());
                        onComplete(BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant());
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Error("Error computing MD5 hash: " + ex.Message);
                onComplete(null);
            }
        });
    }

    public void VerifyMd5HashAsync(string filePath, string expectedHash, Action<bool> onComplete)
    {
        Task.Run(() =>
        {
            try
            {
                using (var md5 = MD5.Create())
                {
                    using (var stream = File.OpenRead(filePath))
                    {
                        var hash = md5.ComputeHash(stream);
                        bool isMatch = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant() == expectedHash;
                        _logger.Info("Verification result: " + isMatch);
                        onComplete(isMatch);
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Error("Error verifying MD5 hash: " + ex.Message);
                onComplete(false);
            }
        });
    }
}
