using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static byte[] DecryptAEScbc(byte[] ciphertext, byte[] key, byte[] iv, string padding)
{
    using (Aes aes = Aes.Create())
    {
        aes.Key = key;
        aes.IV = iv;

        using (MemoryStream ms = new MemoryStream())
        {
            CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write);

            int readCount;
            byte[] buffer = new byte[4096];
            for (int i = 0; i < ciphertext.Length; i += buffer.Length)
            {
                readCount = System.Math.Min(buffer.Length, ciphertext.Length - i);
                cs.Write(ciphertext, i, readCount);
            }
            cs.FlushFinalBlock();
            cs.Close();

            byte[] decryptedBytes = ms.ToArray();

            byte[] paddingBytes;
            switch (padding)
            {
                case "PKCS7":
                    paddingBytes = PadUnpad.PKCS7Unpad(decryptedBytes);
                    break;
                default:
                    throw new ArgumentException("Invalid padding type");
            }

            return paddingBytes;
        }
    }
}
