public class CompressedFileLoader
{
    private readonly ILog _log = LogManager.GetLogger(typeof(CompressedFileLoader));

    public void LoadAndDeserialize(string file_path, out MyCustomDataStructure data)
    {
        data = null;

        try
        {
            using (SevenZipArchive archive = SevenZipExtractor.ExtractToFile(file_path, Path.GetFileNameWithoutExtension(file_path)))
            {
                foreach (ArchiveEntry entry in archive.Entries)
                {
                    if (entry.IsFile && !string.IsNullOrEmpty(entry.FileName))
                    {
                        string file_name = entry.FileName;
                        byte[] file_data;

                        using (Stream stream = archive.OpenFile(entry.FileName))
                        {
                            file_data = new byte[stream.Length];
                            stream.Read(file_data, 0, file_data.Length);
                        }

                        try
                        {
                            data = Deserialize<MyCustomDataStructure>(file_name, file_data);
                            _log.Info($"Loaded and deserialized {file_name} successfully.");
                        }
                        catch (Exception ex)
                        {
                            _log.Error($"Failed to load or deserialize {file_name}: {ex.Message}");
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _log.Fatal("Failed to load the compressed file.", ex);
        }
    }

    T Deserialize<T>(string file_name, byte[] file_data) where T : new()
    {
        using (Stream stream = new MemoryStream(file_data))
        {
            T data = (T)new BinaryFormatter().Deserialize(stream);
            return data;
        }
    }
}

public class MyCustomDataStructure
{
    // custom properties and methods...
}
