import java.io.ObjectInputStream;
import java.lang.reflect.Constructor;

public class ModuleLoader {
    public Object deserializeModule(byte[] data) throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);

        try {
            return ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to find module class: " + e.getMessage());
        } catch (IOException e) {
            throw new RuntimeException("Error deserializing module: " + e.getMessage());
        } finally {
            bais.close();
            try {
                ois.close();
            } catch (IOException e) {
                // Ignore
            }
        }
    }

    public void executeModule(Object module, Class<?>... constructors) throws Exception {
        for (Class<?> constructor : constructors) {
            Constructor<?> c = constructor.getConstructor(module.getClass());
            if (c != null) {
                try {
                    Object result = c.newInstance(module);
                    // Execute the module
                    // ...
                    return;
                } catch (Exception e) {
                    throw new RuntimeException("Failed to execute module: " + e.getMessage(), e);
                }
            }
        }

        throw new RuntimeException("No constructor found for executing module");
    }
}
