        return Math.random() * (max - min) + min;
    }

    generateRandomInt(min: number, max: number): number {
        if (min > max) throw new Error('Invalid range');
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    generateRandomFloatExclusive(min: number, max: number): number {
        if (min >= max) throw new Error('Invalid range');
        return Math.random() * (max - min) + min;
    }

    generateRandomIntExclusive(min: number, max: number): number {
        if (min >= max) throw new Error('Invalid range');
        return Math.floor(Math.random() * (max - min)) + min + 1;
    }

    toString(): string {
        return `Upload Status: ${this.status}, Range: ${this.floatRange[0]},${this.floatRange[1]}`;
