class Vertex {
    String id;
    List<Edge> edges = new ArrayList<>();
}

class Edge {
    String fromId;
    String toId;
}

public class Graph {
    private Map<String, Vertex> vertices = new ConcurrentHashMap<>();
    private Map<String, Set<String>> edgeMap = new ConcurrentHashMap<>();

    public void addVertex(String id) {
        Vertex vertex = vertices.getOrDefault(id, new Vertex());
        vertex.id = id;
        vertices.put(id, vertex);
    }

    public void addEdge(String fromId, String toId) {
        Vertex from = vertices.computeIfAbsent(fromId, k -> new Vertex());
        Vertex to = vertices.computeIfAbsent(toId, k -> new Vertex());
        Edge edge = new Edge();
        edge.fromId = fromId;
        edge.toId = toId;
        from.edges.add(edge);
        to.edges.add(edge);
        Set<String> edges = edgeMap.computeIfAbsent(fromId, k -> new HashSet<>());
        edges.add(toId);
    }

    public void optimizeMemoryUsage(double loadFactor) {
        // adjust memory allocation based on current load
        vertices.values().stream()
                .map(Vertex::edges)
                .flatMap(Collection::stream)
                .distinct()
                .forEach(edge -> edgeMap.computeIfAbsent(edge.fromId, k -> new HashSet<>()).remove(edge.toId));
    }
}']

