use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

fn create_dir_with_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = get_dir_path(dir_name)?;
    let env_var_name = "MY_DIR_PATH";

    if env::var_os(env_var_name).is_none() {
        set_env_var(env_var_name, &dir_path)?;
    } else {
        match env::var(env_var_name) {
            Ok(current_value) => {
                if current_value == dir_path.to_str().unwrap_or("") {
                    return Ok(());
                }
            },
            Err(_) => {}
        };
    }

    fs::create_dir_all(&dir_path)?;

    set_env_var(env_var_name, &dir_path)?;

    Ok(())
}

fn get_dir_path(dir_name: &str) -> Result<String, Box<dyn std::error::Error>> {
    let dir_path = format!("{}{}", "my dirs/", dir_name);

    if fs::read_dir(&PathBuf::from(dir_path.as_str()))?.count() > 0 {
        return Err(format!("Directory '{}' already exists!", dir_name).into());
    }

    Ok(dir_path)
}

fn set_env_var(env_var_name: &str, dir_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let _ = env::set Var(env_var_name, dir_path.to_str())?;
    Ok(())
}
