import json
from collections import defaultdict
from typing import Any, Dict, List

class JsonObject:
    _registry: Dict[str, Any]
    _cache: Dict[Dict, str]

    def __init__(self):
        self._registry = defaultdict(dict)
        self._cache = {}

    def register_factory(self, id: str, factory: callable) -> None:
        self._registry[id] = factory

    def get_instance(self, id: str) -> Any:
        if id not in self._registry:
            raise ValueError(f"Factory for {id} not found")
        return self._registry[id](self)

    def serialize(self, instance: Any) -> str:
        def encode(obj):
            if isinstance(obj, dict):
                return {str(k): encode(v) for k, v in obj.items()}
            elif hasattr(obj, '__dict__'):
                return {k: encode(getattr(obj, k)) for k in obj.__dict__.keys()}
            else:
                return str(obj)

        serialized = json.dumps(encode(instance))
        self._cache[instance] = serialized
        return serialized

    def deserialize(self, json_string: str) -> Any:
        data = json.loads(json_string)
        if isinstance(data, dict):
            for key, value in data.items():
                data[key] = self.deserialize(value)

        return data


