EVP_CIPHER_CTX *validateTokenAndSelectCipher(const char *json) {
    json_object *token = json_object_from_string(json);

    if (!token) {
        return NULL;
    }

    const char *access_token = json_object_get_string(json_object_get(token, "access_token"));
    int expires_in = json_object_get_int(json_object_get(token, "expires_in"));
    const char *token_type = json_object_get_string(json_object_get(token, "token_type"));

    if (!access_token || !token_type) {
        return NULL;
    }

    if (strcmp(token_type, "Bearer") != 0) {
        return NULL;
    }

    if (expires_in <= 0) {
        return NULL;
    }

    const char *refresh_token = json_object_get_string(json_object_get(token, "refresh_token"));

    EVP_CIPHER_CTX *cipher_ctx;

    if (refresh_token && strlen(refresh_token) > 0) {
        cipher_ctx = EVP_CIPHER_CTX_new();
        EVP_CipherInit_ex(cipher_ctx, EVP_aes_256_cfb8(), NULL, refresh_token, strlen(refresh_token));
    } else {
        cipher_ctx = EVP_CIPHER_CTX_new_by_name("ECB");
    }

    return cipher_ctx;
}

