EVP_CIPHER_CTX* select_cipher(int mode, int key_length, int num_rounds) {
    EVP_CIPHER_CTX* cipher_ctx = NULL;
    EVP_CIPHER_CTX_new(&cipher_ctx);

    if (mode == 0 || mode > 4) {
        ERR_error(FUNC_ERR, "Invalid cipher mode selected");
        return NULL;
    }

    switch (mode) {
        case 1: // ECB
            cipher_ctx->cipher = EVP_des_ecb();
            break;
        case 2: // EDE
            cipher_ctx->cipher = EVP_des_ede_cbc();
            break;
        case 3: // EDE3
            cipher_ctx->cipher = EVP_des_ede3_cbc();
            break;
        case 4: // CFB
            cipher_ctx->cipher = EVP_des_cfb64();
            break;
    }

    if (key_length != 56 && key_length != 64) {
        ERR_error(FUNC_ERR, "Invalid key length selected");
        return NULL;
    }

    cipher_ctx->key_length = key_length;
    cipher_ctx->num_rounds = num_rounds;

    return cipher_ctx;
}

void encrypt_data(EVP_CIPHER_CTX* cipher_ctx, unsigned char* plaintext, int plaintext_len, unsigned char** ciphertext) {
    EVP_EncryptInit_ex(cipher_ctx, NULL, NULL);
    EVP_EncryptUpdate(cipher_ctx, *ciphertext, &cipher_ctx->output_length, plaintext, plaintext_len);
}

void decrypt_data(EVP_CIPHER_CTX* cipher_ctx, unsigned char* ciphertext, int ciphertext_len, unsigned char** plaintext) {
    EVP_DecryptInit_ex(cipher_ctx, NULL, NULL);
    EVP_DecryptUpdate(cipher_ctx, *plaintext, &cipher_ctx->output_length, ciphertext, ciphertext_len);
}

int main() {
    // Example usage
    EVP_CIPHER_CTX* cipher_ctx = select_cipher(4, 64, 3);

    if (cipher_ctx == NULL) return 1;

    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char*)plaintext) + 1;
    unsigned char* ciphertext = malloc(cipher_ctx->output_length + plaintext_len);
    encrypt_data(cipher_ctx, plaintext, plaintext_len, &ciphertext);

    // Decompression and decryption
    unsigned char decrypted[plaintext_len];
    decrypt_data(cipher_ctx, ciphertext, cipher_ctx->output_length, &decrypted);

    // Print the decrypted text
    printf("%s\n", (char*)decrypted);

    free(ciphertext);
    EVP_CIPHER_CTX_free(cipher_ctx);

    return 0;
}

