import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;

public class MD5HashProcessor {
    public List<String> processMultipleStrings(List<String> inputStrings) throws Exception {
        List<String> md5Hashes = new ArrayList<>();
        int batchSize = 1000;
        int totalProcessingCount = inputStrings.size();

        for (int i = 0; i < totalProcessingCount; i += batchSize) {
            int startIdx = i;
            int endIdx = Math.min(startIdx + batchSize - 1, totalProcessingCount - 1);

            for (int j = startIdx; j <= endIdx; j++) {
                String inputString = inputStrings.get(j);

                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    byte[] hashBytes = md.digest(inputString.getBytes());
                    BigInteger hashBigInt = new BigInteger(1, hashBytes);
                    String md5Hash = hashBigInt.toString(16).toUpperCase();

                    md5Hashes.add(md5Hash);

                    // Progress tracking
                    System.out.println("Processed " + (j + 1) + "/" + totalProcessingCount + " strings.");
                } catch (Exception e) {
                    // Log error and rethrow
                    System.err.println("Error processing string: " + inputString);
                    throw e;
                }
            }
        }

        return md5Hashes;
    }
}
