        strcpy(new_str, str);
        strcat(new_str, SEPARATOR);
        new_str[len + strlen(SEPARATOR)] = '\0';

        if (log_file) {
            fprintf(log_file, "Processed string: %s\n", new_str);
            fflush(log_file);
        }

        free(str);
        str = new_str;
