import os
import re
from concurrent.futures import ThreadPoolExecutor

# Configuration for metadata extraction
META_REGEX = r"Author: (.*)\nDate: (.*)\nTitle: (.*)"

def extract_metadata(file_path):
    with open(file_path, "r") as file:
        content = file.read()
        match = re.match(META_REGEX, content)
        if match:
            author, date, title = match.groups()
            return {"author": author, "date": date, "title": title}
        else:
            raise ValueError("Invalid metadata format")

def process_files(file_paths):
    max_batch_size = 1000
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(extract_metadata, file_path) for file_path in file_paths]
        results = []
        for future in futures:
            try:
                result = future.result()
                results.append(result)
            except Exception as e:
                print(f"Error processing {future.result():} - {str(e)}")
    return results

if __name__ == "__main__":
    file_paths = [os.path.join("path", "to", "file1.txt"), ...]
    metadata_results = process_files(file_paths)
    for result in metadata_results:
        print(result)
