['```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <memory>
#include <atomic>

struct OctreeNode {
    std::shared_ptr<OctreeNode> children[8];
    bool isLeaf;
    // Additional data structure to store actual node data
};

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    std::mutex mtx;  // Mutex for synchronization
    std::atomic<std::size_t> capacity;

public:
    Octree(std::size_t featureSize, std::size_t leafNodes) : capacity(leafNodes) {
        root = std::make_unique<OctreeNode>();
        root->isLeaf = true;
        initialize(root.get(), 0);
    }

    ~Octree() {
        destroy(root.release());
    }

    void insert(const std::vector<int>& data, int id) {
        auto node = root.get();
        for (const auto& d : data) {
            if (!node->isLeaf) {
                int index = getIndexOf(d, featureSize);
                node = node->children[index].get();
            }
        }
    }

private:
    void initialize(OctreeNode* node, std::size_t level) {
        if (level >= 3) {
            return;  // Reached maximum depth
        }
        for (auto& child : node->children) {
            child = std::make_shared<OctreeNode>();
            child.get()->isLeaf = false;
            initialize(child.get(), level + 1);
        }
    }

    void destroy(OctreeNode* node) {
        if (!node || !node->isLeaf) {
            return;  // Already destroyed or not a leaf
        }
        for (auto& child : node->children) {
            destroy(child.get());
        }
    }

    int getIndexOf(int value, std::size_t featureSize) {
        return static_cast<int>(value / (1 << (featureSize - 3)));
    }
};
