#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>

// Metadata mapping for file extensions based on log entries
static const char* extension_map[] = {"txt", "json", "csv"};

// Asynchronous I/O model flag (1) or synchronous model flag (0)
int async_model = 1;

// Function to process the log file, sort entries by timestamp, extract status code from last entry,
// and dynamically modify the file extension
char* process_log_file(const char* remote_host, int remote_port) {
    // Initialize file pointer and buffer
    FILE *fp;
    char* file_buffer = NULL;

    // Open socket for remote connection
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return "Error: Socket creation failed";
    }

    // Connect to the remote server
    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(remote_port);
    inet_pton(AF_INET, remote_host, &serv_addr.sin_addr);
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        return "Error: Connection failed";
    }

    // Initialize file pointer and buffer
    fp = fopen("log_entries", "wb");
    if (!fp) {
        fclose(fp);
        return "Error: File opening failed";
    }

    // Read log entries from the remote server and write to the file
    char* buffer = malloc(1024);
    while (1) {
        int bytes_read = read(sockfd, buffer, 1024);
        if (bytes_read < 0) {
            free(buffer);
            fclose(fp);
            return "Error: Network interruption";
        }

        // Write log entries to the file
        fwrite(buffer, 1, bytes_read, fp);
    }

    // Close the socket and file
    close(sockfd);
    fclose(fp);

    // Sort log entries by timestamp
    qsort(file_buffer, strlen(file_buffer), sizeof(char), timestamp_sort);

    // Extract status code from last entry
    char* last_entry = file_buffer + strlen(file_buffer) - 1;
    int status_code = strtol(last_entry, NULL, 10);

    // Dynamically modify the file extension based on metadata extracted from log entries
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    char* timestamp_str = asctime(now_tm);
    char* new_filename = malloc(strlen(timestamp_str) + strlen(extension_map[0]) + 1);
    sprintf(new_filename, "%s.%s", timestamp_str, extension_map[0]);

    // Return the new filename
    free(file_buffer);
    return new_filename;
}

// Timestamp sorting function for qsort()
int timestamp_sort(const char* a, const char* b) {
    time_t a_tm = timegm(strptime(a, "%Y-%m-%d %H:%M:%S"));
    time_t b_tm = timegm(strptime(b, "%Y-%m-%d %H:%M:%S"));

    if (a_tm > b_tm)
        return -1;
    else if (a_tm < b_tm)
        return 1;
    else
        return 0;
}

int main() {
    char* result = process_log_file("remote_server", 8080);
    printf("%s\n", result);

    // Free dynamically allocated memory
    free(result);

    return 0;
}
