typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
} MoSTState;

MoSTState* parseToken(json_t *root) {
    json_error_t error;
    if (!json_is_object(root)) return NULL; // Not a JSON object

    MoSTState* state = (MoSTState*)malloc(sizeof(MoSTState));
    state->access_token = strdup(json_string_value(json_object_get(root, "access_token")));
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (expires_in <= 0) return NULL; // Invalid expires_in
    state->expires_in = expires_in;
    state->token_type = strdup(json_string_value(json_object_get(root, "token_type")));

    if (!json_is_string(state->token_type) || strcmp(state->token_type, "Bearer") != 0) {
        free(state);
        return NULL; // Invalid token type
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    state->refresh_token = refresh_token ? strdup(json_string_value(refresh_token)) : NULL;

    if (!json_is_string(state->access_token) || !state->token_type || (state->refresh_token && !json_is_string(refresh_token))) {
        free(state);
        return NULL; // Missing or invalid fields
    }

    free(state->token_type); state->token_type = NULL;
    free(state->refresh_token); state->refresh_token = NULL;

    return state;
}

int main() {
    json_t *root = json_load_file("path/to/token.json", JSON_LOAD_FILE_ERROR_RETURN_NULL);
    MoSTState* state = parseToken(root);
    // Use the state object
    return 0;
}
