import com.fasterxml.jackson.module.jsonSchema.factories.DefaultTypeFactory;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class JSONProcessor {
    public List<Object> processJSON(String jsonString, Class<?> clazz) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.INDENT_BINARY);
        JsonNode root = mapper.readTree(jsonString);

        return findMatchingObjects(root, clazz);
    }

    private List<Object> findMatchingObjects(JsonNode node, Class<?> clazz) {
        List<Object> matchingObjects = new ArrayList<>();
        if (!node.isArray()) {
            Object obj = mapper.treeToValue(node, clazz);
            if (obj != null) {
                matchingObjects.add(obj);
            } else {
                throw new Exception("No object found that matches the specified criteria");
            }
        } else {
            for (JsonNode child : node.array()) {
                List<Object> objectsInChild = findMatchingObjects(child, clazz);
                matchingObjects.addAll(objectsInChild);
            }
        }

        if (matchingObjects.size() > 1) {
            return new ArrayList<>();
        }

        return matchingObjects;
    }
}
