public class TransactionProcessor {
    private static final int BATCH_SIZE = 10000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public enum RiskLevel { LOW, MEDIUM, HIGH }

    interface Callback {
        void update(int progress);
    }

    public RiskLevel processTransactions(List<Transaction> transactions, Callback callback) {
        int totalTransactions = transactions.size();
        int processedTransactions = 0;
        RiskLevel riskLevel = RiskLevel.LOW;

        for (int i = 0; i < totalTransactions; i += BATCH_SIZE) {
            List<Transaction> batch = new ArrayList<>();
            for (int j = i; j < Math.min(i + BATCH_SIZE, totalTransactions); j++) {
                Transaction transaction = transactions.get(j);
                // Process the transaction and determine its risk level
                RiskLevel currentRiskLevel = calculateRiskLevel(transaction);
                if (!currentRiskLevel.equals(RiskLevel.LOW) && !riskLevel.equals(currentRiskLevel)) {
                    riskLevel = currentRiskLevel;
                }
                batch.add(transaction);
            }

            executorService.submit(() -> processBatch(batch, callback));
            processedTransactions += BATCH_SIZE;

            // Update the progress
            if (processedTransactions % 1000 == 0) {
                callback.update((int) ((processedTransactions * 1.0 / totalTransactions) * 100));
            }
        }

        return riskLevel;
    }

    private RiskLevel calculateRiskLevel(Transaction transaction) {
        // Implement your logic to determine the risk level of a transaction
        // For demonstration purposes, consider an account number and amount
        if (transaction.getAccountNumber().endsWith("123") && transaction.getAmount() > 1000) {
            return RiskLevel.HIGH;
        } else if (transaction.getAccountNumber().endsWith("456") || transaction.getAmount() > 500) {
            return RiskLevel.MEDIUM;
        }
        return RiskLevel.LOW;
    }

    private void processBatch(List<Transaction> batch, Callback callback) {
        try {
            for (Transaction transaction : batch) {
                // Process the transaction
                RiskLevel riskLevel = calculateRiskLevel(transaction);
                // Log or store the processed transaction and its risk level
            }
        } catch (Exception e) {
            // Log the exception with detailed error messages
            System.out.println("Error processing transactions: " + e.getMessage());
        }
    }
}
