    SSL_CTX* ssl_ctx = SSL_CTX_new(TLS_client_method());
    if (ssl_ctx == NULL) handle_error("Failed to create SSL context");

    const char* cipher_name = "AES-256-CBC";
    int key_len = 32;

    // Set up the EVP cipher context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) handle_error("Failed to create EVP cipher context");
    if (!EVP_CipherInit_ex(ctx, EVP_get_cipherbyname(cipher_name), NULL, input, strlen(input))) {
        handle_error("Failed to initialize EVP cipher");
    }
    SSL_CTX_free(ssl_ctx);

    // Perform the encryption or decryption based on the command
    if (is_valid_command(command)) {
        char* encrypted = (char*)malloc(strlen(input) * 2);
