import os
import json
import csv
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import List, Tuple
from datetime import datetime
from itertools import islice
from functools import lru_cache

class Config:
    def __init__(self):
        self.tokenizer_stage = True
        self.pos_tagger_stage = True
        self.sentiment_analyzer_stage = True
        self.max_batch_size = 10000
        self.output_format = "JSON"

@lru_cache(maxsize=None)
def process_text(text: str) -> Tuple[dict, int]:
    # Tokenization
    if Config.tokenizer_stage:
        text = text.split()

    # POS Tagging
    if Config.pos_tagger_stage:
        text = [word for word in text if len(word) > 0]

    # Sentiment Analysis
    if Config.sentiment_analyzer_stage:
        text = ["Positive" if i % 2 == 0 else "Negative" for i, _ in enumerate(text)]

    return {"author": "John Doe", "date": datetime.now().strftime("%Y-%m-%d"), "title": "Sample Text"}, len(text)

def process_file(file_path: str) -> List[dict]:
    try:
        with open(file_path, "r") as file:
            lines = [line.strip() for line in file.readlines()]
            lines.sort()
            sequence_number = int(lines[-1])
            metadata, _ = process_text(" ".join(lines))
            metadata["sequence_number"] = sequence_number
            return [metadata]
    except Exception as e:
        print(f"Error processing {file_path}: {str(e)}")
        return []

def process_directory(directory_path: str) -> List[dict]:
    try:
        files = os.listdir(directory_path)
        with ThreadPoolExecutor(max_workers=10) as executor:
            futures = []
            for file in files:
                file_path = os.path.join(directory_path, file)
                if os.path.isfile(file_path):
                    futures.append(executor.submit(process_file, file_path))
                elif os.path.isdir(file_path):
                    futures.extend(executor.submit(process_directory, file_path) for _ in range(10))
            results = [future.result() for future in as_completed(futures)]
            return [item for sublist in results for item in sublist]
    except Exception as e:
        print(f"Error processing directory {directory_path}: {str(e)}")
        return []

def log_progress(processed_files: int, total_files: int) -> None:
    print(f"\rProcessed files: {processed_files}/{total_files} ({int((processed_files / total_files) * 100)}%)", end="")

def main(directory_path: str) -> None:
    try:
        config = Config()
        metadata_list = process_directory(directory_path)
        if config.output_format == "JSON":
            with open("output.json", "w") as file:
                json.dump(metadata_list, file, indent=4)
        elif config.output_format == "CSV":
            with open("output.csv", "w") as file:
                csv.writer(file).writerows([metadata.values() for metadata in metadata_list])
        elif config.output_format == "XML":
            root = ET.Element("root")
            for metadata in metadata_list:
                metadata_element = ET.SubElement(root, "metadata")
                for key, value in metadata.items():
                    ET.SubElement(metadata_element, str(key)).text = str(value)
            tree = ET.ElementTree(root)
            tree.write("output.xml", encoding="unicode", xml_declaration=True)

    except Exception as e:
        print(f"Error: {str(e)}")
