#include <stdio.h>
#include <stdlib.h>

typedef struct record {
    int id;
    int value;
    struct record* next;
} Record;

Record* create_record(int index) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        return NULL;
    }
    new_record->id = index;
    new_record->value = 0;
    new_record->next = NULL;
    return new_record;
}

void insert_record(Record** head, Record* new_record) {
    if (*head == NULL || new_record->id < (*head)->id) {
        new_record->next = *head;
        *head = new_record;
    } else {
        Record* current = *head;
        while (current->next && current->next->id > new_record->id) {
            current = current->next;
        }
        new_record->next = current->next;
        current->next = new_record;
    }
}

void delete_record(Record** head, int id) {
    if (*head == NULL) {
        return;
    }
    if ((*head)->id == id) {
        Record* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }
    Record* current = *head;
    while (current->next && current->next->id != id) {
        current = current->next;
    }
    if (current->next) {
        Record* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}

void resize_arrays(Record** records, long*** offsets, int*** keys, int threshold) {
    if (*records == NULL || (*records)->id >= threshold) {
        Record* new_head = (Record*)malloc(sizeof(Record));
        *new_head = **records;
        *records = new_head;
        threshold *= 2;
    }
}

void free_records(Record** head) {
    while (*head) {
        Record* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int main() {
    int n = 10;
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    Record* records = NULL;

    for (int i = 0; i < n; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Add some more elements
    resize_arrays(&records, &offsets, &keys, n);

    free_records(&records);
    free(offsets);
    free(keys);
    return 0;
}

