public class DynamicRangeValueGenerator
{
    private float _minFloat;
    private float _maxFloat;
    private int _minInt;
    private int _maxInt;
    private (float, float) _subRange;
    private object _lock = new object();

    public DynamicRangeValueGenerator()
    {
        Reset();
    }

    public void SetRange(float min, float max)
    {
        lock (_lock)
        {
            if (min > max)
                throw new ArgumentException("Min value cannot be greater than Max value", nameof(min));
            _minFloat = min;
            _maxFloat = max;
            _subRange = (0f, 1f);
            LogChange();
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            return (float)UnityEngine.Random.Range(_minFloat, _maxFloat + 1);
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lock)
        {
            return UnityEngine.Random.Range(_minInt, _maxInt + 1);
        }
    }

    public float GenerateRandomFloatExcludeBorders()
    {
        lock (_lock)
        {
            return (float)UnityEngine.Random.Range(_minFloat, _maxFloat);
        }
    }

    public int GenerateRandomIntExcludeBorders()
    {
        lock (_lock)
        {
            return UnityEngine.Random.Range(_minInt, _maxInt);
        }
    }

    public float GenerateRandomFloatInRange(float min, float max)
    {
        lock (_lock)
        {
            return (float)UnityEngine.Random.Range(Mathf.Clamp01(min), Mathf.Clamp01(max));
        }
    }

    public int GenerateRandomIntInRange(int min, int max)
    {
        lock (_lock)
        {
            return UnityEngine.Random.Range(Mathf.Clamp(min, int.MinValue, int.MaxValue), Mathf.Clamp(max, int.MinValue, int.MaxValue));
        }
    }

    public void SetSubRange(float min, float max)
    {
        lock (_lock)
        {
            if (min > max)
                throw new ArgumentException("Min value cannot be greater than Max value", nameof(min));
            _subRange = (min, max);
            LogChange();
        }
    }

    public override string ToString()
    {
        return $"Range: [{_minFloat}, {_maxFloat}] Sub-Range: {(_subRange.Item1 > 0f ? (_subRange.Item2 < 1f ? "[" : "(") + _subRange.Item1 + ", " + _subRange.Item2 : "(1.0, 1.0)")}";
    }

    public void Reset()
    {
        SetRange(0f, 100f);
    }

    public void ResetSubRange()
    {
        lock (_lock)
        {
            _subRange = (0f, 1f);
            LogChange();
        }
    }

    private void LogChange()
    {
        // Implement your logging mechanism here
        // For example:
        System.Diagnostics.Debug.WriteLine("Range or Sub-Range changed");
    }

    public float CalculateAverage(int count)
    {
        float sum = 0;
        for (int i = 0; i < count; i++)
        {
            sum += GenerateRandomFloat();
        }
        return sum / count;
    }

    [JsonIgnore]
    public string SaveState()
    {
        return JsonConvert.SerializeObject(new
        {
            MinFloat = _minFloat,
            MaxFloat = _maxFloat,
            MinInt = _minInt,
            MaxInt = _maxInt,
            SubRange = _subRange
        });
    }

    public void LoadState(string state)
