#define MAX_LOG_LEVEL 3
#define DEFAULT_ERROR_MESSAGE "Default Error Message"
#define SEPARATOR "|"

typedef enum {
    LOG_LEVEL_ERROR = 0,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
} log_level;

char* process_string(const char* input_string, size_t size_limit, int priority_level) {
    if (!input_string || size_limit == 0) {
        return "Invalid Input";
    }

    char* result = NULL;
    if (strlen(input_string) <= size_limit) {
        size_t new_size = strlen(input_string) + strlen(SEPARATOR) + 1;
        result = malloc(new_size * sizeof(char));
        strcpy(result, input_string);
        strcat(result, SEPARATOR);
    } else {
        switch (priority_level) {
            case 0:
                result = strdup(DEFAULT_ERROR_MESSAGE);
                break;
            case 1:
                result = strdup("Warning: Input String Exceeds Size Limit");
                break;
            case 2:
                result = strdup("Error: Input String Exceeds Size Limit");
                break;
        }
    }

    if (result) {
        // Log the operation and its outcome
        switch (priority_level) {
            case 0:
                log_error(result);
                break;
            case 1:
                log_warning(result);
                break;
            case 2:
                log_error(result);
                break;
        }
    }

    return result;
}

void log_error(const char* message) {
    // Log the error
    printf("Error: %s\n", message);
}

void log_warning(const char* message) {
    // Log the warning
    printf("Warning: %s\n", message);
}

int main() {
    const char* input_string = "Hello, World!";
    size_t size_limit = 20;
    int priority_level = 1;

    char* result = process_string(input_string, size_limit, priority_level);

    if (result) {
        printf("Result: %s\n", result);
        free(result);
    }

    return 0;
}
