    uint8_t* derived_key = NULL;
    uint32_t derived_key_len = 0;

    // Check if the provided algorithm is valid
    if (strcmp(algorithm, "PBKDF2") == 0) {
        PBKDF2_CTX ctx;
        PBKFD2_param_set_iterations(&ctx, iterations);
        PBKFD2_param_set_memory_cost(&ctx, memory_cost);
        PBKFD2_param_set_parallelism(&ctx, parallelism);
        PBKFD2_param_set_salt_size(&ctx, salt_size);

        // Generate the derived key using PBKDF2
        if (!PBKDF2(password, password_len, NULL, 0, &ctx, 1, &derived_key, &derived_key_len)) {
            ERR_error_fp(stderr, NULL);
            return;
        }

        pkey = EVP_PKEY_new_raw_private_key(EVP_PKEY_KEYTYPE_AES, derived_key_len, derived_key, 0);

    } else if (strcmp(algorithm, "bcrypt") == 0) {
        // Implement bcrypt key derivation function
        // ...

    } else if (strcmp(algorithm, "Argon2") == 0) {
        // Implement Argon2 key derivation function
        // ...

    }

    if (pkey != NULL) {
        // Initialize the AES-256-CBC cipher with the generated key
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, pkey, iv);

        *key = malloc(EVP_MAX_BLOCK_LENGTH);
        *iv = malloc(AES_BLOCK_SIZE);

        EVP_CipherUpdate(ctx, *key, &derived_key_len);
        EVP_CipherFinal_ex(ctx, *key, &derived_key_len);

        // Clean up and disable the cipher
        EVP_CIPHER_CTX_free(ctx);
        EVP_PKEY_free(pkey);
    } else {
        // Handle error gracefully and ensure that all resources are properly released
        ERR_error_fp(stderr, NULL);
    }
}

// Function to clean up and disable the cipher when it is no longer needed
void aesCleanup(unsigned char* key, unsigned char* iv) {
    if (key != NULL) {
        free(key);
    }

    if (iv != NULL) {
        free(iv);
    }
}
