#define MAX_INPUT_LENGTH 1024
#define RAND_SUFIX_LENGTH 16

char* generate_unique_identifier(const char* input) {
    int input_len = strlen(input);
    if (input_len > MAX_INPUT_LENGTH) {
        input =strupr(strncpy((char*)malloc(MAX_INPUT_LENGTH + 1), input, MAX_INPUT_LENGTH));
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, input, input_len);
    SHA256_Final(hash, &sha256_ctx);

    char* rand_sufix = (char*)malloc(RAND_SUFIX_LENGTH + 1);
    srand(time(NULL));
    for (int i = 0; i < RAND_SUFIX_LENGTH; i++) {
        rand_sufix[i] = ((rand() % 26) + 97); // Generate random alphanumeric characters
    }
    rand_sufix[RAND_SUFIX_LENGTH] = '\0';

    char* identifier = (char*)malloc(strlen(input) + RAND_SUFIX_LENGTH + 1);
    strcpy(identifier, input);
    strcat(identifier, rand_sufix);

    free(rand_sufix);
    return identifier;
}
