    // Allocate memory for arrays
    long** offsetArray = (long**)malloc(threshold * sizeof(long*));
    int** keyArray = (int**)malloc(threshold * sizeof(int*));

    // Initialize arrays
    for (int i = 0; i < threshold; i++) {
        offsetArray[i] = (long*)malloc(sizeof(long));
        keyArray[i] = (int*)malloc(sizeof(int));
    }

    // Allocate memory for linked list nodes
    LinkedListNode** llNodes = (LinkedListNode**)malloc(threshold * sizeof(LinkedListNode*));

    // Initialize linked list nodes
    for (int i = 0; i < threshold; i++) {
        llNodes[i] = (LinkedListNode*)malloc(sizeof(LinkedListNode));
        llNodes[i]->record = (Record*)malloc(sizeof(Record));
        llNodes[i]->next = NULL;
    }

    // Initialize linked list head
