    // Allocate new memory for arrays
    long** offsetArrayNew = (long**)malloc((threshold * 2) * sizeof(long*));
    int** keyArrayNew = (int**)malloc((threshold * 2) * sizeof(int*));

    // Copy existing data to new arrays
    int i;
    for (i = 0; i < threshold; i++) {
        offsetArrayNew[i] = offsetArray[i];
        keyArrayNew[i] = keyArray[i];
    }

    // Free old memory
