    // Copy existing data to new linked list nodes
    for (i = 0; i < threshold; i++) {
        llNodesNew[i] = llNodes[i];
    }

    // Free old memory
    for (; i < threshold * 2; i++) {
        free(llNodes[i]->record);
        free(llNodes[i]);
    }
    free(llNodes);

    // Update linked list node pointer
