    // Add more fields as needed
} LTE_Uplink_PDCP_PDU;

// Define the dynamic array structure
typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Custom locking mechanism
} LTE_UPD_CP_PDUs_Array;

// Function to initialize the dynamic array
LTE_UPD_CP_PDUs_Array* lteUPD_CP_PDUs_Init(size_t initialCapacity) {
    LTE_UPD_CP_PDUs_Array* arr = (LTE_UPD_CP_PDUs_Array*)malloc(sizeof(LTE_UPD_CP_PDUs_Array));
    arr->pdus = (LTE_Uplink_PDCP_PDU*)calloc(initialCapacity, sizeof(LTE_Uplink_PDCP_PDU));
    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Function to add a new PDU to the dynamic array
void lteUPD_CP_PDUs_Add(LTE_UPD_CP_PDUs_Array* arr, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        // Check for out-of-memory condition and potential concurrent access issues
        size_t newCapacity = arr->capacity * 2;
        LTE_Uplink_PDCP_PDU** newPdus = (LTE_Uplink_PDCP_PDU**)realloc(arr->pdus, newCapacity * sizeof(LTE_Uplink_PDCP_PDU));

        if (!newPdus) {
            // Handle out-of-memory condition
            pthread_mutex_unlock(&arr->lock);
            return;
        }

        arr->capacity = newCapacity;
        arr->pdus = newPdus;
    }

    arr->pdus[arr->size++] = pdu;
    pthread_mutex_unlock(&arr->lock);
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* lteUPD_CP_PDUs_GetBySN(LTE_UPD_CP_PDUs_Array* arr, int sequenceNumber) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; i++) {
        if (arr->pdus[i]->sequenceNumber == sequenceNumber) {
            pthread_mutex_unlock(&arr->lock);
            return &arr->pdus[i];
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return NULL;
}

// Function to update the error indication for a given SN
void lteUPD_CP_PDUs_UpdateErrorIndication(LTE_UPD_CP_PDUs_Array* arr, int sequenceNumber) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; i++) {
        if (arr->pdus[i]->sequenceNumber == sequenceNumber) {
            arr->pdus[i]->errorIndication = 1;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to mark PDUs as processed
void lteUPD_CP_PDUs_MarkProcessed(LTE_UPD_CP_PDUs_Array* arr, int sequenceNumber) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; i++) {
        if (arr->pdus[i]->sequenceNumber == sequenceNumber) {
            arr->pdus[i]->errorIndication = 0;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to perform periodic garbage collection of processed PDUs
void lteUPD_CP_PDUs_GC(LTE_UPD_CP_PDUs_Array* arr) {
    pthread_mutex_lock(&arr->lock);

    size_t i = 0;
    while (i < arr->size) {
        if (!arr->pdus[i]->errorIndication) {
            // Mark PDU as processed and remove it from the array
            memmove(&arr->pdus[i], &arr->pdus[i + 1], (arr->size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            arr->size--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to free the dynamic array
void lteUPD_CP_PDUs_Free(LTE_UPD_CP_PDUs_Array* arr) {
    free(arr->pdus);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}
