void process_log_file(const char *remote_server, const char *log_file_path) {
    // Initialize AES-256-CBC cipher with given password
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    AES_cbc_encrypt_init(ctx, "your_password", strlen("your_password"));

    // Create a priority queue to manage log entry processing
    struct LogEntry {
        int timestamp;
        char status_code[3];
    };
    struct LogEntryQueue {
        struct LogEntry *log_entries;
        size_t capacity;
        size_t size;
    } log_queue = {NULL, 1000, 0};

    // Connect to the remote server and retrieve the log file
    int socket_fd = connect_to_server(remote_server);
    int file_descriptor = open(log_file_path, O_RDONLY);

    // Read the log entries from the file
    char buffer[4096];
    while (1) {
        ssize_t bytes_read = read(file_descriptor, buffer, 4096);
        if (bytes_read == 0) break;

        // Process each log entry and add it to the priority queue
        for (size_t i = 0; i < bytes_read / sizeof(struct LogEntry); ++i) {
            struct LogEntry *log_entry = (struct LogEntry *)(buffer + i * sizeof(struct LogEntry));

            // Extract the timestamp and status code from the log entry
            int timestamp = log_entry->timestamp;
            char status_code[3] = {0};
            strncpy(status_code, log_entry->status_code, 2);

            // Add the log entry to the priority queue
            if (log_queue.size < log_queue.capacity) {
                log_queue.log_entries[log_queue.size++] = log_entry;
            } else {
                // Resize the priority queue if it's full
                log_queue.log_entries = realloc(log_queue.log_entries, (log_queue.capacity * 2 + 1) * sizeof(struct LogEntry));
                log_queue.capacity *= 2;
            }
        }
    }

    // Close the file descriptor and socket
    close(file_descriptor);
    shutdown(socket_fd, SHUT_RDWR);

    // Extract the status code from the last log entry
    struct LogEntry *last_log_entry = &log_queue.log_entries[log_queue.size - 1];
    char new_status_code[3] = {0};
    strncpy(new_status_code, last_log_entry->status_code, 2);

    // Dynamically modify the file extension based on metadata extracted from the log entries
    char *file_extension = get_file_extension(log_queue.log_entries, log_queue.size);
    char new_filename[256];
    sprintf(new_filename, "processed_%s-%d", file_extension, timestamp);

    // Rename the log file with the updated filename
    rename_log_file(log_file_path, new_filename);

    // Extract the status code from the last entry and append it to the new filename
    char *new_status_code_str = get_status_code_string(new_status_code);
    strcat(new_filename, ".");
    strcat(new_filename, new_status_code_str);
    free(new_status_code_str);

    printf("New filename: %s\n", new_filename);
}

int main() {
    process_log_file("your_remote_server", "log_file.log");
    return 0;
}
