int pdus_size = 0;

// Function to add a new PDU to the dynamic array
void add_pdu(int sequence_number, char *data, int length) {
    pthread_mutex_lock(&lock);

    // Check if the PDU already exists
    for (int i = 0; i < pdus_size; i++) {
        if (pdus[i]->sequence_number == sequence_number) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Allocate new space in the dynamic array
    LTE_Uplink_PDCP_PDU **new_pdus = realloc(pdus, (pdus_size + 1) * sizeof(LTE_Uplink_PDCP_PDU *));
    if (!new_pdus) {
        pthread_mutex_unlock(&lock);
        return;
    }

    pdus = new_pdus;
    pdus[pdus_size] = malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!pdus[pdus_size]) {
        pthread_mutex_unlock(&lock);
        return;
    }

    pdus[pdus_size]->sequence_number = sequence_number;
    pdus[pdus_size]->data = data;
    pdus[pdus_size]->length = length;
    pdus[pdus_size]->processed = 0;

    pdus_size++;
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a specific PDU by its sequence number
