<?php

class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updatePassword($userId, $oldPassword, $newPassword) {
        // Hash and salt the new password before storage
        $hashedNewPassword = password_hash($newPassword, PASSWORD_DEFAULT);

        // Validate user input to prevent common injection attacks
        if (!isset($userId)) {
            throw new Exception('Invalid user ID');
        }

        if (strlen($oldPassword) < 8 || strlen($newPassword) < 8) {
            throw new Exception('Password must be at least 8 characters long');
        }

        // Check if the old password matches the stored hash
        $storedHash = get_user_password_hash($this->db, $userId);
        if (!password_verify($oldPassword, $storedHash)) {
            throw new Exception('Invalid old password');
        }

        // Update the user's password in the database
        $query = "UPDATE users SET password_hash = ? WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute(array($hashedNewPassword, $userId));
    }
}
