void aes_encrypt(char* password, int iterations, int memory_cost, int parallelism, int salt_size, char* data) {
    // Initialize OpenSSL
    ERR_free_strings();
    OpenSSL_add_all_algorithms();
    RAND_poll();

    // Generate a secure random IV for encryption
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Choose the PBKDF based on user input
    int chosen_pbkdf = 0;
    if (/* user input: choose PBKDF */) {
        chosen_pbkdf = PBKDF2;
    } else if(/* user input: choose bcrypt */) {
        chosen_pbkdf = BCrypt;
    } else if(/* user input: choose Argon2 */) {
        chosen_pbkdf = Argon2i;
    }

    // Derive the key using the chosen PBKDF
    unsigned char* derived_key = NULL;
    int key_len = 0;
    switch (chosen_pbkdf) {
        case PBKDF2:
            derived_key = PBKDF2( password, strlen(password), salt_size, iterations, memory_cost, parallelism, &key_len );
            break;
        // Add support for other PBKDFs as needed
        default:
            printf("Invalid PBKDF choice\n");
            return;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    AES_KEY aes_key;
    int aes_key_len = 32;  // AES-256 uses a 256-bit key (32 bytes)
    if (AES_set_encrypt_key(derived_key, aes_key_len, &aes_key) != 1) {
