        return;
    }

    // Encrypt the data using the AES cipher
    unsigned char* encrypted_data = malloc(strlen(data));
    AES_cbc_encrypt((unsigned char*)data, encrypted_data, strlen(data), &aes_key, iv, AES_ENCRYPT);

    // Clean up and disable the cipher when it is no longer needed
    void clean_up() {
        if (derived_key) free(derived_key);
        AES_free_key(&aes_key);
        ERR_error_string(ERR_get_error(), NULL);
    }
}

// Example usage:
int main() {
    char* password = "my_secret_password";
    int iterations = 100000;
    int memory_cost = 64 * 1024;
    int parallelism = 1;
    int salt_size = 16;
    char* data = "Hello, World!";

    aes_encrypt(password, iterations, memory_cost, parallelism, salt_size, data);

    return 0;
