typedef struct record {
    int id;
    char* str;
    double val;
} Record;

Record* insertRecord(Record** head, int size) {
    Record* newRec = (Record*)malloc(sizeof(Record));
    if (!newRec) return NULL;

    newRec->id = size;
    newRec->str = malloc(10);
    strcpy(newRec->str, "New String");

    newRec->val = 3.14;

    Record* current = *head;
    while (current && current->next)
        current = current->next;
    newRec->next = NULL;
    if (*head) {
        current->next = newRec;
    } else {
        *head = newRec;
    }
    return *head;
}

void freeRecord(Record** head, Record* record) {
    if (record && record->str)
        free(record->str);

    if (record && record->next) {
        freeRecord(head, record->next);
        *head = NULL;
    } else if (record)
        free(record);
}

void printRecords(Record* head) {
    Record* current = head;
    while (current) {
        printf("ID: %d, String: %s, Value: %.2f\n", current->id, current->str, current->val);
        current = current->next;
    }
}

int main() {
    int size = 0;
    Record* head = NULL;

    while (size < 10) {
        head = insertRecord(&head, size);
        size++;
    }

    printRecords(head);

    freeRecord(&head, head);

    return 0;
}
