char* unique_identifier(char* input) {
    if (input == NULL || strlen(input) == 0) {
        return "default_identifier";
    }

    char truncated_input[1024];
    strncpy(truncated_input, input, 1023);
    truncated_input[1023] = '\0';

    time_t current_timestamp = time(NULL);

    pthread_mutex_lock(&lock);

    for (int i = 0; i < cache_size; i++) {
        if (strcmp(truncated_input, cache[i]->identifier) == 0) {
            free(cache[i]->identifier);
            free(cache[i]);
            cache[i] = NULL;
            break;
        }
    }

    int found = 0;

    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->timestamp == current_timestamp) {
            free(cache[i]->identifier);
            free(cache[i]);
            cache[i] = NULL;
            found = 1;
            break;
        }
    }

    if (!found) {
        char* buffer[33];
        sprintf(buffer, "Hash collision for input '%s'", truncated_input);

        va_list ap;
        va_start(ap, buffer);
        vsnprintf(buffer, 32, buffer[0], ap);
        va_end(ap);

        fprintf(stderr, "Error: %s\n", buffer);

        hash_collision++;

        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);

        return cache[i]->identifier;
    }

    pthread_mutex_lock(&lock);

    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->timestamp == current_timestamp) {
            return cache[i]->identifier;
        }
    }

    char* identifier = malloc(33);
    sprintf(identifier, "%x%x", MD5(truncated_input), SHA256(truncated_input));

    CacheEntry* entry = malloc(sizeof(CacheEntry));
    entry->identifier = identifier;
    entry->timestamp = current_timestamp;

    pthread_mutex_unlock(&lock);

    if (cache_size == 1024) {
        for (int i = 0; i < cache_size; i++) {
            free(cache[i]->identifier);
            free(cache[i]);
            cache[i] = NULL;
        }
        cache_size = 0;
    } else {
        cache[cache_size++] = entry;
    }

    return identifier;
}

