**Java Method: generateMD5Hash**
```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileUtilities {
    public static String generateMD5Hash(String filename) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = new byte[0];
        try (java.io.FileChannel channel = new java.io.FileInputStream(filename)..getChannel()) {
            long size = channel.size();
            if (size > Integer.MAX_VALUE) {
                // handle large file
                java.io.DataInputStream dis = new java.io.DataInputStream(new java.io.PipedInputStream());
                java.io.DataOutputStream dos = new java.io.DataOutputStream(new java.io.PipedOutputStream(dis));
                byte[] buffer = new byte[1024];
                int read;
                while ((read = channel.read(buffer)) > 0) {
                    dos.write(buffer, 0, read);
                }
                dos.close();
                dis.close();
                hashBytes = md.digest(dos.toByteArray());
            } else {
                // handle small file
                byte[] buffer = new byte[(int) size];
                channel.read(new java.io.DataInputStream(new java.io.PipedInputStream()).read(buffer));
                hashBytes = md.digest(buffer);
            }
        }
        return bytesToHexString(hashBytes);
    }

    private static String bytesToHexString(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (byte a : b) {
            String hex = Integer.toHexString(a & 0xFF);
            if (hex.length() == 1) {
                sb.append('0');
            }
            sb.append(hex.toUpperCase());
        }
        return sb.toString();
    }
}
