public class FileNameModifier {
    public static String modifyFileName(String filename) {
        int digitCount = 0;
        StringBuilder fileType = new StringBuilder();
        for (int i = filename.length() - 1; i >= 0; --i) {
            if (Character.isDigit(filename.charAt(i))) {
                ++digitCount;
            } else if (!fileType.append(filename.charAt(i)).toString().contains(".$~/_")) {
                fileType.setLength(0);
                fileType.append('.').append(Character.toLowerCase(filename.charAt(i)));
