char* get_file_type(const char* filename) {
    int i = strlen(filename);
    for (; i > 0; i--) {
        if (filename[i-1] == '.' || filename[i-1] == '~' || !isalnum((unsigned char)filename[i-1])) {
            return &filename[i-1];
        }
    }
    return NULL;
}

int get_sequence_number(const char* dir, const char* filename) {
    int seq = 0;
    DIR* dp = opendir(dir);
    struct dirent* ent;
    while ((ent = readdir(dp)) != NULL) {
        if (strcmp(ent->d_name, filename) == 0) {
            char temp[10];
            sprintf(temp, "%s", ent->d_name + strlen(filename));
            int num = atoi(temp);
            seq = num > 0 ? num : 1;
            break;
        }
    }
    closedir(dp);
    return seq;
}

int rename_file(const char* filename, const char* dir) {
    char new_filename[100];
    struct stat sb;
    if (stat(filename, &sb) == -1) {
        return -1; // file not found
    }
    time_t now = time(NULL);
    sprintf(new_filename, "%s.%ld%.3d%s",
             dir, now, get_sequence_number(dir, filename), get_file_type(filename));
    int ret = rename(filename, new_filename);
    if (ret != 0) {
        return -1; // failed to rename
    }
    // log the successful renaming
    return 0;
