#include <stdlib.h>
#include <string.h>
#include <time.h>

void modify_filename(char *filename) {
    // Get original filename extension
    char *ext = strrchr(filename, '.');

    // Extract timestamp and sequence number from existing filenames
    int seq_num = 0;
    DIR *dir = opendir(".");
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, filename) == 0) continue;
        char *temp_ext = strrchr(ent->d_name, '.');
        if (temp_ext && strlen(temp_ext) > 1) {
            seq_num++;
        }
    }
    closedir(dir);

    // Generate new filename with timestamp and sequence number
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char new_filename[256];
    sprintf(new_filename, "%s_%d.%d%s", filename, (int) t->tm_sec, seq_num, ext ? ext : "");

    // Rename file
    if (rename(filename, new_filename) == 0) {
        printf("File renamed successfully: %s -> %s\n", filename, new_filename);
    } else {
        perror("Error renaming file");
    }

    // Log successful modification
    FILE *log_file = fopen("log.txt", "a");
    fprintf(log_file, "%s -> %s\n", filename, new_filename);
    fclose(log_file);
}
