void fetch_remote_file(const char* url, void* buffer, size_t* outLen) {
    CURL *easy_handle;
    CURLcode res;
    struct curl_slist *chunk = NULL;

    // Initialize curl
    easy_handle = curl_easy_init();
    if (!easy_handle) {
        return;
    }

    // Set URL and options
    curl_easy_setopt(easy_handle, CURLOPT_URL, url);
    curl_easy_setopt(easy_handle, CURLOPT_WRITEFUNCTION, write_memory_callback);
    curl_easy_setopt(easy_handle, CURLOPT_WRITEDATA, buffer);
    curl_easy_setopt(easy_handle, CURLOPT_MAX_REDIRECTS, 5L); // Allow 5 redirects

    // Set bandwidth limit
    chunk = curl_slist_append(chunk, "max-filesize=1048576"); // Limit to 1MB
    chunk = curl_slist_append(chunk, "max-connections=50"); // Limit concurrent connections
    curl_easy_setopt(easy_handle, CURLOPT_HTTPHEADER, chunk);

    do {
        res = curl_easy_perform(easy_handle);
        if (res != CURLE_OK) {
            // Handle errors and retries
            if (res == CURLE_SENDFAIL || res == CURLE_RECVFAIL) {
                // Retry after 1 second
                sleep(1);
            } else {
                printf("curl_easy_perform() failed: %s\n", curl_errorstr(res));
            }
        }
    } while (res != CURLE_OK && (res == CURLE_SENDFAIL || res == CURLE_RECVFAIL));

    // Clean up
    curl_easy_cleanup(easy_handle);
}

static size_t write_memory_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    char** buffer = (char**)userp;
    (*buffer) = realloc((*buffer), sizeof(char) * (size * nmemb + 1));
    if (!(*buffer)) {
        return CURL_WRITE_BAD; // Out of memory
    }
    memcpy(*buffer, contents, size * nmemb);
    (*buffer)[size * nmemb] = '\0'; // Null-terminate the buffer
    return size * nmemb;
}
