```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* modifyFileName(const char* filename) {
    int digitCount = 0;
    int i = strlen(filename);
    while (i > 0 && !isdigit(filename[--i])) {}
    if (i > 0) {
        do {
            digitCount++;
            i--;
        } while (i > 0 && isdigit(filename[--i]));
    }
    char newFilename[257];
    if (strlen(filename) + 5 > 256) {
        return "File too long";
    }
    sprintf(newFilename, "%s", filename);
    const char* dotPos = strrchr(filename, '.');
    if (dotPos && strlen(dotPos) > 1) {
        dotPos++;
    } else {
        dotPos = filename + strlen(filename);
    }
    *dotPos++ = '\0';
    if (digitCount == 0) {
        strcat(newFilename, "txt");
    } else if (digitCount == 1) {
        strcat(newFilename, "log");
    } else {
        strcat(newFilename, "bin");
    }
    return newFilename;
}
