using System;
using System.Collections.Generic;
using System.Linq;

public class CustomDataProcessor
{
    private List<(long, double)> DataPoints { get; set; }

    public CustomDataProcessor()
    {
        DataPoints = new List<(long, double)>();
    }

    public void AddDataPoint(long timestamp, double value)
    {
        DataPoints.Add((timestamp, value));
    }

    public (long, double)? GetLatestDataPoint()
    {
        return DataPoints.LastOrDefault();
    }

    public List<(long, double)> FilterDataPoints(double threshold)
    {
        return DataPoints.Where(dp => dp.Item2 > threshold).ToList();
    }

    public double CalculateAverageValue(int windowSize)
    {
        if (windowSize < 1) throw new ArgumentException("Window size must be at least 1.", nameof(windowSize));

        var dataPoints = DataPoints
            .OrderBy(dp => dp.Item1)
            .ToList();

        int startIndex = Math.Max(0, dataPoints.Count - windowSize);
        return dataPoints.Skip(startIndex).Average(dp => dp.Item2);
    }

    public List<(long, double)> SortDataPoints()
    {
        return DataPoints.OrderBy(dp => dp.Item1).ToList();
    }

    public override string ToString()
    {
        if (DataPoints.Count == 0) return "No data points available.";

        return $"Data Points: [{string.Join(", ", DataPoints.Select(dp => $"({dp.Item1}, {dp.Item2})"))}]";
    }

    public void ClearDataPoints()
    {
        DataPoints.Clear();
    }

    public void ResetDataPoints(int initialSize = 10)
    {
        ClearDataPoints();

        for (int i = 0; i < initialSize; i++)
        {
            AddDataPoint(i, Math.Sin(i));
        }
    }
}']

