            break;
        case 3: // CFB (Cipher Feedback)
            EVP_CipherInit(ctx, EVP_des_cfb(), NULL, NULL);
            break;
    }

    switch (key_len) {
        case 64: // 64-bit key
            EVP_CipherSetKeyLength(ctx, 64);
            break;
