    set_log_level(LOG_LEVEL_INFO);

    while (1) {
        log_message(LOG_LEVEL_ERROR, "Error message");
        log_message(LOG_LEVEL_WARNING, "Warning message");

        flush_logs();

        sleep(1); // Simulate periodic logging
    }
}
