// Define the structure for LTE uplink PDCP PDUs
typedef struct {
    int sequenceNumber;
    char data[256];
    int processed;
} LTE_Uplink_PDCP_PDU;

// Define a custom locking mechanism using mutexes and condition variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* dynamicArray = NULL; // Dynamic array of LTE uplink PDCP PDUs

int addPDU(int sequenceNumber, char* data) {
    pthread_mutex_lock(&lock);
    // Allocate memory for a new PDU
    void* pdu = malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!pdu) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return -1;
    }
    // Initialize the PDU structure
    LTE_Uplink_PDCP_PDU* pduPtr = (LTE_Uplink_PDCP_PDU*)pdu;
    pduPtr->sequenceNumber = sequenceNumber;
    strcpy(pduPtr->data, data);
    pduPtr->processed = 0;
    // Add the PDU to the dynamic array
    if (!dynamicArray) {
        dynamicArray = pdu;
    } else {
        void* temp = dynamicArray;
        dynamicArray = pdu;
        pdu = temp;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

LTE_Uplink_PDCP_PDU* retrievePDU(int sequenceNumber) {
    pthread_mutex_lock(&lock);
    // Search the dynamic array for the PDU with the specified sequence number
    void* p = dynamicArray;
    while (p) {
        LTE_Uplink_PDCP_PDU* pduPtr = (LTE_Uplink_PDCP_PDU*)p;
        if (pduPtr->sequenceNumber == sequenceNumber) {
            pthread_mutex_unlock(&lock);
            return pduPtr;
        }
        p = ((LTE_Uplink_PDCP_PDU*)p)->processed ? NULL : ((LTE_Uplink_PDCP_PDU*)p) + 1;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

