    void* p = dynamicArray;
    while (p) {
        LTE_Uplink_PDCP_PDU* pduPtr = (LTE_Uplink_PDCP_PDU*)p;
        if (pduPtr->sequenceNumber == sequenceNumber) {
            pduPtr->processed = 1;
            pthread_mutex_unlock(&lock);
            return;
        }
        p = ((LTE_Uplink_PDCP_PDU*)p)->processed ? NULL : ((LTE_Uplink_PDCP_PDU*)p) + 1;
    }
    pthread_mutex_unlock(&lock);
}

void queueTransmission(int sequenceNumber, char* data) {
