}

void garbageCollection() {
    pthread_mutex_lock(&lock);
    // Periodically free up memory and optimize performance
    void* p = dynamicArray;
    while (p) {
        LTE_Uplink_PDCP_PDU* pduPtr = (LTE_Uplink_PDCP_PDU*)p;
        if (pduPtr->processed) {
            free(p);
            p = ((LTE_Uplink_PDCP_PDU*)p)->processed ? NULL : ((LTE_Uplink_PDCP_PDU*)p) + 1;
        }
    }
    pthread_mutex_unlock(&lock);
}
