// Structure definition for LTE_PHY_FRAME_CONFIG_S
typedef struct {
    int modulationScheme;
    float bandwidth;
} LTE_PHY_FRAME_CONFIG_S;

// Function to manage dynamic array of LTE_PHY_FRAME_CONFIG_S structures
int manageLTEConfigurations(LTE_PHY_FRAME_CONFIG_S** configurations, int* numConfigs) {
    int configIndex = *numConfigs;
    int configID = 0;

    // Add new configuration based on user input
    printf("Enter modulation scheme (1: QPSK, 2: 16QAM, 3: 64QAM): ");
    int modulationScheme;
    scanf("%d", &modulationScheme);

    printf("Enter bandwidth: ");
    float bandwidth;
    scanf("%f", &bandwidth);

    // Check for valid bandwidth values and overlapping configurations
    if (bandwidth < 0 || bandwidth > 100) {
        printf("Invalid bandwidth value. Configuration not added.\n");
        return -1;
    }

    for (int i = 0; i < *numConfigs; i++) {
        if (configurations[i]->bandwidth == bandwidth) {
            printf("Configuration already exists with the same bandwidth. Try again.\n");
            return -1;
        }
    }

    // Allocate memory for new configuration
    LTE_PHY_FRAME_CONFIG_S* newConfig = (LTE_PHY_FRAME_CONFIG_S*)malloc(sizeof(LTE_PHY_FRAME_CONFIG_S));

    if (!newConfig) {
        printf("Memory allocation failed. Configuration not added.\n");
        return -1;
    }

    newConfig->modulationScheme = modulationScheme;
    newConfig->bandwidth = bandwidth;

    // Update configurations array and numConfigs
    *numConfigs += 1;
    (*configurations) = (LTE_PHY_FRAME_CONFIG_S**)realloc(*configurations, sizeof(LTE_PHY_FRAME_CONFIG_S*) * (*numConfigs));

    if (!(*configurations)) {
        printf("Memory allocation failed. Configuration not added.\n");
        free(newConfig);
        return -1;
    }

    (*configurations)[configIndex] = newConfig;

    // Return success
    return 0;
}

// Function to retrieve all stored configurations
int retrieveLTEConfigurations(LTE_PHY_FRAME_CONFIG_S** configurations, int numConfigs) {
    for (int i = 0; i < numConfigs; i++) {
        printf("Modulation Scheme: %d, Bandwidth: %.2f\n", configurations[i]->modulationScheme, configurations[i]->bandwidth);
    }

    return 0;
}

int main() {
    int numConfigs = 0;
    LTE_PHY_FRAME_CONFIG_S** configurations = NULL;

    // Add new configurations
    while (1) {
        if (manageLTEConfigurations(&configurations, &numConfigs) == -1) {
            printf("Error adding configuration. Exiting.\n");
            break;
        }

        printf("Enter '0' to exit or any other key to add another configuration: ");
        int choice;
        scanf("%d", &choice);

        if (choice == 0) {
            break;
        }
    }

    // Retrieve all stored configurations
    retrieveLTEConfigurations(configurations, numConfigs);

    // Free memory allocated for configurations array
    for (int i = 0; i < numConfigs; i++) {
        free(configurations[i]);
    }

    free(configurations);

    return 0;
