// Define the structure for LTE_PHY_FRAME_CONFIG_S
typedef struct {
    int modulationScheme;
    float bandwidth;
} LTE_PHY_FRAME_CONFIG_S;

// Function to manage the dynamic array of configurations
void manageConfigurations(LTE_PHY_FRAME_CONFIG_S **configurations, int *numConfigs) {
    // Variable to store the new configuration
    LTE_PHY_FRAME_CONFIG_S *newConfig = NULL;

    while (1) {
        printf("Enter the modulation scheme (0: QPSK, 1: 16QAM, 2: 64QAM), or -1 to exit: ");
        int modulationScheme;
        scanf("%d", &modulationScheme);

        if (modulationScheme == -1)
            break;

        printf("Enter the bandwidth: ");
        float bandwidth;
        scanf("%f", &bandwidth);

        // Check for invalid inputs
        if (modulationScheme < 0 || modulationScheme > 2 || bandwidth <= 0) {
            printf("Invalid input. Please try again.\n");
            continue;
        }

        // Check for overlapping configurations
        int i;
        for (i = 0; i < *numConfigs; i++) {
            if (configurations[i]->bandwidth == bandwidth)
                break;
        }
        if (i < *numConfigs) {
            printf("Configuration already exists. Please try again.\n");
            continue;
        }

        // Allocate memory for the new configuration
        newConfig = (LTE_PHY_FRAME_CONFIG_S *)malloc(sizeof(LTE_PHY_FRAME_CONFIG_S));
        newConfig->modulationScheme = modulationScheme;
        newConfig->bandwidth = bandwidth;

        // Reallocate the dynamic array if necessary
        int newSize = *numConfigs + 1;
        configurations = (LTE_PHY_FRAME_CONFIG_S **)realloc(configurations, sizeof(LTE_PHY_FRAME_CONFIG_S *) * newSize);
        for (i = *numConfigs; i > 0; i--)
            configurations[i] = configurations[i - 1];
        configurations[0] = newConfig;
        (*numConfigs)++;

        printf("Configuration added successfully.\n");
    }
}

// Function to retrieve all stored configurations
void retrieveConfigurations(LTE_PHY_FRAME_CONFIG_S **configurations, int numConfigs) {
    int i;
    for (i = 0; i < numConfigs; i++) {
        printf("Modulation scheme: %s, Bandwidth: %.2f\n",
               i == 0 ? "QPSK" : i == 1 ? "16QAM" : "64QAM", configurations[i]->bandwidth);
    }
}

int main() {
    // Initialize the dynamic array of configurations
    int numConfigs = 0;
    LTE_PHY_FRAME_CONFIG_S *configurations = NULL;

    while (1) {
        printf("Enter your choice:\n");
        printf("1. Add a new configuration\n");
        printf("2. Retrieve all stored configurations\n");
        printf("3. Exit\n");
        int choice;
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                manageConfigurations(&configurations, &numConfigs);
                break;
            case 2:
                retrieveConfigurations(configurations, numConfigs);
                break;
            case 3:
                free(configurations);
                return 0;
            default:
                printf("Invalid choice. Please try again.\n");
        }
    }

    return 0;
}
