    size_t iv_size;
    size_t key_size;
} encryption_settings_t;

// Function to encrypt data using the specified settings
int encrypt_data(unsigned char* input_data, size_t input_len,
                 unsigned char* output_data, size_t* output_len,
                 encryption_settings_t* settings) {
    // AES-128 CBC encryption example
    if (settings->algorithm == AES_128_CBC) {
        AES_KEY aes_key;
        AES_set_encrypt_key(settings->key, settings->key_size, &aes_key);
        unsigned char* iv = (unsigned char*)malloc(settings->iv_size);
        memcpy(iv, settings->iv, settings->iv_size);
        AES_cbc_encrypt(input_data, output_data, input_len,
