    } else if (settings->algorithm == CHACHA20_POLY1305_GCM) {
        CHACHA_KEY chacha_key;
        CHACHA_set_key(settings->key, settings->key_size, &chacha_key);
        unsigned char* iv = (unsigned char*)malloc(settings->iv_size);
        memcpy(iv, settings->iv, settings->iv_size);
        unsigned char tag[AES_BLOCK_SIZE];
        size_t ciphertext_len = 0;
        CHACHA_gcm_encrypt(input_data, input_len, output_data,
                            &ciphertext_len, iv, tag, &chacha_key);
        free(iv);

    // Triple DES ECB encryption example
    } else if (settings->algorithm == TRIPLE_DES_ECB) {
        DES_KEY des_key;
        DES_set_key(settings->key, settings->key_size, &des_key);
        unsigned char* input_block = (unsigned char*)malloc(AES_BLOCK_SIZE);
        size_t output_len = 0;
        for (size_t i = 0; i < input_len; i += AES_BLOCK_SIZE) {
            size_t block_len = MIN(input_len - i, AES_BLOCK_SIZE);
            memcpy(input_block, &input_data[i], block_len);
            unsigned char* output_block = (unsigned char*)malloc(AES_BLOCK_SIZE);
            DES_ecb_encrypt(input_block, output_block, &des_key);
