void manageLTEFrameConfigurations(LTE_PHY_FRAME_CONFIG_S** configurations, int* numConfigs) {
    int newConfigBandwidth = 0; // Initialize to ensure no overlap
    int i;

    while (1) {
        printf("Enter the modulation scheme (QPSK/16QAM/64QAM): ");
        LTE_PHY_FRAME_CONFIG_S config;
        scanf("%d", &config.modulationScheme);

        switch (config.modulationScheme) {
            case QPSK:
                printf("Enter bandwidth for QPSK: ");
                scanf("%d", &newConfigBandwidth);
                break;
            case SIXTEENQAM:
                printf("Enter bandwidth for 16QAM: ");
                scanf("%d", &newConfigBandwidth);
                break;
            case SIXTYFOURQAM:
                printf("Enter bandwidth for 64QAM: ");
                scanf("%d", &newConfigBandwidth);
                break;
        }

        // Check if the requested configuration is supported
        // (assuming this check is implemented elsewhere)
        if (!isSupportedConfiguration(newConfigBandwidth)) {
            printf("Unsupported configuration. Try again.\n");
            continue;
        }

        for (i = 0; i < *numConfigs; i++) {
            if (configurations[i]->bandwidth == newConfigBandwidth) {
                printf("Overlapping bandwidth detected. Try a different bandwidth.\n");
                return;
            }
        }

        // Add the new configuration
        *numConfigs += 1;
        configurations = realloc(configurations, (*numConfigs) * sizeof(LTE_PHY_FRAME_CONFIG_S*));
        configurations[*numConfigs - 1] = &config;

        printf("Configuration added successfully.\n");
    }
}
