void* manage_pdu_arrays(void*) {
    // Initialize array to store PDUs
    LTE_Uplink_PDCP_PDU** pdus = (LTE_Uplink_PDCP_PDU**)malloc(1000 * sizeof(LTE_Uplink_PDCP_PDU*));

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Function to add PDU
    void add_pdu(int seq_num) {
        LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        pdu->seq_num = seq_num;
        pthread_mutex_lock(&lock);
        // Add PDU to the array
        pdus[seq_num % 1000] = pdu;
        pthread_mutex_unlock(&lock);
    }

    // Function to retrieve PDU by sequence number
    LTE_Uplink_PDCP_PDU* get_pdu(int seq_num) {
        pthread_mutex_lock(&lock);
        return pdus[seq_num % 1000];
    }

    // Function to update PDU
    void update_pdu(int seq_num, char data[]) {
        pthread_mutex_lock(&lock);
        LTE_Uplink_PDCP_PDU* pdu = get_pdu(seq_num);
        strcpy(pdu->data, data);
        pthread_mutex_unlock(&lock);
    }

    // Function to mark as processed
    void mark_as_processed(int seq_num) {
        pthread_mutex_lock(&lock);
        LTE_Uplink_PDCP_PDU* pdu = get_pdu(seq_num);
        free(pdu);
        pthread_mutex_unlock(&lock);
    }

    // Function to transmit PDUs
    void transmit_pdus() {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < 1000; i++) {
            LTE_Uplink_PDCP_PDU* pdu = pdus[i];
            // Transmit PDU and mark as processed
            mark_as_processed(pdu->seq_num);
            free(pdu);
        }
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

