        {"extension", required_argument, 0, 'f'},
        {"output-file", required_argument, 0, 'o'},
        {"verbose", no_argument, 0, 'v'},
        {0, 0, 0, 0}
    };
    char *directory = NULL;
    char *extension = NULL;
    char *output_file_name = NULL;
    int verbose = 0;

    while ((c = getopt_long(argc, argv, "hdf:o:v", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                printf("Usage: summary-report [options]\n");
                printf("Options:\n");
                printf("  --help         Display this help message.\n");
                printf("  -d directory   Specify the directory containing the text files to process.\n");
                printf("  -f extension   Limit processing to files with a specific file extension (e.g., .txt, .log).\n");
                printf("  -o output-file Redirect the summary output to a specified file instead of standard output.\n");
                printf("  -v             Enable verbose mode, which includes detailed file metadata in the summary.\n");
                return 0;
            case 'd':
                directory = optarg;
                break;
            case 'f':
                extension = optarg;
                break;
            case 'o':
                output_file_name = optarg;
                break;
            case 'v':
                verbose = 1;
                break;
        }
    }

    if (!directory) {
        printf("Error: Directory not specified.\n");
        return 1;
    }

    FILE *output_file = stdout;
    if (output_file_name) {
        output_file = fopen(output_file_name, "w");
        if (!output_file) {
            printf("Error opening output file.\n");
            return 1;
        }
    }

    process_directory(directory, extension, output_file, verbose);

    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}

void process_directory(const char *directory, const char *extension, FILE *output_file, int verbose) {
    DIR *dir = opendir(directory);
    if (!dir) {
        log_error("Error opening directory: ");
        log_error(directory);
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dir))) {
        char file_path[MAX_DIR_DEPTH * sizeof(char) + MAX_FILE_NAME];
        sprintf(file_path, "%s/%s", directory, ent->d_name);

        if (strcmp(ent->d_type == DT_DIR ? "dir" : ent->d_name, extension) != 0) continue;

        process_file(file_path, output_file, verbose);
    }

    closedir(dir);
}

void process_file(const char *file_path, FILE *output_file, int verbose) {
    // Your file processing logic goes here
    printf("File: %s\n", file_path);

    // Example usage:
    // FileSummary summary;
    // summary.line_count = 0; // Your line count calculation goes here
    // fprintf(output_file, "Line Count: %d\n", summary.line_count);
}

void log_error(const char *message) {
    FILE *log_file = fopen("summary-report.log", "a");
    if (!log_file) {
        printf("Error opening log file.\n");
        return;
    }

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}
