#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_Uplink_PDCP_PDU {
    int sequence_number;
    int error_indication;
} PDU;

void* dynamic_array = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int array_size = 0;
int current_capacity = 10; // Initial capacity

// Function to add a new PDU
void add_pdu(int sequence_number, int error_indication) {
    pthread_mutex_lock(&lock);
    if (array_size == current_capacity) {
        // Reallocate memory with double the size
        void* temp = realloc(dynamic_array, sizeof(PDU) * (current_capacity * 2));
        if (temp == NULL) {
            printf("Out of memory!\n");
            exit(1);
        }
        dynamic_array = temp;
        current_capacity *= 2;
    }

    PDU* new_pdu = (PDU*)dynamic_array + array_size;
    new_pdu->sequence_number = sequence_number;
    new_pdu->error_indication = error_indication;

    array_size++;
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a specific PDU by its sequence number
PDU* get_pdu(int sequence_number) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < array_size; i++) {
        if (((PDU*)dynamic_array + i)->sequence_number == sequence_number) {
            pthread_mutex_unlock(&lock);
            return (PDU*)dynamic_array + i;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to update the error indication for a given SN
void update_error_indication(int sequence_number, int new_error_indication) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < array_size; i++) {
        if (((PDU*)dynamic_array + i)->sequence_number == sequence_number) {
            ((PDU*)dynamic_array + i)->error_indication = new_error_indication;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Function to merge PDUs into larger segments based on their sequence numbers
void merge_pdus() {
    pthread_mutex_lock(&lock);

    // Iterate through the array, merging adjacent PDUs with the same SN
    for (int i = 0; i < array_size - 1; i++) {
        if (((PDU*)dynamic_array + i)->sequence_number == ((PDU*)dynamic_array + i + 1)->sequence_number) {
            // Merge the current PDU with the next one
            ((PDU*)dynamic_array + i)->error_indication |= ((PDU*)dynamic_array + i + 1)->error_indication;
            memmove((void*)&((PDU*)dynamic_array)[i + 1], (void*)&((PDU*)dynamic_array)[i + 2], (array_size - i - 2) * sizeof(PDU));
            array_size--;
            i--; // Skip the merged PDU
        }
    }

    pthread_mutex_unlock(&lock);
}

// Function to log information for monitoring purposes
void log_info() {
    pthread_mutex_lock(&lock);
    printf("Current size: %d, Current capacity: %d\n", array_size, current_capacity);
    pthread_mutex_unlock(&lock);
}
