```java
import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileNameProcessor {
    public static String modifyFileName(String filename) {
        int digitCount = 0;
        for (char c : filename.toCharArray()) {
            if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        StringBuilder newFilename = new StringBuilder(filename);
        newFilename.deleteCharAt(newFilename.length() - 1);

        String extension;
        switch (digitCount) {
            case 0:
                extension = "txt";
                break;
            case 1:
                extension = "log";
                break;
            default:
                extension = "bin";
        }

        return newFilename.append(".").append(extension).toString();
    }

    public static String generateMD5Hash(String filename) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = filename.getBytes();
            byte[] hashBytes = md.digest(bytes);

            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            return "Error: Unable to generate MD5 hash.";
        }
    }
}
