void add_segment(TCP_Segment** head, int seq_num, int ack_num, int data_size, unsigned long checksum) {
    TCP_Segment* new_segment = (TCP_Segment*)malloc(sizeof(TCP_Segment));
    if (!new_segment) {
        printf("Memory allocation failed\n");
        return;
    }
    new_segment->seq_num = seq_num;
    new_segment->ack_num = ack_num;
    new_segment->data_size = data_size;
    new_segment->checksum = checksum;
    new_segment->next = *head;
    *head = new_segment;
}

TCP_Segment* get_segment(TCP_Segment* head, int seq_num) {
    TCP_Segment* current = head;
    while (current && current->seq_num != seq_num) {
        current = current->next;
    }
    return current;
}

void update_acknum(TCP_Segment** head, int seq_num, int ack_num) {
    TCP_Segment* current = *head;
    while (current && current->seq_num != seq_num) {
        current = current->next;
    }
    if (!current) {
        printf("Segment not found\n");
        return;
    }
    current->ack_num = ack_num;
}

unsigned long calculate_checksum(TCP_Segment* head) {
    unsigned long sum = 0;
    TCP_Segment* current = head;
    while (current) {
        sum += current->checksum;
        current = current->next;
    }
    return sum;
}
