typedef struct {
    int id;
    time_t last_seen;
    int* packets;
    size_t packet_count;
} TCP_Session;

void init_session(TCP_Session* session, int id) {
    session->id = id;
    session->last_seen = time(NULL);
    session->packets = NULL;
    session->packet_count = 0;
}

TCP_Session* create_session(int id) {
    TCP_Session* session = (TCP_Session*)malloc(sizeof(TCP_Session));
    init_session(session, id);
    return session;
}

void add_packet(TCP_Session* session, int packet_id) {
    if (!session->packets) {
        session->packets = (int*)malloc((1 + session->packet_count) * sizeof(int));
        session->packets[0] = packet_id;
        session->packet_count++;
    } else {
        session->packets = (int*)realloc(session->packets, (session->packet_count + 1) * sizeof(int));
        session->packets[session->packet_count++] = packet_id;
    }
}

void acknowledge_packet(TCP_Session* session, int packet_id) {
    for (size_t i = 0; i < session->packet_count; i++) {
        if (session->packets[i] == packet_id) {
            for (size_t j = i; j < session->packet_count - 1; j++) {
                session->packets[j] = session->packets[j + 1];
            }
            session->packet_count--;
            break;
        }
    }
}

TCP_Session* get_session(TCP_Session** sessions, size_t count, int id) {
    for (size_t i = 0; i < count; i++) {
        if ((*sessions)[i]->id == id) {
            return (*sessions)[i];
        }
    }
    return NULL;
}

void clean_up_sessions(TCP_Session** sessions, size_t* session_count, time_t threshold) {
    size_t new_count = 0;
    for (size_t i = 0; i < *session_count; i++) {
        if ((time(NULL) - (*sessions)[i]->last_seen) <= threshold) {
            (*sessions)[new_count++] = (*sessions)[i];
        }
    }
    *session_count = new_count;
}

void free_session(TCP_Session* session) {
    free(session->packets);
    free(session);
}
