void add_segment(Node** head, TCP_Segment new_segment) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->segment = new_segment;
    new_node->next = *head;
    *head = new_node;
}

TCP_Segment* get_segment(Node* head, int sequence_number) {
    while(head != NULL) {
        if(head->segment.sequence_number == sequence_number) {
            return &head->segment;
        }
        head = head->next;
    }
    return NULL;
}

void update_acknowledgment(Node** head, int sequence_number, int ack) {
    Node* current = *head;
    while(current != NULL) {
        if(current->segment.sequence_number == sequence_number) {
            current->segment.acknowledgement_number = ack;
            break;
        }
        current = current->next;
    }
}

unsigned long calculate_checksum(Node* head) {
    unsigned long checksum = 0;
    Node* current = head;
    while(current != NULL) {
        checksum += current->segment.checksum;
        current = current->next;
    }
    return checksum;
}

void handle_corrupted_segments(Node** head) {
    // TO DO: implement corrupted segment detection and handling
}

// Log function for tracking changes made to the list
void log_change(int operation, TCP_Segment* segment) {
    printf("Logged change: %s segment with sequence number %d.\n", (operation == 1) ? "added" : (operation == 2) ? "updated" : "deleted", segment->sequence_number);
}

int main() {
    Node* head = init_list();
    TCP_Segment new_segment;
    // Example usage: add a segment
    new_segment.sequence_number = 10;
    new_segment.acknowledgement_number = 100;
    new_segment.data_size = 50;
    new_segment.checksum = 1234;
    add_segment(&head, new_segment);
    log_change(1, &new_segment);

    // Example usage: retrieve a segment
    TCP_Segment* retrieved_segment = get_segment(head, 10);
    printf("Retrieved segment sequence number: %d\n", retrieved_segment->sequence_number);

    // Example usage: update an acknowledgment number
    int ack = 200;
    update_acknowledgment(&head, 10, ack);
    log_change(2, &new_segment);

    // Example usage: calculate the cumulative checksum
    unsigned long total_checksum = calculate_checksum(head);
    printf("Cumulative checksum: %lu\n", total_checksum);

    return 0;
}
