        pthread_mutex_init(&nfapi_crc_indication_pdu_pool->lock, NULL);
    }
}

void* nfapi_crc_indication_pdu_get(NFAPI_CRC_INDICATION_PDU_T_POOL* pool, int index) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T* data = &pool->data[index];
    pthread_mutex_unlock(&pool->lock);
    return (void*)data;
}

void nfapi_crc_indication_pdu_put(NFAPI_CRC_INDICATION_PDU_T_POOL* pool, int index, void* data) {
