typedef struct TCP_Segment {
    int sequenceNumber;
    int acknowledgmentNumber;
    int dataSize;
    int checksum;
    struct TCP_Segment* next;
} TCP_Segment;

TCP_Segment* head = NULL;
int cumulativeChecksum = 0;

void addSegment(TCP_Segment** head, int sequenceNumber, int acknowledgmentNumber, int dataSize, int checksum) {
    TCP_Segment* newSegment = (TCP_Segment*)malloc(sizeof(TCP_Segment));
    if (!newSegment) {
        return; // handle out-of-memory condition
    }
    newSegment->sequenceNumber = sequenceNumber;
    newSegment->acknowledgmentNumber = acknowledgmentNumber;
    newSegment->dataSize = dataSize;
    newSegment->checksum = checksum;
    newSegment->next = *head;
    *head = newSegment;
}

TCP_Segment* getSegmentBySequenceNumber(TCP_Segment* head, int sequenceNumber) {
    TCP_Segment* current = head;
    while (current && current->sequenceNumber != sequenceNumber) {
        current = current->next;
    }
    return current;
}

void updateAcknowledgmentNumberForSequenceNumber(TCP_Segment** head, int sequenceNumber, int acknowledgmentNumber) {
    TCP_Segment* segment = getSegmentBySequenceNumber(*head, sequenceNumber);
    if (segment) {
        segment->acknowledgmentNumber = acknowledgmentNumber;
    }
}

int calculateCumulativeChecksum(TCP_Segment* head) {
    int checksum = 0;
    while (head) {
        checksum += head->dataSize;
        head = head->next;
    }
    return checksum;
}
