char *processFileName(char *filename) {
    int digitCount = 0;
    char *newFilename = malloc(512);
    if (!newFilename) {
        return "Error: Out of memory";
    }

    for (int i = 0; i < strlen(filename); i++) {
        if (isdigit(filename[i])) {
            digitCount++;
        }
    }

    switch (digitCount) {
        case 0:
            strcpy(newFilename, "txt");
            break;
        case 1:
            strcpy(newFilename, "log");
            break;
        default:
            sprintf(newFilename, "bin");
            break;
    }

    if (strlen(filename) > 512 - strlen(newFilename) - 1) {
        free(newFilename);
        return "Error: Filename too long";
    }

    strcat(newFilename, filename + strlen(newFilename));

    free(newFilename);

    return newFilename;
}
