    int checksum;
} TCP_Segment;

typedef struct Node {
    TCP_Segment segment;
    struct Node* next;
} Node;

Node* TCP_SegmentManager(Node** head, int mode) {
    if (mode == 0 || *head == NULL) return NULL; // Pause or resume operation

    Node* current = *head;
    Node* prev = NULL;
    int cumulative_checksum = 0;

    while (current != NULL) {
        cumulative_checksum += current->segment.checksum;
        current = current->next;
    }

