    while (current != NULL) {
        if (current->segment.sequence_number == sequence_number)
            return current->segment;
        current = current->next;
    }
    printf("Segment not found!\n");
    return (TCP_Segment){0}; // Initialize with default values
}

Node* updateAcknowledgment(Node** head, int sequence_number, int new_acknowledgment) {
    Node* current = *head;
    while (current != NULL) {
        if (current->segment.sequence_number == sequence_number) {
            current->segment acknowledgment_number = new_acknowledgment;
            return *head; // Return the updated list
        }
        current = current->next;
    }
    printf("Segment not found!\n");
