    static int *cacheCount = (int *)malloc(cacheSize * sizeof(int));

    int i;
    for(i=0; i<cacheSize; i++) {
        filenameCache[i] = NULL;
        cacheCount[i] = 0;
    }

    int cacheIndex = rand() % cacheSize;
    if(filenameCache[cacheIndex]) {
        free(filenameCache[cacheIndex]);
