#include "tcp_session.h"
#include "memory_pool.h"
#include "logger.h"

void manage_tcp_sessions() {
    // Initialize the memory pool for session allocation and deallocation.
    memory_pool_init();

    // Define a custom function to periodically clean up inactive sessions.
    void (*cleanup_sessions)(void) = &cleanup_inactive_sessions;

    while (1) {
        // Handle new connections
        add_new_session();

        // Process incoming packets and mark them as acknowledged.
        process_packets_and_acknowledge();

        // Periodically clean up inactive sessions.
        cleanup_sessions();
    }

    memory_pool_free();
}

// Custom function to periodically clean up inactive sessions.
void cleanup_inactive_sessions() {
    // Get the current timestamp.
    uint64_t now = get_current_timestamp();

    // Iterate over all TCP sessions and check if they are inactive for a specified duration.
    foreach (TCP_Session* session, tcp_session_list) {
        if (session->last_seen + INACTIVE_SESSION_TIMEOUT <= now) {
            // Session is inactive; remove it from the list and deallocate memory.
            deallocate_session(session);
        }
    }
}

// Function to add a new TCP session.
void add_new_session() {
    // Allocate memory for the new session using the custom memory pool.
    TCP_Session* new_session = memory_pool_alloc(TCP_Session);

    // Initialize the new session with a connection ID and an empty packet queue.
    new_session->connection_id = get_next_connection_id();
    new_session->packet_queue = NULL;
    new_session->last_seen = get_current_timestamp();

    // Add the new session to the list of active TCP sessions.
    tcp_session_list.push_back(new_session);
}

// Function to process incoming packets and mark them as acknowledged.
void process_packets_and_acknowledge() {
    foreach (TCP_Session* session, tcp_session_list) {
        // Process incoming packets for this session.
        process_incoming_packets(session);

        // Mark any unacknowledged packets in the packet queue as acknowledged.
        acknowledge_packets(session);
    }
}

// Function to deallocate memory for a TCP session.
void deallocate_session(TCP_Session* session) {
    // Remove the session from the list of active TCP sessions.
    tcp_session_list.remove(session);

    // Deallocate memory for the session using the custom memory pool.
    memory_pool_free(session);
}
