```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int width;
    int height;
    char format[10];
    char extension[4];
} Metadata;

Metadata processMediaFile(const char *filePath) {
    Metadata metadata;
    char tempExtension[4];

    // Check for null or malformed input
    if (filePath == NULL || strlen(filePath) > 256) {
        return (Metadata){0, 0, "", "ERR"};
    }

    // Extract file dimensions and format from the filename
    int width = -1;
    int height = -1;
    char format[10];
    for (int i = 0; i < strlen(filePath); i++) {
        if (filePath[i] >= '0' && filePath[i] <= '9') {
            // Extract width and height
            if (width == -1) {
                width = atoi(&filePath[i]);
                i += strlen(&filePath[i]) - 1;
            } else {
                height = atoi(&filePath[i]);
                i += strlen(&filePath[i]) - 1;
            }
        } else if (strcmp(&filePath[i], "x") == 0) {
            // Separate width and height with 'x'
            format[0] = '\0';
            break;
        }
    }

    // Determine the new file extension
    int digitCount = countDigits(filePath);
    sprintf(tempExtension, "%s", (digitCount == 0) ? "txt" : (digitCount == 1) ? "log" : "bin");

    // Construct metadata and return
    strcpy(metadata.format, format);
    strcpy(metadata.extension, tempExtension);
    return metadata;
}

int countDigits(const char *filePath) {
    int count = 0;
