typedef struct {
    int width;
    int height;
    char format[4];
    char extension[4];
} metadata_t;

metadata_t processMediaFile(const char *filePath) {
    metadata_t metaData;
    int digitCount = 0;
    int i, len;

    // Check for null or malformed input
    if (filePath == NULL || strlen(filePath) > 256) {
        return (metadata_t){0};
    }

    // Analyze the filename to determine the number of digits present
    for (i = 0; i < strlen(filePath); i++) {
        if (isdigit(filePath[i])) {
            digitCount++;
        }
    }

    // Determine the new file extension format based on the digit count
    char *newExtension;
    if (digitCount == 0) {
        newExtension = "txt";
    } else if (digitCount == 1) {
        newExtension = "log";
    } else {
        newExtension = "bin";
    }

    // Extract dimensions, format, and extension from the filename
    for (i = 0; i < strlen(filePath); i++) {
        if (isalpha(filePath[i])) {
            metaData.format[0] = filePath[i];
            break;
        }
    }

    len = strcspn(filePath + i, ".");
    strncpy(metaData.extension, filePath + i, len);
    metaData.extension[len] = '\0';

    // Extract dimensions from the filename
    int j = 0;
    for (i = 0; i < strlen(filePath); i++) {
        if (isdigit(filePath[i])) {
            j++;
            if (j == 4) {
                break;
            }
        } else {
            j = 0;
        }
    }

    metaData.width = atoi(strndupa(filePath, i));
    metaData.height = atoi(strndupa(filePath + i, j));

    return metaData;
}
