MediaMetadata processMediaFile(const char *filename) {
    if (filename == NULL || strlen(filename) > 256) {
        return (MediaMetadata){0, 0, "", "fileTooLong"};
    }

    MediaMetadata metadata;
    int digitCount = 0;
    char newExtension[5];
    char formatStr[4];

    for (int i = 0; i < strlen(filename); i++) {
        if (isdigit(filename[i])) {
            digitCount++;
        }
    }

    switch (digitCount) {
        case 0:
            sprintf(newExtension, "txt");
            break;
        case 1:
            sprintf(newExtension, "log");
            break;
        default:
            sprintf(newExtension, "bin");
            break;
    }

    strcpy(metadata.extension, newExtension);

    // Format detection logic
    if (strstr(filename, ".jpg") || strstr(filename, ".jpeg")) {
        strncpy(formatStr, "JPEG", 4);
    } else if (strstr(filename, ".png")) {
        strncpy(formatStr, "PNG ", 4);
    } else if (strstr(filename, ".gif")) {
        strncpy(formatStr, "GIF ", 4);
    } else {
        strcpy(formatStr, "unknown");
    }

    metadata.format[0] = '\0';
    for (int i = 0; i < strlen(formatStr); i++) {
        if (formatStr[i] == ' ') {
            metadata.format[i] = '\0';
            break;
        }
        metadata.format[i] = formatStr[i];
    }

    // Dimensions detection logic
    int width = 0, height = 0;
    char *token = strtok(filename, "-");
    while (token != NULL) {
        if (sscanf(token, "%dx%d", &width, &height) == 2) {
            break;
        }
        token = strtok(NULL, "-");
    }

    metadata.width = width;
    metadata.height = height;

    return metadata;
}
