typedef struct LTE_Uplink_PDCP_PDU {
    int RNTI;
    int sequence_number;
    int CRCFLAG;
} PDU;

int pdus_allocated = 0;
int max_pdus = 100;
PDU* pdus = NULL;

// Custom locking mechanism
pthread_mutex_t pdus_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdus_available = PTHREAD_COND_INITIALIZER;

void init_pdus() {
    if(pdus != NULL) return;
    pdus = (PDU*)malloc(max_pdus * sizeof(PDU));
    pdus_allocated = max_pdus;
}

PDU* add_pdu(int RNTI, int sequence_number, int CRCFLAG) {
    PDU* pdu = (PDU*)malloc(sizeof(PDU));
    if(pdu == NULL) return NULL; // out-of-memory

    pthread_mutex_lock(&pdus_lock);
    for(int i = 0; i < pdus_allocated; i++) {
        if(pdus[i].sequence_number + 1 == sequence_number) {
            free(pdu);
            pdu = &pdus[i];
            break;
        }
    }

    if(i == pdus_allocated) {
        if(pdus_allocated >= max_pdus) {
            // out-of-memory
            pthread_mutex_unlock(&pdus_lock);
            return NULL;
        } else {
            pdus[pdus_allocated++] = *pdu;
            pdu = &pdus[pdus_allocated - 1];
        }
    }

    pthread_mutex_unlock(&pdus_lock);

    return pdu;
}

PDU* get_pdu(int sequence_number) {
    PDU* pdu = NULL;

    pthread_mutex_lock(&pdus_lock);
    for(int i = 0; i < pdus_allocated; i++) {
        if(pdus[i].sequence_number == sequence_number) {
            pdu = &pdus[i];
            break;
        }
    }

    pthread_mutex_unlock(&pdus_lock);

