extern crate regex;
use regex::Regex;
use std::collections::HashMap;

struct FileNameModifier {
    cache: HashMap<String, String>,
}

impl FileNameModifier {
    fn new() -> FileNameModifier {
        FileNameModifier { cache: HashMap::new() }
    }

    fn modify_filename(&mut self, filename: &str) -> Result<String, &str> {
        if filename.is_none() || filename.trim().is_empty() {
            return Err("Invalid input");
        }

        let re = Regex::new(r"(\D*)\d+(\D*)").unwrap();
        let cap = re.captures(filename);
        match cap {
            Some(caps) => {
                if caps.get(1).map_or("", |m| m.as_str()).len() > 256 {
                    return Err("Filename too long");
                }

                let new_ext = if caps.get(0).unwrap().as_str().to_lowercase().trim().is_empty() {
                    "txt"
                } else if caps.get(0).unwrap().as_str().to_lowercase().trim().parse::<u32>().ok().map_or(true, |v| v == 1) {
                    "log"
                } else {
                    "bin"
                };

                let new_filename = format!("{}{}", caps.get(1).unwrap().as_str(), new_ext);
                if self.cache.insert(filename.to_string(), new_filename.to_string()).is_some() {
                    return Ok(new_filename);
                }
            }
            None => {
                if filename.len() > 256 {
                    return Err("Filename too long");
                }

                let new_ext = match filename.to_lowercase().trim().parse::<u32>().ok() {
                    Some(0) => "txt",
                    Some(_) => "bin",
                    _ => "log",
                };

                let new_filename = format!("{}{}", filename, new_ext);
                self.cache.insert(filename.to_string(), new_filename.to_string());
                return Ok(new_filename);
            }
        }

        Err("Invalid input")
    }
}

