use tokio::fs;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;

async fn modifyFileName(filename: &str) -> String {
    let mut new_filename = filename.to_string();

    if !filename.contains(|c| c.is_digit(10)) {
        new_filename.push_str(".txt");
    } else if filename.matches(|c| c.is_digit(10)).count() == 1 {
        new_filename.push_str(".log");
    } else {
        new_filename.push_str(".bin");
    }

    new_filename
}

async fn generateMD5Hash(filename: &str) -> String {
    let mut hasher = md5::Md5::new();
    fs::read_dir(filename).await.unwrap().map(|entry| {
        entry.map_or_else(|_| Ok(()), |entry| {
            let mut buffer = Vec::new();
            entry.take_read_dir().take(1024*10).for_each(|e| e.for_each(|e| buffer.extend_from_slice(e.as_bytes())));
            buffer
        }).map(|buffer| hasher.update(buffer));
    }).flatten();

    let hash = String::from_utf8(hasherfinalize()).unwrap();
    hash
}

#[tokio::main]
async fn main() {
    let cache = Arc::new(Mutex::new(HashMap::<String, String>::new()));

    loop {
        let mut input = String::new();

        tokio::io::stdout().write_all(b"Enter a filename: ").await.unwrap();
        tokio::io::stdin().read_line(&mut input).await.unwrap();

        if !input.trim().is_empty() {
            let new_filename = modifyFileName(input.trim()).await;

            thread::sleep(std::time::Duration::from_millis(100));

            if let Ok(Some(filename)) = cache.lock().unwrap().get(&new_filename) {
                println!("Filename already exists in the cache: {}", filename);
            } else {
                let hash = generateMD5Hash(new_filename.as_str()).await;

                *cache.lock().unwrap() = HashMap::from_iter([(new_filename.clone(), new_filename)]);

                println!("New filename: {}, MD5 Hash: {}", new_filename, hash);
            }
        }
    }
}

