void add_child_node(Node* parent, const char* name) {
    // Create the new node and add it as a child of the current directory
    Node* child = create_node(name, time(NULL), time(NULL), 0, 0);
    // Add the child node to the parent's list of children
    int i;
    for (i = 0; i < 2; i++) {
        if (!parent->children.left_right[i].left) {
            parent->children.left_right[i].left = child;
            break;
        }
    }
}

// Function to delete a node from the file system tree
void delete_node(Node* node) {
    // Free the memory allocated for the node's metadata and children
    free(node->name);
    if (node->children.left) {
        free(node->children.left_right[0].left);
        free(node->children.left_right[1].left);
    }
    free(node);
}

// Function to rename a directory or file in the file system tree
void rename_node(Node* node, const char* new_name) {
    // Rename the node's metadata and update its position in the file system tree
    free(node->name);
    node->name = strdup(new_name);
}

// Function to list the contents of a directory
void list_directory(Node* node) {
    // Traverse the subtree rooted at the given directory and print each child node's name
    if (node->children.left) {
        printf("%s/\n", node->name);
        list_directory(node->children.left_right[0].left);
        list_directory(node->children.left_right[1].left);
    }
}

// Function to calculate the total disk space used by a subtree rooted at a given directory
int get_subtree_size(Node* node) {
    // Traverse the subtree and sum up the sizes of all nodes
    int size = 0;
    if (node->children.left) {
        size += node->size; // Add the size of this node to the total
        size += get_subtree_size(node->children.left_right[0].left); // Recursively add the sizes of its children
        size += get_subtree_size(node->children.left_right[1].left);
    }
    return size;
}

// Function to check if a directory exceeds its allocated quota limit
int check_quota(Node* node, int max_quota) {
    // Calculate the total disk space used by this subtree and compare it with the given maximum quota
    int size = get_subtree_size(node);
    if (size > max_quota) {
        return -1; // Directory exceeds its quota
    }
    return 0; // Directory is within its quota
}

// Function to copy a subtree starting from a root directory and recursively copying each node's contents
void copy_subtree(Node* source, Node* destination, int permissions) {
    // Traverse the subtree and copy each node's metadata and children
    if (source->children.left) {
        Node* child = create_node(source->name, time(NULL), time(NULL), 0, permissions);
        // Copy this node's contents to the new directory
        copy_subtree(source->children.left_right[0].left, child, permissions);
        copy_subtree(source->children.left_right[1].left, child, permissions);
    }
}

// Function to check if a file exists in a directory subtree
int file_exists(Node* node, const char* filename) {
    // Traverse the subtree and find the target file
    if (node->name && strcmp(node->name, filename) == 0) {
        return 1; // File found
    }
    if (node->children.left) {
        int i;
        for (i = 0; i < 2; i++) {
            if (file_exists(node->children.left_right[i].left, filename)) {
                return 1; // File found in a child directory
            }
        }
    }
    return 0; // File not found']

