#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    int duration;
    char metadata[256];
} AudioStreamFrame;

typedef struct {
    AudioStreamFrame frame;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_frame(int timestamp, int duration, const char* metadata) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->frame.timestamp = timestamp;
    new_node->frame.duration = duration;
    strcpy(new_node->frame.metadata, metadata);
    new_node->next = head;
    pthread_mutex_lock(&lock);
    if (!head) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next && current->next->frame.timestamp <= timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

void get_frame(int timestamp, AudioStreamFrame* frame) {
    Node* current = head;
    while (current && current->frame.timestamp < timestamp) {
        current = current->next;
    }
    if (!current || current->frame.timestamp != timestamp) {
        *frame = (AudioStreamFrame){0};
    } else {
        memcpy(frame, &current->frame, sizeof(AudioStreamFrame));
    }
}

void update_metadata(int timestamp, const char* metadata) {
    Node* current = head;
    while (current && current->frame.timestamp < timestamp) {
        current = current->next;
    }
    if (!current || current->frame.timestamp != timestamp) {
        printf("Error: Timestamp not found.\n");
    } else {
        strcpy(current->frame.metadata, metadata);
    }
}

void merge_frames(int timestamp, int duration) {
    Node* prev = NULL;
    Node* current = head;
    while (current && current->frame.timestamp < timestamp) {
        prev = current;
        current = current->next;
    }
    if (!current || current->frame.timestamp != timestamp) {
        printf("Error: Timestamp not found.\n");
    } else {
        int merged_duration = 0;
        Node* next = NULL;
        while (current && current->frame.timestamp + current->frame.duration <= timestamp + duration) {
            merged_duration += current->frame.duration;
            prev = current;
            current = current->next;
        }
        if (!current || !current->next) {
            // Merge complete, remove remaining nodes
            Node* temp = head;
            while (temp && temp->frame.timestamp < timestamp + duration) {
                prev = temp;
                temp = temp->next;
            }
            if (prev) {
                prev->next = NULL;
            } else {
                head = NULL;
            }
        } else {
            // Merge in progress, update merged_duration and next
            merged_duration += current->frame.duration;
            next = current->next;
        }
        // Update frame durations and metadata
        if (merged_duration > 0) {
            current->frame.timestamp -= timestamp - prev->frame.timestamp;
            current->frame.duration = merged_duration;
            strcpy(current->frame.metadata, "Merged frames");
        } else {
            printf("Error: Merge failed.\n");
        }
    }
}

void* log_thread(void* arg) {
    FILE* log_file = fopen("audio_processing.log", "a+");
    if (!log_file) {
        printf("Error opening log file.\n");
        return NULL;
    }
    while (1) {
        pthread_mutex_lock(&lock);
        Node* current = head;
        int frame_count = 0;
        while (current) {
            frame_count++;
            current = current->next;
        }
        pthread_mutex_unlock(&lock);
        if (frame_count > 0) {
            fprintf(log_file, "Frames: %d\n", frame_count);
        }
        sleep(1); // adjust logging interval as needed
    }
}

int main() {
    pthread_t log_thread_id;
    pthread_create(&log_thread_id, NULL, log_thread, NULL);

    add_frame(1000, 500, "Frame 1");
    add_frame(1050, 200, "Frame 2");
    add_frame(1200, 300, "Frame 3");
    add_frame(1300, 400, "Frame 4");

    AudioStreamFrame frame;
    get_frame(1100, &frame);
    printf("Frame at timestamp 1100: %s\n", frame.metadata);

    update_metadata(1250, "Updated metadata");

    merge_frames(1350, 500);

    pthread_join(log_thread_id, NULL);

    return 0;
}
