// Function to manage dynamic array of TCP_CONNECTION_S structures
void* manage_connections(int max_connections) {
    TCP_CONNECTION_S** connections = (TCP_CONNECTION_S**)malloc(max_connections * sizeof(TCP_CONNECTION_S*));
    int num_connections = 0; // current number of stored connections

    // Function to check if a new connection would overlap with existing ones
    int is_overlap(TCP_CONNECTION_S* new_conn, int num_cons) {
        for (int i = 0; i < num_cons; i++) {
            if ((new_conn->congestion_window >= connections[i]->congestion_window && new_conn->congestion_window <= connections[i]->congestion_window + 100) ||
                (connections[i]->congestion_window >= new_conn->congestion_window && connections[i]->congestion_window <= new_conn->congestion_window + 100)) {
                return 1; // overlap found
            }
        }
        return 0; // no overlap found
    }

    // Function to add a new connection
    int add_connection(int priority, int congestion_window) {
        if (num_connections >= max_connections) {
            printf("Error: Maximum number of connections reached.\n");
            return -1; // error: too many connections
        }
        if (is_overlap((TCP_CONNECTION_S*)malloc(sizeof(TCP_CONNECTION_S)), num_connections)) {
            free((TCP_CONNECTION_S*)malloc(sizeof(TCP_CONNECTION_S)));
            printf("Error: New connection would overlap with existing ones.\n");
            return -2; // error: overlapping connection
        }
        connections[num_connections] = (TCP_CONNECTION_S*)malloc(sizeof(TCP_CONNECTION_S));
        connections[num_connections]->priority = priority;
        connections[num_connections]->congestion_window = congestion_window;
        num_connections++;
        printf("Connection added successfully.\n");
        return 0; // success: new connection added
    }

    // Function to retrieve all stored connections
