#include <stdlib.h>
#include <stdio.h>

typedef struct TCP_Segment {
    int sequence_number;
    int acknowledgment_number;
    size_t data_size;
    uint16_t checksum;
} TCP_Segment;

struct Node {
    TCP_Segment segment;
    struct Node* next;
};

TCP_Segment* list = NULL; // Head of the linked list
size_t total_data_size = 0; // Total size of data in all segments

// Custom memory allocator to handle large lists efficiently
void* custom_malloc(size_t size) {
    return malloc(size);
}

int add_segment(int sequence_number, int data_size, uint16_t checksum) {
    struct Node* new_node = (struct Node*)custom_malloc(sizeof(struct Node));
    if (!new_node) {
        return 1; // Out of memory
    }

    new_node->segment.sequence_number = sequence_number;
    new_node->segment.data_size = data_size;
    new_node->segment.checksum = checksum;

    if (!list) { // First segment in the list
        list = &new_node;
    } else {
        struct Node* current = list;
        while (current->next && current->segment.sequence_number < sequence_number) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    total_data_size += data_size;

    return 0; // Success
}

TCP_Segment* get_segment(int sequence_number) {
    struct Node* current = list;
    while (current && current->segment.sequence_number < sequence_number) {
        current = current->next;
    }
    if (!current || current->segment.sequence_number != sequence_number) {
        return NULL; // Segment not found
    }
    return &current->segment;
}

int update_acknowledgment(int sequence_number, int acknowledgment_number) {
    TCP_Segment* segment = get_segment(sequence_number);
    if (!segment) {
        return 2; // Segment not found
    }
    segment->acknowledgment_number = acknowledgment_number;
    return 0; // Success
}

uint16_t calculate_cumulative_checksum() {
    uint16_t checksum = 0;
    struct Node* current = list;
    while (current) {
        checksum += current->segment.checksum;
        current = current->next;
    }
    return checksum;
}

int merge_segments(int sequence_number, int data_size, uint16_t checksum) {
    TCP_Segment* segment = get_segment(sequence_number);
    if (!segment) {
        return 2; // Segment not found
    }

    struct Node* previous = list;
    struct Node* current = list->next;

    while (current && current->segment.sequence_number == sequence_number + data_size) {
        previous = current;
        current = current->next;
    }

    if (!current || current->segment.sequence_number != sequence_number + data_size) {
        return 0; // No segments to merge
    }

    segment->data_size += data_size;
    previous->next = current->next;

    free(current);

    total_data_size -= (size_t)data_size;

    return 0; // Success
}
