#include <stdio.h>
#include <stdlib.h>

typedef struct TCP_Segment {
    int sequence_number;
    int ack_number;
    int data_size;
    int checksum;
} TCP_Segment;

typedef struct Node {
    TCP_Segment segment;
    struct Node* next;
} Node;

Node* head = NULL;
int cumulative_checksum = 0;

void TCP_SegmentManager_init() {
    head = NULL;
}

void TCP_SegmentManager_add_segment(TCP_Segment new_segment) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }
    new_node->segment = new_segment;
    new_node->next = head;
    head = new_node;
}

TCP_Segment TCP_SegmentManager_get_segment(int sequence_number) {
    Node* current = head;
    while (current && current->segment.sequence_number != sequence_number) {
        current = current->next;
    }
    if (!current) {
        printf("Segment not found.\n");
        return (TCP_Segment){0};
    }
    return current->segment;
}

void TCP_SegmentManager_update_ack(int sequence_number, int ack_number) {
    Node* current = head;
    while (current && current->segment.sequence_number != sequence_number) {
        current = current->next;
    }
    if (!current) {
        printf("Segment not found.\n");
        return;
    }
    current->segment.ack_number = ack_number;
}

int TCP_SegmentManager_calculate_cumulative_checksum() {
    int sum = 0;
    Node* current = head;
    while (current) {
        sum += current->segment.checksum;
        current = current->next;
    }
    return sum;
}

void TCP_SegmentManager_pause() {
    if (!head) {
        printf("No segments to pause.\n");
        return;
    }
    Node* current = head;
    while (current) {
        TCP_Segment segment = current->segment;
        int* data = (int*) malloc(segment.data_size * sizeof(int));
        if (!data) {
            printf("Memory allocation failed.\n");
            return;
        }
        for (int i = 0; i < segment.data_size; i++) {
            data[i] = i + 1;
        }
        // Save and restore data
        free(data);
        current = current->next;
    }
}

void TCP_SegmentManager_resume() {
    if (!head) {
        printf("No segments to resume.\n");
        return;
    }
    Node* current = head;
    while (current) {
        current = current->next;
    }
}

int TCP_SegmentManager_filter_transactions(int threshold_age, int max_transactions_in_last_3_seconds, float weighted_sum_threshold) {
