int main() {
    int num_hostnames = 0;
    scanf("%d", &num_hostnames);
    Host* hostnames = (Host*)malloc(num_hostnames * sizeof(Host));

    for (int i = 0; i < num_hostnames; i++) {
        char hostname[MAX_HOSTNAME_LENGTH];
        scanf("%s", hostname);
        hostnames[i].hostname = strdup(hostname);
        hostnames[i].ip = NULL;
    }

    pthread_t threads[num_hostnames];

    for (int i = 0; i < num_hostnames; i++) {
        pthread_create(&threads[i], NULL, perform_dns_resolution, &hostnames[i]);
    }

    for (int i = 0; i < num_hostnames; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_hostnames; i++) {
        free(hostnames[i].hostname);
    }

    free(hostnames);

    return 0;
}

void* perform_dns_resolution(void* arg) {
    Host* host = (Host*)arg;

    // Perform DNS resolution using standard library functions
    struct hostent* he = gethostbyname(host->hostname);

    if (!he) {
        log_dns_resolution("Failed to resolve hostname", 1); // log error and return
        return NULL;
    }

    char* ip = inet_ntoa(*(struct in_addr*)he->h_addr);

    host->ip = strdup(ip);

    // Log successful resolution
    log_dns_resolution("Resolved hostname", 0); // log success

    return NULL;
}

