Task* manageDynamicTasksAndModifyFile(int numTasks, const char* filename) {
    // Initialize array of tasks
    Task* tasks = (Task*)malloc(numTasks * sizeof(Task));

    if (!tasks) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    for (int i = 0; i < numTasks; i++) {
        Task task;

        // Generate random priority level and estimated completion time
        task.priorityLevel = rand() % 5 + 1;
        task.estimatedCompletionTime = rand_gaussian(10, 2) * 3600;

        // Initialize task name with randomly generated string
        int nameLength = rand() % 20 + 1;
        char* name = (char*)malloc((nameLength + 1) * sizeof(char));
        for (int j = 0; j < nameLength; j++) {
            name[j] = 'a' + rand() % 26;
        }
        name[nameLength] = '\0';
        task.name = name;

        // Add task to array
        tasks[i] = task;
    }

    // Modify file name and send it to database server
    char* newFilename = modifyFileName(filename);
    if (!newFilename) {
        printf("Error modifying filename.\n");
        return NULL;
    }
    byte[] data = convertToByteArray(newFilename);
    DataTableReader results = SendFileToDatabase(data);

    // Log any errors or warnings to a specified log file
    FILE* logFile = fopen("log.txt", "a+");
    if (!logFile) {
        printf("Error logging message.\n");
    } else {
        fprintf(logFile, "Modified filename: %s\n", newFilename);
        fclose(logFile);
    }

    return tasks;
}

char* modifyFileName(const char* filename) {
    // Validate filename and strip off any extensions
    if (strlen(filename) > 200 || !strchr(filename, '.')) {
        return NULL;
    }
    int start = strlen(filename) - 1;
    while (start >= 0 && filename[start] != '.') {
        start--;
    }
    char* newFilename = strdup(filename);
    size_t newSize = start + 5; // reserve space for a 5-digit number and extension
    newFilename[newSize] = '\0';
    int digitCount = rand() % (newSize - start) + 1;
    sprintf(&newFilename[start], "%09d", rand());
    if (rand() % 2) {
        strcat(newFilename, ".txt");
    } else {
        strcat(newFilename, ".log");
    }
    return newFilename;
}

byte[] convertToByteArray(char* filename) {
    // Convert filename to byte array
    size_t len = strlen(filename);
    byte[] data = (byte*)malloc(len * sizeof(byte));
    for (size_t i = 0; i < len; i++) {
        data[i] = (byte)filename[i];
    }
    return data;
}
