// Function to manage dynamic array of LTE_PHY_FRAME_CONFIG_S structures
int manage_configurations(int* version, LTE_PHY_FRAME_CONFIG_S** configs, int num_configs) {
    // Check if adding new configuration would result in overlapping bandwidths
    for (int i = 0; i < num_configs; i++) {
        for (int j = i + 1; j < num_configs; j++) {
            if (configs[i]->bandwidth >= configs[j]->bandwidth) {
                printf("Error: Adding new configuration would result in overlapping bandwidths.\n");
                return -1;
            }
        }
    }

    // Add new configuration
    LTE_PHY_FRAME_CONFIG_S* new_config = (LTE_PHY_FRAME_CONFIG_S*)malloc(sizeof(LTE_PHY_FRAME_CONFIG_S));
    printf("Enter modulation scheme (0 for QPSK, 1 for 16QAM, 2 for 64QAM): ");
    scanf("%d", &new_config->modulation_scheme);
    printf("Enter bandwidth: ");
    scanf("%lf", &new_config->bandwidth);

    // Check if new configuration is valid
    if (new_config->modulation_scheme < 0 || new_config->modulation_scheme > 2) {
        printf("Error: Invalid modulation scheme.\n");
        free(new_config);
        return -1;
    }
    if (new_config->bandwidth <= 0) {
        printf("Error: Bandwidth cannot be zero or negative.\n");
        free(new_config);
        return -1;
    }

    // Increment version number
    (*version)++;

    // Add new configuration to the array
    *configs = (LTE_PHY_FRAME_CONFIG_S**)realloc(*configs, (*version + 1) * sizeof(LTE_PHY_FRAME_CONFIG_S*));
    configs[(*version)] = new_config;

    return 0;
}

int main() {
    int version = 0;
    LTE_PHY_FRAME_CONFIG_S* configs = NULL;

    // Initialize configurations
    manage_configurations(&version, &configs, 0);

    // Add configurations
    while (1) {
        printf("Enter command (add, show, exit): ");
        char command[3];
        scanf("%2s", command);
        if (strcmp(command, "exit") == 0) {
            break;
        }
        else if (strcmp(command, "add") == 0) {
            manage_configurations(&version, &configs, version + 1);
        }
        else if (strcmp(command, "show") == 0) {
            for (int i = 0; i <= version; i++) {
                printf("Modulation scheme: %d, Bandwidth: %.2lf\n", configs[i]->modulation_scheme, configs[i]->bandwidth);
            }
        }
        else {
            printf("Invalid command. Please enter 'add', 'show', or 'exit'.\n");
        }
    }

    // Free memory
    for (int i = 0; i <= version; i++) {
        free(configs[i]);
    }
    free(configs);

    return 0;
}
