    newConfig->modulationScheme = modulationScheme;
    newConfig->bandwidth = bandwidth;

    if (configArray == NULL) {
        configArray = (LTE_PHY_FRAME_CONFIG_S*)malloc(sizeof(LTE_PHY_FRAME_CONFIG_S));
        configArray[0] = *newConfig;
        configCount++;
