void parseAndIndexLargeBinaryFiles(const char* filename, int verbosityLevel) {
    FILE* file = fopen(filename, "rb");
    if (!file) return; // Handle error

    struct stat statbuf;
    fstat(file->fd, &statbuf);
    size_t fileSize = statbuf.st_size;

    if (fileSize > MAX_FILE_SIZE) {
        fprintf(stderr, "File too large: %s (%zu bytes)\n", filename, fileSize);
        return; // Handle error
    }

    HashTable* table = createHashTable(1000000); // Allocate a hash table for 1 million entries

    unsigned char checksum[4];
    fread(checksum, 1, sizeof(checksum), file);

    if (memcmp(checksum, "MAGIC", sizeof("MAGIC") - 1) != 0) {
        fprintf(stderr, "Invalid file magic: %s\n", filename);
        return; // Handle error
    }

    unsigned char* bytes = malloc(fileSize); // Allocate memory for the entire file
    fread(bytes, 1, fileSize, file);

    int blockCount = 0;
    TransformationCacheEntry cache[TRANSFORMATION_CACHE_SIZE];
    int cacheIndex = 0;

    while (filetell(file) < fileSize) {
        unsigned char* dataBlock = malloc(1024); // Allocate memory for a single data block
        fread(dataBlock, 1, 1024, file);

        if (memcmp(dataBlock, validDataBlockSignature, sizeof(validDataBlockSignature)) != 0) {
            free(dataBlock);
            continue; // Skip invalid blocks
        }

        int transformationAttempts = 0;
        while (transformationAttempts < MAX_TRANSFORMATION_ATTEMPTS) {
            unsigned char* transformedBytes = transformBytes(dataBlock);
            if (!transformedBytes) break; // Handle error

            int cacheIndexFound = 0;
            for (int i = 0; i < TRANSFORMATION_CACHE_SIZE; i++) {
                if (cache[i].blockIndex == blockCount && !memcmp(cache[i].transformedBytes, transformedBytes, 1024)) {
                    free(transformedBytes);
                    cacheIndexFound = 1;
                    break;
                }
            }

            if (!cacheIndexFound) {
                cache[cacheIndex].transformedBytes = transformedBytes;
                cache[cacheIndex].blockIndex = blockCount;
                cacheIndex++;
            } else {
                break; // Reuse cached transformation
            }

            free(dataBlock);
            dataBlock = transformedBytes;
        }

        if (transformationAttempts == MAX_TRANSFORMATION_ATTEMPTS) {
            fprintf(stderr, "Failed to transform data block %d after %d attempts.\n", blockCount, MAX_TRANSFORMATION_ATTEMPTS);
            break; // Handle error
