void ltePhyFrameConfigArrayAddConfig(LtePhyFrameConfigArray* array, LTE_PHY_FRAME_CONFIG_S config) {
    for (int i = 0; i < MAX_CONFIGS && array->configs[i].modulation != 0; i++) {
        if (array->configs[i].bandwidth >= config.bandwidth &&
            array->configs[i].bandwidth + 1e6 <= config.bandwidth) {
            // Bandwidth overlap found, update existing config
            array->configs[i] = config;
            return;
        }
    }
    for (int i = 0; i < MAX_CONFIGS && array->configs[i].modulation == 0; i++) {
        if (i == MAX_CONFIGS - 1) {
            printf("Error: Max number of configurations reached.\n");
            return;
        }
        array->configs[i] = config;
        return;
    }
}

void ltePhyFrameConfigArraySave(LtePhyFrameConfigArray* array, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;
    for (int i = 0; i < MAX_CONFIGS && array->configs[i].modulation != 0; i++) {
        fwrite(&array->configs[i], sizeof(LTE_PHY_FRAME_CONFIG_S), 1, file);
    }
    fclose(file);
}

LtePhyFrameConfigArray* ltePhyFrameConfigArrayLoad(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;
    LtePhyFrameConfigArray* array = (LtePhyFrameConfigArray*)malloc(sizeof(LtePhyFrameConfigArray));
    if (!array) return NULL;
    pthread_mutex_init(&array->mutex, NULL);
    for (int i = 0; file && fread(&array->configs[i], sizeof(LTE_PHY_FRAME_CONFIG_S), 1, file); i++) {
        array->configs[i].modulation = 0;
    }
    fclose(file);
    return array;
}

void ltePhyFrameConfigArrayFree(LtePhyFrameConfigArray* array) {
    free(array);
}

int main() {
    LtePhyFrameConfigArray* array = ltePhyFrameConfigArrayInit();
    // Add some configurations
    LTE_PHY_FRAME_CONFIG_S config1 = {0, 10e6}; 
    LTE_PHY_FRAME_CONFIG_S config2 = {1, 20e6};
    ltePhyFrameConfigArrayAddConfig(array, config1);
    ltePhyFrameConfigArrayAddConfig(array, config2);

    // Save and load configurations
