// Define the structure for TCP segment
typedef struct {
    int seq_num;
    int ack_num;
    int data_size;
    unsigned char checksum[4];
} TCP_Segment;

// Define the linked list node
typedef struct {
    TCP_Segment* segment;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

// Initialize the linked list
LinkedList* initialize_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Add a new segment to the linked list
void add_segment(LinkedList* list, TCP_Segment* segment) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->segment = segment;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
}

// Retrieve a segment by its sequence number
TCP_Segment* get_segment(LinkedList* list, int seq_num) {
    Node* current = list->head;
    while (current != NULL && current->segment->seq_num != seq_num) {
        current = current->next;
    }
    if (current == NULL || current->segment->seq_num != seq_num) {
        return NULL; // Segment not found
    } else {
        return current->segment;
    }
}

// Update the acknowledgment number for a given sequence number
void update_ack(LinkedList* list, int seq_num, int ack_num) {
    Node* current = list->head;
    while (current != NULL && current->segment->seq_num < seq_num) {
        current = current->next;
    }
    if (current == NULL || current->segment->seq_num != seq_num) {
        // Segment not found
    } else {
        current->segment->ack_num = ack_num;
    }
}

// Calculate the cumulative checksum of the entire list
unsigned int calculate_checksum(LinkedList* list) {
    unsigned int checksum = 0;
    Node* current = list->head;
    while (current != NULL) {
        checksum += current->segment->checksum[0] + current->segment->checksum[1];
        current = current->next;
    }
    return checksum;
}

// Main function
int main() {
    LinkedList* list = initialize_list();

    // Add segments to the list
    add_segment(list, (TCP_Segment*)malloc(sizeof(TCP_Segment)));
    add_segment(list, (TCP_Segment*)malloc(sizeof(TCP_Segment)));

    // Retrieve a segment by its sequence number
    TCP_Segment* segment = get_segment(list, 1);
    if (segment != NULL) {
        printf("Segment found: seq_num=%d, ack_num=%d\n", segment->seq_num, segment->ack_num);
    } else {
        printf("Segment not found\n");
    }

    // Update the acknowledgment number for a given sequence number
    update_ack(list, 2, 100);

    // Calculate the cumulative checksum of the entire list
    unsigned int checksum = calculate_checksum(list);
    printf("Cumulative checksum: %u\n", checksum);

    return 0;
}
