typedef struct {
    LTE_RRC_SCG_CONFIG data;
    struct Node* next;
} Node;

Node* init_list(int N) {
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed!\n");
            return NULL;
        }
        node->data.scg_mode = rand() % 10;
        node->data.scg_priority = rand() % 10;
        node->data.tdd_mode = rand() % 2;
        node->next = head;
        head = node;
    }
    return head;
}

void serialize_list(Node* head, char* path, int enableSerialization) {
    FILE* file = fopen(path, "wb");
    if (!file) {
        printf("Failed to open the file for writing!\n");
        return;
    }

    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(LTE_RRC_SCG_CONFIG), 1, file);
        current = current->next;
    }

    if (enableSerialization) {
        fseek(file, 0, SEEK_SET);
        size_t totalBytes = (size_t)(current - head + 1) * sizeof(LTE_RRC_SCG_CONFIG);
        fwrite(&totalBytes, sizeof(size_t), 1, file);
    }

    fclose(file);
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
