['Here is the code block for the C function managing a dynamic hash table for storing and retrieving network configuration settings:

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    int value;
} setting_t;

typedef struct {
    int size;
    int capacity;
    setting_t** table;
} hashtable_t;

hashtable_t* initialize_hashtable(int initial_capacity) {
    hashtable_t* ht = (hashtable_t*)malloc(sizeof(hashtable_t));
    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->table = (setting_t**)calloc(ht->capacity, sizeof(setting_t*));
    return ht;
}

void resize_hashtable(hashtable_t* ht) {
    int new_capacity = ht->capacity * 2;
    setting_t** new_table = (setting_t**)calloc(new_capacity, sizeof(setting_t*));
    for (int i = 0; i < ht->capacity; ++i) {
        if (ht->table[i]) {
            int index = i % new_capacity;
            while (new_table[index]) {
                index = (index + 1) % new_capacity;
            }
            new_table[index] = ht->table[i];
        }
    }
    free(ht->table);
    ht->table = new_table;
    ht->capacity = new_capacity;
}

int hash_function(hashtable_t* ht, const char* key) {
    int sum = 0;
    for (const char* p = key; *p; ++p) {
        sum += *p;
    }
    return sum % ht->capacity;
}

void add_setting(hashtable_t* ht, const char* key, int value) {
    int index = hash_function(ht, key);
    setting_t* setting = (setting_t*)malloc(sizeof(setting_t));
    setting->key = strdup(key);
    setting->value = value;
    if (!ht->table[index]) {
        ht->size++;
    }
    ht->table[index] = setting;
}

int get_setting(hashtable_t* ht, const char* key) {
    int index = hash_function(ht, key);
    for (setting_t* p = ht->table[index]; p; ) {
        if (!strcmp(p->key, key)) {
            return p->value;
        }
        setting_t* next = p->next;
        free(p);
        p = next;
    }
    return -1;
}

void update_setting(hashtable_t* ht, const char* key, int value) {
    int index = hash_function(ht, key);
    for (setting_t* p = ht->table[index]; p; ) {
        if (!strcmp(p->key, key)) {
            p->value = value;
            return;
        }
        setting_t* next = p->next;
        free(p);
        p = next;
    }
}

void delete_setting(hashtable_t* ht, const char* key) {
    int index = hash_function(ht, key);
    for (setting_t** p = &ht->table[index]; *p; ) {
        setting_t* setting = *p;
        if (!strcmp(setting->key, key)) {
            *p = setting->next;
            free(setting->key);
            free(setting);
            ht->size--;
            return;
        }
        setting_t** next = &setting->next;
        free(setting);
        setting = *next;
        free(*next);
        *next = NULL;
    }
}

void free_hashtable(hashtable_t* ht) {
    for (int i = 0; i < ht->capacity; ++i) {
        if (ht->table[i]) {
            setting_t* p = ht->table[i];
            while (p) {
                setting_t* next = p->next;
                free(p->key);
                free(p);
                p = next;
            }
        }
    }
    free(ht->table);
    free(ht);
}
