#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for NetworkInterfaceStatus
typedef struct {
    int interfaceID;
    int status;
    int lastError;
} NetworkInterfaceStatus;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for hash table entry
typedef struct {
    char key[20];
    NetworkInterfaceStatus value;
    NFAPI_CRC_INDICATION_PDU_T pduList[5];
    int pduCount;
} HashEntry;

// Define the structure for hash table
typedef struct {
    HashEntry** entries;
    int size;
    int used;
} DynamicHashTable;

// Function to initialize and populate linked list of NetworkInterfaceStatus structures
void initNetworkInterfaceStatus(DynamicHashTable* hashTable) {
    // Initialize the linked list
    NetworkInterfaceStatus* head = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
    if (!head) return;  // Handle allocation failure

    // Populate the linked list with unique interface IDs, random status and last error values
    for (int i = 0; i < 5; i++) {
        NetworkInterfaceStatus* newEntry = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
        if (!newEntry) return;  // Handle allocation failure

        head->interfaceID++;
        newEntry->status = rand() % 3;
        newEntry->lastError = rand();

        // Add the new entry to the linked list
        head->next = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
        if (!head->next) return;  // Handle allocation failure

        head->next = newEntry;

        // Update the hash table size and used count
        hashTable->size++;
        hashTable->used++;

        // Move to the next entry in the linked list
        head = head->next;
    }
}

// Function to add a new setting to the hash table
void addSetting(DynamicHashTable* hashTable, char key[], NetworkInterfaceStatus value) {
