    int hashCode = 0;
    for (int i = 0; i < strlen(key); i++) {
        hashCode += key[i];
    }

    // Find the index of the corresponding hash table entry
    int index = hashCode % hashTable->size;

    // Check if the entry is already occupied
    if (hashTable->entries[index] != NULL) {
        // Handle collision by rehashing and finding a new index
        int newHashCode = 0;
        for (int i = 0; i < strlen(key); i++) {
            newHashCode += key[i];
        }
        index = newHashCode % hashTable->size;

        // Update the used count of the hash table
        hashTable->used++;
    }

    // Allocate memory for a new entry if the table is not full
    if (hashTable->entries[index] == NULL) {
        hashTable->entries[index] = (HashEntry*)malloc(sizeof(HashEntry));
        if (!hashTable->entries[index]) return;  // Handle allocation failure

        hashTable->used++;

        // Initialize the new entry with the given key and value
        strcpy(hashTable->entries[index]->key, key);
        hashTable->entries[index]->value = value;
    }
}

// Function to retrieve a setting by its key from the hash table
NetworkInterfaceStatus* getSetting(DynamicHashTable* hashTable, char key[]) {
    // Calculate the hash code for the given key
    int hashCode = 0;
    for (int i = 0; i < strlen(key); i++) {
        hashCode += key[i];
    }

    // Find the index of the corresponding hash table entry
    int index = hashCode % hashTable->size;

    // Check if the entry exists in the hash table
    HashEntry* entry = hashTable->entries[index];
    while (entry != NULL) {
        if (!strcmp(entry->key, key)) {
            return &entry->value;
        }
        entry = entry->next;
    }

    // Return a null pointer if the setting is not found
    return NULL;
}

// Function to update an existing setting in the hash table
void updateSetting(DynamicHashTable* hashTable, char key[], NetworkInterfaceStatus value) {
    // Retrieve the existing setting by its key
    NetworkInterfaceStatus* existing = getSetting(hashTable, key);
    if (existing == NULL) return;  // Handle not found

    // Update the existing setting with the new value
    strcpy(existing->key, key);
    existing->value = value;
}

// Function to delete a setting from the hash table
void deleteSetting(DynamicHashTable* hashTable, char key[]) {
    // Retrieve the existing setting by its key
    NetworkInterfaceStatus* existing = getSetting(hashTable, key);
    if (existing == NULL) return;  // Handle not found

    // Find the index of the corresponding hash table entry
    int index = 0;
    HashEntry* prevEntry = NULL;
    for (int i = 0; i < hashTable->size; i++) {
        if (!strcmp(hashTable->entries[i]->key, key)) {
            index = i;
            break;
        }
        prevEntry = hashTable->entries[i];
    }

    // Check if the entry exists in the hash table
    HashEntry* entry = hashTable->entries[index];
    while (entry != NULL) {
        if (!strcmp(entry->key, key)) {
            // Update the used count of the hash table
            hashTable->used--;

            // Remove the entry from the linked list and update the next pointer
            prevEntry->next = entry->next;
            free(entry);

            return;
        }
        entry = entry->next;
    }

    // Handle not found
}

// Function to print the contents of the hash table and linked list
void printHashTable(DynamicHashTable* hashTable) {
    for (int i = 0; i < hashTable->size; i++) {
        HashEntry* entry = hashTable->entries[i];
        while (entry != NULL) {
            printf("Key: %s, Value: ", entry->key);
            NetworkInterfaceStatus* status = &entry->value;
            printf("%d, Status: %d, Last Error: %d\n", status->interfaceID, status->status, status->lastError);

            // Print the array of NFAPI_CRC_INDICATION_PDU_T structures
            for (int j = 0; j < entry->pduCount; j++) {
                printf("RX_UE_INFORMATION_TAG: %s, RNTI: %d, CRCFLAG: %x\n", entry->pduList[j].RX_UE_INFORMATION_TAG, entry->pduList[j].RNTI, entry->pduList[j].CRC_INDICATION_REL8_TAG);
            }

            // Move to the next entry in the linked list
            entry = entry->next;
        }
    }
}

int main() {
    DynamicHashTable hashTable;

    initNetworkInterfaceStatus(&hashTable);

    addSetting(&hashTable, "setting1", (NetworkInterfaceStatus){.interfaceID=1, .status=0, .lastError=2});
    addSetting(&hashTable, "setting2", (NetworkInterfaceStatus){.interfaceID=2, .status=1, .lastError=3});
    updateSetting(&hashTable, "setting1", (NetworkInterfaceStatus){.interfaceID=1, .status=0, .lastError=4});

