["Here is the C function for managing a dynamic hash table:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 1024
#define HASH_FUNCTION(x) ((x) % TABLE_SIZE)

typedef struct {
    char* key;
    int value;
} Settings;

Settings** settingsTable;
int settingsCount = 0;

void addSetting(char* key, int value) {
    if (settingsCount >= TABLE_SIZE) {
        // Reallocate the table when it's full
        settingsTable = realloc(settingsTable, (TABLE_SIZE * 2 + 1));
        TABLE_SIZE *= 2;
    }

    settingsTable[HASH_FUNCTION(settingsCount)] = malloc(sizeof(Settings));
    settingsTable[HASH_FUNCTION(settingsCount)]->key = key;
    settingsTable[HASH_FUNCTION(settingsCount)]->value = value;
    settingsCount++;
}

int getSetting(char* key) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (settingsTable[i] && !strcmp(settingsTable[i]->key, key)) {
            return settingsTable[i]->value;
        }
    }

    return -1;
}

void updateSetting(char* key, int value) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (settingsTable[i] && !strcmp(settingsTable[i]->key, key)) {
            settingsTable[i]->value = value;
            break;
        }
    }
}

void deleteSetting(char* key) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (settingsTable[i] && !strcmp(settingsTable[i]->key, key)) {
            free(settingsTable[i]);
            settingsTable[i] = NULL;
            break;
        }
    }

    // Rebalance the table if it's too sparse
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (!settingsTable[i]) {
            for (int j = i + 1; j < TABLE_SIZE; j++) {
                settingsTable[i] = settingsTable[j];
                j++;
            }
            break;
        }
    }
}

void freeSettings() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (settingsTable[i]) {
            free(settingsTable[i]);
        }
    }

    free(settingsTable);
}
