typedef struct {
    int version;
    char* key;
    void* value;
} ConfigSetting;

typedef struct {
    int size;
    ConfigSetting** table;
    int version_count;
} DynamicHashTable;

void initialize_hash_table(DynamicHashTable* hash_table) {
    hash_table->size = 16;
    hash_table->table = (ConfigSetting**)malloc(hash_table->size * sizeof(ConfigSetting*));
    for(int i=0; i<hash_table->size; i++) {
        hash_table->table[i] = NULL;
    }
    hash_table->version_count = 1;
}

void add_setting(DynamicHashTable* hash_table, char* key, void* value) {
    int index = key % hash_table->size;
    ConfigSetting* setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    setting->version = hash_table->version_count++;
    setting->key = (char*)malloc(strlen(key)+1);
    strcpy(setting->key, key);
    setting->value = value;
    if(hash_table->table[index] != NULL) {
        ConfigSetting* prev = hash_table->table[index];
        while(prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = setting;
    } else {
        hash_table->table[index] = setting;
    }
}

void update_setting(DynamicHashTable* hash_table, char* key, void* value) {
    int index = key % hash_table->size;
    ConfigSetting* current = hash_table->table[index];
    while(current != NULL) {
        if(strcmp(current->key, key) == 0) {
            current->value = value;
            return;
        }
        current = current->next;
    }
}

void delete_setting(DynamicHashTable* hash_table, char* key) {
    int index = key % hash_table->size;
    ConfigSetting* prev = NULL;
    ConfigSetting* current = hash_table->table[index];
    while(current != NULL) {
        if(strcmp(current->key, key) == 0) {
            if(prev == NULL) {
                hash_table->table[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->key);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void print_hash_table(DynamicHashTable* hash_table) {
    for(int i=0; i<hash_table->size; i++) {
        ConfigSetting* current = hash_table->table[i];
        while(current != NULL) {
            printf("Key: %s, Version: %d\n", current->key, current->version);
            current = current->next;
        }
    }
}

int main() {
    DynamicHashTable hash_table;
    initialize_hash_table(&hash_table);
    add_setting(&hash_table, " Setting1", 1);
    add_setting(&hash_table, "Setting2", 2);
    update_setting(&hash_table, "Setting1", 3);
    print_hash_table(&hash_table);
    return 0;
}
