#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int priority;
    void (*callback)(void *);
    void *data;
} Task;

typedef struct {
    Task *tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PriorityQueue;

PriorityQueue *pq_create(size_t capacity) {
    PriorityQueue *pq = (PriorityQueue *)malloc(sizeof(PriorityQueue));
    pq->capacity = capacity;
    pq->size = 0;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void pq_add(PriorityQueue *pq, Task task) {
    pthread_mutex_lock(&pq->lock);
    if (pq->size == pq->capacity) {
        // Reallocate the array with double capacity
        pq->tasks = realloc(pq->tasks, (pq->capacity *= 2) * sizeof(Task));
        pq->capacity *= 2;
    }
    pq->tasks[pq->size++] = task;
    pthread_mutex_unlock(&pq->lock);
}

Task *pq_next(PriorityQueue *pq) {
    Task *task = NULL;
    pthread_mutex_lock(&pq->lock);
    if (pq->size > 0) {
        // Find the task with the highest priority
        int i, maxPriority = -1;
        for (i = 0; i < pq->size; i++) {
            if (pq->tasks[i].priority > maxPriority) {
                task = &pq->tasks[i];
                maxPriority = pq->tasks[i].priority;
            }
        }
    }
    pthread_mutex_unlock(&pq->lock);
    return task;
}

void pq_update(PriorityQueue *pq, int index, Task task) {
    pthread_mutex_lock(&pq->lock);
    if (index >= 0 && index < pq->size) {
        // Update the priority and callback of the task
        pq->tasks[index].priority = task.priority;
        pq->tasks[index].callback = task.callback;
    }
    pthread_mutex_unlock(&pq->lock);
}

void pq_delete(PriorityQueue *pq, Task task) {
    pthread_mutex_lock(&pq->lock);
    if (pq->size > 0) {
        // Find and remove the task with matching data
        int i;
        for (i = 0; i < pq->size; i++) {
            if (task.data == pq->tasks[i].data) {
                // Shift elements to fill the gap
                memmove(&pq->tasks[i], &pq->tasks[i + 1], (pq->size - i - 1) * sizeof(Task));
                pq->size--;
                break;
            }
        }
    }
    pthread_mutex_unlock(&pq->lock);
}

void pq_free(PriorityQueue *pq) {
    free(pq->tasks);
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}
