        // Realocate memory when the array is full
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, (array->max_size * 2 + 1) * sizeof(LTE_Uplink_PDCP_PDU));
        array->max_size *= 2;
    }
    pthread_mutex_lock(&array->lock);
    array->pdus[array->size] = pdu;
    array->size++;
    array->num_added++;
    pthread_mutex_unlock(&array->lock);
