            return &array->pdus[i];
        }
    }
    return NULL;
}

void pdcPduArray_update_error_indication(PdcPduArray* array, int sequence_number, int error_indication) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequence_number == sequence_number) {
            array->pdus[i].error_indication = error_indication;
            array->num_updated++;
            return;
        }
    }
}

void pdcPduArray_calculate_cumulative_sdu_size(PdcPduArray* array, int* cumulative_sdu_size) {
    *cumulative_sdu_size = 0;
    for (int i = 0; i < array->size; i++) {
        *cumulative_sdu_size += array->pdus[i].sd_size;
    }
}

void pdcPduArray_reset(PdcPdcPArray* array) {
    pthread_mutex_lock(&array->lock);
    array->num_added = 0;
    array->num_updated = 0;
    pthread_mutex_unlock(&array->lock);
}
