// Function to initialize a new hash table with a given capacity and initial size
HashTable* init_hash_table(int capacity, int initial_size) {
    // Allocate memory for the hash table structure
    HashTable *ht = (HashTable*) malloc(sizeof(HashTable));

    ht->capacity = capacity;
    ht->size = initial_size;
    ht->table = (Setting**) calloc(initial_size, sizeof(Setting*));
    ht->max_version = 1;
    ht->current_version = 1;
    ht->last_update = time(NULL);

    return ht;
