#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a user
typedef struct {
    char username[20];
    char password[20];
} User;

// Define the global user database
User* users;
int num_users = 0;

// Function to add a new user
void add_user(char* username, char* password) {
    // Check if the username is already in use
    int found = 0;
    for (int i = 0; i < num_users; i++) {
        if (strcmp(users[i].username, username) == 0) {
            printf("Error: Username already exists.\n");
            return;
        }
    }

    // Add the new user
    User* new_user = malloc(sizeof(User));
    strcpy(new_user->username, username);
    strcpy(new_user->password, password);
    users = realloc(users, (num_users + 1) * sizeof(User));
    users[num_users++] = *new_user;
}

// Function to update an existing user
void update_user(char* username, char* new_password) {
    int found = 0;
    for (int i = 0; i < num_users; i++) {
        if (strcmp(users[i].username, username) == 0) {
            strcpy(users[i].password, new_password);
            found = 1;
            break;
        }
    }

    if (!found) {
        printf("Error: User not found.\n");
    }
}

// Function to delete a user
void delete_user(char* username) {
    int found = 0;
    for (int i = 0; i < num_users; i++) {
        if (strcmp(users[i].username, username) == 0) {
            for (int j = i; j < num_users - 1; j++) {
                users[j] = users[j + 1];
            }
            num_users--;
            found = 1;
            break;
        }
    }

    if (!found) {
        printf("Error: User not found.\n");
    }
}

// Function to list all users
void list_users() {
    for (int i = 0; i < num_users; i++) {
        printf("%s %s\n", users[i].username, users[i].password);
    }
}

