    // Parse command line options
    int help = 0;
    char* username = NULL;
    int add = 0;
    int update = 0;
    int delete_user = 0;
    int list = 0;
    FILE* output_file = NULL;
    int verbose = 0;
    int parallel = 1;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            help = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            username = argv[++i];
        } else if (strcmp(argv[i], "-a") == 0) {
            add = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            update = 1;
        } else if (strcmp(argv[i], "-d") == 0) {
            delete_user = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            list = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = fopen(argv[++i], "w");
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], "-p") == 0) {
            parallel = atoi(argv[++i]);
        }
    }

    // Handle command line options
    if (help) {
        printf("Usage: user_manager [options]\n");
        printf("Options:\n");
        printf("-h, --help       Display this help message\n");
        printf("-u username     Specify a username to add, update, or delete a user\n");
        printf("-a             Add a new user to the database\n");
        printf("-u             Update an existing user's information\n");
