    int priority;
    double estimated_completion_time;
} Task;

typedef struct {
    int connection_id;
    time_t last_seen_timestamp;
    size_t packet_queue_size;
    int** sequence_numbers;
} TCPSession;

Task* handleDynamicEntitiesAndSessionManagement(int max_entities) {
    Task* tasks = (Task*)calloc(max_entities, sizeof(Task));
    TCPSession* sessions = (TCPSession*)calloc(max_entities, sizeof(TCPSession));

    for (int i = 0; i < max_entities; i++) {
        EntityType type;
        if ((type = random() % 2) == TASK) {
            tasks[i].name = (char*)malloc(strlen("Task ") + 1);
            strcpy(tasks[i].name, "Task ");
            tasks[i].priority = rand() % 5 + 1;
            tasks[i].estimated_completion_time = rand_gaussian(10.0, 2.0);
        } else {
            sessions[i].connection_id = i;
            sessions[i].last_seen_timestamp = time(NULL);
            sessions[i].packet_queue_size = 0;
            sessions[i].sequence_numbers = (int**)calloc(max_entities, sizeof(int*));
        }
    }

    return tasks;
}

void freeDynamicEntitiesAndSessionManagement(Task* tasks, TCPSession* sessions, int max_entities) {
    for (int i = 0; i < max_entities; i++) {
        if (tasks[i].name)
            free(tasks[i].name);
        if (sessions[i].sequence_numbers)
            for (size_t j = 0; j < sessions[i].packet_queue_size; j++)
                free(sessions[i].sequence_numbers[j]);
        free(sessions[i].sequence_numbers);
    }

    free(tasks);
    free(sessions);
}

int rand_gaussian(double mean, double stddev) {
    static double last_normal;
    static int is_ready;

    if (!is_ready) {
        static int seed = (int)time(NULL);
        srand(seed);
        is_ready = 1;
    }

    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;

    double rand_std = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);

    double result = mean + rand_std * stddev;

    return (int)result;
}
