#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int modulationScheme;
    int bandwidth;
} LTE_PHY_FRAME_CONFIG_S;

int configurations = 0;
LTE_PHY_FRAME_CONFIG_S* configArray = NULL;

void addConfig(int modulationScheme, int bandwidth) {
    if (bandwidth <= 0 || modulationScheme < 1 || modulationScheme > 3) {
        printf("Invalid input: Modulation scheme must be QPSK(1), 16QAM(2), or 64QAM(3)\n");
        return;
    }

    for (int i = 0; i < configurations; i++) {
        if (configArray[i].modulationScheme == modulationScheme && configArray[i].bandwidth > bandwidth) {
            printf("Error: Bandwidth overlap detected. Please update the existing configuration.\n");
            return;
        }
    }

    LTE_PHY_FRAME_CONFIG_S* newConfig = realloc(configArray, sizeof(LTE_PHY_FRAME_CONFIG_S) * (configurations + 1));
    if (!newConfig) {
        printf("Memory allocation failed\n");
        return;
    }

    configArray = newConfig;
    configArray[configurations].modulationScheme = modulationScheme;
    configArray[configurations].bandwidth = bandwidth;
    configurations++;
}

void retrieveConfigs() {
    for (int i = 0; i < configurations; i++) {
        printf("Modulation scheme: %d, Bandwidth: %d\n", configArray[i].modulationScheme, configArray[i].bandwidth);
    }
}

int main() {
    addConfig(1, 10); // Adding QPSK configuration with bandwidth 10
    addConfig(2, 20); // Adding 16QAM configuration with bandwidth 20
    addConfig(3, 15); // Adding 64QAM configuration with bandwidth 15

    retrieveConfigs(); // Retrieving all stored configurations

    return 0;
}

