#define MAX_TASKS 10000
#define MAX_PDU_SEQ 65536

typedef struct {
    char* name;
    int priority;
    double estimatedCompletionTime;
} Task;

typedef struct {
    int sequenceNumber;
    // add more fields as needed
} LTE_Uplink_PDCP_PDU;

void manageDynamicTasksAndModifyFile() {
    srand(time(NULL));

    Task* tasks = (Task*)malloc(MAX_TASKS * sizeof(Task));
    if (!tasks) {
        printf("Error: unable to allocate memory for tasks.\n");
        return;
    }

    LTE_Uplink_PDCP_PDU* pdus = (LTE_Uplink_PDCP_PDU*)malloc(MAX_PDU_SEQ * sizeof(LTE_Uplink_PDCP_PDU));
    if (!pdus) {
        printf("Error: unable to allocate memory for PDUs.\n");
        free(tasks);
        return;
    }

    // initialize tasks and pdus
    int i = 0;
    while (i < MAX_TASKS) {
        Task task;
        task.name = (char*)malloc(strlen(getRandomName()) + 1);
        strcpy(task.name, getRandomName());
        task.priority = rand() % 5 + 1;
        task.estimatedCompletionTime = normrand(10.0, 2.0);

        tasks[i] = task;

        LTE_Uplink_PDCP_PDU pdu;
        pdu.sequenceNumber = i + 1; // assign unique sequence number
        pdus[i] = pdu;

        i++;
    }

    // save tasks and pdus to file
    FILE* file = fopen("tasks.txt", "w");
    if (!file) {
        printf("Error: unable to open file for writing.\n");
        free(tasks);
        free(pdus);
        return;
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        fprintf(file, "%s %d %.2f\n", tasks[i].name, tasks[i].priority, tasks[i].estimatedCompletionTime);
        // append pdus to file
        fwrite(&pdus[i], sizeof(LTE_Uplink_PDCP_PDU), 1, file);
    }

    fclose(file);

    free(tasks);
    free(pdus);
}

// helper function to generate a random name
char* getRandomName() {
    static char buffer[256];
    FILE* f = fopen("/usr/share/dict", "r");
    if (!f) {
        printf("Error: unable to open dictionary file.\n");
        return NULL;
    }

    fgets(buffer, sizeof(buffer), f);
    fclose(f);

    // modify buffer to meet desired naming convention
    // ...

    return buffer;
}

// helper function to generate a random number from a normal distribution
double normrand(double mean, double stddev) {
    static int seed = 0;
    if (!seed) {
        seed = (int)time(NULL);
    }

    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;

    double rsq = u1 * u2;
    double randomNormalVariate = sqrt(-2.0 * log(rsq)) * cos(2.0 * M_PI * u1);
    return mean + stddev * randomNormalVariate;
}

int main() {
    manageDynamicTasksAndModifyFile();
    return 0;
}
