    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    uint32_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indications(int n, FILE* log_file) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_list = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    uint32_t total_crc_indications = 0;
    uint8_t rnti_range_min = 1;
    uint8_t rnti_range_max = 65535;

    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_pdu) {
            perror("Error allocating memory");
            fprintf(log_file, "Memory allocation failed\n");
            return -1;
        }

        pthread_mutex_lock(&mutex);
        crc_pdu->rx_ue_info_tag.rnti = (uint16_t)(rand() % (rnti_range_max - rnti_range_min + 1)) + rnti_range_min;
        if (!(crc_pdu->rx_ue_info_tag.rnti >= rnti_range_min && crc_pdu->rx_ue_info_tag.rnti <= rnti_range_max)) {
            free(crc_pdu);
            pthread_mutex_unlock(&mutex);
            fprintf(log_file, "Invalid RNTI value: %u\n", crc_pdu->rx_ue_info_tag.rnti);
            return -1;
        }

        crc_pdu->timestamp = (uint8_t)(time(NULL) % 256);
        crc_pdu->crc_indication_rel8_tag = (uint32_t)i;

        if (atomic_fetch_add(&total_crc_indications, 1) > 0xFFFFFFFFFFFFF)
            return -1;

        pthread_mutex_unlock(&mutex);
    }

    free(crc_pdu_list);
    return i;
}
