} LogEntry;

LogEntry** processAndPersistLogData(int maxEntries) {
    // Initialize the log entries array
    LogEntry** logEntries = (LogEntry**)malloc(maxEntries * sizeof(LogEntry*));

    // Initialize the global counter for unique IDs
    uint64_t uniqueIdCounter = 0;

    // Initialize the current system time for timestamp generation
    time_t currentTime = time(NULL);

    for (int i = 0; i < maxEntries; i++) {
        LogEntry* logEntry = (LogEntry*)malloc(sizeof(LogEntry));

        // Generate a random severity level between 0 and 5
        int severityLevel = rand() % 6;

        // Derive the timestamp from the current system time
        char* timestamp = ctime(&currentTime);

        // Generate a unique identifier using the global counter
        uint64_t uniqueId = uniqueIdCounter++;

        logEntry->timestamp = timestamp;
        logEntry->message = "Example message";
        logEntry->severityLevel = severityLevel;
        logEntry->uniqueId = uniqueId;

        logEntries[i] = logEntry;
    }

    return logEntries;
}

int main() {
    int maxEntries = 10; // Example value
    LogEntry** logEntries = processAndPersistLogData(maxEntries);

    for (int i = 0; i < maxEntries; i++) {
        printf("Timestamp: %s, Message: %s, Severity Level: %d, Unique ID: %llu\n",
               logEntries[i]->timestamp, logEntries[i]->message, logEntries[i]->severityLevel, logEntries[i]->uniqueId);
    }

    // Free allocated memory
    for (int i = 0; i < maxEntries; i++) {
        free(logEntries[i]);
    }
    free(logEntries);

    return 0;
}
