typedef struct {
    char* name;
    int priority;
    double estimated_completion_time;
    size_t task_id;
    struct timespec timestamp;
} Task;

void manageDynamicTasksAndModifyFile() {
    // Initialize dynamic array
    Task** tasks = NULL;
    size_t num_tasks = 0;

    // Allocate initial memory for the tasks array
    void* temp = malloc(sizeof(Task) * 10);
    if (!temp) {
        printf("Memory allocation failed.\n");
        return;
    }

    tasks = (Task**)temp;

    // Initialize each task with a randomly generated priority level, estimated completion time, and timestamp
    for (size_t i = 0; i < 10; i++) {
        Task* new_task = (Task*)malloc(sizeof(Task));

        // Generate random priority level between 1 and 5
        new_task->priority = rand() % 4 + 1;

        // Generate estimated completion time based on a normal distribution with mean of 10 hours and standard deviation of 2 hours
        new_task->estimated_completion_time = (double)rand() / (RAND_MAX / 20.0);

        // Initialize task ID
        new_task->task_id = i;

        // Set timestamp to current system time
        clock_gettime(CLOCK_REALTIME, &new_task->timestamp);

        tasks[i] = new_task;
    }

    num_tasks = 10;

    // Manage memory allocation for the array dynamically
    while (1) {
        size_t new_num_tasks = num_tasks + 10;

        void* temp2 = realloc(tasks, sizeof(Task) * new_num_tasks);

        if (!temp2) {
            printf("Memory reallocation failed.\n");
            break;
        }

        tasks = (Task**)temp2;
        num_tasks = new_num_tasks;
    }

    // Manage memory deallocation for the array dynamically
    while (num_tasks > 0) {
        size_t i = 0;

        for (; i < num_tasks; i++) {
            free(tasks[i]);
        }

        free(tasks);
        break;
    }
}
