    EVP_PKEY *pkey = EVP_PKEY_new_raw_key(AES_KEY_SIZE, 1);
    if (!EVP_PKEY_set_raw_public_key(pkey, key)) {
        return NULL;
    }
    EVP_PKEY_free(pkey);

    // Initialize and set the IV
    unsigned char *ivPointer = iv;
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        iv[i] = i % 256;
    }

    // Initialize the cipher
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, ivPointer)) {
        return NULL;
    }
    EVP_CIPHER_CTX_free(ctx);

    // Get the pointer to the cipher context
    result = (unsigned char *)EVP_CIPHER_CTX_ctrl(NULL, 0x1001);
    if (!result) {
        return NULL;
    }

    return result;
}

void cleanupEncryptCipher(void *cipherContext) {
    EVP_CIPHER_CTX_free(cipherContext);
}
