NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int n, const char* hostname) {
    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        indications[i].rnti = rand() % 100000;

        // Perform DNS resolution
        struct addrinfo hints, *res;
        int s;
        char* result;

        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        hints.ai_protocol = IPPROTO_TCP;

        s = getaddrinfo(hostname, NULL, &hints, &res);

        if (s != 0) {
            // Handle DNS resolution error
            free(indications);
            return NULL;
        }

        result = inet_ntop(AF_INET, &((struct sockaddr_in*)res->ai_addr)->sin_addr, NULL);

        sprintf(indications[i].rx_ue_info_tag, "RX_UE_INFO_TAG_%s", result);

        // Perform external data retrieval
        int cell_id = get_cell_data(hostname, res);

        if (cell_id == -1) {
