int lte_uplink_pdcps_add(LTE_Uplink_PDCP_PDU **array, size_t *size, LTE_Uplink_PDCP_PDU* pdu) {
    if (*size == 0) {
        *array = malloc(sizeof(LTE_Uplink_PDCP_PDU *));
        if (!*array) return -1;
        *size = 1;
    } else {
        size_t i;
        for (i = 0; i < *size; i++) {
            if (((*array)[i]->sn + 1) == pdu->sn) {
                memmove(&((*array)[i]), &((*array)[i+1]), (*size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU *));
                (*array)[--(*size)] = *pdu;
                return 0;
            }
        }
    }
    if (!realloc(array, sizeof(LTE_Uplink_PDCP_PDU *) * ((*size + 2)))) {
        free(*array);
        *size = 0;
        return -1;
    }
    (*array)[*size++] = pdu;
    return 0;
}

LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get(LTE_Uplink_PDCP_PDU **array, size_t size, int sn) {
    for (int i = 0; i < size; i++) {
        if (((*array)[i]->sn) == sn)
            return &((*array)[i]);
    }
    return NULL;
}

void lte_uplink_pdcps_update_error(LTE_Uplink_PDCP_PDU **array, size_t size, int sn, int error_indication) {
    for (int i = 0; i < size; i++) {
        if (((*array)[i]->sn) == sn)
            (*array)[i]->error_indication = error_indication;
    }
}

void lte_uplink_pdcps_remove(LTE_Uplink_PDCP_PDU **array, size_t *size) {
    for (int i = 0; i < *size - 1; i++) {
        (*array)[i] = (*array)[++i];
    }
    free((*array));
    *size = 0;
}

void lte_uplink_pdcps_compact(LTE_Uplink_PDCP_PDU **array, size_t *size) {
    if (*size < 2)
        return;

    int i = 0;
    while (i < *size - 1) {
        if ((*array)[i]->sn + 1 == (*array)[i+1]->sn) {
            free((*array++));
            (*size)--;
        } else
            i++;
    }
}
