NR_Downlink_PDCP_PDU_Array* nr_downlink_pdcplib_init() {
    NR_Downlink_PDCP_PDU_Array* array = malloc(sizeof(NR_Downlink_PDCP_PDU_Array));
    if (!array) return NULL;

    array->pdus = NULL;
    array->capacity = 1;
    array->size = 0;

    return array;
}

void nr_downlink_pdcplib_add_pdu(NR_Downlink_PDCP_PDU_Array* array, NR_Downlink_PDCP_PDU pdu) {
    if (!array || !pdu) return;

    // Grow the array if necessary
    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * NR_DOWNLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR;
        array->pdus = realloc(array->pdus, sizeof(NR_Downlink_PDCP_PDU) * newCapacity);
        array->capacity = newCapacity;
    }

    // Add the PDU to the array
    array->pdus[array->size++] = pdu;
}

NR_Downlink_PDCP_PDU* nr_downlink_pdcplib_get_pdu_by_sn(NR_Downlink_PDCP_PDU_Array* array, uint32_t sequenceNumber) {
    if (!array) return NULL;

    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            return &array->pdus[i];
        }
    }

    return NULL;
}

void nr_downlink_pdcplib_update_error_indication(NR_Downlink_PDCP_PDU_Array* array, uint32_t sequenceNumber, bool errorIndication) {
    if (!array) return;

    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            array->pdus[i].errorIndication = errorIndication;
            return;
        }
    }
}

void nr_downlink_pdcplib_remove_pdu(NR_Downlink_PDCP_PDU_Array* array, uint32_t sequenceNumber) {
    if (!array) return;

    NR_Downlink_PDCP_PDU* pdu = NULL;
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            pdu = &array->pdus[i];
            break;
        }
    }

    if (!pdu) return;

    // Shift the remaining PDUs to compact the array
    memmove(&array->pdus[0], &array->pdus[pdu - array->pdus], (array->size - 1) * sizeof(NR_Downlink_PDCP_PDU));
    array->size--;

    if (array->size < array->capacity / NR_DOWNLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR) {
        // Re-allocate the array with a smaller capacity
        array->pdus = realloc(array->pdus, sizeof(NR_Downlink_PDCP_PDU) * array->capacity / NR_DOWNLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR);
        array->capacity /= NR_DOWNLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR;
    }
}

void nr_downlink_pdcplib_monitor_health(NR_Downlink_PDCP_PDU_Array* array, bool* isHealthy) {
    if (!array || !isHealthy) return;

    *isHealthy = true; // Assume the array is healthy initially

    // Monitor for potential issues
    for (int i = 0; i < array->size; i++) {
        NR_Downlink_PDCP_PDU pdu = array->pdus[i];
        if (!pdu.sequenceNumber || pdu.sduSize > NR_DOWNLINK_PDCP_PDU_MAX_SIZE) {
            *isHealthy = false;
            break;
        }
    }

    // Trigger alerts if necessary
    if (!*isHealthy) {
        // TO DO: Implement alert mechanism
    }
}

void nr_downlink_pdcplib_deinit(NR_Downlink_PDCP_PDU_Array* array) {
    if (array) {
        free(array->pdus);
        free(array);
    }
}
