TCP_Session **tcp_sessions = NULL;
int tcp_session_count = 0;
pthread_mutex_t tcp_session_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new TCP session
void add_tcp_session(int session_id, char *ip_address) {
    TCP_Session *new_session = (TCP_Session *)malloc(sizeof(TCP_Session));
    if (!new_session) return; // Handle out-of-memory condition

    new_session->session_id = session_id;
    strcpy(new_session->ip_address, ip_address);
    new_session->bytes_sent = 0;
    new_session->bytes_received = 0;

    pthread_mutex_lock(&tcp_session_lock);
    if (tcp_sessions) {
        tcp_sessions = (TCP_Session **)realloc(tcp_sessions, (tcp_session_count + 1) * sizeof(TCP_Session *));
        if (!tcp_sessions) return; // Handle out-of-memory condition
    } else {
        tcp_sessions = (TCP_Session **)malloc(sizeof(TCP_Session *));
        if (!tcp_sessions) return; // Handle out-of-memory condition
    }
    tcp_sessions[tcp_session_count] = new_session;
    tcp_session_count++;
    pthread_mutex_unlock(&tcp_session_lock);
}

// Function to retrieve a specific TCP session by its ID
TCP_Session *get_tcp_session(int session_id) {
    for (int i = 0; i < tcp_session_count; i++) {
        if (tcp_sessions[i]->session_id == session_id) return tcp_sessions[i];
    }
    return NULL;
}

// Function to update session statistics and notify external monitoring service
void update_tcp_session_stats(int session_id, int bytes_sent, int bytes_received) {
