    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // or handle error
    }

    int i;
    for (i = 0; i < N; i++) {
        array[i].rx_ue_info = ...; // initialize RX_UE_INFORMATION_TAG
        array[i].rnti = states[i % num_states]; // cycle through available RNTIs
        array[i].crc_indication_rel8_tag = ...; // initialize CRC_INDICATION_REL8_TAG
        array[i].crcflag = rand() % 2 ? 1 : 0; // probabilistically set CRCFLAG to 0 or 1
    }

    int* state_list = malloc((num_states + 1) * sizeof(int));
    if (!state_list) {
        free(array);
        return NULL; // or handle error
    }

    for (i = 0; i < num_states; i++) {
        state_list[i] = states[i];
    }
    state_list[num_states] = last_state;

    struct FSA* new_fsa = malloc(sizeof(struct FSA));
    if (!new_fsa) {
        free(array);
        free(state_list);
        return NULL; // or handle error
