class SandeshClient {
public:
    SandeshClient(asio::io_service& io_service, int max_concurrent_requests)
        : io_service_(io_service), thread_pool_(max_concurrent_requests),
          priority_queue_(new std::priority_queue<Request*, std::vector<Request*>>()) {}

    void start() {
        for (int i = 0; i < 50; ++i) {
            asio::io_service::work work(io_service_);
            io_service_.run();
        }
    }

    void send_request(Request* request) {
