        if ((rand() % 100) > 75) {
            request->success = false;
        } else {
            request->success = true;
        }

        // Add request to the priority queue
        priority_queue_->push(request);

        // Start the thread pool
        thread_pool_.start();
    }

    void stop() {
        io_service_.stop();
    }

private:
    class ThreadPool {
    public:
        ThreadPool(size_t num_threads) : stopped_(false), threads_(num_threads) {}

        template <typename Function>
        void start(const Function& f) {
            for (size_t i = 0; i < threads_; ++i) {
                threads_.emplace_back([this, &f]() mutable {
                    while (!stopped_) {
                        if (priority_queue_->empty()) {
                            std::this_thread::sleep_for(std::chrono::milliseconds(1));
                        } else {
                            Request* request = priority_queue_->top();
                            priority_queue_->pop();

                            // Process the request
                            f(request);

                            if (!request->success) {
                                // Log error and retry up to three times with exponentially increasing delays
                                int attempts = 0;
                                while (!request->success && attempts < 3) {
                                    std::this_thread::sleep_for(std::chrono::milliseconds(
                                        static_cast<unsigned long>(pow(2, attempts))));
                                    attempt_request(request);
                                    ++attempts;
                                }
                            }
                        }
                    }
                });
            }

        // Start the thread pool
        void start() {
            for (auto& thread : threads_) {
                thread.join();
            }
        }

    private:
        bool stopped_;
        std::vector<std::thread> threads_;
        std::priority_queue<Request*, std::vector<Request*>> priority_queue_;
    };

    // Implement the FindVmUuidFromMetadataIp function
