// Function to initialize and manage a dynamic array of TCP_Connector structures
TCP_Connector *tcp_connectors = NULL;
int num_connections = 0;
void *mutex = PTHREAD_MUTEX_INITIALIZER; // For thread-safe operations

// Function to add a new connection
void add_connection(int id, time_t last_active, int status) {
    TCP_Connector *new_conn = (TCP_Connector *)malloc(sizeof(TCP_Connector));
    if (!new_conn) {
        perror("Memory allocation failed");
        return;
    }
    new_conn->id = id;
    new_conn->last_active = last_active;
    new_conn->status = status;

    pthread_mutex_lock(mutex);
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Maximum connections reached!\n");
        return;
    }
    tcp_connectors[num_connections++] = *new_conn;
    pthread_mutex_unlock(mutex);

    free(new_conn);
}

// Function to retrieve a specific connection by its ID
TCP_Connector *get_connection(int id) {
    for (int i = 0; i < num_connections; i++) {
        if (tcp_connectors[i].id == id)
            return &tcp_connectors[i];
    }
    printf("Connection not found!\n");
    return NULL;
}

// Function to update the status of a given connection
void update_connection_status(int id, int new_status) {
    TCP_Connector *conn = get_connection(id);
    if (conn) {
        conn->status = new_status;
    } else {
        printf("Connection not found!\n");
    }
}

// Function to serialize the array to disk
void serialize_to_disk() {
    FILE *fp = fopen("tcp_connectors.bin", "wb");
    fwrite(&num_connections, sizeof(int), 1, fp);
    for (int i = 0; i < num_connections; i++) {
        fwrite(&tcp_connectors[i], sizeof(TCP_Connector), 1, fp);
    }
    fclose(fp);
}

// Function to deserialize the array from disk
void deserialize_from_disk() {
    FILE *fp = fopen("tcp_connectors.bin", "rb");
    fread(&num_connections, sizeof(int), 1, fp);
    tcp_connectors = (TCP_Connector *)malloc(num_connections * sizeof(TCP_Connector));
    for (int i = 0; i < num_connections; i++) {
        fread(&tcp_connectors[i], sizeof(TCP_Connector), 1, fp);
    }
    fclose(fp);
}

// Function to log detailed debug information
void log_debug_info(int id, int status) {
    time_t now = time(NULL);
    printf("Connection %d: Established/terminated at timestamp %ld with status %d\n", id, now, status);
}

// Function to perform DNS resolution for a given hostname
char *perform_dns_resolution(char *hostname) {
