void updateStatus(TCP_Connector** array, int id, char* status);
int serializeConnections(TCP_Connector** array, FILE* file);
int deserializeConnections(TCP_Connector*** array, FILE* file);

// Function to add new connection
TCP_Connector* addConnection(TCP_Connector** array, int id) {
    // Allocate memory for the new connection
    TCP_Connector* newConn = (TCP_Connector*) malloc(sizeof(TCP_Connector));

    if (newConn == NULL) {
        printf("Out of memory\n");
        return NULL;
    }

    newConn->id = id;
    time_t timestamp = time(NULL);
    newConn->timestamp = timestamp;
    strcpy(newConn->status, "open");

    // Insert the new connection at the end of the array
    *array = (TCP_Connector**) realloc(*array, sizeof(TCP_Connector*) * (++(*array) ? 1 : 0));

    if (*array == NULL) {
        printf("Out of memory\n");
        free(newConn);
        return NULL;
    }

    (*array)[(*array)-1] = newConn;

    return newConn;
}

// Function to retrieve a specific connection
TCP_Connector* getConnection(TCP_Connector** array, int id) {
    for (int i = 0; i < *array - 1; ++i) {
        if ((*array)[i]->id == id) {
            return (*array)[i];
        }
    }

    return NULL;
}

// Function to update the status of a connection
void updateStatus(TCP_Connector** array, int id, char* status) {
    for (int i = 0; i < *array - 1; ++i) {
        if ((*array)[i]->id == id) {
            strcpy((*array)[i]->status, status);
            return;
        }
    }
}

// Function to serialize the connections
int serializeConnections(TCP_Connector** array, FILE* file) {
    // Serialize each connection in the array
    for (int i = 0; i < *array - 1; ++i) {
        fwrite(&((*array)[i]->id), sizeof(int), 1, file);
        fwrite(&((*array)[i]->timestamp), sizeof(time_t), 1, file);
        fwrite((*array)[i]->status, strlen((*array)[i]->status) + 1, 1, file);
    }

    return 0;
}

// Function to deserialize the connections
int deserializeConnections(TCP_Connector*** array, FILE* file) {
    // Read the number of connections from the file
    int numConn = 0;
    fread(&numConn, sizeof(int), 1, file);

    // Allocate memory for the new connection array and read each connection
    *array = (TCP_Connector**) malloc(sizeof(TCP_Connector*) * numConn);
    for (int i = 0; i < numConn; ++i) {
        (*array)[i] = (TCP_Connector*) malloc(sizeof(TCP_Connector));

        if ((*array)[i] == NULL) {
            printf("Out of memory\n");
            return -1;
        }

        fread(&((*array)[i]->id), sizeof(int), 1, file);
        fread(&((*array)[i]->timestamp), sizeof(time_t), 1, file);
        fgets((*array)[i]->status, strlen((*array)[i]->status) + 1, file);

        // Remove the newline character from the status string
        (*array)[i]->status[strcspn((*array)[i]->status, "\n")] = '\0';
    }

    return 0;
}

int main() {
    TCP_Connector* array = NULL;

    // Add some connections to the array
    for (int i = 0; i < 5; ++i) {
        addConnection(&array, i);
    }

    // Retrieve a specific connection and update its status
    TCP_Connector* conn = getConnection(array, 1);
    if (conn != NULL) {
        updateStatus(&array, 1, "closed");
    }

    // Serialize the connections to a file
    FILE* file = fopen("connections.txt", "wb");
    serializeConnections(&array, file);

    // Close the file and deallocate memory
    fclose(file);
    for (int i = 0; i < array - 1; ++i) {
        free(array[i]);
    }
    free(array);

    return 0;
}

