// Define a structure to hold the dynamic array and its metadata
typedef struct {
    NFAPI_RRC_UE_CONTEXT_T* contexts;
    int size;
    int capacity;
} RRCUEContextArray;

// Function to manage the dynamic array of NFAPI_RRC_UE_CONTEXT_T structures
void rrc_ue_context_array_init(RRCUEContextArray* arr, int initial_capacity) {
    arr->contexts = (NFAPI_RRC_UE_CONTEXT_T*)malloc(initial_capacity * sizeof(NFAPI_RRC_UE_CONTEXT_T));
    arr->size = 0;
    arr->capacity = initial_capacity;
}

// Function to add a new NFAPI_RRC_UE_CONTEXT_T instance to the array
void rrc_ue_context_array_add(RRCUEContextArray* arr, NFAPI_RRC_UE_CONTEXT_T* context) {
    if (arr->size >= arr->capacity) {
        // Resize the array if it's full
        int new_capacity = arr->capacity * 2;
        arr->contexts = (NFAPI_RRC_UE_CONTEXT_T*)realloc(arr->contexts, new_capacity * sizeof(NFAPI_RRC_UE_CONTEXT_T));
        arr->capacity = new_capacity;
    }
    arr->contexts[arr->size] = context;
    arr->size++;
}

// Function to remove a NFAPI_RRC_UE_CONTEXT_T instance from the array
void rrc_ue_context_array_remove(RRCUEContextArray* arr, int index) {
    if (index >= 0 && index < arr->size) {
        // Shift all subsequent elements down by one position
        for (int i = index; i < arr->size - 1; i++) {
            arr->contexts[i] = arr->contexts[i + 1];
        }
        arr->size--;
    }
}

// Function to free all allocated resources when the array is no longer needed
void rrc_ue_context_array_free(RRCUEContextArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        // Free each dynamically allocated RRU_RX_UE_DCI_INFO structure
        if (arr->contexts[i]->rru_rx_ue_dci_info != NULL) {
            free(arr->contexts[i]->rru_rx_ue_dci_info);
        }
    }
    free(arr->contexts);
}

// Example usage:
int main() {
    RRCUEContextArray arr;
    rrc_ue_context_array_init(&arr, 5);

    NFAPI_RRC_UE_CONTEXT_T* context1 = (NFAPI_RRC_UE_CONTEXT_T*)malloc(sizeof(NFAPI_RRC_UE_CONTEXT_T));
    // Initialize context1...

    NFAPI_RRC_UE_CONTEXT_T* context2 = (NFAPI_RRC_UE_CONTEXT_T*)malloc(sizeof(NFAPI_RRC_UE_CONTEXT_T));
    // Initialize context2...

    rrc_ue_context_array_add(&arr, context1);
    rrc_ue_context_array_add(&arr, context2);

    // ...add more contexts as needed...

    // Remove a context
    rrc_ue_context_array_remove(&arr, 0);

    // Free all resources when done
    rrc_ue_context_array_free(&arr);

    return 0;
}
