// Helper function to simulate Gaussian distribution
double rand_gaussian(double mean, double std_dev) {
    static double prev_rand = 0.0;
    static int initialized = 0;

    if (!initialized) {
        srandom(time(NULL));
        initialized = 1;
    }

    double u1 = (double)random() / RAND_MAX;
    double u2 = (double)random() / RAND_MAX;

    double rand_var = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
    double result = mean + std_dev * rand_var;

    return result;
}

// Helper function to simulate network connectivity issues
int simulate_network_connectivity_issues() {
    // Simulate random network connectivity issues with exponential backoff
    int retries = 0;
    while (retries < 3) {
        if (!network_connection_available()) {
            // Network connection unavailable, retry after exponential backoff
            sleep(pow(2, retries));
            retries++;
        } else {
            return 1; // Connection available, exit loop
        }
    }
    return 0; // Maximum retries exceeded, exit loop
}

// Helper function to simulate network availability
int network_connection_available() {
    // Simulate random network availability
    if (rand() % 2) {
        return 1; // Network connection available
    } else {
        return 0; // Network connection unavailable
    }
}
