#include <stdlib.h>
#include <stdio.h>

// Define the LTE_Uplink_PDCP_PDU structure
typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

// Function to initialize and manage a dynamic array of LTE_Uplink_PDCP_PDU structures
LTE_Uplink_PDCP_PDU** lte_pdcps_array_init(size_t initial_capacity) {
    size_t i;
    LTE_Uplink_PDCP_PDU** pdcps_array = (LTE_Uplink_PDCP_PDU**)malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU*));
    if (!pdcps_array) return NULL;

    for (i = 0; i < initial_capacity; i++) {
        pdcps_array[i] = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        if (!pdcps_array[i]) {
            // Handle out-of-memory condition
            for (size_t j = 0; j < i; j++)
                free(pdcps_array[j]);
            free(pdcps_array);
            return NULL;
        }
    }

    return pdcps_array;
}

// Function to add a new PDU to the dynamic array
int lte_pdcps_array_add(LTE_Uplink_PDCP_PDU** pdcps_array, size_t* capacity, LTE_Uplink_PDCP_PDU* pdu) {
    if (*capacity == 0) return -1; // Array is full

    if (pdu->SN >= *capacity) {
        // Reallocate and shift existing PDUs
        *capacity *= 2;
        LTE_Uplink_PDCP_PDU** new_array = lte_pdcps_array_init(*capacity);
        if (!new_array) return -1; // Out-of-memory condition

        for (size_t i = 0; i < *capacity / 2; i++) {
            new_array[i] = pdcps_array[i];
            free(pdcps_array[i]);
        }

        free(pdcps_array);
        pdcps_array = new_array;
    }

    pdcps_array[*capacity - 1] = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!pdcps_array[(*capacity) - 1]) return -1; // Out-of-memory condition
    *capacity += 1;

    pdcps_array[*capacity - 2] = pdu;
    return *capacity - 1;
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* lte_pdcps_array_get(LTE_Uplink_PDCP_PDU** pdcps_array, size_t capacity, int SN) {
    for (size_t i = 0; i < capacity; i++) {
        if (pdcps_array[i]->SN == SN)
            return pdcps_array[i];
    }
    return NULL;
}

// Function to update the error indication for a given sequence number
int lte_pdcps_array_update_error(LTE_Uplink_PDCP_PDU** pdcps_array, size_t capacity, int SN) {
    for (size_t i = 0; i < capacity; i++) {
        if (pdcps_array[i]->SN == SN) {
            pdcps_array[i]->error_indication = 1;
            return 0;
        }
    }
    return -1;
}

// Function to remove a PDU from the dynamic array based on its sequence number
int lte_pdcps_array_remove(LTE_Uplink_PDCP_PDU** pdcps_array, size_t capacity, int SN) {
    for (size_t i = 0; i < capacity; i++) {
        if (pdcps_array[i]->SN == SN) {
            free(pdcps_array[i]);
            memmove(&pdcps_array[i], &pdcps_array[i + 1], (capacity - i - 1) * sizeof(LTE_Uplink_PDCP_PDU*));
            return capacity - 1;
        }
    }
    return capacity; // PDU not found
}

// Function to free the dynamic array and its contents
void lte_pdcps_array_free(LTE_Uplink_PDCP_PDU** pdcps_array, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        free(pdcps_array[i]);
    }
    free(pdcps_array);
}
