#define MAX_CONTEXTS 10

typedef struct {
    int rrc_ue_id;
    int cell_id;
    void* lte_ccch_message_config; // dynamically allocated memory
} LTE_RRC_UE_CONTEXT;

void initLTERRCUETable(int** table, size_t* tableSize) {
    *table = (int*)malloc(MAX_CONTEXTS * sizeof(LTE_RRC_UE_CONTEXT));
    if (*table == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    *tableSize = MAX_CONTEXTS;

    // Initialize each context
    for (size_t i = 0; i < *tableSize; i++) {
        LTE_RRC_UE_CONTEXT* ctx = &((*table)[i]);

        // Verify integrity of allocated memory
        if (ctx == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        // Dynamically allocate memory for lte_ccch_message_config
        ctx->lte_ccch_message_config = malloc(sizeof(LTE_CCCH_MESSAGE_CONFIG));
        if (ctx->lte_ccch_message_config == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        // Set valid RRC_UE_ID and CELL_ID
        ctx->rrc_ue_id = i;
        ctx->cell_id = i;
    }
}

void freeLTERRCUETable(int** table, size_t* tableSize) {
    for (size_t i = 0; i < *tableSize; i++) {
        LTE_RRC_UE_CONTEXT* ctx = &((*table)[i]);

        if (ctx->lte_ccch_message_config != NULL) {
            free(ctx->lte_ccch_message_config);
            ctx->lte_ccch_message_config = NULL;
        }
    }

    free(*table);
    *table = NULL;
    *tableSize = 0;
}

void garbageCollectLTERRCUETable(int** table, size_t* tableSize) {
    for (size_t i = 0; i < *tableSize; i++) {
        LTE_RRC_UE_CONTEXT* ctx = &((*table)[i]);

        if (ctx->lte_ccch_message_config == NULL && ctx->rrc_ue_id >= MAX_CONTEXTS) {
            // Context is unused, free it
            free(ctx);
            (*table)[--(*tableSize)] = 0;
            i--;
        }
    }
}

int main() {
    int* table = NULL;
    size_t tableSize = 0;

    initLTERRCUETable(&table, &tableSize);

    // Use the initialized table

    freeLTERRCUETable(&table, &tableSize);

    return 0;
}
