typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PDCP_Array;

void pdcplib_init(PDCP_Array* array, size_t initial_capacity) {
    array->pdus = (LTE_Uplink_PDCP_PDU*)malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void pdcplib_add(PDCP_Array* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->size >= array->capacity * 3 / 4) { // Reallocate when 75% full
        array->capacity *= 2;
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    }
    memcpy(&array->pdus[array->size], &pdu, sizeof(LTE_Uplink_PDCP_PDU));
    array->size++;
}

LTE_Uplink_PDCP_PDU* pdcplib_get(PDCP_Array* array, uint32_t sn) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sn == sn) {
            LTE_Uplink_PDCP_PDU* pdu = &array->pdus[i];
            pthread_mutex_unlock(&array->mutex);
            return pdu;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

void pdcplib_update_error(PDCP_Array* array, uint32_t sn, int error_indication) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sn == sn) {
            array->pdus[i].error_indication = error_indication;
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void pdcplib_remove(PDCP_Array* array, uint32_t sn) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sn == sn) {
            memmove(&array->pdus[i], &array->pdus[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (array->size - i));
            array->size--;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void pdcplib_deinit(PDCP_Array* array) {
    free(array->pdus);
    pthread_mutex_destroy(&array->mutex);
}
