#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint16_t SN;
    uint32_t SDU_size;
    int8_t error_indication;
} LTE_Uplink_PDCP_PDU;

void* custom_malloc(size_t size) {
    void* mem = malloc(size);
    if (mem == NULL && size > 0) {
        // handle out-of-memory condition
        printf("Out of memory! Allocation failed.\n");
    }
    return mem;
}

void custom_free(void* ptr, size_t size) {
    free(ptr);
}

int add_PDU(LTE_Uplink_PDCP_PDU** pdcps, uint16_t SN, uint32_t SDU_size, int8_t error_indication) {
    // calculate the required memory for the new PDU
    size_t required_memory = sizeof(LTE_Uplink_PDCP_PDU);

    void* new_pdu = custom_malloc(required_memory);
    if (new_pdu == NULL) {
        // handle out-of-memory condition, return failure
        printf("Out of memory! Allocation failed.\n");
        return 1;
    }

    LTE_Uplink_PDCP_PDU* new_pdcps = new_pdu;

    // assign the PDU's SN, SDU size and error indication
    new_pdcps->SN = SN;
    new_pdcps->SDU_size = SDU_size;
    new_pdcps->error_indication = error_indication;

    // update the array pointer
    *pdcps = (LTE_Uplink_PDCP_PDU**)realloc(*pdcps, sizeof(LTE_Uplink_PDCP_PDU*) * ((*pdcps == NULL) ? 1 : (*pdcps)[0]->SN + 1));
    if (*pdcps == NULL) {
        // handle out-of-memory condition, return failure
        printf("Out of memory! Allocation failed.\n");
        custom_free(new_pdu, required_memory);
        return 1;
    }

    // add the new PDU to the array
    (*pdcps)[(*pdcps == NULL) ? 0 : (*pdcps)[0]->SN] = new_pdcps;

    return 0;
}

LTE_Uplink_PDCP_PDU* get_PDU(LTE_Uplink_PDCP_PDU** pdcps, uint16_t SN) {
    for (int i = 0; i < (*pdcps == NULL) ? 1 : (*pdcps)[0]->SN + 1; i++) {
        if ((*pdcps)[i] != NULL && (*pdcps)[i]->SN == SN) {
            return *pdcps[i];
        }
    }

    return NULL;
}

int update_error_indication(LTE_Uplink_PDCP_PDU** pdcps, uint16_t SN, int8_t error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = get_PDU(pdcps, SN);
    if (pdu == NULL) {
        // handle PDU not found
        printf("SN %d: PDU not found.\n", SN);
        return 1;
    }

    pdu->error_indication = error_indication;

    return 0;
}

int remove_PDU(LTE_Uplink_PDCP_PDU** pdcps, uint16_t SN) {
    int i = 0;
    while (i <= (*pdcps == NULL) ? 1 : (*pdcps)[0]->SN) {
        if ((*pdcps)[i] != NULL && (*pdcps)[i]->SN > SN) {
            // move the PDU to fill the gap
            if (!(*pdcps[i-1])) {
                // handle out-of-range access, return failure
                printf("Out of range! SN %d not found.\n", SN);
                return 1;
            }
            (*pdcps)[i-1]->SN = (*pdcps)[i]->SN;
            i++;
        } else if ((*pdcps)[i] != NULL && (*pdcps)[i]->SN == SN) {
            // found the PDU, remove it
            free((*pdcps)[i]);
            (*pdcps)[i] = NULL;
            return 0;
        }
        i++;
    }

    return 1;
}
