MemoryPool* init_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    mp->base = malloc(block_size * num_blocks);
    mp->top = mp->base;
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    free(mp->base);
    free(mp);
}

LTE_Uplink_PDCP_PDU** init_array(MemoryPool* mp, size_t initial_capacity) {
    LTE_Uplink_PDCP_PDU** array = malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU*));
    for (size_t i = 0; i < initial_capacity; i++) {
        array[i] = (LTE_Uplink_PDCP_PDU*)malloc(mp->block_size);
    }
    return array;
}

void destroy_array(LTE_Uplink_PDCP_PDU** array, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
