#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_POOL_SIZE 1024
#define BLOCK_SIZE 128
#define PDUS_PER_BLOCK (MAX_POOL_SIZE / BLOCK_SIZE)

typedef struct {
    int seq_num;
    int sdusize;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

void *malloc_block(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        // Try to allocate with reduced block size
        size /= 2;
        ptr = malloc(size);
        if (!ptr) {
            // Log failure reason and retry again
            printf("Out-of-memory condition! Aborting.\n");
            exit(1);
        }
    }
    return ptr;
}

void free_block(void *block, size_t size) {
    free(block);
}

void flush_pdu(LTE_Uplink_PDCP_PDU *pdu) {
    // Notification mechanism to higher layers
    pthread_cond_signal(&flush_notifier);
}

void init_pool() {
    pool_ptr = malloc(MAX_POOL_SIZE);
    block_count = 0;
    pdus_per_block = PDUS_PER_BLOCK;
}

int add_pdu(LTE_Uplink_PDCP_PDU *pdu) {
    if (block_count < pdus_per_block) {
        // Add PDU to current block
        ((LTE_Uplink_PDCP_PDU *)pool_ptr)[block_count++] = *pdu;
    } else {
        // Allocate new block and add PDU
        void *new_block = malloc_block(BLOCK_SIZE);
        memcpy(new_block, pool_ptr, BLOCK_SIZE);
        free(pool_ptr);
        pool_ptr = new_block;
        block_count++;
    }
    return 0;
}

LTE_Uplink_PDCP_PDU *get_pdu(int seq_num) {
    for (int i = 0; i < block_count; i++) {
        LTE_Uplink_PDCP_PDU *pdu = &((LTE_Uplink_PDCP_PDU *)pool_ptr)[i];
        if (pdu->seq_num == seq_num) {
            return pdu;
        }
    }
    return NULL;
}

int update_error_indication(int seq_num, int new_value) {
    LTE_Uplink_PDCP_PDU *pdu = get_pdu(seq_num);
    if (!pdu) return -1;
    pdu->error_indication = new_value;
    return 0;
}

void flush_all() {
    // Priority-based queue for flushing PDUs
    int i, j, last_idx = block_count - 1;
    for (i = 0; i < last_idx; i++) {
        LTE_Uplink_PDCP_PDU *pdu = &((LTE_Uplink_PDCP_PDU *)pool_ptr)[i];
        if (pdu->error_indication) {
            flush_pdu(pdu);
        }
    }
}

int main() {
    // Initialize the dynamic array and custom memory pool
    init_pool();

    // Add PDUs to the array
    add_pdu(&pdu1);
    add_pdu(&pdu2);

    // Retrieve a specific PDU by its sequence number
    LTE_Uplink_PDCP_PDU *pdu = get_pdu(seq_num);

    // Update error indication for a given SN
    update_error_indication(seq_num, 1);

    // Flush all PDUs with critical error conditions
    flush_all();

    return 0;
}
