void manageLTEUplinkPDCPPDUs(int *totalMemoryUsage, LTE_Uplink_PDCP_PDU **pdcps, NFAPI_RRC_UE_CONTEXT_T **rrc_ue_contexts) {
    // Initialize arrays
    *pdcps = (LTE_Uplink_PDCP_PDU *)malloc(MAX_PDCP_PDUS * sizeof(LTE_Uplink_PDCP_PDU));
    *rrc_ue_contexts = (NFAPI_RRC_UE_CONTEXT_T *)malloc(MAX_RRC_UE_CONTEXTS * sizeof(NFAPI_RRC_UE_CONTEXT_T));

    // Initialize arrays with 0
    for (int i = 0; i < MAX_PDCP_PDUS; i++) {
        (*pdcps)[i].PDCP_SeqNum = 0;
        (*pdcps)[i].SDU_Size = 0;
        (*pdcps)[i].Error_Indication = 0;
    }

    for (int i = 0; i < MAX_RRC_UE_CONTEXTS; i++) {
        (*rrc_ue_contexts)[i].RX_Ue_Info_Tag = 0;
        (*rrc_ue_contexts)[i].RNTI = 0;
        (*rrc_ue_contexts)[i].RRU_RX_Ue_DCI_Info = NULL;
    }

    // Implement adding new PDUs to the array
    void addPDCPPDU(LTE_Uplink_PDCP_PDU pdcp) {
        for (int i = 0; i < MAX_PDCP_PDUS; i++) {
            if ((*pdcps)[i].PDCP_SeqNum == 0) {
                (*pdcps)[i] = pdcp;
                return;
            }
        }
    }

    // Implement retrieving a specific PDU by its sequence number
    LTE_Uplink_PDCP_PDU* getSpecificPDU(int SN) {
        for (int i = 0; i < MAX_PDCP_PDUS; i++) {
            if ((*pdcps)[i].PDCP_SeqNum == SN) {
                return &((*pdcps)[i]);
            }
        }
        return NULL;
    }

    // Implement updating the error indication for a given sequence number
    void updateErrorIndication(int SN, int Error_Indication) {
        for (int i = 0; i < MAX_PDCP_PDUS; i++) {
            if ((*pdcps)[i].PDCP_SeqNum == SN) {
                (*pdcps)[i].Error_Indication = Error_Indication;
                return;
            }
        }
    }

    // Implement allocating and freeing resources
    void* allocateMemory(int size) {
        if (totalMemoryUsage + size > MAX_MEMORY_USAGE) {
            printf("Out of memory! Cannot allocate %d bytes.\n", size);
            return NULL;
        }
        *totalMemoryUsage += size;
        return malloc(size);
    }

    void freeResources(void* ptr, int size) {
        free(ptr);
        *totalMemoryUsage -= size;
    }

    // Implement mechanisms to efficiently manage memory
    void updateRXUeInfoTag(NFAPI_RRC_UE_CONTEXT_T context) {
        for (int i = 0; i < MAX_RRC_UE_CONTEXTS; i++) {
            if ((*rrc_ue_contexts)[i].RX_Ue_Info_Tag == 0) {
                (*rrc_ue_contexts)[i] = context;
                return;
            }
        }
    }

    void updateRNTI(NFAPI_RRC_UE_CONTEXT_T context, int RNTI) {
        for (int i = 0; i < MAX_RRC_UE_CONTEXTS; i++) {
            if ((*rrc_ue_contexts)[i].RX_Ue_Info_Tag == 0) {
                (*rrc_ue_contexts)[i] = context;
                (*rrc_ue_contexts)[i].RNTI = RNTI;
                return;
            }
        }
    }

    void freeRRU_RX_Ue_DCI_Info(NFAPI_RRC_UE_CONTEXT_T context) {
        free((void*)context.RRU_RX_Ue_DCI_Info);
    }
}
