// Structure representing a TCP/UDP connection with bandwidth limitations
typedef struct {
    int socket_type; // 0: UDP, 1: TCP
    int bandwidth;
} TCP_CONNECTION_RECORD;

// Dynamic array of connection records
TCP_CONNECTION_RECORD* connections = NULL;
int num_connections = 0;
int max_connections = 10; // Initial capacity

// Function to add a new connection record with error handling
void add_connection(int socket_type, int bandwidth) {
    if (num_connections >= max_connections) {
        printf("Error: No more available slots in the connections array.\n");
        return;
    }

    TCP_CONNECTION_RECORD* new_connection = (TCP_CONNECTION_RECORD*)malloc(sizeof(TCP_CONNECTION_RECORD));
    new_connection->socket_type = socket_type;
    new_connection->bandwidth = bandwidth;

    // Check for overlapping bandwidth limitations
    int found_overlap = 0;
    for (int i = 0; i < num_connections; i++) {
        if ((new_connection->bandwidth >= connections[i]->bandwidth && new_connection->bandwidth <= (connections[i]->bandwidth + 100)) ||
            (connections[i]->bandwidth >= new_connection->bandwidth && connections[i]->bandwidth <= (new_connection->bandwidth + 100))) {
            found_overlap = 1;
            break;
        }
    }

    if (found_overlap) {
        printf("Error: Overlapping bandwidth limitations. Try again.\n");
        free(new_connection);
        return;
    }

    // Add the new connection to the array and update statistics
    connections[num_connections] = *new_connection;
    num_connections++;

    printf("Connection added successfully.\n");
}

// Function to retrieve all stored connection records with error handling
void print_all_connections() {
    if (num_connections == 0) {
        printf("No connections available.\n");
        return;
    }

    for (int i = 0; i < num_connections; i++) {
        printf("Socket type: %d, Bandwidth: %d\n", connections[i].socket_type, connections[i].bandwidth);
    }
}

// Function to handle invalid inputs
void handle_invalid_input() {
    printf("Invalid input. Try again.\n");
}

int main() {
    // Initialize the connection array
    connections = (TCP_CONNECTION_RECORD*)malloc(max_connections * sizeof(TCP_CONNECTION_RECORD));

    while (1) {
        int choice;
        printf("Enter 1 to add a new connection, 2 to print all connections, or 3 to exit: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                int socket_type, bandwidth;
                printf("Enter socket type (0 for UDP, 1 for TCP): ");
                scanf("%d", &socket_type);
                printf("Enter bandwidth limitation: ");
                scanf("%d", &bandwidth);
                add_connection(socket_type, bandwidth);
                break;

            case 2:
                print_all_connections();
                break;

            case 3:
                free(connections); // Deallocate the connection array
                return 0;

            default:
                handle_invalid_input();
        }
    }

    return 0;
}

