```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include "network_analysis_library.h"
#include "monitoring_service.h"

#define MAX_ENTRIES 1000000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int bytes_sent;
    int bytes_received;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdu_array[MAX_ENTRIES];
int pdu_count = 0;

void add_pdu_entry(int unique_id, RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu;
    if(pdu_count < MAX_ENTRIES) {
        new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_pdu->rx_ue_info = rx_ue_info;
        new_pdu->rnti = rnti;
        new_pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
        new_pdu->bytes_sent = 0;
        new_pdu->bytes_received = 0;
        new_pdu->crcflag = rand() % 2; // Randomly set CRC flag
        pdu_array[pdu_count] = new_pdu;
        pdu_count++;
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_entry(int unique_id) {
    for(int i=0; i<pdu_count; i++) {
        if(pdu_array[i]->rx_ue_info == rx_ue_info && pdu_array[i]->rnti == rnti) {
            return pdu_array[i];
        }
    }
    return NULL;
}

void update_pdu_statistics(int unique_id, int bytes_sent, int bytes_received) {
    for(int i=0; i<pdu_count; i++) {
        if(pdu_array[i]->rx_ue_info == rx_ue_info && pdu_array[i]->rnti == rnti) {
            pdu_array[i]->bytes_sent += bytes_sent;
            pdu_array[i]->bytes_received += bytes_received;
        }
    }
}

void update_pdu_crcflag(int unique_id, int crcflag) {
    for(int i=0; i<pdu_count; i++) {
        if(pdu_array[i]->rx_ue_info == rx_ue_info && pdu_array[i]->rnti == rnti) {
            pdu_array[i]->crcflag = crcflag;
        }
    }
}

void update_pdu_metrics(int unique_id, int bytes_sent, int bytes_received) {
    for(int i=0; i<pdu_count; i++) {
        if(pdu_array[i]->rx_ue_info == rx_ue_info && pdu_array[i]->rnti == rnti) {
            // Update PDU statistics
            pdu_array[i]->bytes_sent += bytes_sent;
            pdu_array[i]->bytes_received += bytes_received;
            // Send updated metrics to monitoring service
            send_pdu_metrics_to_monitoring_service(pdu_array[i]);
        }
