['```java
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingDeque;
import java.util.concurrent.TimeUnit;

public class AsyncTaskManager {
    private final int MAX_THREADS = 5; // adjustable number of threads
    private ExecutorService executor;
    private BlockingQueue<Runnable> taskQueue;
    private LogService logService;

    public AsyncTaskManager(int initialPoolSize, LogService logService) {
        this.logService = logService;
        this.executor = Executors.newFixedThreadPool(MAX_THREADS);
        this.taskQueue = new LinkedBlockingDeque<>();
    }

    public void scheduleTask(Runnable task) {
        try {
            taskQueue.put(task);
        } catch (InterruptedException e) {
            logService.error("Exception occurred while scheduling the task", e);
        }
    }

    public <T> T submitTask(Callable<T> callable, long timeout, TimeUnit timeUnit) throws InterruptedException, ExecutionException {
        Future<T> future = executor.submit(callable);
        return future.get(timeout, timeUnit);
    }

    public void shutdown() {
        try {
            if (!executor.isShutdown()) {
                logService.info("Shutting down the thread pool");
                executor.shutdown();
                while (true) {
                    try {
                        executor.awaitTermination(1, TimeUnit.SECONDS);
                    } catch (InterruptedException e) {
                        logService.error("Error occurred during shutdown", e);
                    }
                    if (executor.isTerminated()) break;
                }
            }
        } catch (Exception e) {
            logService.error("Error occurred during shutdown", e);
        }
    }

    public void start() {
        executor = Executors.newFixedThreadPool(MAX_THREADS); // reinitializes the thread pool
        taskQueue = new LinkedBlockingDeque<>();
    }
}

interface Callable<T> {
    T call() throws Exception;
}
