    DIR *dp;
    struct dirent *entry;

    if ((dp = opendir(dir)) == NULL) {
        perror("Error opening directory");
        return -1;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char *file_path = (char *)malloc(strlen(dir) + strlen(entry->d_name) + 2);
        sprintf(file_path, "%s/%s", dir, entry->d_name);

        if (entry->d_type == DT_DIR) {
            process_dir(file_path, level + 1);
        } else {
            summarize_file(file_path);
        }

        free(file_path);
    }

    closedir(dp);
    return 0;
