Task* handleDynamicTasksAndCommunication(size_t capacity) {
    Task* tasks = (Task*)malloc(capacity * sizeof(Task));
    if (!tasks) return NULL; // Handle out-of-memory condition

    for (size_t i = 0; i < capacity; i++) {
        tasks[i].name = malloc(256); // Allocate memory for the name
        sprintf(tasks[i].name, "Task %zu", i);
        tasks[i].priorityLevel = rand() % 5 + 1;
        tasks[i].estimatedCompletionTime = exp(normal(10.0, 2.0));
        tasks[i].taskID = i;
        tasks[i].status = PENDING;
    }

    return tasks;
}

double normal(double mean, double std_dev) {
    static double last_std = 5.0; // Initialize the random number generator
    static double last_mean = 10.0;

    if (mean != last_mean || std_dev != last_std) {
        srandom(time(NULL)); // Re-seed the RNG with the current time
        last_mean = mean;
        last_std = std_dev;
    }

    return normrand() * std_dev + mean; // Generate a random number from a normal distribution
}

double normrand(void) {
    static double r; // Initialize the random number generator
    if (r <= 0.0) {
        r = ((double)rand()) / RAND_MAX;
    }
    return -log(1.0 - r); // Generate a uniform random variable and transform it to a normal variable
}

void freeTasks(Task* tasks, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        free(tasks[i].name);
    }
    free(tasks);
}
