#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_Uplink_PDCP_PDU {
    int sequence_number;
    // PDU contents
} LTE_Uplink_PDCP_PDU;

// Dynamic array of LTE_Uplink_PDCP_PDU structures
typedef struct {
    LTE_Uplink_PDCP_PDU* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;  // Mutex for thread safety
} LTE_Uplink_PDCP_PDUs;

// Function to initialize the dynamic array
void lte_uplink_pdcps_init(LTE_Uplink_PDCP_PDUs* pdus) {
    pdus->data = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU) * 16);
    pdus->capacity = 16;
    pdus->size = 0;
    pthread_mutex_init(&pdus->mutex, NULL);
}

// Function to add a new PDU to the array
void lte_uplink_pdcps_add(LTE_Uplink_PDCP_PDUs* pdus, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&pdus->mutex);
    if (pdus->size == pdus->capacity) {
        // Compact the array if it's fragmented
        pdus->data = (LTE_Uplink_PDCP_PDU*)realloc(pdus->data, sizeof(LTE_Uplink_PDCP_PDU) * pdus->capacity * 2);
        pdus->capacity *= 2;
    }
    pdus->data[pdus->size] = *pdu;
    pdus->size++;
    pthread_mutex_unlock(&pdus->mutex);
}

// Function to retrieve a PDU by its sequence number
LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get(LTE_Uplink_PDCP_PDUs* pdus, int sequence_number) {
    pthread_mutex_lock(&pdus->mutex);
    for (size_t i = 0; i < pdus->size; i++) {
        if (pdus->data[i].sequence_number == sequence_number) {
            LTE_Uplink_PDCP_PDU* pdu = &pdus->data[i];
            pthread_mutex_unlock(&pdus->mutex);
            return pdu;
        }
    }
    pthread_mutex_unlock(&pdus->mutex);
    return NULL;
}

// Function to update the error indication for a given sequence number
void lte_uplink_pdcps_update_error(LTE_Uplink_PDCP_PDUs* pdus, int sequence_number, int error) {
    pthread_mutex_lock(&pdus->mutex);
    for (size_t i = 0; i < pdus->size; i++) {
        if (pdus->data[i].sequence_number == sequence_number) {
            pdus->data[i].error = error;
            break;
        }
    }
    pthread_mutex_unlock(&pdus->mutex);
}

// Function to remove a PDU by its sequence number
void lte_uplink_pdcps_remove(LTE_Uplink_PDCP_PDUs* pdus, int sequence_number) {
    pthread_mutex_lock(&pdus->mutex);
    for (size_t i = 0; i < pdus->size; i++) {
        if (pdus->data[i].sequence_number == sequence_number) {
            memmove(&pdus->data[i], &pdus->data[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (pdus->size - i - 1));
            pdus->size--;
            if (i >= pdus->capacity / 4 && pdus->capacity > 16) {
                // Compact the array if it's fragmented
                pdus->data = (LTE_Uplink_PDCP_PDU*)realloc(pdus->data, sizeof(LTE_Uplink_PDCP_PDU) * pdus->capacity / 2);
                pdus->capacity /= 2;
            }
            break;
        }
    }
    pthread_mutex_unlock(&pdus->mutex);
}

// Function to free the dynamic array
void lte_uplink_pdcps_free(LTE_Uplink_PDCP_PDUs* pdus) {
    for (size_t i = 0; i < pdus->size; i++) {
        free(pdus->data[i].contents); // Free PDU contents if necessary
    }
    free(pdus->data);
    pthread_mutex_destroy(&pdus->mutex);
}
