void insertAfterOrAppend(std::vector<int>& vec, int target, int search, int insert, int& insertionCount, int maxCapacity, std::ofstream& logFile) {
    bool found = false;
    for (int i = 0; !found && i < vec.size(); i++) {
        if (vec[i] == search) {
            found = true;
            vec.insert(vec.begin() + i + 1, insert);
            insertionCount++;
        }
    }
    if (!found) {
        vec.push_back(insert);
        insertionCount++;
    }

    // check for capacity constraints
    size_t newCapacity = vec.size() * 2;
    if (newCapacity > maxCapacity) {
        logFile << "Warning: Capacity exceeded (" << maxCapacity << "). Further insertions are disallowed." << std::endl;
        while (newCapacity > maxCapacity) {
            newCapacity /= 2;
        }
        vec.reserve(newCapacity);
    } else if (newCapacity > vec.capacity()) {
        vec.reserve(newCapacity);
    }
}
