#define NR_Downlink_PDCP_PDU_MAX_SIZE 1024 // Assuming a maximum size of PDU structures

typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
} NR_Downlink_PDCP_PDU;

typedef struct {
    NR_Downlink_PDCP_PDU* pdus;
    int capacity;
    int size;
    pthread_mutex_t mutex; // Mutex for thread-safe operations
} PDU_Array;

PDU_Array* init_pdu_array(int initial_capacity) {
    PDU_Array* array = (PDU_Array*)malloc(sizeof(PDU_Array));
    array->pdus = (NR_Downlink_PDCP_PDU*)calloc(initial_capacity, sizeof(NR_Downlink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void add_pdu(PDU_Array* array, NR_Downlink_PDCP_PDU pdu) {
    if (array->size == array->capacity) {
        array->capacity *= 2; // Double the capacity for better performance
        array->pdus = (NR_Downlink_PDCP_PDU*)realloc(array->pdus, array->capacity * sizeof(NR_Downlink_PDCP_PDU));
    }
    array->pdus[array->size] = pdu;
    array->size++;
}

NR_Downlink_PDCP_PDU* get_pdu(PDU_Array* array, int SN) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

void update_error(PDU_Array* array, int SN, int error_indication) {
    NR_Downlink_PDCP_PDU* pdu = get_pdu(array, SN);
    if (pdu != NULL) {
        pdu->error_indication = error_indication;
    }
}

int remove_pdu(PDU_Array* array, int SN) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            memmove(&array->pdus[i], &array->pdus[i + 1], (array->size - i - 1) * sizeof(NR_Downlink_PDCP_PDU));
            array->size--;
            return 0;
        }
    }
    return -1; // PDU not found
}

void compact_array(PDU_Array* array) {
    NR_Downlink_PDCP_PDU* new_pds = (NR_Downlink_PDCP_PDU*)calloc(array->size, sizeof(NR_Downlink_PDCP_PDU));
    int offset = 0;
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN != -1) { // Assuming all PDUs have a valid SN
            new_pds[offset] = array->pdus[i];
            offset++;
        }
    }
    free(array->pdus);
    array->pdus = new_pds;
}

void send_event(PDU_Array* array, const char* event_type) {
    // Send the event to the external logging system
    printf("Sending event: %s\n", event_type);
}

int is_array_healthy(PDU_Array* array) {
    int missing_pdus = 0;
    for (int i = 0; i < array->size; i++) {
        NR_Downlink_PDCP_PDU pdu = array->pdus[i];
        if (pdu.SN == -1) { // Assuming all PDUs have a valid SN
            missing_pdus++;
        }
    }
    if (missing_pdus > 0) {
        send_event(array, "Missing PDUs");
        return 0; // Array is not healthy
    }
    return 1; // Array is healthy
}

void monitor_array_health(PDU_Array* array) {
    int health_check_interval = 10000; // Check the array every 10 seconds
    while (1) {
        if (!is_array_healthy(array)) {
            // Trigger alerts or perform recovery actions
            printf("Array not healthy, triggering alert\n");
        }
        usleep(health_check_interval);
    }
}

int main() {
    PDU_Array* array = init_pdu_array(10);

    NR_Downlink_PDCP_PDU pdu1 = {1, 100, 0};
    add_pdu(array, pdu1);
    send_event(array, "PDU added");

    NR_Downlink_PDCP_PDU pdu2 = {2, 200, 0};
    add_pdu(array, pdu2);
    send_event(array, "PDU added");

    NR_Downlink_PDCP_PDU* pdu3 = get_pdu(array, 1);
    if (pdu3 != NULL) {
        update_error(array, 1, 1);
        send_event(array, "PDU updated");
    }

    remove_pdu(array, 2);
    send_event(array, "PDU removed");

    compact_array(array);

    monitor_array_health(array);

    return 0;
}
