        (*pdus[i]).crcflag = rand() % 2; // Randomly set CRCFLAG

        statistics[0]++; // Increment number of PDUs generated
    }

    int retries = 0;
    for(int i = 0; i < num_pds; i++) {
        // Simulate delay and retry mechanism
        sleep(rand() % 3 + 1); // Randomly pause for 1-3 seconds
        if(rand() % 2) { // Random chance to fail
