typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    int SDU_size;
    int error_indication;
} PDU;

void* operator new(size_t) = delete; // disable default allocation
PDU** pdcps = nullptr;
int max_pdcps = 10000;
int current_pdcps = 0;

PDU** add_PDU(PDU* pdu) {
    if (current_pdcps >= max_pdcps) return nullptr;
    PDU** new_array = (PDU**)realloc(pdcps, sizeof(PDU*) * (current_pdcps + 1));
    if (!new_array) return nullptr;
    pdcps = new_array;
    pdcps[current_pdcps++] = pdu;
    return pdcps;
}

PDU* get_PDU(int SN) {
    for (int i = 0; i < current_pdcps; i++) {
        if (pdcps[i]->SN == SN)
            return pdcps[i];
    }
    return nullptr;
}

void update_Error(int SN, int error_indication) {
    for (int i = 0; i < current_pdcps; i++) {
        if (pdcps[i]->SN == SN) {
            pdcps[i]->error_indication = error_indication;
            break;
        }
    }
}

PDU** remove_PDU(int SN) {
    PDU** new_array = nullptr;
    for (int i = 0; i < current_pdcps; i++) {
        if (pdcps[i]->SN != SN)
            new_array = add_PDU(pdcps[i]);
        else
            current_pdcps--;
    }
    free(pdcps);
    pdcps = new_array;
    return pdcps;
}
