typedef struct {
    int sequence_number;
    int sdusize;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

struct memory_pool {
    void* base;
    size_t size;
};

LTE_Uplink_PDCP_PDU* dynamic_array = NULL;
size_t array_size = 0;
struct memory_pool pool;

void init_pool(size_t size) {
    pool.base = malloc(size);
    if (!pool.base) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    pool.size = size;
}

LTE_Uplink_PDCP_PDU* create_pdu() {
    LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)pool.base;
    pool.base += PDU_SIZE;
    return pdu;
}

void free_pool() {
    free(pool.base);
}

int add_pdu(int sequence_number, int sdusize, int error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = create_pdu();
    pdu->sequence_number = sequence_number;
    pdu->sdusize = sdusize;
    pdu->error_indication = error_indication;
    if (array_size == MAX_PDUS) {
        printf("Array full. Cannot add more PDUs.\n");
        return -1; // array full
    }
    dynamic_array[array_size] = *pdu;
    array_size++;
    return 0;
}

LTE_Uplink_PDCP_PDU* get_pdu(int sequence_number) {
    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i].sequence_number == sequence_number) {
            return &dynamic_array[i];
        }
    }
    printf("PDU not found.\n");
    return NULL;
}

int update_pdu(int sequence_number, int error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = get_pdu(sequence_number);
    if (!pdu) {
        return -1; // PDU not found
    }
    pdu->error_indication = error_indication;
    return 0;
}

void serialize_array() {
    FILE* file = fopen("pdus.dat", "wb");
    fwrite(&array_size, sizeof(size_t), 1, file);
    for (int i = 0; i < array_size; i++) {
        fwrite(&dynamic_array[i], PDU_SIZE, 1, file);
    }
    fclose(file);
}

void deserialize_array() {
    FILE* file = fopen("pdus.dat", "rb");
    if (!file) {
        printf("File not found.\n");
        return;
    }
    size_t array_size;
    fread(&array_size, sizeof(size_t), 1, file);
    dynamic_array = malloc(array_size * PDU_SIZE);
    for (int i = 0; i < array_size; i++) {
        fread(&dynamic_array[i], PDU_SIZE, 1, file);
    }
    fclose(file);
}

void* thread_function(void* arg) {
    int error_count = 0;
    size_t total_data_throughput = 0;
    for (int i = 0; i < array_size; i++) {
        LTE_Uplink_PDCP_PDU* pdu = &dynamic_array[i];
        // process PDU
        if (pdu->error_indication) {
            error_count++;
        }
        total_data_throughput += pdu->sdusize;
    }
    printf("Total data throughput: %zu\n", total_data_throughput);
    printf("Error count: %d\n", error_count);
    return NULL;
}

int main() {
    pthread_t thread;
    init_pool(MAX_PDUS * PDU_SIZE);
    // Add some PDUs
    add_pdu(1, 100, 0);
    add_pdu(2, 200, 0);
    add_pdu(3, 300, 0);
    // Serialize the array
    serialize_array();
    // Create a new thread to process the array
    pthread_create(&thread, NULL, thread_function, NULL);
    // Wait for the thread to finish
    pthread_join(thread, NULL);
    free_pool();
    return 0;
}
