#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int PDCP_SeqNum;
    int SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

void handleLTEUplinkPDUS(int sequenceNumber, int size, int error) {
    // Initialize the cache
    pthread_mutex_init(&cacheMutex, NULL);
    pthread_cond_init(&cacheCondVar, NULL);

    // Check if the PEM file is in the cache
    if (pthread_mutex_lock(&cacheMutex) == 0) {
        // Cache hit: retrieve the PEM file from memory
        PEM_file = cache[PDCP_SeqNum];
        pthread_mutex_unlock(&cacheMutex);
    } else {
        // Cache miss: retrieve the PEM file from disk
        PEM_file = loadPEMfileFromDisk(PDCP_SeqNum);
        if (PEM_file) {
            cache[PDCP_SeqNum] = PEM_file;
            pthread_cond_signal(&cacheCondVar);
        }
    }

    // Check if the private key and certificate are present in the PEM file
    if (PEM_file && (checkPEMfile(PEM_file) == 0)) {
        // Initialize the dynamic array of LTE_Uplink_PDCP_PDU structures
        LTE_Uplink_PDCP_PDU *PDUs = (LTE_Uplink_PDCP_PDU *)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        PDUs->PDCP_SeqNum = sequenceNumber;
        PDUs->SDU_size = size;
        PDUs->error_indication = error;

        // Add the PDU to the array
        addPDUToArray(PDUs);

        // Update the error indication for the given SN
        updateErrorIndication(sequenceNumber, error);
    }

    // Log the operation
    logOperation(sequenceNumber, size, error);

    // Return the PEM file
    return PEM_file;
}

void addPDUToArray(LTE_Uplink_PDCP_PDU *pdu) {
    // Initialize the dynamic array
    LTE_Uplink_PDCP_PDU **PDUs = (LTE_Uplink_PDCP_PDU **)malloc(sizeof(LTE_Uplink_PDCP_PDU *));
    PDUs->PDCP_SeqNum = pdu->PDCP_SeqNum;
    PDUs->SDU_size = pdu->SDU_size;
    PDUs->error_indication = pdu->error_indication;

    // Add the PDU to the array
    if (PDUs == NULL) {
        // Handle error: no memory available
        return;
    } else {
        // Update the array with the new PDU
        updateArray(PDus);
    }
}

void updateErrorIndication(int sequenceNumber, int error) {
    // Find the PDU in the array with the given sequence number
    LTE_Uplink_PDCP_PDU *pdu = findPDUInArray(sequenceNumber);

    if (pdu == NULL) {
        // Handle error: PDU not found
        return;
    } else {
        // Update the error indication for the given SN
        pdu->error_indication = error;
    }
}

void logOperation(int sequenceNumber, int size, int error) {
    // Log the operation with a timestamp and verbosity level
    if (verbosityLevel == 1) {
        printf("Sequence Number: %d, SDU Size: %d, Error Indication: %d\n", sequenceNumber, size, error);
    }
}

int findPDUInArray(int sequenceNumber) {
    // Find the PDU in the array with the given sequence number
    LTE_Uplink_PDCP_PDU *pdu = NULL;
    for (int i = 0; i < PDUs_length; i++) {
        if (PDus[i]->PDCP_SeqNum == sequenceNumber) {
            pdu = PDus[i];
            break;
        }
    }
    return pdu;
}

void updateArray(LTE_Uplink_PDCP_PDU **pdu) {
    // Update the array with the new PDU
    if (PDUs_length < MAX_PDUS) {
        PDus[PDUs_length++] = pdu;
    } else {
        // Handle error: no more memory available
        return;
    }
}

int checkPEMfile(char *peM_file) {
    // Check if the PEM file is valid and contains a private key and certificate
    if (peM_file == NULL || !checkPrivatekey(peM_file) || !checkCertificate(peM_file)) {
        return 0;
    } else {
        return 1;
    }
}

char *loadPEMfileFromDisk(int sequenceNumber) {
    // Load the PEM file from disk with the given sequence number
    char *peM_file = NULL;
    if (pthread_mutex_lock(&cacheMutex) == 0) {
        peM_file = cache[sequenceNumber];
        pthread_mutex_unlock(&cacheMutex);
    } else {
        // Cache miss: retrieve the PEM file from disk
        peM_file = loadPEMfileFromDisk(sequenceNumber);
        if (peM_file) {
            cache[sequenceNumber] = peM_file;
            pthread_cond_signal(&cacheCondVar);
        }
    }
}

