#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LTE_UPLINK_PDCP_PDUS 1000
#define RETRY_MAX 5
#define JITTER_FRACTION 0.2

typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    int SDU_size;
    int error_indication;
    char RX_UE_INFORMATION_TAG[10];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
} LTE_Uplink_PDCP_PDU;

typedef struct TransmissionQueue {
    LTE_Uplink_PDCP_PDU* pdu;
    time_t sent_at;
    int retries;
    struct TransmissionQueue* next;
} TransmissionQueue;

typedef struct PDU_Queue {
    TransmissionQueue* head;
    TransmissionQueue* tail;
} PDU_Queue;

// Custom locking mechanism
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_PDU(LTE_Uplink_PDCP_PDU* pdu, int SN) {
    // Initialize PDU with random CRCFLAG and other parameters from an external data source
    srand(time(NULL));
    pdu->SN = SN;
    pdu->SDU_size = rand() % 100 + 1; // Random SDU size between 1-100 bytes
    pdu->error_indication = 0; // Initialize error indication to 0 (no error)
    strcpy(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG"); // Initialize RX UE information tag
    pdu->RNTI = rand() % 100 + 1; // Random RNTI between 1-100
    strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRC_INDICATOR_TAG"); // Initialize CRC indication tag
}

void add_PDU(PDU_Queue* queue, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&lock);

    TransmissionQueue* new_queue = (TransmissionQueue*)malloc(sizeof(TransmissionQueue));
    new_queue->pdu = pdu;
    new_queue->sent_at = time(NULL);
    new_queue->retries = 0;

    if(queue->head == NULL) {
        queue->head = new_queue;
        queue->tail = new_queue;
    } else {
        queue->tail->next = new_queue;
        queue->tail = new_queue;
    }

    pthread_mutex_unlock(&lock);
}

LTE_Uplink_PDCP_PDU* get_PDU(PDU_Queue* queue, int SN) {
    pthread_mutex_lock(&lock);

    TransmissionQueue* current = queue->head;
    while(current != NULL) {
        if(current->pdu->SN == SN) {
            LTE_Uplink_PDCP_PDU* pdu = current->pdu;
            pthread_mutex_unlock(&lock);
            return pdu;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL; // PDU not found
}

void update_error(PDU_Queue* queue, int SN) {
    pthread_mutex_lock(&lock);

    TransmissionQueue* current = queue->head;
    while(current != NULL) {
        if(current->pdu->SN == SN) {
            current->pdu->error_indication = 1; // Update error indication
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void mark_processed(PDU_Queue* queue, int SN) {
    pthread_mutex_lock(&lock);

    TransmissionQueue* current = queue->head;
    while(current != NULL) {
        if(current->pdu->SN == SN) {
            // Mark PDU as processed
            free(current->pdu);
            if(queue->head == current) {
                queue->head = current->next;
            }
            if(queue->tail == current) {
                queue->tail = current->next;
            }
            free(current);

            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void transmit_PDU(PDU_Queue* queue, int SN) {
