            // ...

            pthread_mutex_unlock(&lock);
            return; // PDU transmitted
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

void periodic_garbage_collection(PDU_Queue* queue) {
    pthread_mutex_lock(&lock);

    TransmissionQueue* current = queue->head;
    while(current != NULL) {
        if(current->pdu->error_indication == 1) { // PDU marked as processed
            free(current->pdu);
            if(queue->head == current) {
                queue->head = current->next;
            }
            if(queue->tail == current) {
                queue->tail = current->next;
            }
            free(current);

            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

