        printf("Initialization failed.\n");
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indications(int n, int verbose) {
    NFAPI_CRC_INDICATION_PDU_T** cache = NULL;
    int cache_size = 0;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = NULL;

        if (!cache || cache_size <= 0) { // Reuse memory block
            structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            int idx = rand() % cache_size;
            structure = cache[idx];
            cache[idx] = NULL; // Mark as free
            cache[idx + 1] = &structure; // Update next pointer
            cache_size--;
        }

        if (structure) {
            struct timeval tv;
            gettimeofday(&tv, NULL);
            log_info((verbose ? "Initializing indication %d at %s" : "Initialization failed: %s") 
                      , i, ctime(&tv));

            structure->RX_UE_INFORMATION_TAG = i * 100 + 1;
            structure->RNTI = i * 2 + 1;
            structure->CRC_INDICATION_REL8_TAG = i;

            if (!is_valid_structure(structure)) {
                free(structure);
                continue; // Try next indication
            }

            if (cache) { // Add to cache
                int idx = rand() % cache_size;
                cache[idx] = structure;
                cache_size++;
            }
        }

        if (verbose && i < n - 1) {
            printf("Indication %d initialized successfully.\n", i);
        } else {
            printf("Initialization failed for indication %d.\n", i);
        }
    }

    return !cache || cache_size == 0 ? NULL : *cache;
}

