} LTE_Uplink_PDCP_PDU;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LTE_Uplink_PDCP_PDU** pdcps = NULL;
size_t pdcps_size = 0;

void lte_uplink_pdcp_pdu_array_init() {
    pdcps = (LTE_Uplink_PDCP_PDU**)malloc(sizeof(LTE_Uplink_PDCP_PDU*) * LTE_UPLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR);
    pdcps_size = LTE_UPLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR;
}

void lte_uplink_pdcp_pdu_array_add(LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&lock);
    if (pdcps_size == 0) {
        pdcps = (LTE_Uplink_PDCP_PDU**)realloc(pdcps, sizeof(LTE_Uplink_PDCP_PDU*) * LTE_UPLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR);
        pdcps_size = LTE_UPLINK_PDCP_PDU_ARRAY_GROWTH_FACTOR;
    }
    for (size_t i = 0; i < pdcps_size; ++i) {
        if (!pdcps[i]) {
            pdcps[i] = pdu;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

LTE_Uplink_PDCP_PDU* lte_uplink_pdcp_pdu_array_get(uint16_t sequence_number) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < pdcps_size; ++i) {
        if (pdcps[i] && pdcps[i]->sequence_number == sequence_number) {
            LTE_Uplink_PDCP_PDU* pdu = pdcps[i];
            pthread_mutex_unlock(&lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void lte_uplink_pdcp_pdu_array_update_error(uint16_t sequence_number, int error) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < pdcps_size; ++i) {
        if (pdcps[i] && pdcps[i]->sequence_number == sequence_number) {
            pdcps[i]->data->error = error;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void lte_uplink_pdcp_pdu_array_free() {
    for (size_t i = 0; i < pdcps_size; ++i) {
        if (pdcps[i]) {
            free(pdcps[i]->data);
            free(pdcps[i]);
        }
    }
    free(pdcps);
}
