typedef struct {
    uint16_t seqNum;
    LTE_Uplink_PDCP_PDU data;
    int errorIndication;
} LTE_Uplink_PDCP_PDU;

struct PDU_Array {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
};

void init_PDU_Array(struct PDU_Array* array, size_t initial_capacity) {
    array->pdus = (LTE_Uplink_PDCP_PDU*)malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);
}

void add_PDU(struct PDU_Array* array, LTE_Uplink_PDCP_PDU new_pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        // Reallocate memory
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, 2 * array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
        array->capacity *= 2;
    }
    array->pdus[array->size++] = new_pdu;
    pthread_mutex_unlock(&array->lock);
}

LTE_Uplink_PDCP_PDU* get_PDU_by_seqNum(struct PDU_Array* array, uint16_t seq_num) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].seqNum == seq_num) {
            LTE_Uplink_PDCP_PDU* pdu = &array->pdus[i];
            pthread_mutex_unlock(&array->lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void update_error_indication(struct PDU_Array* array, uint16_t seq_num) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].seqNum == seq_num) {
            array->pdus[i].errorIndication++;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void monitor_memory_usage(struct PDU_Array* array) {
    // Implement memory usage monitoring and reporting
}

// Dynamic adjustment of the internal structure based on observed usage patterns
void adjust_PDU_Array(struct PDU_Array* array, size_t capacity_threshold) {
    if (array->size > capacity_threshold * 0.5) {
        // Scale up the array to handle increased load
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, capacity_threshold * sizeof(LTE_Uplink_PDCP_PDU));
        array->capacity = capacity_threshold;
    } else if (array->size < capacity_threshold * 0.1) {
        // Scale down the array to conserve memory
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, array->size * sizeof(LTE_Uplink_PDCP_PDU));
        array->capacity = array->size;
    }
}

void close_PDU_Array(struct PDU_Array* array) {
    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
    pthread_cond_destroy(&array->cond);
}
