['```java
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicIntegerArray;

public class LTEUplinkPdcpManager {
    private static final int MAX_ALLOWED_SDU_SIZE = 1024;
    private static final int MIN_SEQUENCE_NUMBER = 0;
    private static final int MAX_SEQUENCE_NUMBER = Integer.MAX_VALUE;
    private static final int INITIAL_ALLOCATION = 16;

    private List<LTE_Uplink_PDCP_PDU> pdus;
    private AtomicIntegerArray sequenceNumbersUsed;
    private AtomicIntegerArray sequenceNumberIndex;

    public LTEUplinkPdcpManager() {
        pdus = new ArrayList<>();
        sequenceNumbersUsed = new AtomicIntegerArray(INITIAL_ALLOCATION);
        sequenceNumberIndex = new AtomicIntegerArray(INITIAL_ALLOCATION);

        for (int i = 0; i < INITIAL_ALLOCATION; i++) {
            sequenceNumbersUsed.set(i, false);
        }
    }

    public int addPDU(LTE_Uplink_PDCP_PDU pdu) throws Exception {
        if (!isSequenceNumberValid(pdu.getSequenceNumber())) {
            return -1;
        }

        if (pdu.getSduSize() > MAX_ALLOWED_SDU_SIZE) {
            return -2;
        }

        int newIndex = findNextAvailableIndex();
        if (newIndex == -1) {
            // out of memory
            return -3;
        }

        pdus.add(newIndex, pdu);
        sequenceNumbersUsed.set(newIndex, true);

        return newIndex;
    }

    public LTE_Uplink_PDCP_PDU getPDU(int sequenceNumber) throws Exception {
        for (int i = 0; i < pdus.size(); i++) {
            if (pdus.get(i).getSequenceNumber() == sequenceNumber) {
                return pdus.get(i);
            }
        }

        // not found, create a new empty PDU
        LTE_Uplink_PDCP_PDU pdu = new LTE_Uplink_PDCP_PDU(sequenceNumber, 0, false, System.currentTimeMillis());
        return pdu;
    }

    public int updateErrorIndication(int sequenceNumber) throws Exception {
        for (int i = 0; i < pdus.size(); i++) {
            if (pdus.get(i).getSequenceNumber() == sequenceNumber) {
                pdus.get(i).setErrorIndication(true);
                return 1;
            }
        }

        // not found
        return -1;
    }

    public int removePDU(int sequenceNumber) throws Exception {
        for (int i = 0; i < pdus.size(); i++) {
            if (pdus.get(i).getSequenceNumber() == sequenceNumber) {
                pdus.remove(i);
                sequenceNumbersUsed.set(i, false);
                return 1;
            }
        }

        // not found
        return -1;
    }

    public List<LTE_Uplink_PDCP_PDU> listAllPDUs() {
        return pdus;
    }

    private int findNextAvailableIndex() throws Exception {
        for (int i = 0; i < sequenceNumbersUsed.length(); i++) {
            if (!sequenceNumbersUsed.get(i)) {
                sequenceNumberIndex.set(sequenceNumberIndex.length(), i);
                return i;
            }
        }

        // out of memory
        return -1;
    }

    public void startService() throws Exception {
        while (true) {
            Thread.sleep((int) Math.round(Math.random() * 10));
            sendStopMessage();
        }
    }

    private void sendStopMessage() {
        // implementation omitted for brevity
    }
}
