// Define probability distribution for packet loss (1 - 0.9)
#define PACKET_LOSS_PROBABILITY 0.05

// Function to generate a unique RNTI value
unsigned int get_unique_rnti(void) {
    static unsigned int rnti = 0;
    return ++rnti;
}

// Function to set CRCFLAG based on packet loss probability
int get_crcflag(void) {
    double random_value = (double)rand() / RAND_MAX;
    if (random_value < PACKET_LOSS_PROBABILITY)
        return 1; // Packet is lost, set CRCFLAG to 1
    else
        return 0; // Packet is not lost, set CRCFLAG to 0
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the list and its elements
    crc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc((n+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list) {
        LOG_ERROR("Memory allocation failed");
        return NULL;
    }

    // Populate the list with unique RNTI and CRCFLAG values
    for (int i = 0; i < n; i++) {
        crc_list[i].rx_ue_info_tag = get_unique_rnti();
        crc_list[i].rnti = get_unique_rnti();
        crc_list[i].crc_ind_rel8_tag.crcflag = get_crcflag();
    }

    return crc_list;
}
