#include <stdlib.h>
#include <string.h>

typedef struct {
    int SN;
    size_t SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* arr;
    size_t capacity;
    size_t used;
} PDCP_Array;

void pdc_array_init(PDCP_Array* array, size_t capacity) {
    array->capacity = capacity;
    array->used = 0;
    array->arr = (LTE_Uplink_PDCP_PDU*)malloc(capacity * sizeof(LTE_Uplink_PDCP_PDU));
}

int pdc_array_add(PDCP_Array* array, LTE_Uplink_PDCP_PDU new_pdu) {
    if(array->used >= array->capacity) {
        printf("Out of memory! Cannot add more PDUs.\n");
        return -1;
    }
    array->arr[array->used] = new_pdu;
    (array->used)++;
    return 0;
}

LTE_Uplink_PDCP_PDU* pdc_array_get(PDCP_Array* array, int SN) {
    for(size_t i = 0; i < array->used; i++) {
        if(array->arr[i].SN == SN) {
            LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
            *pdu = array->arr[i];
            return pdu;
        }
    }
    printf("PDU not found with SN %d.\n", SN);
    return NULL;
}

int pdc_array_update(PDCP_Array* array, int SN, int error_indication) {
    for(size_t i = 0; i < array->used; i++) {
        if(array->arr[i].SN == SN) {
            array->arr[i].error_indication = error_indication;
            return 0;
        }
    }
    printf("PDU not found with SN %d.\n", SN);
    return -1;
}

int pdc_array_remove(PDCP_Array* array, int SN) {
    for(size_t i = 0; i < array->used; i++) {
        if(array->arr[i].SN == SN) {
            memmove(&array->arr[i], &array->arr[i+1], (array->used - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            (array->used]--;
            return 0;
        }
    }
    printf("PDU not found with SN %d.\n", SN);
    return -1;
}

// Web API functions
void handle_put_request(int id, LTE_Uplink_PDCP_PDU* new_pdu) {
    PDCP_Array array;
    pdc_array_init(&array, 10); // Initialize the array with a capacity of 10

    int ret = pdc_array_add(&array, *new_pdu);
    if(ret == -1) {
        printf("Error adding PDU.\n");
        return;
    }

    LTE_Uplink_PDCP_PDU* updated_pdu = pdc_array_get(&array, new_pdu->SN);
    if(updated_pdu != NULL) {
        pdc_array_update(&array, updated_pdu->SN, 1); // Update the error indication
    } else {
        printf("PDU not found with SN %d.\n", new_pdu->SN);
    }

    // Return the updated resource
    printf("Updated PDU: SN=%d, SDU_size=%zu, error_indication=%d\n", 
           updated_pdu->SN, updated_pdu->SDU_size, updated_pdu->error_indication);
}

void handle_delete_request(int id) {
    PDCP_Array array;
    pdc_array_init(&array, 10); // Initialize the array with a capacity of 10

    int ret = pdc_array_remove(&array, id); // Remove the PDU with SN equal to 'id'
    if(ret == -1) {
        printf("Error removing PDU.\n");
        return;
    }

    // Return the new resource with default values after deletion
    LTE_Uplink_PDCP_PDU* new_pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    new_pdu->SN = id; // Set the SN to 'id'
    new_pdu->SDU_size = 0; // Set the SDU size to 0
    new_pdu->error_indication = 1; // Set the error indication to 1

    printf("Deleted PDU: SN=%d, SDU_size=0, error_indication=1\n", id);
}

int main() {
    // Example usage:
    LTE_Uplink_PDCP_PDU new_pdu;
    new_pdu.SN = 123; // Set the sequence number
    new_pdu.SDU_size = 1024; // Set the SDU size
    new_pdu.error_indication = 0; // Set the error indication

    handle_put_request(123, &new_pdu); // Update the PDU with SN equal to '123'

    handle_delete_request(123); // Remove the PDU with SN equal to '123'
    return 0;
}
