#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STORAGE 1000 // Define the maximum storage limit
#define LTE_UPLINK_PDCP_pdu_MAX_SIZE 1024 // Define the maximum size of a PDU

typedef struct {
    int sequenceNumber;
    int sizeIndicator;
    int errorStatus;
} LTE_Uplink_PDCP_PDU;

// Function to manage dynamic array of PDU structures
LTE_Uplink_PDCP_PDU* managePduArray(int* size, LTE_Uplink_PDCP_PDU** pdus) {
    if (*size >= MAX_STORAGE) {
        printf("Error: Storage limit reached.\n");
        return *pdus;
    }

    int newSize = *size + 1;

    // Dynamically allocate memory for the new PDU
    *pdus = (LTE_Uplink_PDCP_PDU*)realloc(*pdus, sizeof(LTE_Uplink_PDCP_PDU) * newSize);

    if (*pdus == NULL) {
        printf("Error: Out of memory.\n");
        return *pdus;
    }

    (*pdus)[*size].sequenceNumber = 0; // Initialize the new PDU with default values
    (*pdus)[*size].sizeIndicator = LTE_UPLINK_PDCP_pdu_MAX_SIZE;
    (*pdus)[*size].errorStatus = 0;

    return *pdus;
}

// Function to add a new PDU to the dynamic array
void addPdu(int* size, LTE_Uplink_PDCP_PDU** pdus) {
    managePduArray(size, pdus);
    (*size)++;
}

// Function to retrieve a PDU by sequence number
LTE_Uplink_PDCP_PDU* getPdu(int* size, LTE_Uplink_PDCP_PDU** pdus, int sequenceNumber) {
    for (int i = 0; i < *size; i++) {
        if ((*pdus)[i].sequenceNumber == sequenceNumber)
            return &((*pdus)[i]);
    }
    return NULL;
}

// Function to update the error status of a PDU
void updateErrorStatus(int* size, LTE_Uplink_PDCP_PDU** pdus, int sequenceNumber, int errorStatus) {
    LTE_Uplink_PDCP_PDU* pdu = getPdu(size, pdus, sequenceNumber);

    if (pdu != NULL)
        pdu->errorStatus = errorStatus;
}

// Function to remove a PDU by sequence number
void removePdu(int* size, LTE_Uplink_PDCP_PDU** pdus, int sequenceNumber) {
    for (int i = 0; i < *size; i++) {
        if ((*pdus)[i].sequenceNumber == sequenceNumber) {
            memmove(&((*pdus))[i], &((*pdus))[i + 1], (*size - i) * sizeof(LTE_Uplink_PDCP_PDU));
            (*size)--;

            // Dynamically reallocate memory to remove the removed PDU
            *pdus = (LTE_Uplink_PDCP_PDU*)realloc(*pdus, sizeof(LTE_Uplink_PDCP_PDU) * (*size));

            return;
        }
    }
}

// Web API functions

// Function to handle HTTP PUT operation
void putOperation(int* size, LTE_Uplink_PDCP_PDU** pdus, int resourceId, LTE_Uplink_PDCP_PDU* pdu) {
    // Update the existing resource with new data from the request body
    LTE_Uplink_PDCP_PDU* existingPdu = getPdu(size, pdus, resourceId);

    if (existingPdu != NULL) {
        updateErrorStatus(size, pdus, resourceId, pdu->errorStatus);
    } else {
        // Create a new resource with default values if the resource does not exist
        addPdu(size, pdus);
        existingPdu = &((*pdus)[*size - 1]);
        existingPdu->sequenceNumber = resourceId;
        existingPdu->sizeIndicator = pdu->sizeIndicator;
        existingPdu->errorStatus = pdu->errorStatus;
    }
}

// Function to handle HTTP DELETE operation
void deleteOperation(int* size, LTE_Uplink_PDCP_PDU** pdus, int resourceId) {
    // Remove the resource by its unique ID and return a new resource initialized with default values
    removePdu(size, pdus, resourceId);

    addPdu(size, pdus);
}

int main() {
    int size = 0;
    LTE_Uplink_PDCP_PDU* pdus = NULL;

    // Initialize the dynamic array of PDU structures
    managePduArray(&size, &pdus);

    // Add PDUs to the array and perform operations
    putOperation(&size, &pdus, 1, (LTE_Uplink_PDCP_PDU){0, LTE_UPLINK_PDCP_pdu_MAX_SIZE, 0});
    putOperation(&size, &pdus, 2, (LTE_Uplink_PDCP_PDU){1, LTE_UPLINK_PDCP_pdu_MAX_SIZE, 1});

    deleteOperation(&size, &pdus, 1);

    return 0;
}
