```java
import java.util.*;

class LTE_Uplink_PDCP_PDU {
    int SN;
    int size;
    boolean errorIndication;
    long timestamp;

    public LTE_Uplink_PDCP_PDU(int SN, int size) {
        this.SN = SN;
        this.size = size;
        this.errorIndication = false;
        this.timestamp = System.currentTimeMillis();
    }
}

public class PDCP_PDU_Manager {

    private HashMap<Integer, LTE_Uplink_PDCP_PDU> pduMap;
    private LinkedList<LTE_Uplink_PDCP_PDU> pduList;

    public PDCP_PDU_Manager() {
        pduMap = new HashMap<>();
        pduList = new LinkedList<>();
    }

    public int addPDU(int SN, int size) {
        if (SN <= 0 || size > getMaxAllowedSize()) {
            return -1; // invalid SN or SDU size
        }
        try {
            while (true) {
                LTE_Uplink_PDCP_PDU pdu = new LTE_Uplink_PDCP_PDU(SN, size);
                if (!pduMap.containsKey(SN)) {
                    pduMap.put(SN, pdu);
                    pduList.add(pdu);
                    return 0; // successful addition
                }
            }
        } catch (OutOfMemoryError e) {
            try {
                Thread.sleep(100); // retry after a brief delay
                continue;
            } catch (InterruptedException ie) {
                return -2; // interrupted exception
            }
        }
    }

    public LTE_Uplink_PDCP_PDU getPDU(int SN) {
        if (!pduMap.containsKey(SN)) {
            return new LTE_Uplink_PDCP_PDU(0, 0);
        } else {
            return pduMap.get(SN);
        }
    }

    public int updateErrorIndication(int SN, boolean errorIndication) {
        synchronized (this) {
            if (!pduMap.containsKey(SN)) {
                return -1; // invalid sequence number
            }
            LTE_Uplink_PDCP_PDU pdu = pduMap.get(SN);
            pdu.errorIndication = errorIndication;
            return 0; // successful update
        }
    }

    public int removePDU(int SN) {
        synchronized (this) {
            if (!pduList.isEmpty()) {
                Iterator<LTE_Uplink_PDCP_PDU> iterator = pduList.iterator();
                while (iterator.hasNext()) {
                    LTE_Uplink_PDCP_PDU pdu = iterator.next();
                    if (pdu.SN == SN) {
                        iterator.remove();
                        return 0; // successful removal
                    }
                }
            }
            return -1; // invalid sequence number or not found
        }
    }

    public void listPDUs(boolean filterByErrorState) {
        List<LTE_Uplink_PDCP_PDU> filteredList = new ArrayList<>();
        synchronized (this) {
            for (LTE_Uplink_PDCP_PDU pdu : pduList) {
                if ((filterByErrorState && !pdu.errorIndication) || (!filterByErrorState)) {
                    filteredList.add(pdu);
                }
            }
        }
        // print the filtered list
    }

    public static void main(String[] args) {
        PDCP_PDU_Manager manager = new PDCP_PDU_Manager();
        for (int i = 0; i < 10; i++) {
            int SN = i + 1;
            int size = (int) (Math.random() * 100);
            int status = manager.addPDU(SN, size);
            if (status != 0) {
                System.out.println("Error adding PDU: " + status);
            }
        }
        try {
            Thread.sleep((long) (Math.random() * 10)); // random delay
            System.out.println("Stopping service...");
            manager.listPDUs(true); // filter by error state
        } catch (InterruptedException e) {
            System.out.println("Service interrupted");
        }
    }

    private int getMaxAllowedSize() {
        return 1024; // arbitrary size limit
    }
}
