    };

    struct RetentionPolicy {
        size_t retentionPeriodDays;
    };

    class Exception : public std::runtime_error {
    public:
        Exception(const std::string& message) : runtime_error(message) {}
    };

    LoggingConfig() = default;

    LoggingConfig(LogLevel level, const FileRotationPolicy& policy, const RetentionPolicy& retention)
        : level_(level), policy_(policy), retention_(retention) {}

    LogLevel getLevel() const { return level_; }
    void setLevel(LogLevel level) {
        if (level != DEBUG && level != INFO && level != WARNING && level != ERROR) {
            throw Exception("Invalid log level");
        }
        level_ = level;
    }

    FileRotationPolicy getPolicy() const { return policy_; }
    void setPolicy(const FileRotationPolicy& policy) {
        policy_ = policy;
    }

    RetentionPolicy getRetention() const { return retention_; }
    void setRetention(const RetentionPolicy& retention) {
        retention_ = retention;
    }

private:
    LogLevel level_;
    FileRotationPolicy policy_;
    RetentionPolicy retention_;
};

class LoggingConfigManager {
public:
    static std::map<std::string, LoggingConfig> configurations;

    void addConfiguration(const std::string& name, const LoggingConfig& config) {
        if (configurations.find(name) != configurations.end()) {
            throw std::invalid_argument("Configuration already exists");
        }
        configurations[name] = config;
    }

    LoggingConfig getConfiguration(const std::string& name) {
        auto it = configurations.find(name);
        if (it == configurations.end()) {
            throw std::invalid_argument("Configuration not found");
        }
        return it->second;
    }

private:
    static std::map<std::string, LoggingConfig> configurations;
};

std::map<std::string, LoggingConfig> LoggingConfigManager::configurations = {};
