void* process_and_store_sensor_data(void* arg) {
    config_t *config = (config_t*)arg;
    FILE *file = fopen(config->filename, "r");

    if (!file) {
        // handle error
    }

    int batch_count = 0;
    float sum = 0.0f;
    int count = 0;

    while (1) {
        // Read a batch of sensor data
        char buffer[1024];
        fgets(buffer, sizeof(buffer), file);

        if (feof(file)) break;

        // Validate checksum and filter out corrupted or anomalous readings
        if (!validate_checksum(buffer)) continue;

        // Transform using moving average filter to smooth out noise and detect trends
        float reading = transform_data(buffer);
        sum += reading;
        count++;

        batch_count++;

        if (batch_count >= config->batch_size) {
            // Aggregate and store in time-series database
            float average = sum / count;

            // Store in time-series database

            sum = 0.0f;
            count = 0;
            batch_count = 0;
        }
    }

    fclose(file);
}

void process_and_store_sensor_data_main(config_t *config) {
    int num_threads = 4; // adjust this based on system load
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; i++) {
        config_t *thread_config = malloc(sizeof(config_t));
        memcpy(thread_config, config, sizeof(config_t));

        pthread_create(&threads[i], NULL, process_and_store_sensor_data, thread_config);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    // Initialize configuration
    config_t config;
    config.filename = "sensor_data.csv";
    config.batch_size = 100;
    config.smoothing_window_size = 30;
    config.anomaly_detection_threshold = 3.0f;

    process_and_store_sensor_data_main(&config);

    return 0;
}

