#include <stdlib.h>
#include <stdio.h>

typedef struct LTE_Uplink_PDCP_PDU {
    uint32_t SN;
    uint16_t SDU_size;
    int8_t error_indication;
} LTE_Uplink_PDCP_PDU;

typedef struct Dynamic_Array {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dynamic_Array;

Dynamic_Array* init_dynamic_array(size_t initial_capacity) {
    Dynamic_Array* da = (Dynamic_Array*)malloc(sizeof(Dynamic_Array));
    da->pdus = (LTE_Uplink_PDCP_PDU*)calloc(initial_capacity, sizeof(LTE_Uplink_PDCP_PDU));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void add_pdu(Dynamic_Array* da, LTE_Uplink_PDCP_PDU pdu) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity * 2 + 1;
        LTE_Uplink_PDCP_PDU* new_pdus = (LTE_Uplink_PDCP_PDU*)realloc(da->pdus, new_capacity * sizeof(LTE_Uplink_PDCP_PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&da->lock);
            printf("Error allocating memory for PDU.\n");
            return;
        }
        da->pdus = new_pdus;
        da->capacity = new_capacity;
    }

    da->pdus[da->size] = pdu;
    da->size++;

    pthread_mutex_unlock(&da->lock);
}

LTE_Uplink_PDCP_PDU* get_pdu(Dynamic_Array* da, uint32_t SN) {
    pthread_mutex_lock(&da->lock);

    for (int i = 0; i < da->size; i++) {
        if (da->pdus[i].SN == SN) {
            LTE_Uplink_PDCP_PDU* pdu = &da->pdus[i];
            pthread_mutex_unlock(&da->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return NULL;
}

void update_pdu_error(Dynamic_Array* da, uint32_t SN, int8_t error_indication) {
    pthread_mutex_lock(&da->lock);

    for (int i = 0; i < da->size; i++) {
        if (da->pdus[i].SN == SN) {
            da->pdus[i].error_indication = error_indication;
            pthread_mutex_unlock(&da->lock);
            return;
        }
    }

    pthread_mutex_unlock(&da->lock);
}

void remove_pdu(Dynamic_Array* da, uint32_t SN) {
    pthread_mutex_lock(&da->lock);

    for (int i = 0; i < da->size; i++) {
        if (da->pdus[i].SN == SN) {
            LTE_Uplink_PDCP_PDU* new_pdu = &da->pdus[i];
            memmove(new_pdu, &da->pdus[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (da->size - i - 1));
            da->size--;
            free(da->pdus);
            da->pdus = new_pdu;
            da->capacity = da->size;
        }
    }

    pthread_mutex_unlock(&da->lock);
}

void finalize_dynamic_array(Dynamic_Array* da) {
    free(da->pdus);
    pthread_mutex_destroy(&da->lock);
    free(da);
}
