        tasks[i].name = (char*)malloc(64 * sizeof(char)); // assume 64-character max name length
        sprintf(tasks[i].name, "Task-%zu", i);

        tasks[i].priorityLevel = rand() % 5 + 1;
        tasks[i].estimatedCompletionTime = (double)rand() / RAND_MAX * 2.0 + 10.0;
