        if (log_file_ptr != NULL) {
            fprintf(log_file_ptr, "[%s] %s added with version %d and checksum 0x%X.\n", 
                    asctime(localtime(&chunk->metadata.last_modified)), chunk->id, chunk->metadata.version, chunk->metadata.checksum);
            fclose(log_file_ptr);
        }
    }

    // Function to handle HTTP requests for data verification
    void verifyData(char* id) {
        // Make an HTTP request to the server with the given ID
        // Handle response and perform necessary actions
    }

