typedef struct {
    uint16_t sequence_number;
    char hostname[256];
} DNS_CACHE_ENTRY;

DNS_CACHE_ENTRY* dns_cache = NULL;
int32_t dns_cache_size = 0;
int32_t dns_cache_capacity = 1000; // Initial capacity

// Define the LRU cache eviction policy
void lru_cache_eviction() {
    if (dns_cache_size > 0) {
        int32_t evicted_index = 0;
        for (int32_t i = 1; i < dns_cache_size; i++) {
            if (dns_cache[i].sequence_number < dns_cache[evicted_index].sequence_number) {
                evicted_index = i;
            }
        }
        // Remove the least recently used entry
        free(dns_cache[evicted_index].hostname);
        for (int32_t i = evicted_index; i < dns_cache_size - 1; i++) {
            strcpy(dns_cache[i].hostname, dns_cache[i + 1].hostname);
        }
        free(dns_cache);
        dns_cache = NULL;
        dns_cache = (DNS_CACHE_ENTRY*)malloc(sizeof(DNS_CACHE_ENTRY) * dns_cache_capacity);
        dns_cache_size--;
    }
}

// Define the function to initialize and manage the dynamic array of PDU structures
int init_pdu_array(int32_t capacity) {
    pdus_capacity = capacity;
    pdus = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU) * pdus_capacity);
    if (!pdus) {
        return -1; // Out of memory
    }
    return 0;
}

// Define the function to add a new PDU to the array
int add_pdu(int16_t sn, int32_t sdu_size, int8_t error_indication) {
    if (pdus_size >= pdus_capacity) {
        pdus_capacity *= 2; // Double the capacity
        pdus = (LTE_Uplink_PDCP_PDU*)realloc(pdus, sizeof(LTE_Uplink_PDCP_PDU) * pdus_capacity);
        if (!pdus) {
            return -1; // Out of memory
        }
    }
    pdus[pdus_size].sn = sn;
    pdus[pdus_size].sdu_size = sdu_size;
    pdus[pdus_size].error_indication = error_indication;
    pdus_size++;
    return 0;
}

// Define the function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* get_pdu_by_sn(int16_t sn) {
    for (int32_t i = 0; i < pdus_size; i++) {
        if (pdus[i].sn == sn) {
            return &pdus[i];
        }
    }
    return NULL;
}

// Define the function to update the error indication for a given SN
int update_pdu_error_indication(int16_t sn, int8_t error_indication) {
