}

// Define the function to perform DNS resolution and cache management
int perform_dns_resolution(char* hostname) {
    // Check if the hostname is already cached
    for (int32_t i = 0; i < dns_cache_size; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            return 0; // Already cached
        }
    }
    // Perform DNS resolution and cache the result
    char* resolved_hostname = gethostbyname(hostname);
    if (!resolved_hostname) {
        return -1; // DNS resolution failed
    }
    // Cache the result
    dns_cache[dns_cache_size].sequence_number = (uint16_t)getpid();
    strcpy(dns_cache[dns_cache_size].hostname, hostname);
    dns_cache_size++;
    return 0;
