async function traverseFileSystem(rootDir, extension, testFn) {
  const fs = require('fs');
  const path = require('path');

  try {
    await new Promise((resolve, reject) => {
      fs.readdir(rootDir, (err, files) => {
        if (err) throw err;
        resolve(files);
      });
    });

    async function traverse(dirPath, dirName) {
      try {
        const files = await new Promise((resolve, reject) => {
          fs.readdir(path.join(rootDir, dirName), (err, files) => {
            if (err) throw err;
            resolve(files);
          });
        });

        for (const file of files) {
          const filePath = path.join(rootDir, dirName, file);

          try {
            await new Promise((resolve, reject) => {
              fs.stat(filePath, (err, stats) => {
                if (err) throw err;
                resolve(stats);
              });
            });

            if (stats.isDirectory()) {
              await traverse(filePath, file);
            } else if (path.extname(file) === `.${extension}`) {
              if (await testFn(file)) yield filePath;
            }
          } catch (error) {
            console.error(`Error traversing ${filePath}:`, error);
          }
        }
      } catch (error) {
        console.error(`Error traversing ${dirPath}:`, error);
      }
    }

    for await (const file of traverse(rootDir, '')) {}

    return [];
  } catch (error) {
    console.error('Error traversing file system:', error);
  }
}
