#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct FileMetadata {
    char* path;
    time_t last_modified;
    off_t size;
    char* hash_value;
    int access_frequency;
    bool is_deleted;
} FileMetadata;

FileMetadata** files = NULL;
int file_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_files() {
    pthread_mutex_lock(&lock);
    if (files != NULL) {
        for (int i = 0; i < file_count; i++) {
            free(files[i]->path);
            free(files[i]->hash_value);
        }
        free(files);
    }
    files = NULL;
    file_count = 0;
    pthread_mutex_unlock(&lock);
}

void add_file(const char* path, time_t last_modified, off_t size, const char* hash_value) {
    pthread_mutex_lock(&lock);
    FileMetadata* new_file = (FileMetadata*) malloc(sizeof(FileMetadata));
    new_file->path = strdup(path);
    new_file->last_modified = last_modified;
    new_file->size = size;
    new_file->hash_value = strdup(hash_value);
    new_file->access_frequency = 0;
    new_file->is_deleted = false;
    if (files == NULL) {
        files = (FileMetadata**) malloc(sizeof(FileMetadata*));
        file_count = 1;
    } else {
        FileMetadata** temp = (FileMetadata**) realloc(files, sizeof(FileMetadata*) * ++file_count);
        temp[file_count - 1] = new_file;
        files = temp;
    }
    pthread_mutex_unlock(&lock);
}

FileMetadata* get_file(const char* path) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < file_count; i++) {
        if (strcmp(files[i]->path, path) == 0) {
            pthread_mutex_unlock(&lock);
            return files[i];
        }
