    NetworkEvent** networkEvents = (NetworkEvent**)malloc(numEvents * sizeof(NetworkEvent*));
    if (!networkEvents) {
        return NULL; // Allocation failed
    }

    for (int i = 0; i < numEvents; i++) {
        NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
        if (!event) {
            free(networkEvents);
            return NULL; // Allocation failed
        }

        event->userId = i;
        event->timestamp = i * 1000000; // Milliseconds since epoch
        size_t dataSize = sizeof(char) * (i % 10 + 1); // Varying data sizes
        event->dataSize = dataSize;
        event->dataBuffer = malloc(dataSize);
        if (!event->dataBuffer) {
            free(event);
            free(networkEvents);
            return NULL; // Allocation failed
        }

        networkEvents[i] = event;
    }

    return networkEvents;
}

int getTotalNetworkEvents(NetworkEvent** events, int numEvents) {
    return numEvents;
}

void freeNetworkEvents(NetworkEvent** events, int numEvents) {
    for (int i = 0; i < numEvents; i++) {
        if (events[i]->dataBuffer)
            free(events[i]->dataBuffer);
        free(events[i]);
    }
    free(events);
}
