        UserIdentifier* user = (UserIdentifier*)malloc(sizeof(UserIdentifier));
        getUserData(i, user, sizeof(UserIdentifier));
        events[i] = (NetworkEvent*)malloc(sizeof(NetworkEvent));
        events[i]->user = *user;
        events[i]->timestamp = time(NULL);

        DataSequence* seq = (DataSequence*)malloc(sizeof(DataSequence));
        getEventData(i, &seq, sizeof(DataSequence));
        events[i]->data.capacity = seq->capacity;
        events[i]->data.buffer = seq->buffer;
        events[i]->data.len = seq->len;

        free(user);
        free(seq);
    }

    return events;
}

int getTotalEvents(NetworkEvent** events, int numEvents) {
