const {parallelize} = require('parallel-transform');
const {caching} = require('cache-ify');
const {asyncTraverse, validateFileNames} = require('./fileSystemTraversal');

function getFilesByExtension(fileSystem, extension, validationFunction) {
  const cachedResults = caching(() => {
    let result = [];
    asyncTraverse(fileSystem, (fileOrDir) => {
      if (fileOrDir.isFile()) {
        if (fileOrDir.name.endsWith(extension)) {
          const isValid = validateFileNames(validationFunction, fileOrDir.name);
          if (isValid) {
            result.push({path: fileOrDir.path, name: fileOrDir.name});
          }
        }
      } else if (fileOrDir.isDirectory()) {
        result = [...result, ...getFilesByExtension(fileOrDir.contents, extension, validationFunction)];
      }
    });
    return result;
  });

  const parallelResults = parallelize(() => {
    return cachedResults();
  }, {maxConcurrency: 4});

  return parallelResults.then((results) => results.flat());
}

async function asyncTraverse(fileSystem, callback) {
  for await (const fileOrDir of fileSystem) {
    callback(fileOrDir);
    if (fileOrDir.isDirectory()) {
      await asyncTraverse(fileOrDir.contents, callback);
    }
  }
}

function validateFileNames(validationFunction, fileName) {
  try {
    return validationFunction(fileName);
  } catch (error) {
    console.error('Error validating file name:', error);
    return false;
  }
}
