#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
    long timestamp;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* PDUs;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} PDCP_Array;

void init_array(PDCP_Array* array) {
    array->PDUs = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    array->size = 1;
    array->capacity = 1;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_PDU(PDCP_Array* array, int SN, int SDU_size) {
    LTE_Uplink_PDCP_PDU new_PDU;
    new_PDU.SN = SN;
    new_PDU.SDU_size = SDU_size;
    new_PDU.error_indication = 0;
    new_PDU.timestamp = time(NULL);

    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        array->PDUs = realloc(array->PDUs, sizeof(LTE_Uplink_PDCP_PDU) * (array->capacity *= 2));
    }
    array->PDUs[array->size++] = new_PDU;
    pthread_mutex_unlock(&array->mutex);
}

LTE_Uplink_PDCP_PDU* get_PDU(PDCP_Array* array, int SN) {
    for (int i = 0; i < array->size; i++) {
        if (array->PDUs[i].SN == SN) {
            return &array->PDUs[i];
        }
    }
    return NULL;
}

void update_error_indication(PDCP_Array* array, int SN) {
    for (int i = 0; i < array->size; i++) {
        if (array->PDUs[i].SN == SN) {
            array->PDUs[i].error_indication = 1;
            return;
        }
    }
}

void remove_outdated_PDUs(PDCP_Array* array, int age_threshold) {
    for (int i = 0; i < array->size; i++) {
        if ((time(NULL) - array->PDUs[i].timestamp) > age_threshold) {
            memmove(&array->PDUs[i], &array->PDUs[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (array->size-- - i));
            i--;
        }
    }
}

void free_array(PDCP_Array* array) {
    pthread_mutex_lock(&array->mutex);
    if (array->size > 0) {
        free(array->PDUs);
    }
    pthread_mutex_unlock(&array->mutex);
}
