#define MAX_FRAMES 1024
#define MAX_RF_BANDS 8

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    PHY_Reception_Timestamp timestamp;
    float SNR;
    RF_band rf_band;
    center_frequency freq;
    bandwidth bw;
} LTE_PHY_RX_FRAME_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
LTE_PHY_RX_FRAME_T* frames[MAX_FRAMES];
int frame_count = 0;

void* allocate_frame(int rf_band) {
    LTE_PHY_RX_FRAME_T* frame = (LTE_PHY_RX_FRAME_T*) malloc(sizeof(LTE_PHY_RX_FRAME_T));
    if (!frame) {
        LOG_ERROR("Memory allocation failed for RF band %d", rf_band);
        return NULL;
    }
    frame->rf_band = rf_band;
    frame->freq = ...; // Frequency metadata
    frame->bw = ...; // Bandwidth metadata
    return frame;
}

void free_frame(LTE_PHY_RX_FRAME_T* frame) {
    if (frame) free(frame);
}

void process_frame(int rf_band, LTE_PHY_RX_FRAME_T* frame) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < frame_count; i++) {
        if (frames[i]->rf_band == rf_band && frames[i]->freq == frame->freq && frames[i]->bw == frame->bw) {
            // Frame already processed, skip duplicates
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Process the frame...
}

void* process_frames(void* arg) {
    int* config = (int*) arg;
    for (int i = 0; i < *config; i++) {
        LTE_PHY_RX_FRAME_T* frame = allocate_frame(i % MAX_RF_BANDS);
        if (!frame) continue;
        // Process the frame...
        free_frame(frame);
    }
    return NULL;
}

void serialize_frames(LTE_PHY_RX_FRAME_T** frames, int count) {
    FILE* file = fopen("frames.bin", "wb");
    fwrite(frames, sizeof(LTE_PHY_RX_FRAME_T), count, file);
    fclose(file);
}

LTE_PHY_RX_FRAME_T** deserialize_frames() {
    FILE* file = fopen("frames.bin", "rb");
    LTE_PHY_RX_FRAME_T** frames = (LTE_PHY_RX_FRAME_T**) malloc(MAX_FRAMES * sizeof(LTE_PHY_RX_FRAME_T));
    fread(frames, sizeof(LTE_PHY_RX_FRAME_T), MAX_FRAMES, file);
    fclose(file);
    return frames;
}

int main() {
    int config = 100; // Number of frames to process
    pthread_t thread;
    pthread_create(&thread, NULL, process_frames, &config);
    pthread_join(thread, NULL);

    LTE_PHY_RX_FRAME_T** serialized_frames = deserialize_frames();

    for (int i = 0; i < MAX_FRAMES; i++) {
        if (!serialized_frames[i]) break;
        // Process the frame...
    }

    return 0;
}
