#define LTE_UPLINK_PDCP_pdu_MAX_SIZE 1024
#define LTE_UPLINK_PDCP_pdu_ARRAY_GROWTH 16

typedef struct {
    uint32_t sn;
    uint16_t sdu_size;
    uint8_t error_indication;
    time_t timestamp;
} LTE_Uplink_PDCP_PDU;

void lte_uplink_pdcps_init(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size);
int lte_uplink_pdcps_add_pdu(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, LTE_Uplink_PDCP_PDU *new_pdu);
LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get_pdu_by_sn(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, uint32_t sn);
int lte_uplink_pdcps_update_error_indication(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, uint32_t sn, uint8_t new_error_indication);
int lte_uplink_pdcps_remove_outdated_pdus(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, time_t age_threshold);

void lte_uplink_pdcps_init(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size) {
    *pdu_array = NULL;
    *array_size = 0;
}

int lte_uplink_pdcps_add_pdu(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, LTE_Uplink_PDCP_PDU *new_pdu) {
    // Handle out-of-memory condition
    if (*array_size >= LTE_UPLINK_PDCP_pdu_MAX_SIZE) {
        return -ENOMEM;
    }

    // Create a new array with the specified growth factor
    size_t new_array_size = *array_size + LTE_UPLINK_PDCP_pdu_ARRAY_GROWTH;
    LTE_Uplink_PDCP_PDU *new_pdu_array = realloc(*pdu_array, sizeof(LTE_Uplink_PDCP_PDU) * new_array_size);
    if (!new_pdu_array) {
        return -ENOMEM;
    }

    // Copy existing PDUs to the new array
    memcpy(new_pdu_array, *pdu_array, *array_size * sizeof(LTE_Uplink_PDCP_PDU));
    free(*pdu_array);
    *pdu_array = new_pdu_array;

    // Add the new PDU
    (*pdu_array)[*array_size] = *new_pdu;
    (*array_size)++;

    return 0;
}

LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get_pdu_by_sn(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, uint32_t sn) {
    for (size_t i = 0; i < *array_size; i++) {
        if ((*pdu_array)[i].sn == sn) {
            return &(*pdu_array)[i];
        }
    }

    return NULL;
}

int lte_uplink_pdcps_update_error_indication(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, uint32_t sn, uint8_t new_error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = lte_uplink_pdcps_get_pdu_by_sn(pdu_array, array_size, sn);
    if (!pdu) {
        return -ENOENT; // PDU not found
    }

    pdu->error_indication = new_error_indication;

    return 0;
}

int lte_uplink_pdcps_remove_outdated_pdus(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, time_t age_threshold) {
    for (size_t i = 0; i < *array_size; i++) {
        if (time(NULL) - (*pdu_array)[i].timestamp > age_threshold) {
            memmove(&(*pdu_array)[i], &(*pdu_array)[i + 1], (*array_size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            (*array_size)--;
        }
    }

    return 0;
}
