#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SN;
    int SDU_size;
    int error;
    long timestamp;
    char status;
} LTE_Uplink_PDCP_PDU;

void *malloc(size_t size);
int free(void *ptr);

// Dynamic array management function
void lte_pdc_pdu_array_mgmt(LTE_Uplink_PDCP_PDU **pdus, int *size, int threshold) {
    if (*size == 0) {
        // Initialize the array with a minimum capacity
        *pdus = (LTE_Uplink_PDCP_PDU *)malloc(threshold * sizeof(LTE_Uplink_PDCP_PDU));
        *size = threshold;
    }

    // Compression mechanism: compress when PDUs < threshold
    if (*size <= threshold / 2) {
        int new_size = threshold / 2;
        LTE_Uplink_PDCP_PDU *new_pdus = (LTE_Uplink_PDCP_PDU *)malloc(new_size * sizeof(LTE_Uplink_PDCP_PDU));

        // Copy relevant PDUs to the compressed array
        for (int i = 0; i < *size; i++) {
            new_pdus[i] = pdus[i][0];
        }

        // Free original array
        free(pdus);
        *pdus = new_pdus;
        *size = new_size;
    }
}

// Add a new PDU to the array
void add_pdu(LTE_Uplink_PDCP_PDU **pdus, int *size) {
    LTE_Uplink_PDCP_PDU *new_pdu = (LTE_Uplink_PDCP_PDU *)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    new_pdu->SN = 0;
    new_pdu->SDU_size = 0;
    new_pdu->error = 0;
    new_pdu->timestamp = time(NULL);
    new_pdu->status = ' '; // Initial status: not delivered

    *pdus = (LTE_Uplink_PDCP_PDU *)realloc(*pdus, (*size + 1) * sizeof(LTE_Uplink_PDCP_PDU));
    (*pdus)[*size] = *new_pdu;
    (*size)++;
}

// Retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU *get_pdu_by_sn(LTE_Uplink_PDCP_PDU **pdus, int size, int sn) {
    for (int i = 0; i < size; i++) {
        if ((*pdus)[i].SN == sn)
            return &((*pdus)[i]);
    }
    return NULL;
}

// Update the error indication field for a given SN
void update_error(LTE_Uplink_PDCP_PDU **pdus, int size, int sn, int error) {
    for (int i = 0; i < size; i++) {
        if ((*pdus)[i].SN == sn)
            (*pdus)[i].error = error;
    }
}

// Mark PDUs as successfully delivered
void mark_delivered(LTE_Uplink_PDCP_PDU **pdus, int size) {
    for (int i = 0; i < size; i++) {
        (*pdus)[i].status = 'D'; // Status: delivered
    }
}

// Remove PDUs older than a configurable time threshold
void remove_old_pdus(LTE_Uplink_PDCP_PDU **pdus, int size, long threshold) {
    for (int i = 0; i < size; i++) {
        if ((*pdus)[i].timestamp <= threshold)
            (*pdus)[i] = (*pdus[--size]);
    }

    *pdus = (LTE_Uplink_PDCP_PDU *)realloc(*pdus, size * sizeof(LTE_Uplink_PDCP_PDU));
}

// Thread-safe operations
void lte_pdc_pdu_array_mgmt_threadsafe(LTE_Uplink_PDCP_PDU **pdus, int *size, int threshold) {
    pthread_mutex_lock(&mutex);
    lte_pdc_pdu_array_mgmt(pdus, size, threshold);
    pthread_mutex_unlock(&mutex);
}
