#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PDUS 1000
#define THRESHOLD 500
#define MODE_NORMAL 0
#define MODE_STRESS 1

typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    int SDU_size;
    int error_indication;
    long timestamp;
} PDU_t;

void *malloc_compressed(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        // handle out-of-memory condition
        printf("Out of memory\n");
    }
    return ptr;
}

void free_compressed(void *ptr, size_t size) {
    free(ptr);
}

PDU_t **pdus = NULL;
int pdus_count = 0;
int mode = MODE_NORMAL;

// Function to add a new PDU
void add_pdu(int SN, int SDU_size, int error_indication, long timestamp) {
    if (mode == MODE_STRESS && pdus_count >= THRESHOLD) {
        // simulate high load condition
        int i;
        for (i = 0; i < 10000; i++) {
            add_pdu(rand() % MAX_PDUS, rand() % 1024, rand() % 2, time(NULL));
        }
    } else if (pdus_count >= MAX_PDUs) {
        // dynamically compress the array to reclaim memory
        size_t old_size = sizeof(PDU_t *) * pdus_count;
        PDU_t **old_pdus = malloc_compressed(old_size);
        memcpy(old_pdus, pdus, old_size);
        free_compressed(pdus, old_size);
        pdus = old_pdus;
        pdus_count -= THRESHOLD / 2; // re-allocate half of the array
    }
    PDU_t *new_pdu = malloc_compressed(sizeof(PDU_t));
    new_pdu->SN = SN;
    new_pdu->SDU_size = SDU_size;
    new_pdu->error_indication = error_indication;
    new_pdu->timestamp = timestamp;
    pdus = realloc(pdus, sizeof(PDU_t *) * ++pdus_count);
    pdus[pdus_count - 1] = new_pdu;
}

// Function to retrieve a specific PDU by its sequence number
PDU_t *get_pdu(int SN) {
    int i;
    for (i = 0; i < pdus_count; i++) {
        if (pdus[i]->SN == SN) {
            return pdus[i];
        }
    }
    return NULL;
}

// Function to update the error indication for a given SN
void update_error(int SN, int new_error_indication) {
    int i;
    for (i = 0; i < pdus_count; i++) {
        if (pdus[i]->SN == SN) {
            pdus[i]->error_indication = new_error_indication;
            return;
        }
    }
}

// Function to remove PDUs older than a specified time threshold
void remove_old_pds(long timestamp_threshold) {
    int i, j = 0;
    for (i = 0; i < pdus_count; i++) {
        if (pdus[i]->timestamp <= timestamp_threshold) {
            // move the PDU to the front of the array
            pdus[j] = pdus[i];
            j++;
        } else {
            break;
        }
    }
    for (i = 0; i < j; i++) {
        free(pdus[i]);
    }
    pdus_count -= i;
}

// Function to log system performance and memory usage
void log_stats() {
    printf("PDUs processed per second: %d\n", pdus_count);
    printf("Average time taken to process each PDU: %f seconds\n", (double)time(NULL));
    printf("Memory usage statistics: %lu bytes allocated, %lu bytes freed\n",
           sizeof(PDU_t *) * pdus_count, sizeof(PDU_t *) * THRESHOLD / 2);
}

// Function to switch between normal and stress test mode
void set_mode(int new_mode) {
    if (new_mode == MODE_NORMAL || new_mode == MODE_STRESS) {
        mode = new_mode;
    } else {
        // handle invalid mode request
        printf("Invalid mode request\n");
    }
}

int main() {
    // initialize the array with some sample data
    pdus_count = 10;
    pdus = malloc_compressed(sizeof(PDU_t *) * pdus_count);
    int i;
    for (i = 0; i < pdus_count; i++) {
        PDU_t *pdu = malloc_compressed(sizeof(PDU_t));
        pdu->SN = rand() % MAX_PDUS;
        pdu->SDU_size = rand() % 1024;
        pdu->error_indication = rand() % 2;
        pdu->timestamp = time(NULL);
        pdus[i] = pdu;
    }

    // perform some operations
    add_pdu(1, 10, 0, time(NULL));
    update_error(1, 1);
    remove_old_pds(time(NULL) - THRESHOLD / 2);
    log_stats();

    return 0;
}

