function getFileList(dirPath, extensionFilter, fileChecker) {
  const cache = new Map();
  const queue = [];
  const results = [];

  function traverseDir(path) {
    if (cache.has(path)) return cache.get(path);

    let files = null;
    try {
      files = fs.readdirSync(path);
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }

    const fileMap = new Map();
    for (const file of files) {
      const filePath = path + '/' + file;
      if (fs.statSync(filePath).isDirectory()) {
        queue.push({ dir: filePath });
      } else {
        fileMap.set(file, extensionFilter(filePath));
      }
    }

    cache.set(path, { files: fileMap });

    async function processQueue() {
      while (queue.length > 0) {
        const item = await queue.shift();
        if (!item) continue;

        try {
          const dirFiles = fs.readdirSync(item.dir);
          for (const file of dirFiles) {
            const filePath = item.dir + '/' + file;
            queue.push({ file: filePath });
          }
        } catch (err) {
          if (err.code === 'ENOENT') continue;
          throw err;
        }
      }

      async function processQueueHelper() {
        while (queue.length > 0) {
          const item = await queue.shift();
          if (!item) continue;

          try {
            const file = fs.statSync(item.file);
            if (file.isFile()) {
              const result = await Promise.all([
                fileChecker(item.file),
                ...Object.values(cache.get(item.dir).files)
                  .filter(file => file && extensionFilter(item.file))
                  .map(file => fileChecker(file)),
              ]);
              results.push(...result.filter(Boolean));
            }
          } catch (err) {
            if (err.code === 'ENOENT') continue;
            throw err;
          }
        }
      }

      await processQueueHelper();
    }

    await processQueue();

    return results;
  }

  // Authentication and Data Validation Mechanisms

  const auth = new Auth({
    username: 'your_username',
    password: 'your_password',
  });

