int lteUplinkPdcpPduArrayInit(LTE_Uplink_PDCP_PDU** array, size_t capacity) {
    *array = (LTE_Uplink_PDCP_PDU*) allocateMemory(capacity * sizeof(LTE_Uplink_PDCP_PDU));
    return 0;
}

int lteUplinkPdcpPduArrayAdd(LTE_Uplink_PDCP_PDU** array, size_t capacity, LTE_Uplink_PDCP_PDU* pdu) {
    if (*array == NULL || capacity <= 0) {
        return -1; // Out of memory or invalid capacity
    }

    for (size_t i = 0; i < capacity; i++) {
        if (((*array)[i]).sequenceNumber == pdu->sequenceNumber) {
            return -2; // PDU already exists in the array
        }
    }

    if (capacity > 0) {
        (*array)[capacity-1] = *pdu;
    } else {
        (*array)[0] = *pdu;
    }

    return 0; // Success
}

LTE_Uplink_PDCP_PDU* lteUplinkPdcpPduArrayGet(LTE_Uplink_PDCP_PDU** array, size_t capacity, int sequenceNumber) {
    if (*array == NULL || capacity <= 0) {
        return NULL; // Array is empty or invalid
    }

    for (size_t i = 0; i < capacity; i++) {
        if (((*array)[i]).sequenceNumber == sequenceNumber) {
            return &((*array)[i]);
        }
    }

    return NULL; // PDU not found in the array
}

int lteUplinkPdcpPduArrayUpdate(LTE_Uplink_PDCP_PDU** array, size_t capacity, int sequenceNumber, int errorIndication) {
    if (*array == NULL || capacity <= 0) {
        return -1; // Array is empty or invalid
    }

    for (size_t i = 0; i < capacity; i++) {
        if (((*array)[i]).sequenceNumber == sequenceNumber) {
            ((*array)[i]).errorIndication = errorIndication;
            return 0; // Success
        }
    }

    return -2; // PDU not found in the array
}

void lteUplinkPdcpPduArrayFree(LTE_Uplink_PDCP_PDU** array, size_t capacity) {
    if (*array != NULL) {
        freeMemory(*array);
    }
}
