// Initialize dynamic array of PDUs
void initPDUArray(LTE_Uplink_PDCP_PDU **pduArray, int *arraySize) {
    *arraySize = 1; // Initial size is 1
    *pduArray = (LTE_Uplink_PDCP_PDU *)malloc(*arraySize * sizeof(LTE_Uplink_PDCP_PDU));
}

// Add new PDU to the array
void addPDU(LTE_Uplink_PDCP_PDU **pduArray, int *arraySize, LTE_Uplink_PDCP_PDU *newPDU) {
    // Create a new array with increased size
    int newSize = *arraySize + 1;
    LTE_Uplink_PDCP_PDU *newArray = (LTE_Uplink_PDCP_PDU *)malloc(newSize * sizeof(LTE_Uplink_PDCP_PDU));

    // Copy existing PDUs to the new array
    for (int i = 0; i < *arraySize; i++) {
        newArray[i] = (*pduArray)[i];
    }

    // Add the new PDU to the end of the array
    newArray[*arraySize - 1] = *newPDU;

    // Update the array size and pointer
    free(*pduArray);
    *pduArray = newArray;
    *arraySize = newSize;
}

// Retrieve a specific PDU by its sequence number (SN)
LTE_Uplink_PDCP_PDU *getPDU(LTE_Uplink_PDCP_PDU **pduArray, int arraySize, int SN) {
    for (int i = 0; i < arraySize; i++) {
        if ((*pduArray)[i].SN == SN) {
            return &(*pduArray)[i];
        }
    }
    return NULL;
}

// Update the error indication for a given PDU
void updateErrorIndication(LTE_Uplink_PDCP_PDU **pduArray, int arraySize, int SN, int newErrorIndication) {
    for (int i = 0; i < arraySize; i++) {
        if ((*pduArray)[i].SN == SN) {
            (*pduArray)[i].errorIndication = newErrorIndication;
            return;
        }
    }
}

// Clean up unused or outdated PDUs periodically
void cleanUpPDUArray(LTE_Uplink_PDCP_PDU **pduArray, int *arraySize) {
    // Implement periodic cleanup logic here
}

// Main function to manage the dynamic array of PDUs
int main() {
    LTE_Uplink_PDCP_PDU *pduArray;
    int arraySize;

    initPDUArray(&pduArray, &arraySize);

    // Add new PDUs to the array
    addPDU(&pduArray, &arraySize, (LTE_Uplink_PDCP_PDU){1, 100, 0});
    addPDU(&pduArray, &arraySize, (LTE_Uplink_PDCP_PDU){2, 200, 0});

    // Retrieve a specific PDU by its sequence number
    LTE_Uplink_PDCP_PDU *targetPDU = getPDU(&pduArray, arraySize, 1);

    if (targetPDU != NULL) {
        printf("Retrieved PDU with SN %d and SDU size %d\n", targetPDU->SN, targetPDU->SDUSize);
    } else {
        printf("No PDU found with SN 1.\n");
    }

    // Update the error indication for a given PDU
    updateErrorIndication(&pduArray, arraySize, 1, 1);

    // Clean up unused or outdated PDUs periodically
    cleanUpPDUArray(&pduArray, &arraySize);

    return 0;
}

