public class DirectoryCounter {
    public static int countDistinctDirectories(Set<String> filePaths) {
        Set<String> directories = new HashSet<>();
        long startTime = System.nanoTime();

        for (String filePath : filePaths) {
            File file = new File(filePath);
            while (file != null && !file.isDirectory()) {
                file = file.getParentFile();
            }
            if (file != null && file.isDirectory() && !directories.add(file.getAbsolutePath())) {
                // Log the duplicate directory path
                System.out.println("Duplicate directory: " + file.getAbsolutePath());
            }
        }

        long endTime = System.nanoTime();
        System.out.println("Time taken to process directories: " + (endTime - startTime) / 1_000_000 + " milliseconds");

        return directories.size();
    }
}
