#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_PDU_SIZE 1024
#define MEMORY_THRESHOLD 10
#define LOG_INTERVAL 1

typedef struct LTE_Uplink_PDCP_PDU {
    int32_t sequence_number;
    uint16_t sd_size;
    uint8_t error_indication;
    time_t timestamp;
} LTE_Uplink_PDCP_PDU;

void *lte_pdcps_array = NULL;
size_t lte_pdcps_array_size = 0;
int lte_pdcps_array_count = 0;
mode_t lte_pdcps_mode = NORMAL_MODE;

void process_pdu(LTE_Uplink_PDCP_PDU pdu) {
    // validate PDU
    if (pdu.sequence_number < 0 || pdu.sd_size > MAX_PDU_SIZE) {
        // log error and skip processing
        return;
    }

    // add to array or update existing PDU
    pthread_mutex_lock(&array_mutex);
    if (!lte_pdcps_array) {
        lte_pdcps_array = malloc(MAX_PDU_SIZE * sizeof(LTE_Uplink_PDCP_PDU));
        lte_pdcps_array_size = MAX_PDU_SIZE;
    }
    for (size_t i = 0; i < lte_pdcps_array_count; i++) {
        if (lte_pdcps_array[i].sequence_number == pdu.sequence_number) {
            // update existing PDU
            memcpy(&lte_pdcps_array[i], &pdu, sizeof(LTE_Uplink_PDCP_PDU));
            pthread_mutex_unlock(&array_mutex);
            return;
        }
    }

    // add new PDU to array if within memory constraints
    if (lte_pdcps_array_count < lte_pdcps_array_size && 
        (lte_pdcps_array_size * sizeof(LTE_Uplink_PDCP_PDU) + 
         sizeof(LTE_Uplink_PDCP_PDU)) <= getrlimit(RLIMIT_AS).rlim_cur) {
        memcpy(&lte_pdcps_array[lte_pdcps_array_count], &pdu, sizeof(LTE_Uplink_PDCP_PDU));
        lte_pdcps_array_count++;
    } else {
        // log memory error and skip processing
        return;
    }

    pthread_mutex_unlock(&array_mutex);
}

LTE_Uplink_PDCP_PDU *get_pdu_by_sequence_number(int32_t sequence_number) {
    for (size_t i = 0; i < lte_pdcps_array_count; i++) {
        if (lte_pdcps_array[i].sequence_number == sequence_number) {
            return &lte_pdcps_array[i];
        }
    }
    return NULL;
}

void update_pdu_error(int32_t sequence_number, uint8_t error_indication) {
    LTE_Uplink_PDCP_PDU *pdu = get_pdu_by_sequence_number(sequence_number);
    if (pdu) {
        pdu->error_indication = error_indication;
    }
}

void remove_old_pus(time_t threshold) {
    pthread_mutex_lock(&array_mutex);
    for (size_t i = 0; i < lte_pdcps_array_count; i++) {
        if (lte_pdcps_array[i].timestamp <= threshold) {
            // compress array if necessary
            if (!lte_pdcps_array_size / 2) {
                size_t new_size = lte_pdcps_array_count * sizeof(LTE_Uplink_PDCP_PDU);
                void *new_array = realloc(lte_pdcps_array, new_size);
                if (new_array) {
                    lte_pdcps_array = new_array;
                    lte_pdcps_array_size = new_size / sizeof(LTE_Uplink_PDCP_PDU);
                }
            }

            // remove PDU
            memmove(&lte_pdcps_array[i], &lte_pdcps_array[i+1], 
                    (lte_pdcps_array_count - i) * sizeof(LTE_Uplink_PDCP_PDU));
            lte_pdcps_array_count--;
        }
    }
    pthread_mutex_unlock(&array_mutex);
}

void log_performance() {
    static time_t last_log = 0;
    if ((time(NULL) - last_log) >= LOG_INTERVAL) {
        last_log = time(NULL);

        // calculate metrics
        int32_t pdus_processed = 0;
        for (size_t i = 0; i < lte_pdcps_array_count; i++) {
            pdus_processed++;
        }
        double avg_time_per_pdu = 0.0;

        // log performance and memory statistics
        printf("PDU processed per second: %d\n", pdus_processed);
        printf("Average time taken to process each PDU: %.2f sec\n", avg_time_per_pdu);
        printf("Memory usage statistics: %d%%\n", 
               (int)((double)getrlimit(RLIMIT_AS).rlim_cur / getpagesize() * 100));
    }
}

void lte_pdcps_manager(int mode) {
    if (mode != NORMAL_MODE && mode != STRESS_TEST_MODE) {
        // log error
        return;
    }

    // set mode and logging interval based on the specified mode
    lte_pdcps_mode = mode;

    while (1) {
        // process PDUs in loop to avoid thread starvation
        LTE_Uplink_PDCP_PDU pdu;
        int32_t sequence_number, sd_size;
        uint8_t error_indication;
        time_t timestamp;

        // simulate high load conditions for stress test mode
        if (lte_pdcps_mode == STRESS_TEST_MODE) {
            for (int i = 0; i < 10000; i++) {
                sequence_number = rand();
                sd_size = rand() % MAX_PDU_SIZE;
                error_indication = rand() % 2;
                timestamp = time(NULL);

                // validate and process PDU
                if (!process_pdu((LTE_Uplink_PDCP_PDU) { .sequence_number = sequence_number, 
                                                         .sd_size = sd_size, 
                                                         .error_indication = error_indication, 
                                                         .timestamp = timestamp })) {
                    break;
                }
            }

            // simulate PDU retrieval and updating
            for (int i = 0; i < 10000; i++) {
                sequence_number = rand();
                pdu = *get_pdu_by_sequence_number(sequence_number);

                if (pdu) {
                    error_indication = rand() % 2;
                    update_pdu_error(sequence_number, error_indication);
                }
            }

            // simulate PDU removal
            for (int i = 0; i < 10000; i++) {
                sequence_number = rand();
                remove_old_pus(time(NULL) - timestamp);
            }
        } else {
            // process PDUs in normal mode
            while (1) {
                sequence_number = read_sequence_number();
                sd_size = read_sdu_size();
                error_indication = read_error_indication();
                timestamp = time(NULL);

                // validate and process PDU
                if (!process_pdu((LTE_Uplink_PDCP_PDU) { .sequence_number = sequence_number, 
                                                         .sd_size = sd_size, 
                                                         .error_indication = error_indication, 
                                                         .timestamp = timestamp })) {
                    break;
                }

                // log performance and memory statistics periodically
                if ((time(NULL) - last_log) >= LOG_INTERVAL) {
                    log_performance();
                }
            }
        }
    }
}
