```
use std::sync::{mpsc, Arc};
use std::thread;
use chrono::prelude::*;
use notify_rust::Notify;

struct HealthChecker {
    services: Vec<String>,
    threshold: u32,
    email_notify: bool,
    email_recipient: String,
}

impl HealthChecker {
    fn new(services: Vec<String>, threshold: u32, email_notify: bool, email_recipient: String) -> Self {
        HealthChecker { 
            services, 
            threshold, 
            email_notify, 
            email_recipient 
        }
    }

    fn check_services(&self) {
        for service in &self.services {
            if !service.is_running() {
                if self.email_notify {
                    let notify = Notify::new().show();
                    notify.alert("Service Down", &format!("{} is down!", service)).unwrap();
                }
            }
        }
    }

    fn start_thread(&self) {
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(60 * 60)); // check every hour
            self.check_services();
        });
    }
}
