class ModuleLoader {
  constructor() {
    this.modules = {};
    this.loadQueue = [];
    this.concurrentRequests = 0;
  }

  loadModule(name) {
    if (!this.modules[name]) {
      this.loadQueue.push(name);
      this.loadNext();
    }
  }

  loadNext() {
    if (this.concurrentRequests >= 5) return; // throttle concurrent requests

    const nextModule = this.loadQueue.shift();
    this.concurrentRequests++;

    fetch(`module/${nextModule}.js`)
      .then(response => response.text())
      .then(script => {
        this.execScript(nextModule, script);
      })
      .catch(error => {
        console.error(`Error loading ${nextModule}:`, error);
        this.loadQueue.push(nextModule); // failed load, retry later
      })
      .finally(() => {
        this.concurrentRequests--;
        if (this.loadQueue.length) this.loadNext();
      });
  }

  execScript(name, script) {
    try {
      eval(script);
    } catch (error) {
      console.error(`Error executing ${name}:`, error);
    }
  }

  // fallback or polyfill for unsupported features
  checkBrowserCompatibility() {
    if (!window.Promise) {
      // implement a Promise-like API or use a polyfill
    }
  }
}

const loader = new ModuleLoader();
loader.loadModule('main');
