#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000

typedef struct {
    int sequenceNumber;
    int sdusize;
    int errorIndicator;
} LTE_Uplink_PDCP_PDU;

void* operator new(size_t size) {
    return malloc(size);
}

void operator delete(void* ptr) {
    free(ptr);
}

class PDCPArray {
private:
    LTE_Uplink_PDCP_PDU** pdus;
    int size;
    int maxsize;
    pthread_mutex_t mutex;

public:
    PDCPArray() : size(0), maxsize(MAX_SIZE), pdus(NULL) {
        pdus = new LTE_Uplink_PDCP_PDU*[maxsize];
        for (int i = 0; i < maxsize; i++) {
            pdus[i] = NULL;
        }
        pthread_mutex_init(&mutex, NULL);
    }

    ~PDCPArray() {
        if (pdus) {
            for (int i = 0; i < size; i++) {
                delete pdus[i];
            }
            delete[] pdus;
        }
        pthread_mutex_destroy(&mutex);
    }

    bool addPDU(LTE_Uplink_PDCP_PDU* pdu) {
        if (size >= maxsize) {
            printf("Warning: Array is full, cannot add more PDUs.\n");
            return false;
        }
        pdus[size] = new LTE_Uplink_PDCP_PDU(*pdu);
        size++;
        return true;
    }

    LTE_Uplink_PDCP_PDU* getPDUS(int sequenceNumber) {
        for (int i = 0; i < size; i++) {
            if (pdus[i]->sequenceNumber == sequenceNumber) {
                return pdus[i];
            }
        }
        return NULL;
    }

    bool updateErrorIndicator(int sequenceNumber, int errorIndicator) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < size; i++) {
            if (pdus[i]->sequenceNumber == sequenceNumber) {
                pdus[i]->errorIndicator = errorIndicator;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
        return true;
    }

    bool resizeArray(int newSize) {
        if (newSize > maxsize) {
            printf("Warning: Attempting to resize array beyond maximum allowed size.\n");
            return false;
        }
        LTE_Uplink_PDCP_PDU** newPDUs = new LTE_Uplink_PDCP_PDU*[newSize];
        for (int i = 0; i < newSize; i++) {
            newPDUs[i] = NULL;
        }

        pthread_mutex_lock(&mutex);
        int j = 0;
        for (int i = 0; i < size; i++) {
            if (pdus[i]) {
                newPDUs[j] = pdus[i];
                j++;
            }
        }
        delete[] pdus;
        pdus = newPDUs;
        maxsize = newSize;
        size = j;
        pthread_mutex_unlock(&mutex);

        return true;
    }
};
