```java
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class TaskManager {
    public void manageAsynchronousTaskQueue(int numThreads, int maxPoolSize) throws Exception {
        final BlockingQueue<Runnable> taskQueue = new LinkedBlockingQueue<>();
        ThreadPoolExecutor executor = new ThreadPoolExecutor(numThreads, maxPoolSize, 0L, TimeUnit.MILLISECONDS);

        // fetch tasks from external data source
        List<Task> tasks = fetchDataFromDataSource();

        for (Task task : tasks) {
            taskQueue.put(task);
        }

        try {
            while (!taskQueue.isEmpty()) {
                executor.submit(() -> {
                    Task task = taskQueue.take();
                    try {
                        task.execute();
                    } catch (Exception e) {
                        // handle exceptions
                        logger.error("Error processing task: {}", e.getMessage());
                    }
                });
            }
        } finally {
            executor.shutdown();
        }
    }
}
