ImageMetadata* processImageMetadata(const char* filePath) {
    char buffer[256];
    sprintf(buffer, "metadata-%s.txt", filePath);

    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        return NULL; // handle error
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    ImageMetadata* metadata = (ImageMetadata*) malloc(sizeof(ImageMetadata));
    fread(metadata->format, sizeof(metadata->format), 1, file);
    metadata->width = atoi(fread(buffer, sizeof(int), 1, file));
    metadata->height = atoi(fread(buffer, sizeof(int), 1, file));

    fclose(file);

    return metadata;
}

