int* validRntiRanges = (int*)malloc(2 * sizeof(int));
validRntiRanges[0] = 1000000; // Range start value
validRntiRanges[1] = 2000000; // Range end value

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populateNfaPiList(int n, int** list, int* listSize) {
    srand(time(NULL)); // Seed random number generator

    // Initialize the list with a default size
    *list = (int*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *listSize = n;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate a random RNTI value
        int rnti = rand() % ((validRntiRanges[1] - validRntiRanges[0]) + 1) + validRntiRanges[0];

        // Validate the RNTI value against the predefined ranges
        if (!isValidRnti(rnti, listSize)) {
            i--; // Discard invalid RNTI and retry
            continue;
        }

        // Generate a random CRC flag value
        pdu.crcflag = (unsigned char)rand();

        (*list)[i] = pdu; // Add the structure to the list
    }
}

// Helper function to validate an RNTI value against the predefined ranges
int isValidRnti(int rnti, int* listSize) {
    for (int i = 0; i < *listSize; i++) {
        if ((*list)[i].rnti == rnti) return 0; // Duplicate RNTI detected
    }

    // Check if the RNTI value falls within a valid range
    if (rnti >= validRntiRanges[0] && rnti <= validRntiRanges[1]) {
        return 1;
    }

    return 0; // Invalid RNTI
}

// Function to dynamically resize the list and prune unused structures
void resizeAndPruneList(int** list, int* listSize) {
    if (*listSize < (int)sqrt(2 * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        // Dynamic resizing based on memory efficiency considerations
        *list = (int*)realloc(*list, 2 * (*listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        *listSize *= 2;
    }

    for (int i = *listSize - 1; i >= 0; i--) {
        if ((*list)[i].rnti == 0) { // Prune unused structures
            memmove(*list + i, *list + i + 1, (*listSize - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *listSize--;
            i--; // Decrement the index to avoid overwriting the same element again
        }
    }
}

// Function to integrate with a logging module
void logNfaPiList(int** list, int* listSize, int numValidRnti, int numDuplicateRnti) {
    printf("Valid RNTI checks: %d\n", numValidRnti);
    printf("Duplicate RNTI detections: %d\n", numDuplicateRnti);
}

int main() {
    int n = 1000; // Number of NFAPI_CRC_INDICATION_PDU_T structures to create
    int* list;
    int listSize;

    populateNfaPiList(n, &list, &listSize);
    resizeAndPruneList(&list, &listSize);
    logNfaPiList(&list, &listSize, 1000, 20); // Example logging output

    free(list);
    return 0;
}
