```java
import java.util.*;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;

public class DynamicTaskManager {
    private static final int DEFAULT_CACHE_SIZE = 1000;
    private static final int DEFAULT_MAX_THREADS = 5;
    private static final int MAX_CACHE_SIZE = 10000;

    private final ExecutorService executorService;
    private final Cache cache;
    private final Logger logger;

    public DynamicTaskManager() {
        this.executorService = new ThreadPoolExecutor(DEFAULT_MAX_THREADS, DEFAULT_MAX_THREADS, 0L, TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<Runnable>());
        this.cache = new LruCache(DEFAULT_CACHE_SIZE);
        this.logger = LoggerFactory.getLogger(DynamicTaskManager.class);
    }

    // Task management methods
    public <T> Future<T> submit(Runnable task) {
        return executorService.submit(task);
    }

    public List<TaskResult> getResults() {
        List<TaskResult> results = new ArrayList<>();
        for (Future<?> future : executorService.getCompletedTaskCount()) {
            try {
                Object result = future.get();
                results.add((TaskResult) result);
            } catch (ExecutionException e) {
                logger.error("Task execution failed", e);
            }
        }
        return results;
    }

    // Caching mechanism
    public <T> T getFromCache(String key, Class<T> clazz) {
        return cache.get(key, clazz);
    }

    public void putInCache(String key, Object value) {
        cache.put(key, value);
    }

    private class LruCache<K, V> {
        private final int capacity;
        private final Map<K, V> map;

        public LruCache(int capacity) {
            this.capacity = capacity;
            this.map = new LinkedHashMap<K, V>(capacity, 0.75f, true) {
                @Override
                protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                    return size() > capacity;
                }
            };
        }

        public <T> T get(K key, Class<T> clazz) {
            return (T) map.get(key);
        }

        public void put(K key, V value) {
            map.put(key, value);
        }
    }

    // Logging mechanism
    public void logTaskProgress(String taskName, TaskResult result) {
        logger.info("Task {} completed with result {}", taskName, result);
    }

    public void logTaskFailure(String taskName, Exception e) {
        logger.error("Task {} failed", taskName, e);
    }

    // Image metadata processing method
    public ImageMetadata processImageMetadata(String filePath) throws IOException {
        File file = new File(filePath);
        String format = getFileFormat(file.getName());
        if (format == null || !isValidFormat(format)) {
            throw new InvalidFormatException("Unsupported format: " + file.getName());
        }

        // Read metadata from the first few bytes of the file
        ImageMetadata metadata;
        try (FileInputStream fis = new FileInputStream(file);
             DataInputStream dis = new DataInputStream(new BufferedInputStream(fis))) {
            int width = dis.readInt();
            int height = dis.readInt();
            String compressionType = dis.readUTF();

            metadata = new ImageMetadata(width, height, format, compressionType);
        } catch (IOException e) {
            logger.error("Failed to read image metadata", e);
            throw new IOException("Failed to read image metadata");
        }

        return metadata;
    }

    private static String getFileFormat(String fileName) {
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex == -1) {
            return null;
        }
        return fileName.substring(dotIndex + 1).toLowerCase();
    }

    // Validate the format based on its extension
    private boolean isValidFormat(String format) {
        // TO DO: implement a list of supported formats and their extensions
        return true; // for simplicity, assume all formats are valid
    }

    // File streaming method
    public InputStream streamFileContent(String filePath, int bufferSize) throws IOException {
        File file = new File(filePath);
        try (FileInputStream fis = new FileInputStream(file)) {
            return new BufferedInputStream(new ChunkedInputStream(fis, bufferSize));
        }
    }

    private class ChunkedInputStream extends FilterInputStream {
        private final int bufferSize;

        public ChunkedInputStream(InputStream in, int bufferSize) {
            super(in);
            this.bufferSize = bufferSize;
        }

        @Override
        public int read() throws IOException {
            return in.read();
        }

        @Override
        public int read(byte[] b) throws IOException {
            return in.read(b);
        }

        @Override
        public long skip(long n) throws IOException {
            return in.skip(n);
        }
    }
}
