// Define the logging function with thread-safe and structured logging capabilities
void log(const char *level, const char *message, ...) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static FILE *log_file = fopen("log.txt", "a");

    if (log_file == NULL) {
        printf("Error: Could not open log file.\n");
        return;
    }

    // Get the current timestamp
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    char timestamp_str[64];
    strftime(timestamp_str, 64, "%Y-%m-%d %H:%M:%S", timestamp);

    pthread_mutex_lock(&mutex);

    // Check if the message exceeds the maximum allowed length (1024 characters)
    int len = strlen(message);
    if (len > 1024) {
        va_list ap;
        va_start(ap, message);
        vfprintf(log_file, "WARNING: Log message truncated to %d characters.\n", 1024);
        va_end(ap);
        fprintf(log_file, "%s | %s | ", timestamp_str, level);
        fwrite(message, len > 1024 ? 1023 : len, 1, log_file);
    } else {
        va_list ap;
        va_start(ap, message);
        vfprintf(log_file, "%s | %s | ", timestamp_str, level);
        vfprintf(log_file, message, ap);
        va_end(ap);
    }

    pthread_mutex_unlock(&mutex);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int N) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pdu_list[i].RNTI = rand() % 10000;
        pdu_list[i].CRCFLAG = rand() % 2;

        log(INFO, "Created CRC indication PDU with RX UE INFO tag: %d, RNTI: %d, and CRC flag: %d.", pdu_list[i].RX_UE_INFORMATION_TAG, pdu_list[i].RNTI, pdu_list[i].CRCFLAG);
    }

    return pdu_list;
}
