typedef struct {
    int SN;
    size_t SDU_size;
    int error_indication;
    time_t timestamp;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    clock_t age_threshold;
} PDCP_PDU_Array;

PDCP_PDU_Array* pdcppdu_array_init(size_t initial_capacity) {
    PDCP_PDU_Array* array = (PDCP_PDU_Array*)malloc(sizeof(PDCP_PDU_Array));
    array->pdus = (LTE_Uplink_PDCP_PDU*)calloc(initial_capacity, sizeof(LTE_Uplink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond, NULL);
    array->age_threshold = clock() + (CLOCKS_PER_SEC * 60); // set the age threshold to 1 minute
    return array;
}

void pdcppdu_array_free(PDCP_PDU_Array* array) {
    for(size_t i = 0; i < array->size; i++) {
        free(&array->pdus[i]);
    }
    free(array->pdus);
    pthread_mutex_destroy(&array->mutex);
    pthread_cond_destroy(&array->cond);
    free(array);
}

LTE_Uplink_PDCP_PDU* pdcppdu_array_add(PDCP_PDU_Array* array, int SN, size_t SDU_size, int error_indication) {
    if (array->size >= array->capacity) {
        // resize the array
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, sizeof(LTE_Uplink_PDCP_PDU)*(array->capacity*2));
        array->capacity *= 2;
    }
    LTE_Uplink_PDCP_PDU* pdu = &array->pdus[array->size];
    pdu->SN = SN;
    pdu->SDU_size = SDU_size;
    pdu->error_indication = error_indication;
    pdu->timestamp = clock();
    array->size++;
    return pdu;
}

LTE_Uplink_PDCP_PDU* pdcppdu_array_get(PDCP_PDU_Array* array, int SN) {
    for(size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

void pdcppdu_array_update_error(PDCP_PDU_Array* array, int SN, int error_indication) {
    for(size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            array->pdus[i].error_indication = error_indication;
            break;
        }
    }
}

void pdcppdu_array_remove_by_timestamp(PDCP_PDU_Array* array, time_t timestamp) {
    for(size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].timestamp <= timestamp) {
            // move the last PDU to this position and decrement the size
            array->pdus[i] = array->pdus[--array->size];
            i--;
        }
    }
}

void pdcppdu_array_remove_by_SN(PDCP_PDU_Array* array, int SN) {
    for(size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            // move the last PDU to this position and decrement the size
            array->pdus[i] = array->pdus[--array->size];
            i--;
        }
    }
}

void pdcppdu_array_clean_up(PDCP_PDU_Array* array, clock_t current_time) {
    for(size_t i = 0; i < array->size; i++) {
        if (current_time - array->pdus[i].timestamp > array->age_threshold) {
            // remove the PDU
            array->pdus[i] = array->pdus[--array->size];
            i--;
        }
    }
}

void pdcppdu_array_reorder(PDCP_PDU_Array* array) {
    for(size_t i = 0; i < array->size - 1; i++) {
        for(size_t j = i + 1; j < array->size; j++) {
            if (array->pdus[i].SN > array->pdus[j].SN) {
                // swap the PDUs
                LTE_Uplink_PDCP_PDU temp = array->pdus[i];
                array->pdus[i] = array->pdus[j];
                array->pdus[j] = temp;
            }
        }
    }
}

void pdcppdu_array_update_age_threshold(PDCP_PDU_Array* array, clock_t new_threshold) {
    array->age_threshold = new_threshold;
}
