} NFAPI_CRC_INDICATION_PDU_ARRAY_T;

NFAPI_CRC_INDICATION_PDU_ARRAY_T* nfapi_crc_indication_pdu_array_create(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_ARRAY_T* array = malloc(sizeof(NFAPI_CRC_INDATION_PDU_ARRAY_T));
    if (!array) return NULL;
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    NFAPI_CRC_INDICATION_PDU_T* entry = &array->data[array->size++];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
