pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} pdpQueue = {NULL, 0, 0, lock};

void lteUplinkPdcPduQueueInit() {
    pdpQueue.capacity = LTE_UPLINK_PDCP_PDU_QUEUE_CAPACITY;
    pdpQueue.pdus = (LTE_Uplink_PDCP_PDU*)malloc(pdpQueue.capacity * sizeof(LTE_Uplink_PDCP_PDU));
    pthread_mutex_init(&pdpQueue.lock, NULL);
}

void lteUplinkPdcPduQueueAdd(LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&pdpQueue.lock);
    if (pdpQueue.count == pdpQueue.capacity) {
        // Queue is full, wait for space to become available
        pthread_cond_wait(&cond, &pdpQueue.lock);
    }
    memcpy(pdpQueue.pdus + pdpQueue.count++, pdu, sizeof(LTE_Uplink_PDCP_PDU));
    if (pdpQueue.count == pdpQueue.capacity) {
        // Wake up any waiting threads
        pthread_cond_broadcast(&cond);
    }
    pthread_mutex_unlock(&pdpQueue.lock);
}

LTE_Uplink_PDCP_PDU* lteUplinkPdcPduQueueGet(uint32_t sequenceNumber) {
    pthread_mutex_lock(&pdpQueue.lock);
    for (size_t i = 0; i < pdpQueue.count; i++) {
        if (pdpQueue.pdus[i].sequenceNumber == sequenceNumber) {
            LTE_Uplink_PDCP_PDU* pdu = &pdpQueue.pdus[i];
            pthread_mutex_unlock(&pdpQueue.lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&pdpQueue.lock);
    return NULL;
}

void lteUplinkPdcPduQueueUpdateErrorIndication(uint32_t sequenceNumber, uint8_t errorIndication) {
    pthread_mutex_lock(&pdpQueue.lock);
    for (size_t i = 0; i < pdpQueue.count; i++) {
        if (pdpQueue.pdus[i].sequenceNumber == sequenceNumber) {
            pdpQueue.pdus[i].errorIndication = errorIndication;
            pthread_mutex_unlock(&pdpQueue.lock);
            return;
        }
    }
    pthread_mutex_unlock(&pdpQueue.lock);
}

void lteUplinkPdcPduQueueRemoveOldPdus(uint64_t thresholdTimestamp) {
    pthread_mutex_lock(&pdpQueue.lock);
    size_t i = 0;
    while (i < pdpQueue.count) {
        if (pdpQueue.pdus[i].timestamp <= thresholdTimestamp) {
            // Remove old PDUs
            memmove(pdpQueue.pdus + i, pdpQueue.pdus + i + 1, sizeof(LTE_Uplink_PDCP_PDU) * (pdpQueue.count - i - 1));
            pdpQueue.count--;
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&pdpQueue.lock);
}

void lteUplinkPdcPduQueueCleanup() {
    while (pdpQueue.count > 0) {
        size_t i = 0;
        while (i < pdpQueue.count) {
            if (pdpQueue.pdus[i].timestamp <= pdpQueue.pdus[0].timestamp - LTE_UPLINK_PDCP_PDU_CLEANUP_THRESHOLD) {
                // Remove old PDUs
                memmove(pdpQueue.pdus + i, pdpQueue.pdus + i + 1, sizeof(LTE_Uplink_PDCP_PDU) * (pdpQueue.count - i - 1));
                pdpQueue.count--;
            } else {
                break;
            }
        }
    }
}

void lteUplinkPdcPduQueueReorder() {
    pthread_mutex_lock(&pdpQueue.lock);
    for (size_t i = 0; i < pdpQueue.count - 1; i++) {
        size_t j = i + 1;
        while (j < pdpQueue.count) {
            if (pdpQueue.pdus[i].sequenceNumber > pdpQueue.pdus[j].sequenceNumber) {
                // Swap PDUs
