#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    int SDU_size;
    int error_indication;
    long timestamp;
} PDU;

void* operator new(size_t size) {
    return malloc(size);
}

void operator delete(void* p) {
    free(p);
}

class LTE_UPDUQueue {
public:
    void enqueue(PDU pdu) {
        if (!pq.empty()) {
            if (pdu.timestamp < pq.top()->timestamp)
                pq.push(pdu);
            else
                pq.push(*new PDU[pq.size()]);
        } else pq.push(pdu);
    }

    PDU dequeue() {
        if (pq.empty()) throw runtime_error("Queue is empty");
        PDU temp = *pq.top();
        pq.pop();
        return temp;
    }

    bool isEmpty() {
        return pq.empty();
    }
private:
    priority_queue<PDU> pq;
};

class LTE_UPDUManager {
public:
    void init(LTE_UPDUQueue* upduQ) {
        this->upduQ = upduQ;
        pdcps.push_back(NULL);
    }

    bool addPDU(int SN, int SDU_size, int error_indication, long timestamp) {
        PDU pdu;
        pdu.SN = SN;
        pdu.SDU_size = SDU_size;
        pdu.error_indication = error_indication;
        pdu.timestamp = timestamp;

        while (!pdcps.empty() && pdcps.back()->timestamp <= timestamp)
            removePDU();

        upduQ->enqueue(pdu);
    }

    PDU* getSN(int SN) {
        for (int i = 0; i < pdcps.size(); i++) {
            if (pdcps[i]->SN == SN) return &pdcps[i];
        }
        return NULL;
    }

    void updateErrorIndication(int SN, int error_indication) {
        PDU* pdu = getSN(SN);
        if (!pdu) throw runtime_error("PDU not found");
        pdu->error_indication = error_indication;
    }

    void removePDU() {
        while (timestamp >= pdcps[0]->timestamp) {
            delete pdcps[0];
            pdcps.pop_back();
        }
    }
private:
    LTE_UPDUQueue* upduQ;
    vector<PDU*> pdcps;
};

