typedef struct {
    Voice_Call_Session* sessions;
    int size;
    int capacity;
    time_t retention_period;
} Voice_Call_Sessions;

Voice_Call_Sessions* voice_call_sessions_new(time_t retention_period) {
    Voice_Call_Sessions* new_list = (Voice_Call_Sessions*)malloc(sizeof(Voice_Call_Sessions));
    if (!new_list) return NULL;
    new_list->size = 0;
    new_list->capacity = 1;
    new_list->sessions = (Voice_Call_Session*)calloc(new_list->capacity, sizeof(Voice_Call_Session));
    new_list->retention_period = retention_period;
    return new_list;
}

void voice_call_sessions_add_session(Voice_Call_Sessions* list, int id) {
    if (!list || !list->sessions) return;

    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->sessions = (Voice_Call_Session*)realloc(list->sessions, sizeof(Voice_Call_Session) * list->capacity);
    }

    Voice_Call_Session* new_session = &list->sessions[list->size++];
    new_session->id = id;
    new_session->start_time = time(NULL);
    new_session->end_time = 0;
    new_session->duration = 0;
    new_session->network_type = '\0';
}

Voice_Call_Session* voice_call_sessions_get_session(Voice_Call_Sessions* list, int session_id) {
    if (!list || !list->sessions) return NULL;

    for (int i = 0; i < list->size; i++) {
        if (list->sessions[i].id == session_id) {
            return &list->sessions[i];
        }
    }

    return NULL;
}

void voice_call_sessions_update_session(Voice_Call_Sessions* list, int session_id, time_t end_time) {
    Voice_Call_Session* session = voice_call_sessions_get_session(list, session_id);
    if (!session) return;

    session->end_time = end_time;
    session->duration = (int)difftime(end_time, session->start_time);
}

void voice_call_sessions_update_all_durations(Voice_Call_Sessions* list) {
    for (int i = 0; i < list->size; i++) {
        if (list->sessions[i].end_time > 0) {
            list->sessions[i].duration = (int)difftime(list->sessions[i].end_time, list->sessions[i].start_time);
        }
    }
}

void voice_call_sessions_clean_up_old_sessions(Voice_Call_Sessions* list) {
    time_t current_time = time(NULL);

    for (int i = 0; i < list->size; i++) {
        if (list->sessions[i].end_time + list->retention_period <= current_time) {
            for (int j = i + 1; j < list->size; j++) {
                list->sessions[j - 1] = list->sessions[j];
            }
            list->size--;
            i--;
        }
    }

    if (list->size > 0) {
        list->capacity = list->size;
        list->sessions = (Voice_Call_Session*)realloc(list->sessions, sizeof(Voice_Call_Session) * list->size);
    } else {
        free(list->sessions);
        list->size = 0;
        list->capacity = 0;
    }
}

void voice_call_sessions_free(Voice_Call_Sessions* list) {
