#define MAX_SESSIONS 1000
#define RETENTION_PERIOD 60 // in seconds

typedef struct {
    int id;
    time_t start_timestamp;
    int duration;
    char network_type[16];
    int is_active;
} VoiceCallSession;

VoiceCallSession* session_list = NULL;
int num_sessions = 0;
FILE* log_file = fopen("session_log.txt", "w");

void init_session_list() {
    session_list = (VoiceCallSession*)malloc(MAX_SESSIONS * sizeof(VoiceCallSession));
    num_sessions = 0;
}

void add_session(int id, time_t start_timestamp, int duration, char* network_type) {
    if (num_sessions >= MAX_SESSIONS) {
        printf("Out of memory!\n");
        return;
    }

    VoiceCallSession* new_session = &session_list[num_sessions++];
    new_session->id = id;
    new_session->start_timestamp = start_timestamp;
    new_session->duration = duration;
    strcpy(new_session->network_type, network_type);
    new_session->is_active = 1;

    fprintf(log_file, "Added session %d at timestamp %lu\n", id, (unsigned long)start_timestamp);

    // Calculate total call duration for active sessions
    int total_duration = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (session_list[i].is_active)
            total_duration += session_list[i].duration;
    }
    fprintf(log_file, "Total call duration: %d seconds\n", total_duration);
}

VoiceCallSession* get_session(int id) {
    for (int i = 0; i < num_sessions; i++) {
        if (session_list[i].id == id)
            return &session_list[i];
    }
    return NULL;
}

void update_end_timestamp(int id, time_t end_timestamp) {
    VoiceCallSession* session = get_session(id);
    if (!session)
        return;

    session->start_timestamp = end_timestamp;
    fprintf(log_file, "Updated end timestamp for session %d\n", id);
}

int calculate_total_duration() {
    int total_duration = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (session_list[i].is_active)
            total_duration += session_list[i].duration;
    }
    return total_duration;
}

void pause_session(int id) {
    VoiceCallSession* session = get_session(id);
    if (!session)
        return;

    session->is_active = 0;
    fprintf(log_file, "Paused session %d\n", id);
}

void resume_session(int id) {
    VoiceCallSession* session = get_session(id);
    if (!session)
        return;

    session->is_active = 1;
    fprintf(log_file, "Resumed session %d\n", id);
}

void cleanup_sessions() {
    time_t current_timestamp = time(NULL);
    for (int i = num_sessions - 1; i >= 0; i--) {
        if ((current_timestamp - session_list[i].start_timestamp) > RETENTION_PERIOD && !session_list[i].is_active)
            // Remove paused sessions older than retention period
            memmove(&session_list[i], &session_list[++i], (num_sessions - i) * sizeof(VoiceCallSession));
    }
    num_sessions--;
}

void log_operations() {
    fprintf(log_file, "Logged at timestamp %lu\n", time(NULL));
}

int main() {
