#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure to hold a voice call session
typedef struct {
    int id;
    time_t start_timestamp;
    int duration;
    char network_type[16];
    int is_active;
} Voice_Call_Session;

// Function prototypes
Voice_Call_Session* create_session(int id, const char* network_type);
void add_session(Voice_Call_Session** sessions, int num_sessions, Voice_Call_Session* new_session);
Voice_Call_Session* get_session(Voice_Call_Session** sessions, int num_sessions, int session_id);
void update_end_timestamp(Voice_Call_Session** sessions, int num_sessions, int session_id);
int calculate_total_duration_active_sessions(Voice_Call_Session** sessions, int num_sessions);
void pause_session(Voice_Call_Session** sessions, int num_sessions, int session_id);
void resume_session(Voice_Call_Session** sessions, int num_sessions, int session_id);
void log_operation(const char* operation, time_t timestamp);
void serialize_sessions(Voice_Call_Session** sessions, int num_sessions);
void deserialize_sessions(Voice_Call_Session*** sessions_ptr, int* num_sessions);

// Function to initialize and manage a dynamic list of Voice Call Session structures
void voice_call_session_manager(int max_num_sessions) {
    // Initialize the session list and number of sessions
    Voice_Call_Session** sessions = (Voice_Call_Session**)malloc(max_num_sessions * sizeof(Voice_Call_Session*));
    int num_sessions = 0;

    // Function to create a new session structure
    Voice_Call_Session* create_session(int id, const char* network_type) {
        Voice_Call_Session* new_session = (Voice_Call_Session*)malloc(sizeof(Voice_Call_Session));
        new_session->id = id;
        strcpy(new_session->network_type, network_type);
        new_session->start_timestamp = time(NULL);
        new_session->duration = 0;
        new_session->is_active = 1;
        return new_session;
    }

    // Function to add a new session to the list
    void add_session(Voice_Call_Session** sessions, int num_sessions, Voice_Call_Session* new_session) {
        // Check if the session is within the maximum allowed number of sessions
        if (num_sessions >= max_num_sessions) {
            printf("Error: Maximum number of sessions reached.\n");
            return;
        }
        // Add the new session to the list and increment the number of sessions
        sessions[num_sessions] = new_session;
        num_sessions++;
    }

    // Function to retrieve a specific session by its ID
    Voice_Call_Session* get_session(Voice_Call_Session** sessions, int num_sessions, int session_id) {
        for (int i = 0; i < num_sessions; i++) {
            if (sessions[i]->id == session_id) {
                return sessions[i];
            }
        }
        // Return NULL if the session is not found
        return NULL;
    }

    // Function to update the end timestamp of a given session
    void update_end_timestamp(Voice_Call_Session** sessions, int num_sessions, int session_id) {
        Voice_Call_Session* session = get_session(sessions, num_sessions, session_id);
        if (session == NULL || session->is_active != 1) {
            printf("Error: Session not found or is inactive.\n");
            return;
        }
        session->end_timestamp = time(NULL);
    }

    // Function to calculate the total call duration for all active sessions
    int calculate_total_duration_active_sessions(Voice_Call_Session** sessions, int num_sessions) {
        int total_duration = 0;
        for (int i = 0; i < num_sessions; i++) {
            if (sessions[i]->is_active == 1) {
                total_duration += sessions[i]->duration;
            }
        }
        return total_duration;
    }

    // Function to pause a session, marking it as inactive but retaining all its data
    void pause_session(Voice_Call_Session** sessions, int num_sessions, int session_id) {
        Voice_Call_Session* session = get_session(sessions, num_sessions, session_id);
        if (session == NULL || session->is_active != 1) {
            printf("Error: Session not found or is inactive.\n");
            return;
        }
        session->is_active = 0;
    }

    // Function to resume a paused session by setting its status back to active
    void resume_session(Voice_Call_Session** sessions, int num_sessions, int session_id) {
        Voice_Call_Session* session = get_session(sessions, num_sessions, session_id);
        if (session == NULL || session->is_active != 0) {
            printf("Error: Session not found or is already active.\n");
            return;
        }
        session->is_active = 1;
    }

    // Function to log all operations performed on the session list
    void log_operation(const char* operation, time_t timestamp) {
        printf("%s at %s\n", operation, ctime(&timestamp));
    }

    // Function to serialize the session list to disk
    void serialize_sessions(Voice_Call_Session** sessions, int num_sessions) {
        FILE* file = fopen("sessions.txt", "w");
        if (file == NULL) {
            printf("Error: Unable to open file.\n");
            return;
        }
        for (int i = 0; i < num_sessions; i++) {
            fprintf(file, "%d %ld %s %d\n", sessions[i]->id, sessions[i]->start_timestamp, sessions[i]->network_type, sessions[i]->is_active);
        }
        fclose(file);
    }

    // Function to deserialize the session list from disk
    void deserialize_sessions(Voice_Call_Session*** sessions_ptr, int* num_sessions) {
        FILE* file = fopen("sessions.txt", "r");
        if (file == NULL) {
            printf("Error: Unable to open file.\n");
            return;
        }
        *num_sessions = 0;
        Voice_Call_Session** new_sessions = (Voice_Call_Session**)malloc(10 * sizeof(Voice_Call_Session*));
        while (!feof(file)) {
            Voice_Call_Session* new_session = (Voice_Call_Session*)malloc(sizeof(Voice_Call_Session));
            fscanf(file, "%d %ld %s %d\n", &new_session->id, &new_session->start_timestamp, new_session->network_type, &new_session->is_active);
            add_session(new_sessions, *num_sessions, new_session);
            (*num_sessions)++;
        }
        free(new_sessions);
        fclose(file);
    }

    // Main function to manage the dynamic list of Voice Call Session structures
    int main() {
        // Initialize and manage the session list
        voice_call_session_manager(10);

        return 0;
    }
