#define MAX_ELEMENTS 10000
#define THRESHOLD_1 0x000F
#define THRESHOLD_2 0xF000

typedef struct {
    unsigned char RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} ListNode;

void* my_calloc(size_t size) {
    void* ptr = calloc(1, size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void log_allocation(int success_count, int fail_count) {
    printf("Successful allocations: %d, Failed allocations: %d\n", success_count, fail_count);
}

int main() {
    ListNode* head = NULL;
    int success_allocations = 0;
    int fail_allocations = 0;

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = my_calloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_element == NULL) {
            fail_allocations++;
        } else {
            success_allocations++;

            // Randomly set CRCFLAG
            unsigned short crcflag = rand() % 0xFFFF;
            if (crcflag > THRESHOLD_1 && crcflag < THRESHOLD_2) {
                printf("CRCFLAG value exceeded threshold: %x\n", crcflag);
            }

            // Add new element to the list
            ListNode* new_node = my_calloc(sizeof(ListNode));
            new_node->data = *new_element;
            new_node->next = head;
            head = &new_node->data;

            free(new_element);
        }
    }

    log_allocation(success_allocations, fail_allocations);

    return 0;
}
