#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define LOG_LEVEL 1
#define CRCFLAG_THRESHOLD 0x80

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_list = NULL;
int list_size = 0;

void log_message(int level, const char* message) {
    if (level >= LOG_LEVEL)
        printf("LOG: %s\n", message);
}

int allocate_list() {
    int* temp = malloc(sizeof(int));
    if (!temp) {
        log_message(1, "Error allocating memory for list");
        return -1;
    }
    free(temp); // Free the temporary pointer
    nfapi_crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_crc_indation_pdu_list) {
        log_message(1, "Error allocating memory for list");
        return -1;
    }
    nfapi_crc_indication_pdu_list->CRCFLAG = rand() & CRCFLAG_THRESHOLD; // Randomly set CRCFLAG
    return 0;
}

int filter_transactions(NFAPI_CRC_INDICATION_PDU_T* transactions) {
    int max_weighted_sum = 0, max_rnti = -1;
    for (int i = 0; i < list_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T transaction = transactions[i];
        if (transaction.RX_UE_INFORMATION_TAG > 3 && transaction.RNTI > 10) {
            transaction.CRCFLAG &= ~CRCFLAG_THRESHOLD;
        }
        int weighted_sum = transaction.RX_UE_INFORMATION_TAG + transaction.RNTI;
        if (weighted_sum > max_weighted_sum) {
            max_weighted_sum = weighted_sum;
            max_rnti = transaction.RNTI;
        }
    }
    return max_weighted_sum;
}

int main() {
    srand(time(NULL));
    int result = allocate_list();
    if (result == 0) {
        for (int i = 0; i < list_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T transaction = nfaapi_crc_indication_pdu_list[i];
            // Update metrics and return the maximum weighted sum
            int max_weighted_sum = filter_transactions(nfaapi_crc_indication_pdu_list);
            printf("Maximum weighted sum: %d, Corresponding RNTI: %d\n", max_weighted_sum, max_rnti);
        }
    } else {
        log_message(1, "Error allocating memory for list");
    }
    return 0;
}
