#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define RETENTION_PERIOD 300 // in seconds
#define SECONDS_PER_MINUTE 60

typedef struct {
    int id;
    time_t start_timestamp;
    int duration; // in seconds
    char network_type[16];
    int is_active;
} Voice_Call_Session;

Voice_Call_Session* sessions = NULL;
int num_sessions = 0;
time_t last_purge_time = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void init_sessions() {
    sessions = (Voice_Call_Session*)malloc(MAX_SESSIONS * sizeof(Voice_Call_Session));
}

void cleanup_sessions(int retention_period) {
    time_t now = time(NULL);
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < num_sessions; i++) {
        if ((now - sessions[i].start_timestamp > retention_period) && !sessions[i].is_active) {
            free(sessions + i);
            memmove(sessions + i, sessions + i + 1, (num_sessions - i - 1) * sizeof(Voice_Call_Session));
            num_sessions--;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void add_session(int id, time_t start_timestamp, int duration, char* network_type) {
    if (num_sessions >= MAX_SESSIONS) {
        printf("Session list full. Cannot add more sessions.\n");
        return;
    }
    Voice_Call_Session* new_session = &sessions[num_sessions];
    new_session->id = id;
    new_session->start_timestamp = start_timestamp;
    new_session->duration = duration;
    strcpy(new_session->network_type, network_type);
    new_session->is_active = 1; // initially active
    num_sessions++;
}

Voice_Call_Session* get_session(int id) {
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].id == id) {
            return &sessions[i];
        }
    }
    printf("Session not found: %d\n", id);
    return NULL;
}

void update_session_end_timestamp(Voice_Call_Session* session, time_t end_timestamp) {
    pthread_mutex_lock(&session_lock);
    if (session->is_active) {
        session->end_timestamp = end_timestamp;
    } else {
        printf("Cannot update end timestamp for a terminated/paused session.\n");
    }
    pthread_mutex_unlock(&session_lock);
}

int calculate_total_call_duration() {
    int total_duration = 0;
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].is_active) {
            total_duration += sessions[i].duration;
        }
    }
    pthread_mutex_unlock(&session_lock);
    return total_duration;
}

void pause_session(Voice_Call_Session* session) {
    pthread_mutex_lock(&session_lock);
    session->is_active = 0; // pause the session
    pthread_mutex_unlock(&session_lock);
}

void resume_session(Voice_Call_Session* session) {
    pthread_mutex_lock(&session_lock);
    session->is_active = 1; // resume the session
    pthread_mutex_unlock(&session_lock);
}

void log_operation(char* operation, Voice_Call_Session* session) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld %s: Session ID %d\n", now, operation, session->id);
}

int main() {
    init_sessions();
    // ...
    return 0;
}
