#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE Uplink PDCP PDU
typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
    long timestamp;
} LTE_Uplink_PDCP_PDU;

// Define a thread-safe queue using a linked list
typedef struct Node {
    LTE_Uplink_PDCP_PDU *pdu;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void enqueue(LTE_Uplink_PDCP_PDU* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->pdu = pdu;
    new_node->next = head;
    pthread_mutex_lock(&mutex);
    if(head == NULL)
        head = new_node;
    else
        ((Node*)head)->next = new_node;
    pthread_mutex_unlock(&mutex);
}

LTE_Uplink_PDCP_PDU* dequeue() {
    Node* temp = head;
    LTE_Uplink_PDCP_PDU* pdu = NULL;
    if(temp != NULL) {
        pdu = temp->pdu;
        head = temp->next;
        free(temp);
    }
    return pdu;
}

// Function to initialize and manage the dynamic array of PDU structures
