pthread_mutex_t pdcp_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdcp_cond = PTHREAD_COND_INITIALIZER;

void add_pdu(LTE_Uplink_PDCP_PDU* new_pdu) {
    pthread_mutex_lock(&pdcp_lock);
    if (pdcp_count < MAX_PDUS) {
        pdcps[pdcp_count] = *new_pdu;
        pdcp_count++;
    } else {
        printf("Array is full. Cannot add more PDUs.\n");
    }
    pthread_mutex_unlock(&pdcp_lock);
}

LTE_Uplink_PDCP_PDU* get_pdu(int PDCP_Seq_Num) {
    for (int i = 0; i < pdcp_count; i++) {
        if (pdcps[i].PDCP_Seq_Num == PDCP_Seq_Num) {
            return &pdcps[i];
        }
    }
    return NULL;
}

void update_pdu_error(int PDCP_Seq_Num, int error_indication) {
    for (int i = 0; i < pdcp_count; i++) {
        if (pdcps[i].PDCP_Seq_Num == PDCP_Seq_Num) {
            pdcps[i].Error_Indication = error_indication;
            return;
        }
    }
}

void remove_pdu(int PDCP_Seq_Num) {
    int removed_count = 0;
    LTE_Uplink_PDCP_PDU temp_pdcp;
    for (int i = 0; i < pdcp_count; i++) {
        if (pdcps[i].PDCP_Seq_Num == PDCP_Seq_Num) {
            removed_count++;
            continue;
        }
        temp_pdcp = pdcps[i];
        pdcps[i] = pdcps[removed_count];
        pdcps[removed_count++] = temp_pdcp;
    }
    if (removed_count < pdcp_count) {
        memmove(pdcps, &pdcps[removed_count], sizeof(LTE_Uplink_PDCP_PDU) * (pdcp_count - removed_count));
    }
    pdcp_count -= removed_count;
}

int main() {
    return 0;
