#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define BANDWIDTH_LIMIT 1024 // 1KB default limit

typedef struct TCP_Segment {
    int seq_num;
    size_t payload_size;
    time_t timestamp;
} TCP_Segment;

typedef struct LinkList {
    TCP_Segment* current;
    TCP_Segment* head;
    size_t total_size;
    int segment_count;
} LinkList;

LinkList* ll_init() {
    LinkList* list = (LinkList*)malloc(sizeof(LinkList));
    list->current = NULL;
    list->head = NULL;
    list->total_size = 0;
    list->segment_count = 0;
    return list;
}

void ll_add_segment(LinkList* list, TCP_Segment segment) {
    if (list->total_size + segment.payload_size > BANDWIDTH_LIMIT) {
        printf("Warning: Bandwidth limit exceeded! Discarding older segments...\n");
        while (list->segment_count && (list->head)->timestamp < segment.timestamp - 10) {
            ll_remove_segment(list);
        }
    }

    if (!list->head) {
        list->head = &segment;
    } else {
        TCP_Segment* prev = list->head;
        while (prev->next) {
            prev = prev->next;
        }
        prev->next = &segment;
    }

    list->current = &segment;
    list->total_size += segment.payload_size;
    list->segment_count++;

    if (list->total_size > BANDWIDTH_LIMIT) {
        printf("Warning: Bandwidth limit exceeded! Further additions will be blocked.\n");
    }
}

TCP_Segment* ll_get_segment(LinkList* list, int seq_num) {
    TCP_Segment* current = list->head;
    while (current && current->seq_num != seq_num) {
        current = current->next;
    }

    return current ? &(*current) : NULL;
}

void ll_remove_segment(LinkList* list) {
    if (!list->head) {
        printf("Warning: List is empty! No segment removed.\n");
        return;
    }

    TCP_Segment* prev = list->head;
    TCP_Segment* curr = list->head;
    while (curr && curr->next) {
        prev = curr;
        curr = curr->next;
    }
    if (curr) {
        prev->next = NULL;
    } else {
        list->head = NULL;
    }

    list->total_size -= curr->payload_size;
    list->segment_count--;

    free(curr);
}

void ll_update_timestamp(LinkList* list, int seq_num, time_t timestamp) {
    TCP_Segment* segment = ll_get_segment(list, seq_num);
    if (segment) {
        segment->timestamp = timestamp;
    }
}

void ll_prune_old_segments(LinkList* list, time_t prune_threshold) {
    while (list->head && list->head->timestamp < prune_threshold - 10) {
        ll_remove_segment(list);
    }
}

int main() {
    LinkList* list = ll_init();

    // Example usage
    TCP_Segment segment1 = {1, sizeof(char)};
    TCP_Segment segment2 = {2, sizeof(int)};
    TCP_Segment segment3 = {3, sizeof(float)};

    ll_add_segment(list, segment1);
    ll_add_segment(list, segment2);
    ll_add_segment(list, segment3);

    // Retrieve a specific segment
    TCP_Segment* retrieved_segment = ll_get_segment(list, 2);
    printf("Retrieved segment: %d\n", retrieved_segment->seq_num);

    // Update the transmission timestamp
    ll_update_timestamp(list, 1, time(NULL));

    // Prune old segments
    ll_prune_old_segments(list, time(NULL) - 10);

    return 0;
}

