#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define RETENTION_PERIOD 300 // seconds
#define REPORTING_INTERVAL 60 // seconds

typedef struct {
    int id;
    time_t start_time;
    time_t end_time;
    int duration; // in seconds
    char network_type;
    int is_active;
} Voice_Call_Session;

Voice_Call_Session *sessions[MAX_SESSIONS];
int session_count = 0;

// Function to initialize the sessions list
void init_sessions_list() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        sessions[i] = NULL;
    }
}

// Function to add a new voice call session
void add_session(int id, time_t start_time, char network_type) {
    Voice_Call_Session *new_session = (Voice_Call_Session *)malloc(sizeof(Voice_Call_Session));
    new_session->id = id;
    new_session->start_time = start_time;
    new_session->end_time = 0;
    new_session->duration = 0;
    new_session->network_type = network_type;
    new_session->is_active = 1;

    sessions[session_count] = new_session;
    session_count++;
}

// Function to retrieve a specific voice call session by its ID
Voice_Call_Session *get_session(int id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->id == id) {
            return sessions[i];
        }
    }
    return NULL;
}

// Function to update the end timestamp of a given voice call session
void update_end_time(int id, time_t end_time) {
    Voice_Call_Session *session = get_session(id);
    if (session != NULL) {
        session->end_time = end_time;
    }
}

// Function to calculate the total call duration for all active sessions
int get_total_active_duration() {
    int total_duration = 0;
    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->is_active) {
            total_duration += sessions[i]->duration;
        }
    }
    return total_duration;
}

// Function to automatically clean up terminated sessions
void cleanup_terminated_sessions() {
    for (int i = session_count - 1; i >= 0; i--) {
        if (!sessions[i]->is_active) {
            free(sessions[i]);
            sessions[i] = NULL;
            session_count--;
        }
    }
}

// Function to generate periodic reports on the number of active, paused, and terminated sessions
void report_sessions() {
    int active_sessions = 0;
    int paused_sessions = 0;
    int terminated_sessions = 0;

    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->is_active) {
            active_sessions++;
        } else if (!sessions[i]->is_active && sessions[i]->duration > 0) {
            paused_sessions++;
        } else {
            terminated_sessions++;
        }
    }

    printf("Active Sessions: %d\n", active_sessions);
    printf("Paused Sessions: %d\n", paused_sessions);
    printf("Terminated Sessions: %d\n", terminated_sessions);
}

// Function to serialize and deserialize the session list to disk
void save_session_list() {
    FILE *fp = fopen("sessions.txt", "wb");
    for (int i = 0; i < session_count; i++) {
        if (sessions[i] != NULL) {
            fwrite(&sessions[i]->id, sizeof(int), 1, fp);
            fwrite(&sessions[i]->start_time, sizeof(time_t), 1, fp);
            fwrite(&sessions[i]->end_time, sizeof(time_t), 1, fp);
            fwrite(&sessions[i]->duration, sizeof(int), 1, fp);
            fwrite(&sessions[i]->network_type, sizeof(char), 1, fp);
            fwrite(&sessions[i]->is_active, sizeof(int), 1, fp);
        }
    }
    fclose(fp);
}

void load_session_list() {
    FILE *fp = fopen("sessions.txt", "rb");
    if (fp != NULL) {
        for (int i = 0; i < MAX_SESSIONS; i++) {
            sessions[i] = NULL;
        }

        int id;
        time_t start_time, end_time;
        int duration;
        char network_type;
        int is_active;

        while (fread(&id, sizeof(int), 1, fp) == 1 &&
               fread(&start_time, sizeof(time_t), 1, fp) == 1 &&
               fread(&end_time, sizeof(time_t), 1, fp) == 1 &&
               fread(&duration, sizeof(int), 1, fp) == 1 &&
               fread(&network_type, sizeof(char), 1, fp) == 1 &&
               fread(&is_active, sizeof(int), 1, fp) == 1) {
            Voice_Call_Session *new_session = (Voice_Call_Session *)malloc(sizeof(Voice_Call_Session));
            new_session->id = id;
            new_session->start_time = start_time;
            new_session->end_time = end_time;
            new_session->duration = duration;
            new_session->network_type = network_type;
            new_session->is_active = is_active;

            sessions[session_count] = new_session;
            session_count++;
        }
        fclose(fp);
    }
}

int main() {
    init_sessions_list();

    // Example usage:
    add_session(1, time(NULL), 'A');
    add_session(2, time(NULL), 'B');

    report_sessions();
    save_session_list();

    return 0;
}
