} TCP_CONNECTION_RECORD;

// Function prototype for managing dynamic array of TCP connection records
TCP_CONNECTION_RECORD* manage_connections(TCP_CONNECTION_RECORD*, int);

int main() {
    // Initialize the array with 100,000 elements
    TCP_CONNECTION_RECORD* connections = (TCP_CONNECTION_RECORD*)malloc(100000 * sizeof(TCP_CONNECTION_RECORD));

    // Test adding and retrieving a connection record
    TCP_CONNECTION_RECORD* conn1 = (TCP_CONNECTION_RECORD*)malloc(sizeof(TCP_CONNECTION_RECORD));
    conn1->CONNECTION_ID = 123;
    strcpy(conn1->SOURCE_IP, "192.168.1.100");
    strcpy(conn1->DESTINATION_IP, "8.8.8.8");

    manage_connections(connections, 0);

    // Update statistics for the connection
    connections[0].BYTES_RECEIVED += 1024;
    connections[0].BYTES_SENT += 2048;

    free(conn1);
    free(connections);

    return 0;
}

TCP_CONNECTION_RECORD* manage_connections(TCP_CONNECTION_RECORD* connections, int index) {
    // Add a new connection record
    TCP_CONNECTION_RECORD* conn = (TCP_CONNECTION_RECORD*)malloc(sizeof(TCP_CONNECTION_RECORD));
    conn->CONNECTION_ID = index + 1;
    strcpy(conn->SOURCE_IP, "192.168.1.");
    sprintf(conn->DESTINATION_IP, "%ld.%ld.%ld.%ld", 8, 8, 8, 8);
    conn->BYTES_TRANSFERRED = 0;

    // Update the connection record at the specified index
    if (index < 100000) {
        connections[index] = *conn;
    }

    return connections;
}

