    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} PDU_Array;

PDU_Array* pdu_array_create(size_t initial_capacity) {
    PDU_Array* array = (PDU_Array*)malloc(sizeof(PDU_Array));
    if (!array) return NULL;

    array->pdus = (LTE_Uplink_PDCP_PDU*)malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    if (!array->pdus) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void pdu_array_free(PDU_Array* array) {
    pthread_mutex_destroy(&array->mutex);
    if (array->pdus) free(array->pdus);
    free(array);
}

int pdu_array_add(PDU_Array* array, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->length >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uplink_PDCP_PDU* new_pds = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, new_capacity * sizeof(LTE_Uplink_PDCP_PDU));
        if (!new_pds) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Out of memory
        }

        array->capacity = new_capacity;
        array->pdus = new_pds;
    }

    array->pdus[array->length++] = *pdu;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

LTE_Uplink_PDCP_PDU* pdu_array_get(PDU_Array* array, int sequence_number) {
    pthread_mutex_lock(&array->mutex);

    for (int i = 0; i < array->length; i++) {
        if (array->pdus[i].sequence_number == sequence_number) {
            LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
            *pdu = array->pdus[i];
            pthread_mutex_unlock(&array->mutex);

            return pdu;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return NULL; // PDU not found
}

