size_t task_size = 0;
size_t task_capacity = 10000; // adjust as needed

int pdcp_pdu_alloc() {
    size_t new_size = pdcp_pdu_capacity * sizeof(LTE_Uplink_PDCP_PDU);
    void* new_ptr = realloc(pdcp_pdu_array, new_size);
    if (!new_ptr) return -1;
    pdcp_pdu_array = new_ptr;
    pdcp_pdu_size = 0;
    pdcp_pdu_capacity *= 2; // double capacity for next allocation
    return 0;
}

int task_alloc() {
    size_t new_size = task_capacity * sizeof(Task);
    void* new_ptr = realloc(task_array, new_size);
    if (!new_ptr) return -1;
    task_array = new_ptr;
    task_size = 0;
    task_capacity *= 2; // double capacity for next allocation
    return 0;
}

int add_pdu(int SN, int SDU_size) {
    if (pdcp_pdu_size >= pdcp_pdu_capacity)
        pdcp_pdu_alloc();
    LTE_Uplink_PDCP_PDU* new_pdu = &((LTE_Uplink_PDCP_PDU*)pdcp_pdu_array)[pdcp_pdu_size];
    new_pdu->SN = SN;
    new_pdu->SDU_size = SDU_size;
    new_pdu->error_indication = 0;
    pdcp_pdu_size++;
    return 0;
}

int add_task(char* name) {
    if (task_size >= task_capacity)
        task_alloc();
    Task* new_task = &((Task*)task_array)[task_size];
    new_task->name = name;
    new_task->priority_level = rand() % 5 + 1; // random priority level
    new_task->estimated_completion_time = (double)rand() / RAND_MAX * 12.0 + 10.0; // normal distribution for estimated completion time
    task_size++;
    return 0;
}

LTE_Uplink_PDCP_PDU* get_pdu_by_SN(int SN) {
    int i;
    for (i = 0; i < pdcp_pdu_size; i++) {
        if (((LTE_Uplink_PDCP_PDU*)pdcp_pdu_array)[i].SN == SN)
            return &((LTE_Uplink_PDCP_PDU*)pdcp_pdu_array)[i];
    }
    return NULL;
}

Task* get_task_by_name(char* name) {
    int i;
    for (i = 0; i < task_size; i++) {
        if (!strcmp(((Task*)task_array)[i].name, name))
            return &((Task*)task_array)[i];
    }
    return NULL;
}

int update_pdu_error(int SN, int error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = get_pdu_by_SN(SN);
    if (!pdu)
        return -1; // PDU not found
    pdu->error_indication = error_indication;
    return 0;
}

int update_task_priority(char* name, int priority_level) {
    Task* task = get_task_by_name(name);
    if (!task)
        return -1; // task not found
    task->priority_level = priority_level;
    return 0;
}
