int computeCRC(void* data, int size) {
    uint32_t crc = 0xFFFFFFFF;

    for (int i = 0; i < size; i++) {
        uint8_t byte = ((uint8_t*)data)[i];

        for (int j = 0; j < 8; j++) {
            if (((crc >> 7) & 1) == (byte & 0x80)) {
                crc <<= 1;
                crc ^= CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }

            byte >>= 1;
        }
    }

    return ~crc;
}

