#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>

EVP_CIPHER_CTX* cipher_select(const char* algo, const char* password) {
    // SHA-1 hash function to derive encryption keys from passwords
    unsigned char key[32];
    SHA1(password, strlen(password), key);

    EVP_CIPHER_CTX* ctx = NULL;

    if (strcmp(algo, "AES-256-CBC") == 0) {
        ctx = EVP_Cipher_CTX_new(EVP_aes_256_cbc());
    } else if (strcmp(algo, "DES-ECB") == 0 || strcmp(algo, "DES-EDE") == 0 || strcmp(algo, "DES-EDE3") == 0 || strcmp(algo, "DES-CFB") == 0) {
        ctx = EVP_Cipher_CTX_new(EVP_des_ede_cfb64());
    } else if (strcmp(algo, "NULL") == 0) {
        ctx = EVP_Cipher_CTX_new(NULL_CIPHER);
    }

    // Set fixed IV and key lengths
    EVP_Cipher_CTX_ctrl(ctx, EVP_CTRL_SET_FIXED_IV, 16);
    EVP_Cipher_CTX_ctrl(ctx, EVP_CTRL_SET_KEY_LENGTH, 32);

    return ctx;
}

int verify_cipher(EVP_CIPHER_CTX* ctx, const char* data) {
    HMAC_CTX* hmac = HMAC_CTX_new();
    HMAC_Init_ex(hmac, key, 32, EVP_sha1());
    HMAC_Update(hmac, data, strlen(data));
    unsigned char hash[20];
    HMAC_Final(hmac, hash);
    HMAC_free(hmac);

    // Verify the integrity and authenticity of encrypted data
    int result = HMAC_verify(ctx, data, strlen(data), hash);
    HMAC_CTX_free(hmac);

    return result;
}

void cipher_cleanup(EVP_CIPHER_CTX* ctx) {
    EVP_Cipher_CTX_free(ctx);
}
