typedef struct {
    unsigned char* key;
    unsigned char* iv;
    unsigned char* tag;
} CipherContext;

CipherContext* aes256_gcm_init(const char* hostname, const char* password, int iterations) {
    if (password == NULL || strlen(password) == 0) {
        return NULL; // handle null or empty password
    }

    // derive key and iv using PBKDF2 with HMAC-SHA256
    unsigned char* derived_key = PBKDF2_derive_key(password, hostname, iterations);
    if (derived_key == NULL) {
        return NULL; // handle key derivation failure due to insufficient entropy or resource limitations
    }

    unsigned char* salt = generate_salt();
    unsigned char* iv = PBKDF2_derive_iv(derived_key, salt, iterations);

    CipherContext* cipher_ctx = malloc(sizeof(CipherContext));
    cipher_ctx->key = derived_key;
    cipher_ctx->iv = iv;
    cipher_ctx->tag = malloc(AES_BLOCK_SIZE); // initialize authentication tag

    return cipher_ctx;
}

void aes256_gcm_cleanup(CipherContext* cipher_ctx) {
    if (cipher_ctx == NULL) {
        return; // handle null cipher context
    }

    free(cipher_ctx->key);
    free(cipher_ctx->iv);
    free(cipher_ctx->tag);

    free(cipher_ctx);
}

