// Mutex for synchronizing access to the PDU array
pthread_mutex_t pduMutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for signaling changes in the PDU array
pthread_cond_t pduCond = PTHREAD_COND_INITIALIZER;

// Worker thread ID
typedef enum {
    IDLE,
    BUSY,
    ERROR
} workerState;

// Worker thread structure
typedef struct {
    int id;
    pthread_t threadId;
    workerState state;
    LTE_Uplink_PDCP_PDU *pdu;
} workerThread;

// Array to store the worker threads
workerThread workers[MAX_WORKER_THREADS];

// Current size of the worker array
int workerSize = 0;

// Mutex for synchronizing access to the worker array
pthread_mutex_t workerMutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for signaling changes in the worker array
pthread_cond_t workerCond = PTHREAD_COND_INITIALIZER;

// Function to create a new worker thread
void* createWorker(void* arg) {
    int id;
    LTE_Uplink_PDCP_PDU *pdu;

    // Get the ID and PDU from the argument
    id = *(int*)arg;
    pdu = *(LTE_Uplink_PDCP_PDU**)arg;

    // Set the worker thread state to IDLE
    workers[id].state = IDLE;

    // Initialize the worker thread
    pthread_create(&workers[id].threadId, NULL, processWorker, &id);

    return NULL;
}

// Function to process a worker thread
void* processWorker(void* arg) {
    int id;

    // Get the ID from the argument
    id = *(int*)arg;

    // Process the PDU
    while (1) {
        pthread_mutex_lock(&pduMutex);
        if (pduSize == 0) {
            pthread_cond_wait(&pduCond, &pduMutex);
        }

        // Get the next PDU from the array
        LTE_Uplink_PDCP_PDU *pdu = pdus + id % pduSize;

        // Process the PDU
        processPDU(pdu);

        // Update the PDU state
        pthread_mutex_unlock(&pduMutex);
    }

    return NULL;
}

// Function to add a new PDU to the array
void addPDU(LTE_Uplink_PDCP_PDU *pdu) {
    int i;

    // Search for an empty slot in the array
    for (i = 0; i < pduSize; i++) {
        if (!pdus[i].sequenceNumber) {
            break;
        }
    }

    // Add the PDU to the array
    pdus[i] = *pdu;

    // Increment the PDU size
    pduSize++;

    // Signal the worker threads
    pthread_cond_signal(&pduCond);
}

// Function to retrieve a PDU by sequence number
LTE_Uplink_PDCP_PDU* get_pdu_by_sequence_number(int sequenceNumber) {
    int i;

    for (i = 0; i < pduSize; i++) {
        if (pdus[i].sequenceNumber == sequenceNumber) {
            return &pdus[i];
        }
    }

    // Return NULL if the PDU is not found
    return NULL;
}

// Function to update the error indication of a PDU
void update_pdu_error(int sequenceNumber, int errorIndication) {
    int i;

    for (i = 0; i < pduSize; i++) {
        if (pdus[i].sequenceNumber == sequenceNumber) {
            pdus[i].errorIndication = errorIndication;
            break;
        }
    }
}

// Function to remove an old PDU from the array
void remove_pdu(int sequenceNumber) {
    int i, j;

    for (i = 0; i < pduSize; i++) {
        if (pdus[i].sequenceNumber == sequenceNumber) {
            // Shift the remaining PDUs down the array
            for (j = i; j < pduSize - 1; j++) {
                pdus[j] = pdus[j + 1];
            }

            // Decrement the PDU size
            pduSize--;

            // Signal the worker threads
            pthread_cond_signal(&pduCond);

            return;
        }
    }
}

