import argparse
import csv
import json
import multiprocessing
import os
import threading
from collections import defaultdict

class UserDatabase:
    def __init__(self):
        self.users = {}

    def add_user(self, username, password, email):
        if username in self.users:
            print("Error: Username already exists.")
            return
        self.users[username] = {"password": password, "email": email}

    def update_user(self, username, new_password, new_email):
        if username not in self.users:
            print("Error: User does not exist.")
            return
        self.users[username]["password"] = new_password
        self.users[username]["email"] = new_email

    def delete_user(self, username):
        if username not in self.users:
            print("Error: User does not exist.")
            return
        del self.users[username]

    def list_users(self, verbose=False, output_file=None):
        if verbose:
            for user, details in self.users.items():
                print(f"Username: {user}, Password: {details['password']}, Email: {details['email']}")
        else:
            for user in self.users:
                print(user)

    def load_users(self, file_path):
        try:
            with open(file_path, "r") as file:
                if file.name.endswith(".json"):
                    self.users = json.load(file)
                elif file.name.endswith(".csv"):
                    reader = csv.reader(file)
                    for row in reader:
                        self.add_user(row[0], row[1], row[2])
        except FileNotFoundError:
            print("Error: File not found.")
        except json.JSONDecodeError:
            print("Error: Invalid JSON format.")

    def save_users(self, file_path):
        try:
            with open(file_path, "w") as file:
                if args.output_format == "json":
                    json.dump(self.users, file)
                elif args.output_format == "csv":
                    writer = csv.writer(file)
                    for user, details in self.users.items():
                        writer.writerow([user, details["password"], details["email"]])
        except IOError:
            print("Error: Unable to write to file.")

def parallel_process_users(users, num_threads):
    threads = []
    with multiprocessing.Pool(processes=num_threads) as pool:
        for user in users:
            thread = threading.Thread(target=process_user, args=(user,))
            threads.append(thread)
            thread.start()
        for thread in threads:
            thread.join()

def process_user(username):
