    parser.add_argument("--help", action="store_true", help="Display this message and exit.")
    parser.add_argument("-u", "--username", required=False, help="Specify a username to add, update, or delete a user.")
    parser.add_argument("-a", "--add", nargs=3, help="Add a new user with the given username, password, and email.")
    parser.add_argument("-u", "--update", nargs=3, help="Update an existing user's information with the given username, new password, and email.")
    parser.add_argument("-d", "--delete", help="Delete a user from the database by their username.")
    parser.add_argument("-l", "--list", action="store_true", help="List all users in the database.")
    parser.add_argument("-o", "--output_file", help="Redirect the list output to a specified file instead of standard output.")
    parser.add_argument("-v", "--verbose", action="store_true", help="Enable verbose mode and include detailed user metadata in the list output.")
    parser.add_argument("-p", "--parallel_threads", type=int, default=1, help="Specify the number of parallel threads to use for concurrent operations.")
    parser.add_argument("-f", "--load_file", help="Load a user database from a specified file at startup.")
    args = parser.parse_args()

