    if not args.username and not (args.add or args.update or args.delete):
        print("Error: No operation specified. Use -h for help.")
        exit()

    if args.list:
        db.list_users(verbose=args.verbose, output_file=args.output_file)
    elif args.add:
        username = args.add[0]
        password = args.add[1]
        email = args.add[2]
        db.add_user(username, password, email)
    elif args.update:
