    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0) {
            printf("Usage: %s [-h] [-d directory] [-e extension] [-v verbose]\n", argv[0]);
            exit(0);
        } else if (strcmp(argv[i], "-d") == 0) {
