            // Set file extensions
        } else if (strcmp(argv[i], "-v") == 0) {
            // Enable verbose mode
        }
    }

    // Allocate array
    array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(numThreads * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < numThreads; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxFilesPerThread * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Process files
    DIR *dir;
    struct dirent *ent;
    int threadIndex = 0;
    for (int i = 0; i < numThreads; i++) {
        dir = opendir(argv[1]);
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;
            array[threadIndex][totalFiles].field1 = i;
            strcpy(array[threadIndex][totalFiles].field2, ent->d_name);
            array[threadIndex][totalFiles++].field3 = totalFiles;
            if (totalFiles >= maxFilesPerThread) {
                threadIndex++;
                totalFiles = 0;
            }
        }
        closedir(dir);
    }

    // Print summary report
    for (int i = 0; i < numThreads; i++) {
        printf("Thread %d: %d files\n", i, maxFilesPerThread);
    }

    // Deallocate array
    for (int i = 0; i < numThreads; i++) {
        free(array[i]);
    }
    free(array);

    return 0;
}
