        if (strcmp(argv[i], "--manpage") == 0 || strcmp(argv[i], "-cs") == 0) {
            // print help message or usage information
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            char* output_file = argv[i + 1];
            FILE* out = fopen(output_file, "w");
            fclose(out);
        } else if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("Usage: %s [options] <input_file>\n", argv[0]);
            exit(1);
        } else if (strcmp(argv[i], "output_file") == 0 && i + 1 < argc) {
            input_file = fopen(argv[i + 1], "r");
            if (!input_file) {
                fprintf(stderr, "Error opening file: %s\n", argv[i + 1]);
                exit(2);
            }
        } else {
            printf("Invalid option or argument: %s\n", argv[i]);
            exit(3);
        }
    }

    fseek(input_file, 0, SEEK_END);
    long size = ftell(input_file);
    rewind(input_file);

    char* line = (char*)malloc((size + 1) * sizeof(char));
    fread(line, sizeof(char), size, input_file);
    line[size] = '\0';

    printf("Number of lines: %d\n", count_lines(line));

    free(line);
    fclose(input_file);

    return 0;
}

int count_lines(char* str) {
    int count = 1;
    while (*str != '\0') {
        if (*str == '\n') {
            count++;
        }
        str++;
    }
    return count;
}
