LTEManager* lte_manager_init() {
    LTEManager* manager = (LTEManager*)malloc(sizeof(LTEManager));
    manager->pdus = NULL;
    manager->pdus_size = 0;
    manager->contexts = NULL;
    manager->contexts_size = 0;
    return manager;
}

void lte_manager_add_pdu(LTEManager* manager, PDCPPDU* pdu) {
    if (manager->pdus == NULL || manager->pdus_size <= 0) {
        manager->pdus = (PDCPPDU**)malloc((manager->pdus_size + 1) * sizeof(PDCPPDU*));
        manager->pdus_size++;
    }
    memcpy(&manager->pdus[manager->pdus_size - 1], pdu, sizeof(PDCPPDU));
}

void lte_manager_add_context(LTEManager* manager, RRCUEContext* context) {
    if (manager->contexts == NULL || manager->contexts_size <= 0) {
        manager->contexts = (RRCUEContext**)malloc((manager->contexts_size + 1) * sizeof(RRCUEContext*));
        manager->contexts_size++;
    }
    memcpy(&manager->contexts[manager->contexts_size - 1], context, sizeof(RRCUEContext));
}

PDCPPDU* lte_manager_get_pdu_by_sn(LTEManager* manager, int sequence_number) {
    for (size_t i = 0; i < manager->pdus_size; i++) {
        if (manager->pdus[i]->sequence_number == sequence_number) {
            return &manager->pdus[i]->sequence_number;
        }
    }
    return NULL;
}

int lte_manager_update_pdu_error(LTEManager* manager, int sequence_number, int error_indication) {
    for (size_t i = 0; i < manager->pdus_size; i++) {
        if (manager->pdus[i]->sequence_number == sequence_number) {
            manager->pdus[i]->error_indication = error_indication;
            return 0;
        }
    }
    return -1;
}

void lte_manager_free(LTEManager* manager) {
    for (size_t i = 0; i < manager->pdus_size; i++) {
        free(manager->pdus[i]);
    }
    free(manager->pdus);
    for (size_t i = 0; i < manager->contexts_size; i++) {
        if (manager->contexts[i]->ccch_message_config != NULL) {
            free(manager->contexts[i]->ccch_message_config);
        }
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    free(manager);
}
