typedef struct {
    int sequence_number;
    int sd_size;
    int error_indication;
} PDCP_PDU;

typedef struct {
    int ue_id;
    int cell_id;
    char* message_config;
} RRC_CONTEXT;

// Initialize the dynamic arrays
void init_data_structures() {
    // Define initial sizes for the data structures
    int initial_pdcp_size = 10;
    int initial_rrc_size = 5;

    // Allocate memory for the PDUs and RRC contexts
    PDCP_PDU* pdcp_pdus = (PDCP_PDU*)malloc(initial_pdcp_size * sizeof(PDCP_PDU));
    RRC_CONTEXT* rrc_contexts = (RRC_CONTEXT*)malloc(initial_rrc_size * sizeof(RRC_CONTEXT));

    // Initialize the data structures
    pdcp_pdus[0].sequence_number = 1;
    pdcp_pdus[0].sd_size = 100;
    pdcp_pdus[0].error_indication = 0;

    rrc_contexts[0].ue_id = 10;
    rrc_contexts[0].cell_id = 20;
    rrc_contexts[0].message_config = (char*)malloc(100 * sizeof(char));

    // Store the initial sizes for dynamic allocation
    int current_pdcp_size = initial_pdcp_size;
    int current_rrc_size = initial_rrc_size;
}

// Add a new PDU or RRC context
void add_element(int type, int sn, int sd_size, int error_indication) {
    if (type == 0) { // PDCP PDU
        // Check if the dynamic array needs to be resized
        if (current_pdcp_size == total_elements(current_pdcp_size)) {
            current_pdcp_size *= 2;
            pdcp_pdus = realloc(pdcp_pdus, current_pdcp_size * sizeof(PDCP_PDU));
        }

        // Add the new PDU to the array
        pdcp_pdus[current_pdcp_size - 1].sequence_number = sn;
        pdcp_pdus[current_pdcp_size - 1].sd_size = sd_size;
        pdcp_pdus[current_pdcp_size - 1].error_indication = error_indication;

    } else if (type == 1) { // RRC context
        // Check if the dynamic array needs to be resized
        if (current_rrc_size == total_elements(current_rrc_size)) {
            current_rrc_size *= 2;
            rrc_contexts = realloc(rrc_contexts, current_rrc_size * sizeof(RRC_CONTEXT));
        }

        // Add the new RRC context to the array
        rrc_contexts[current_rrc_size - 1].ue_id = sn;
        rrc_contexts[current_rrc_size - 1].cell_id = sd_size;
        rrc_contexts[current_rrc_size - 1].message_config = (char*)malloc(sd_size * sizeof(char));
    }
}

// Retrieve a PDU by its sequence number
PDCP_PDU* retrieve_pdu(int sn) {
    for (int i = 0; i < current_pdcp_size; i++) {
        if (pdcp_pdus[i].sequence_number == sn) {
            return &pdcp_pdus[i];
        }
    }

    // PDU not found
    return NULL;
}

// Update the error indication for a given sequence number
void update_error_indication(int sn, int error_indication) {
    for (int i = 0; i < current_pdcp_size; i++) {
        if (pdcp_pdus[i].sequence_number == sn) {
            pdcp_pdus[i].error_indication = error_indication;
            return;
        }
    }

    // PDU not found
}

// Print the contents of the data structures
void print_data_structures() {
    printf("PDCP PDUs:\n");
    for (int i = 0; i < current_pdcp_size; i++) {
        printf("Sequence Number: %d, SD Size: %d, Error Indication: %d\n", pdcp_pdus[i].sequence_number, pdcp_pdus[i].sd_size, pdcp_pdus[i].error_indication);
    }

    printf("\nRRC Contexts:\n");
    for (int i = 0; i < current_rrc_size; i++) {
        printf("UE ID: %d, CELL ID: %d, Message Config: %s\n", rrc_contexts[i].ue_id, rrc_contexts[i].cell_id, rrc_contexts[i].message_config);
    }
}

// Helper function to calculate the total number of elements
int total_elements(int size) {
    return size;
}

int main() {
    // Initialize the data structures
    init_data_structures();

    // Add some PDUs and RRC contexts
    add_element(0, 1, 100, 0);
    add_element(0, 2, 200, 1);
    add_element(1, 10, 20, 0);

    // Retrieve a PDU by its sequence number
    PDCP_PDU* pdu = retrieve_pdu(2);
    if (pdu != NULL) {
        printf("Retrieved PDU: Sequence Number: %d, SD Size: %d, Error Indication: %d\n", pdu->sequence_number, pdu->sd_size, pdu->error_indication);
    } else {
        printf("PDU not found!\n");
    }

    // Update the error indication for a given sequence number
    update_error_indication(1, 1);

    // Print the contents of the data structures
    print_data_structures();

    return 0;
}
