int updateErrorIndication(LTE_Uplink_PDCP_PDU** pdpu_array, size_t* pdpu_size, int SN, int new_error_indication);

void initArrays(LTE_Uplink_PDCP_PDU** pdpu_array, LTE_RRC_UE_CONTEXT** rrc_ctx_array) {
    *pdpu_array = (LTE_Uplink_PDCP_PDU*)malloc(PDPU_ARRAY_SIZE * sizeof(LTE_Uplink_PDCP_PDU));
    *rrc_ctx_array = (LTE_RRC_UE_CONTEXT*)malloc(RRC_CTX_ARRAY_SIZE * sizeof(LTE_RRC_UE_CONTEXT));
}

int addPDU(LTE_Uplink_PDCP_PDU** pdpu_array, size_t* pdpu_size, LTE_Uplink_PDCP_PDU new_pdu) {
    int i;
    for (i = 0; i < *pdpu_size; i++) {
        if ((*pdpu_array)[i].SN == new_pdu.SN) {
            // Update existing PDU
            (*pdpu_array)[i] = new_pdu;
            return 1;
        }
    }
    // Add new PDU to end of array
    if (*pdpu_size < PDPU_ARRAY_SIZE - 1) {
        (*pdpu_array)[*pdpu_size] = new_pdu;
        (*pdpu_size)++;
        return 1;
    } else {
        printf("PDU array is full.\n");
        return 0;
    }
}

LTE_Uplink_PDCP_PDU* getPDUbySN(LTE_Uplink_PDCP_PDU** pdpu_array, size_t* pdpu_size, int target_SN) {
    int i;
    for (i = 0; i < *pdpu_size; i++) {
        if ((*pdpu_array)[i].SN == target_SN) {
            return &(*pdpu_array)[i];
        }
    }
    return NULL;
}

int updateErrorIndication(LTE_Uplink_PDCP_PDU** pdpu_array, size_t* pdpu_size, int SN, int new_error_indication) {
