    public async Task UpdatePageSectionAsync(string sessionToken, int pageSectionId, string elementId, string htmlContent, string clientVersion)
    {
        if (!ValidateSessionToken(sessionToken))
        {
            throw new InvalidOperationException("Unauthorized or invalid session token");
        }

        var request = new UpdateRequest
        {
            PageSectionId = pageSectionId,
            ElementId = elementId,
            HtmlContent = htmlContent,
            ClientVersion = clientVersion
        };

        try
        {
            var response = await _httpClient.PostAsync("update", JsonConvert.SerializeObject(request));
            response.EnsureSuccessStatusCode();
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to update page section: {response.StatusCode}");
            }
        }
        catch (HttpRequestException ex) when (ex.Message.Contains("Connection timed out"))
        {
            // Handle network failure with exponential backoff retries
            await ExponentialBackoffRetry(ex);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update page section");
            throw;
        }

        // Validate updated content and log successful updates
        var validationResult = _contentValidationService.Validate(request.HtmlContent);
        if (!validationResult.IsValid)
        {
            _logger.LogError(validationResult.ErrorMessage, "Invalid content update");
        }
        else
        {
            _logger.LogInformation($"Updated page section {pageSectionId} with element ID {elementId}");
        }
    }

    private bool ValidateSessionToken(string sessionToken)
    {
        // Implement session token validation logic here
        return true; // Replace with actual validation implementation
    }

    private async Task ExponentialBackoffRetry(HttpRequestException ex)
    {
        var retryCount = 0;
        var maxRetries = 5;

        while (retryCount < maxRetries)
        {
            await Task.Delay(1000 * (int)Math.Pow(2, retryCount));
            try
            {
                // Retry the request with exponential backoff
                _httpClient.PostAsync("update", JsonConvert.SerializeObject(request)).Wait();
                return;
            }
            catch (HttpRequestException ex) when (ex.Message.Contains("Connection timed out"))
            {
                retryCount++;
            }
        }

        throw new InvalidOperationException("Failed to update page section after max retries");
    }
}

public class UpdateRequest
{
    public int PageSectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
    public string ClientVersion { get; set; }
}
