                }
            } catch (IOException e) {
                logger.error("Error processing file content: {}", e.getMessage());
            }
        }

        @Override
        public int compareTo(Task other) {
            return this.taskCount.compareTo(other.taskCount);
        }
    }
}

class LRUCache<K, V> implements Cache<K, V> {
    private final Map<K, V> cacheMap = new LinkedHashMap<>(256, 0.75f, true);
    private final int capacity;

    public LRUCache(int capacity) {
        this.capacity = capacity;
    }

    @Override
    public void put(K key, V value) {
        cacheMap.put(key, value);
    }

    @Override
    public V get(K key) {
        return cacheMap.get(key);
    }

    @Override
    public void clear() {
        cacheMap.clear();
    }
}
