#define MAX_REQUESTS 1000
#define MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct HTTP_Request {
    char method[10];
    char uri[255];
    int timestamp;
    void* headers;
} HTTP_Request;

void list_add(HTTP_Request** head, const char* method, const char* uri, time_t timestamp, void* headers);
HTTP_Request* list_search(HTTP_Request** head, const char* uri);
int list_update(HTTP_Request** head, const char* uri, void* new_headers);

void list_prune(HTTP_Request** head, time_t threshold);
int list_size(HTTP_Request* head);
size_t total_memory(const HTTP_Request* head);

int main() {
    // Initialize the request list
    HTTP_Request* requests = NULL;
    int cache_hit_rate = 0;
    size_t total_size = 0;

    while (1) {
        // Monitor memory usage and log warnings if necessary
        if (total_size > MEMORY_LIMIT) {
            printf("Memory limit exceeded! Further additions will not be possible.\n");
        }

        // Periodically prune the list of old requests
        time_t threshold = time(NULL) - 60 * 60; // Prune requests older than 1 hour
        list_prune(&requests, threshold);

        // Adjust memory limit based on system load (for demonstration purposes)
        // int system_load = get_system_load();
        // MEMORY_LIMIT *= (1 + system_load / 100.0);
    }

    return 0;
}

void list_add(HTTP_Request** head, const char* method, const char* uri, time_t timestamp, void* headers) {
    HTTP_Request* new_request = malloc(sizeof(HTTP_Request));
    strcpy(new_request->method, method);
    strcpy(new_request->uri, uri);
    new_request->timestamp = timestamp;
    new_request->headers = headers;

    if (*head == NULL || strcmp((*head)->uri, uri) > 0) {
        new_request->next = *head;
        *head = new_request;
    } else {
        HTTP_Request* current = *head;
        while (current->next && strcmp(current->next->uri, uri) < 0) {
            current = current->next;
        }
        new_request->next = current->next;
        current->next = new_request;
    }

    total_size += sizeof(HTTP_Request);
}

HTTP_Request* list_search(HTTP_Request** head, const char* uri) {
    HTTP_Request* current = *head;
    while (current && strcmp(current->uri, uri)) {
        current = current->next;
    }
    return current;
}

int list_update(HTTP_Request** head, const char* uri, void* new_headers) {
    HTTP_Request* request = list_search(head, uri);
    if (request) {
        request->headers = new_headers;
        return 1; // Request found and updated
    } else {
        return 0; // Request not found
    }
}

void list_prune(HTTP_Request** head, time_t threshold) {
    HTTP_Request* current = *head;
    HTTP_Request* previous = NULL;

    while (current && current->timestamp < threshold) {
        previous = current;
        current = current->next;
    }

    if (previous) {
        *head = current;
    } else {
        free(current);
    }
}

int list_size(HTTP_Request* head) {
    int size = 0;
    while (head) {
        size++;
        head = head->next;
    }
    return size;
}

size_t total_memory(const HTTP_Request* head) {
    size_t total = sizeof(HTTP_Request);
    while (head) {
        total += sizeof(HTTP_Request);
        head = head->next;
    }
    return total;
}
