public class ImageMetadata {
    public String format;
    public int width;
    public int height;
    // ... (other relevant properties)

    public ImageMetadata(String filePath) throws IOException {
        String fileExtension = getFileExtension(filePath);
        format = determineFormat(fileExtension);

        ImageReader reader = ImageIO.getImageReadersByFormatName(format);
        if (reader == null) {
            throw new IOException("Unsupported image format: " + format);
        }

        ImageInputStream stream = new FileInputStream(filePath);
        reader.setInput(stream);
        IIOMetadata metadata = reader.getImageMetadata();

        width = metadata.getWidth();
        height = metadata.getHeight();
    }

    private String getFileExtension(String filePath) {
        int lastDot = filePath.lastIndexOf('.');
        if (lastDot != -1) {
            return filePath.substring(lastDot + 1).toLowerCase();
        }
        return "";
    }

    private String determineFormat(String fileExtension) {
        // implement logic to determine the image format based on the file extension
    }
}
