void create_MAC_PDUs(int num_PDUs, MAC_PDU** pdus) {
    int i;
    for (i = 0; i < num_PDUs; i++) {
        MAC_PDU* pdu = malloc(sizeof(MAC_PDU));
        if (!pdu) {
            printf("Memory allocation failed!\n");
            return;
        }

        // Initialize PREAMBLE and SFI
        pdu->PREAMBLE = rand() % 1000;
        pdu->SFI = rand() % 2; // Assuming only two possible values for SFI

        // Generate random LCI value
        srand(time(NULL) + i); // Ensure randomness for each pdu
        int lci = rand() % 256;

        // Allocate memory for MAC_HEADER and align it correctly
        void* mac_header = malloc(4); // Assuming a 32-bit header
        if (!mac_header) {
            free(pdu);
            printf("Memory allocation failed!\n");
            return;
        }
        *(int*)mac_header = lci; // Store LCI in MAC_HEADER

        pdu->LCI = lci;
        pdu->MAC_HEADER = mac_header;

        // Verify integrity of each MAC_PDU
        if (pdu->PREAMBLE < 0 || pdu->SFI < 0 || pdu->LCI < 0) {
            printf("Invalid PDU values!\n");
            free(pdu);
            return;
        }

        // Record detailed information about the MAC_PDU using an external library
        // For demonstration purposes, we'll just print the details to stdout
        printf("Created PDU: PREAMBLE=%d SFI=%d LCI=%d\n", pdu->PREAMBLE, pdu->SFI, pdu->LCI);

        (*pdus) = realloc(*pdus, (i + 2) * sizeof(MAC_PDU*));
        (*pdus)[i] = pdu;
    }
}
