} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    pthread_t thread;
} PDU_Array;

PDU_Array pdu_array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, NULL};

void init_pdu_array() {
    pdu_array.pdus = (LTE_Uplink_PDCP_PDU *)malloc(MAX_ARRAY_SIZE * sizeof(LTE_Uplink_PDCP_PDU));
    pthread_cond_init(&pdu_array.cond, NULL);
}

int add_pdu(int PDCP_Seq_Num, int SDU_Size) {
    if (pdu_array.size >= pdu_array.capacity) {
        if (pthread_mutex_lock(&pdu_array.lock)) {
            perror("Error locking mutex");
            return -1;
        }
        if (pdu_array.size == MAX_ARRAY_SIZE) {
            printf("Array is full. Cannot add more PDUs.\n");
        } else {
            pdu_array.capacity *= 2;
            pdu_array.pdus = realloc(pdu_array.pdus, pdu_array.capacity * sizeof(LTE_Uplink_PDCP_PDU));
            if (!pdu_array.pdus) {
                perror("Error resizing array");
                return -1;
            }
        }
        pthread_mutex_unlock(&pdu_array.lock);
    }

    if (pdu_array.size >= pdu_array.capacity / 2) {
        printf("Array is half full. Consider reducing size.\n");
    }

    int i = 0;
    for (; i < pdu_array.size; i++) {
        if (pdu_array.pdus[i].PDCP_Seq_Num == PDCP_Seq_Num) {
            break;
        }
    }

    if (i >= pdu_array.size) {
        if (pthread_mutex_lock(&pdu_array.lock)) {
            perror("Error locking mutex");
            return -1;
        }
        memcpy(&pdu_array.pdus[pdu_array.size], &PDCP_Seq_Num, sizeof(LTE_Uplink_PDCP_PDU));
        pdu_array.size++;
        pthread_cond_signal(&pdu_array.cond);
        pthread_mutex_unlock(&pdu_array.lock);

    }

}

LTE_Uplink_PDCP_PDU* get_pdu(int PDCP_Seq_Num) {
    int i = 0;
    for (; i < pdu_array.size; i++) {
        if (pdu_array.pdus[i].PDCP_Seq_Num == PDCP_Seq_Num) {
            return &pdu_array.pdus[i];
        }
    }
    return NULL;
}

void update_pdu(int PDCP_Seq_Num, int Error_Indication) {
