    if (pdu) {
        pdu->Error_Indication = Error_Indication;
    }
}

void* scheduler_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&pdu_array.lock);
        if (pthread_cond_wait(&pdu_array.cond, &pdu_array.lock)) {
            perror("Error waiting on condition");
        }

        int i = 0;
        for (; i < pdu_array.size; i++) {
            LTE_Uplink_PDCP_PDU *pdu = &pdu_array.pdus[i];
            // process pdu
            pthread_mutex_unlock(&pdu_array.lock);
        }
    }
}

void register_callback(void (*callback)(LTE_Uplink_PDCP_PDU*)) {
    // implement callback registration mechanism
}

void handle_pdu_processing(LTE_Uplink_PDCP_PDU* pdu) {
    if (pdu->Error_Indication) {
        // notify error handling module
    } else {
        // notify processing completed module
    }
}

int main() {
