#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000
#define CHECKSUM_SIZE 4

typedef struct LTE_Uplink_PDCP_PDU {
    int sequenceNumber;
    int sduSize;
    int errorIndication;
} LTE_Uplink_PDCP_PDU;

// Dynamic array management function
LTE_Uplink_PDCP_PDU* pdcppdu_array = NULL;
int pdcppdu_array_size = 0;
int max_pdcppdu_array_size = MAX_ARRAY_SIZE;
int total_pdcppdu_count = 0;

pthread_mutex_t pdcppdu_array_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdcppdu_array_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t pdcppdu_array_full = PTHREAD_COND_INITIALIZER;

// Function to add a new PDU to the array
void addPDCPPDU(LTE_Uplink_PDCP_PDU* pdu) {
    if (pdcppdu_array_size == max_pdcppdu_array_size) {
        // If the array is full, log a warning and exit
        printf("Array is full. Cannot add more PDUs.\n");
        return;
    }

    pthread_mutex_lock(&pdcppdu_array_lock);
    if (pdcppdu_array_size == max_pdcppdu_array_size) {
        // If the array is still full after acquiring the lock, 
        // log a warning and exit
        printf("Array is still full. Cannot add more PDUs.\n");
        pthread_mutex_unlock(&pdcppdu_array_lock);
        return;
    }

    pdcppdu_array[pdcppdu_array_size] = *pdu;
    pdcppdu_array_size++;
    total_pdcppdu_count++;

    if (pdcppdu_array_size == max_pdcppdu_array_size) {
        pthread_cond_signal(&pdcppdu_array_full);
    }

    pthread_mutex_unlock(&pdcppdu_array_lock);
}

// Function to retrieve a PDU by its sequence number
LTE_Uplink_PDCP_PDU* getPDUCPPDU(int seqNumber) {
    for (int i = 0; i < pdcppdu_array_size; i++) {
        if (pdcppdu_array[i].sequenceNumber == seqNumber) {
            return &pdcppdu_array[i];
        }
    }

    // If the PDU is not found, log a warning and return NULL
    printf("PDU with sequence number %d not found.\n", seqNumber);
    return NULL;
}

// Function to update the error indication for a given SN
void updateErrorIndication(int sequenceNumber, int error) {
    pthread_mutex_lock(&pdcppdu_array_lock);

    for (int i = 0; i < pdcppdu_array_size; i++) {
        if (pdcppdu_array[i].sequenceNumber == sequenceNumber) {
            pdcppdu_array[i].errorIndication = error;
            break;
        }
    }

    pthread_mutex_unlock(&pdcppdu_array_lock);
}

// Function to track system-wide resource availability
void monitorResources() {
    // Monitor CPU, memory, and disk I/O usage
    if (resource_usage_level < CRITICAL_THRESHOLD) {
        max_pdcppdu_array_size = adjusted_max_array_size;
    }
}

// Function to add a new PDU to the array with integrity check
int addPDCPPDUWithCheck(LTE_Uplink_PDCP_PDU* pdu) {
    int checksum = calculate_checksum(pdu->sdu);
    if (checksum != pdu->checksum) {
        printf("Corrupted SDU detected. Rejecting PDU.\n");
        return -1;
    }

    addPDCPPDU(pdu);
    return 0;
}

// Function to log statistics and notify callbacks
void logStatistics() {
    // Log the number of pending PDUs, average processing time per PDU, etc.
    printf("Statistics: %d PDUs pending, avg processing time per PDU = %.2f sec\n", total_pdcppdu_count, average_processing_time);
}

// Callback mechanism to notify external modules
void registerCallback(void (*callback)(int, int)) {
    callback_registration_list.push_back(callback);
}

// Function to invoke callbacks for processed PDUs or errors
void invokeCallbacks(int sequenceNumber, int status) {
    for (auto callback : callback_registration_list) {
        callback(sequenceNumber, status);
    }
}
