#include <stdlib.h>
#include <string.h>

typedef struct LTE_Uplink_PDCP_PDU {
    uint32_t SN;
    uint16_t SDU_size;
    uint8_t error_indication;
} PDU;

void* operator new(size_t size) throw()
{
    void *p = malloc(size);
    if (p == 0)
        throw std::bad_alloc();
    return p;
}

void operator delete(void *p) throw()
{
    free(p);
}

class LTE_Uplink_PDCP_PDU_array {
public:
    LTE_Uplink_PDCP_PDU_array() : size(0), capacity(10), pdus(new PDU[capacity]) {}

    ~LTE_Uplink_PDCP_PDU_array() {
        for (int i = 0; i < size; i++) {
            delete[] pdus[i].SN;
            delete[] pdus[i].SDU_size;
            delete[] pdus[i].error_indication;
        }
        delete[] pdus;
    }

    void addPDU(PDU* p) {
        if (size == capacity) {
            capacity *= 2;
            PDU* temp = new PDU[capacity];
            memcpy(temp, pdus, size * sizeof(PDU));
            delete[] pdus;
            pdus = temp;
        }
        pdus[size] = *p;
        size++;
    }

    PDU* get(const uint32_t SN) {
        for (int i = 0; i < size; i++) {
            if (pdus[i].SN == SN)
                return &pdus[i];
        }
        return nullptr;
    }

    void updateErrorIndication(const uint32_t SN, const uint8_t error_indication) {
        for (int i = 0; i < size; i++) {
            if (pdus[i].SN == SN) {
                pdus[i].error_indication = error_indication;
                return;
            }
        }
    }

private:
    int size;
    int capacity;
    PDU* pdus;
};
