#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
    long timestamp;
} LTE_Uplink_PDCP_PDU;

struct {
    LTE_Uplink_PDCP_PDU* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} pdcp_pdu_array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_pdu_array() {
    if (pdcp_pdu_array.array != NULL) return; // Already initialized
    pdcp_pdu_array.capacity = 16;
    pdcp_pdu_array.array = malloc(pdcp_pdu_array.capacity * sizeof(LTE_Uplink_PDCP_PDU));
    pdcp_pdu_array.size = 0;
    pthread_mutex_init(&pdcp_pdu_array.mutex, NULL);
}

LTE_Uplink_PDCP_PDU* add_pdu(int SN, int SDU_size) {
    pthread_mutex_lock(&pdcp_pdu_array.mutex);

    if (pdcp_pdu_array.size >= pdcp_pdu_array.capacity) {
        // Reallocate memory with double the size
        size_t new_capacity = pdcp_pdu_array.capacity * 2;
        LTE_Uplink_PDCP_PDU* new_array = realloc(pdcp_pdu_array.array, new_capacity * sizeof(LTE_Uplink_PDCP_PDU));
        if (new_array == NULL) {
            // Out of memory
            printf("Out of memory\n");
            pthread_mutex_unlock(&pdcp_pdu_array.mutex);
            return NULL;
        }
        pdcp_pdu_array.capacity = new_capacity;
        pdcp_pdu_array.array = new_array;
    }

    LTE_Uplink_PDCP_PDU* pdu = &pdcp_pdu_array.array[pdcp_pdu_array.size++];
    pdu->SN = SN;
    pdu->SDU_size = SDU_size;
    pdu->error_indication = 0; // Initialize to no error
    pdu->timestamp = time(NULL);
    pthread_mutex_unlock(&pdcp_pdu_array.mutex);
    return pdu;
}

LTE_Uplink_PDCP_PDU* get_pdu(int SN) {
    pthread_mutex_lock(&pdcp_pdu_array.mutex);

    for (size_t i = 0; i < pdcp_pdu_array.size; i++) {
        if (pdcp_pdu_array.array[i].SN == SN) {
            pthread_mutex_unlock(&pdcp_pdu_array.mutex);
            return &pdcp_pdu_array.array[i];
        }
    }

    pthread_mutex_unlock(&pdcp_pdu_array.mutex);
    return NULL;
}

void update_pdu_error(int SN, int error_indication) {
    pthread_mutex_lock(&pdcp_pdu_array.mutex);

    for (size_t i = 0; i < pdcp_pdu_array.size; i++) {
        if (pdcp_pdu_array.array[i].SN == SN) {
            pdcp_pdu_array.array[i].error_indication = error_indication;
            pthread_mutex_unlock(&pdcp_pdu_array.mutex);
            return;
        }
    }

    pthread_mutex_unlock(&pdcp_pdu_array.mutex);
}

void delete_pdu(int SN) {
    pthread_mutex_lock(&pdcp_pdu_array.mutex);

    for (size_t i = 0; i < pdcp_pdu_array.size; i++) {
        if (pdcp_pdu_array.array[i].SN == SN) {
            // Shift remaining PDUs to the left
            memmove(&pdcp_pdu_array.array[i], &pdcp_pdu_array.array[i + 1], (pdcp_pdu_array.size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            pdcp_pdu_array.size--;
            break;
        }
    }

    pthread_mutex_unlock(&pdcp_pdu_array.mutex);
}

int main() {
    init_pdu_array();
    LTE_Uplink_PDCP_PDU* pdu = add_pdu(1, 100);
    // ...
    return 0;
}
