USE [EmployeesDB]

DECLARE @SupervisorID INT = ?; -- dynamic input parameter

CREATE TYPE dbo.SupervisorIDType AS INT;

CREATE PROCEDURE GetEmployeeInfoBySupervisorID 
    @supervisorID SupervisorIDType READONLY, 
    @cacheTimeout INT = 3600, -- default cache timeout in seconds
    @maxRetryAttempts INT = 3, -- max retry attempts for connection timeouts
    @retryInterval INT = 5000  -- retry interval in milliseconds

AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EmployeeName NVARCHAR(50),
            @City NVARCHAR(50),
            @Address NVARCHAR(100);

    IF EXISTS (SELECT 1 FROM Employees WHERE SupervisorID = @supervisorID)
    BEGIN
        SELECT @EmployeeName = e.Name, @City = e.City, @Address = e.Address
        FROM Employees e
        WHERE e.SupervisorID = @supervisorID;

        -- cache the result for a specified time period (default 1 hour)
        INSERT INTO CacheEmployees (SupervisorID, EmployeeName, City, Address, ExpirationTime)
        VALUES (@supervisorID, @EmployeeName, @City, @Address, DATEADD(SECOND, @cacheTimeout, GETDATE()));

        -- log query execution time and result
        DECLARE @queryExecutionTime INT;
        SET @queryExecutionTime = DATEDIFF(MILLISECOND, GETDATE(), GETDATE());
        INSERT INTO QueryLog (SupervisorID, QueryExecutionTime, EmployeeName, City, Address)
        VALUES (@supervisorID, @queryExecutionTime, @EmployeeName, @City, @Address);
    END
    ELSE
    BEGIN
        -- handle supervisor ID not found
        RAISERROR ('Supervisor ID not found', 16, 1);
    END;

END

GO

CREATE PROCEDURE GetEmployeeInfoBySupervisorIDWithCache
    @supervisorID SupervisorIDType READONLY,
    @retryAttempts INT = @maxRetryAttempts,
    @retryInterval INT = @retryInterval
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EmployeeName NVARCHAR(50),
            @City NVARCHAR(50),
            @Address NVARCHAR(100);

    -- check cache for the result (if available within timeout period)
    IF EXISTS (SELECT 1 FROM CacheEmployees WHERE SupervisorID = @supervisorID AND ExpirationTime > GETDATE())
    BEGIN
        SELECT @EmployeeName = ce.EmployeeName, @City = ce.City, @Address = ce.Address
        FROM CacheEmployees ce
        WHERE ce.SupervisorID = @supervisorID;

        -- log query execution time and result (cached)
        DECLARE @queryExecutionTime INT;
        SET @queryExecutionTime = DATEDIFF(MILLISECOND, GETDATE(), GETDATE());
        INSERT INTO QueryLog (SupervisorID, QueryExecutionTime, EmployeeName, City, Address)
        VALUES (@supervisorID, @queryExecutionTime, @EmployeeName, @City, @Address);
    END
    ELSE
    BEGIN
        -- if cache timeout or no cache available, execute the query and retry on failure
        WHILE @retryAttempts > 0 AND @retryInterval > 0
        BEGIN
            TRY
                EXEC GetEmployeeInfoBySupervisorID @supervisorID;
                SET @retryAttempts = 0;  -- break retry loop if successful
            CATCH
            BEGIN
                -- handle query failure and retry on connection timeout or other transient errors
                WAITFOR TIMEOUT '00:00:05';  -- wait for 5 seconds before next retry
                SET @retryInterval -= 5000;
                SET @retryAttempts -= 1;
            END TRY
        END WHILE;

        IF @retryAttempts = 0 AND @retryInterval = 0
        BEGIN
            -- query execution successful, update cache and log
            INSERT INTO CacheEmployees (SupervisorID, EmployeeName, City, Address, ExpirationTime)
            VALUES (@supervisorID, @EmployeeName, @City, @Address, DATEADD(SECOND, @cacheTimeout, GETDATE()));

            DECLARE @queryExecutionTime INT;
            SET @queryExecutionTime = DATEDIFF(MILLISECOND, GETDATE(), GETDATE());
            INSERT INTO QueryLog (SupervisorID, QueryExecutionTime, EmployeeName, City, Address)
            VALUES (@supervisorID, @queryExecutionTime, @EmployeeName, @City, @Address);
        END
    END;

END

GO

CREATE PROCEDURE GetEmployeeInfoBySupervisorIDWithCacheAndIntegration
    @supervisorID SupervisorIDType READONLY,
    @retryAttempts INT = @maxRetryAttempts,
    @retryInterval INT = @retryInterval
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @EmployeeName NVARCHAR(50),
