} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdus[MAX_PDU];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int pdu_count = 0;

void create_pdu(NFAPI_CRC_INDICATION_PDU_T** pdus_ptr, int seq_num) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Out of memory\n");
        return;
    }
    pdu->rx_ue_info = ...; // random initialization
    pdu->rnti = ...; // random initialization
    pdu->crc_ind_rel8 = ...; // random initialization
    pdu->crcflag = rand() % 2; // random CRCFLAG value
    *pdus_ptr = pdu;
}

void add_pdu(int seq_num) {
    pthread_mutex_lock(&mutex);
    if (pdu_count < MAX_PDU) {
        create_pdu(&pdus[pdu_count], seq_num);
        pdu_count++;
    } else {
        printf("PDU list is full\n");
    }
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(int seq_num) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < pdu_count; i++) {
        if (pdus[i]->seq_num == seq_num) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = pdus[i];
            pthread_mutex_unlock(&mutex);
            return pdu;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_crc(int seq_num, int new_crcflag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < pdu_count; i++) {
        if (pdus[i]->seq_num == seq_num) {
            pdus[i]->crcflag = new_crcflag;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free(pdu);
}
