        printf("PDU list is full. Cannot add more.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);
    pdu_list[pdu_count] = pdu;
    pdu_count++;
    pthread_mutex_unlock(&lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *get_pdu(int sn) {
    if (sn >= pdu_count) {
        printf("PDU not found.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_list[sn];
    pthread_mutex_unlock(&lock);

    return pdu;
}

int update_pdu(int sn, int new_crcflag) {
    if (sn >= pdu_count) {
        printf("PDU not found.\n");
        return -1;
    }

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_list[sn];
    pdu->crcflag = new_crcflag;
    pthread_mutex_unlock(&lock);

    return 0;
}

int prune_old_pus(int threshold) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_PDU; i++) {
        if (pdu_list[i] != NULL && pdu_list[i]->crcflag < threshold) {
            pdu_list[i] = NULL;
        }
    }
    pthread_mutex_unlock(&lock);

    return 0;
}

void* thread_function(void* arg) {
    int sn = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = get_pdu(sn);
    if (pdu != NULL) {
        // process pdu
    }

    return NULL;
}

void run_threads() {
    pthread_t threads[MAX_PDU];
    for (int i = 0; i < MAX_PDU; i++) {
        int* sn = malloc(sizeof(int));
        *sn = i;
        pthread_create(&threads[i], NULL, thread_function, sn);
    }

    for (int i = 0; i < MAX_PDU; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    create_pdu_list();
    // run threads
    return 0;
}
