typedef struct {
    uint32_t seq_num;
    uint32_t ack_num;
    int seg_size;
    uint16_t flags;
    int error_ind;
} TCP_Segment;

typedef struct {
    TCP_Segment* segments;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SegmentArray;

void segment_array_init(SegmentArray* arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->segments = (TCP_Segment*)malloc(initial_capacity * sizeof(TCP_Segment));
    pthread_mutex_init(&arr->lock, NULL);
}

int segment_array_add(SegmentArray* arr, TCP_Segment seg) {
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        arr->segments = realloc(arr->segments, new_capacity * sizeof(TCP_Segment));
        arr->capacity = new_capacity;
    }
    arr->segments[arr->size++] = seg;
    return 0;
}

TCP_Segment* segment_array_get(SegmentArray* arr, uint32_t seq_num) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->segments[i].seq_num == seq_num) {
            pthread_mutex_unlock(&arr->lock);
            return &arr->segments[i];
        }
    }
    return NULL;
}

void segment_array_update_error(SegmentArray* arr, uint32_t seq_num, int error_ind) {
    pthread_mutex_lock(&arr->lock);
    for (int i = 0; i < arr->size; i++) {
        if (arr->segments[i].seq_num == seq_num) {
            arr->segments[i].error_ind = error_ind;
            break;
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

void segment_array_free(SegmentArray* arr) {
    free(arr->segments);
    pthread_mutex_destroy(&arr->lock);
}
