typedef struct {
    char method[4];
    char url[MAX_URL_LENGTH];
    int status_code;
} HTTP_Request;

typedef struct {
    HTTP_Request* requests;
    int request_count;
    pthread_mutex_t lock;
} RequestCollection;

RequestCollection* request_collection_create() {
    RequestCollection* collection = (RequestCollection*)malloc(sizeof(RequestCollection));
    collection->requests = (HTTP_Request*)malloc(MAX_REQUESTS * sizeof(HTTP_Request));
    collection->request_count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void request_collection_add(RequestCollection* collection, const char* method, const char* url) {
    pthread_mutex_lock(&collection->lock);
    if (collection->request_count >= MAX_REQUESTS) {
        printf("Error: Request collection is full.\n");
        exit(1);
    }
    strcpy(collection->requests[collection->request_count].method, method);
    strncpy(collection->requests[collection->request_count].url, url, MAX_URL_LENGTH - 1);
    collection->request_count++;
    pthread_mutex_unlock(&collection->lock);
}

HTTP_Request* request_collection_get(RequestCollection* collection, const char* url) {
    for (int i = 0; i < collection->request_count; i++) {
        if (strcmp(collection->requests[i].url, url) == 0) {
            return &collection->requests[i];
        }
    }
    printf("Error: Request not found.\n");
    exit(1);
}

void request_collection_update_status(RequestCollection* collection, const char* url, int status_code) {
    HTTP_Request* request = request_collection_get(collection, url);
    pthread_mutex_lock(&collection->lock);
    request->status_code = status_code;
    pthread_mutex_unlock(&collection->lock);
}
