#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONCURRENT_PDU 50000
#define MAX_PDU_PER_SECOND 5000
#define PDU_SIZE sizeof(LTE_Uplink_PDCP_PDU) + sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    LTE_Uplink_PDCP_PDU pdu;
    NFAPI_CRC_INDICATION_PDU_T crcIndicationPdu;
} PDU_Type;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
PDU_Type* pdus = NULL;
int pduCount = 0;
int allocatedBytes = 0;

void* addPdus(void* args) {
    int numPdus = (int)args;

    for(int i=0; i < numPdus; i++) {
        PDU_Type* newPdu = (PDU_Type*)malloc(PDU_SIZE);

        if(newPdu != NULL) {
            // Initialize PDU fields
            // ...

            pthread_mutex_lock(&lock);
            pdus = realloc(pdus, (pduCount + 1) * PDU_SIZE);
            allocatedBytes += PDU_SIZE;
            pdus[pduCount].pdu.sn = i; // Assign SN to new PDU
            pdus[pduCount++].crcIndicationPdu.RX_UE_INFORMATION_TAG = ...; // Initialize other fields

            pthread_mutex_unlock(&lock);
        } else {
            // Handle allocation error
        }
    }

    return NULL;
}

void* retrievePduBySn(void* args) {
    int sn = (int)args;

    for(int i=0; i < pduCount; i++) {
        if(pdus[i].pdu.sn == sn) {
            // Return the PDU
            return &pdus[i];
        }
    }

    return NULL;
}

void* updateErrorIndication(void* args) {
    int sn = (int)args;

    for(int i=0; i < pduCount; i++) {
        if(pdus[i].pdu.sn == sn) {
            // Update error indication field
            pdus[i].crcIndicationPdu.errorIndicationField = ...;

            return NULL;
        }
    }

    return NULL;
}

void* deletePdusBySn(void* args) {
    int* sns = (int*)args;
    int snCount = *sns++;

    for(int i=0; i < snCount; i++) {
        for(int j=0; j < pduCount; j++) {
            if(pdus[j].pdu.sn == *sns++) {
                // Delete PDU
                pthread_mutex_lock(&lock);
                memmove(&pdus[j], &pdus[j+1], (pduCount - j - 1) * PDU_SIZE);
                pduCount--;
                free(pdus + j * PDU_SIZE);
                allocatedBytes -= PDU_SIZE;

                pthread_mutex_unlock(&lock);
            }
        }
    }

    return NULL;
}

void logStatistics() {
    printf("Memory Pressure: %d\n", allocatedBytes / (pduCount * PDU_SIZE));
    printf("Successful Allocations: %d\n", pduCount);
}

int main(int argc, char** argv) {
    pthread_t threads[10];

    for(int i=0; i < 5; i++) {
        int numPdus = rand() % MAX_PDU_PER_SECOND;
        pthread_create(&threads[i], NULL, addPdus, (void*)numPdus);
    }

    // Simulate concurrent PDU operations
    for(int i=0; i < 5; i++) {
        int sn = rand() % pduCount;
        pthread_create(&threads[5 + i], NULL, retrievePduBySn, (void*)sn);

        sn = rand() % pduCount;
        pthread_create(&threads[10 + i], NULL, updateErrorIndication, (void*)sn);
    }

    // Simulate PDU deletion
    int sns[] = {0};
    sns[0] = 1; sns[1] = 2; sns[2] = pduCount - 1;
    pthread_create(&threads[15], NULL, deletePdusBySn, (void*)sns);

    // Wait for threads to finish
    for(int i=0; i < 16; i++) {
        pthread_join(threads[i], NULL);
    }

    logStatistics();

    return 0;
}
