#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define structures
typedef struct {
    int pdcp_sequence_number;
    int sdusize;
    int error_indication;
    long timestamp;
    int connection_id;
    int status;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    int rnti;
    int crcflag;
    // ... other fields
} NFAPI_CRC_INDICATION_PDU_T;

// Define the main structure to hold both structures
typedef struct {
    LTE_Uplink_PDCP_PDU pdcp_pdu;
    NFAPI_CRC_INDICATION_PDU_T nfa_pdu;
    TCP_Connector connector;
} DynamicArrayEntry;

// Function prototypes
void* dynamic_array_allocate(size_t size);
void dynamic_array_free(void** ptr, size_t size);

// Initialize and manage the dynamic array of structures
int lte_uplink_pdcps_init(int max_size) {
    // Create a dynamic array with space for up to 'max_size' entries
    void **array = dynamic_array_allocate(max_size * sizeof(DynamicArrayEntry*));

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    return 0;
}

// Add a new entry to the array
int lte_uplink_pdcps_add(void** array, int max_size, LTE_Uplink_PDCP_PDU* pdcp_pdu, TCP_Connector* connector) {
    // Find the first empty slot in the array
    for (int i = 0; i < max_size; i++) {
        if (!array[i]) {
            // Allocate memory for a new entry and store it at this position
            DynamicArrayEntry* entry = dynamic_array_allocate(sizeof(DynamicArrayEntry));
            entry->pdcp_pdu = *pdcp_pdu;
            entry->connector = *connector;
            array[i] = &entry;
            return i;  // Return the index of the new entry
        }
    }

    return -1;  // Array is full, cannot add more entries
}

// Retrieve an entry by its sequence number or connection ID
int lte_uplink_pdcps_get(void** array, int max_size, int seq_num_or_id) {
    // Search for the first matching sequence number or connection ID in the array
    for (int i = 0; i < max_size; i++) {
        if (!array[i]) continue;

        DynamicArrayEntry* entry = *array[i];
        if (entry->pdcp_pdu.pdcp_sequence_number == seq_num_or_id || entry->connector.connection_id == seq_num_or_id) {
            return i;  // Return the index of the matching entry
        }
    }

    return -1;  // Not found
}

// Update an existing entry by its sequence number or connection ID
int lte_uplink_pdcps_update(void** array, int max_size, int seq_num_or_id, LTE_Uplink_PDCP_PDU* pdcp_pdu, TCP_Connector* connector) {
    // Find the matching entry in the array
    int index = lte_uplink_pdcps_get(array, max_size, seq_num_or_id);
    if (index == -1) return -1;  // Not found

    DynamicArrayEntry* entry = *array[index];
    // Update the fields of the existing entry
    entry->pdcp_pdu = *pdcp_pdu;
    entry->connector = *connector;

    return 0;  // Success
}

// Delete an entry by its sequence number or connection ID
