```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t sequence_number;
    uint32_t acknowledgment_number;
    uint16_t segment_size;
    uint8_t flags;
    int error_indication;
} TCP_Segment;

struct Segments {
    TCP_Segment* segments;
    size_t capacity;
    size_t size;
};

TCP_Segment* segment_array_init(size_t initial_capacity) {
    struct Segments* seg = malloc(sizeof(struct Segments));
    seg->segments = calloc(initial_capacity, sizeof(TCP_Segment));
    seg->capacity = initial_capacity;
    seg->size = 0;
    return &seg->segments[0];
}

void segment_array_free(struct Segments* segments) {
    free(segments->segments);
    free(segments);
}

TCP_Segment* segment_array_add_segment(TCP_Segment** segments, size_t capacity, TCP_Segment new_segment) {
    if (*segments == NULL || *segments->size >= capacity) {
        // Realloc the array with a larger capacity
        TCP_Segment* new_segments = realloc(*segments, sizeof(TCP_Segment) * (capacity *= 2));
        *segments = &new_segments[0];
    }
    (*segments)->segments[*segments->size++] = new_segment;
    return &((*segments)->segments[*segments->size - 1]);
}

TCP_Segment* segment_array_get_segment(TCP_Segment** segments, size_t capacity, uint32_t sequence_number) {
    for (int i = 0; i < *segments->size; i++) {
        if ((*segments)->segments[i].sequence_number == sequence_number) {
            return &((*segments)->segments[i]);
        }
    }
    // Return NULL if the segment is not found
    return NULL;
}

void segment_array_update_error(TCP_Segment** segments, size_t capacity, uint32_t sequence_number, int error_indication) {
    for (int i = 0; i < *segments->size; i++) {
        if ((*segments)->segments[i].sequence_number == sequence_number) {
            (*segments)->segments[i].error_indication = error_indication;
            return;
        }
    }
}
