typedef struct {
    HTTP_Request* request;
    struct list_node* next;
} List_Node;

typedef struct {
    List_Node* head;
    int size;
} Dynamic_List;

void init_list(Dynamic_List* list) {
    list->head = NULL;
    list->size = 0;
}

HTTP_Request* create_request(char* method, char* uri, time_t timestamp, int id) {
    HTTP_Request* request = (HTTP_Request*) malloc(sizeof(HTTP_Request));
    request->method = strdup(method);
    request->uri = strdup(uri);
    request->retry_count = 0;
    request->timestamp = timestamp;
    request->id = id;
    return request;
}

void add_request(Dynamic_List* list, HTTP_Request* request) {
    List_Node* new_node = (List_Node*) malloc(sizeof(List_Node));
    new_node->request = request;
    new_node->next = NULL;

    if (!list->head) {
        list->head = new_node;
    } else {
        List_Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->size++;
}

HTTP_Request* get_request_by_uri(Dynamic_List* list, char* uri) {
    List_Node* current = list->head;
    while (current) {
        if (strcmp(current->request->uri, uri) == 0) {
            return current->request;
        }
        current = current->next;
    }

    return NULL;
}

