```java
import java.util.*;
import java.io.*;

public class ImageCache {
    private Map<String, Bitmap> cache;
    private String defaultDirectory;
    private int maxCacheSize;
    private Logger logger;

    public ImageCache(String defaultDirectory, int maxCacheSize) {
        this.defaultDirectory = defaultDirectory;
        this.maxCacheSize = maxCacheSize;
        this.cache = new LRUHashMap<>();
        this.logger = LoggerFactory.getLogger(ImageCache.class);
    }

    public void putImage(String key, Bitmap image) throws IOException {
        if (image != null && !cache.containsKey(key)) {
            // Compress and optimize the image
            Bitmap optimizedImage = ImageProcessor.optimize(image);
            cache.put(key, optimizedImage);
            logger.info("Cached image: " + key);
        } else if (!image.isRecyclable()) {
            throw new IOException("Image is not recyclable");
        }
    }

    public Bitmap getImage(String key) {
        return cache.getOrDefault(key, null);
    }

    public void removeImage(String key) {
        cache.remove(key);
    }

    public void clearCache() {
        cache.clear();
    }

    public int getSize() {
        return cache.size();
    }

    // Image resizing mechanism
    public Bitmap resizeImage(String key, int width, int height) {
        Bitmap image = getImage(key);
        if (image != null) {
            Bitmap resizedImage = ImageProcessor.resize(image, width, height);
            putImage(key, resizedImage);
            return resizedImage;
        }
        return null;
    }

    // Mechanism to detect and handle corrupted images
    public void checkAndRemoveCorruptedImages() {
        for (Map.Entry<String, Bitmap> entry : cache.entrySet()) {
            if (!entry.getValue().isRecyclable()) {
                removeImage(entry.getKey());
            }
        }
    }

    // Lazy loading mechanism
    public Bitmap lazyLoadImage(String key) {
        if (!cache.containsKey(key)) {
            // Download the image and store it in the cache
            Bitmap image = ImageProcessor.loadImageFromUrl(key);
            putImage(key, image);
        }
        return cache.getOrDefault(key, null);
    }

    // Compression strategy
    public void compressImages() {
        for (Map.Entry<String, Bitmap> entry : cache.entrySet()) {
            Bitmap compressedImage = ImageProcessor.compress(entry.getValue());
            putImage(entry.getKey(), compressedImage);
        }
    }

    // Tracking and logging image requests
    public void logImageRequests() {
        logger.info("Total images requested: " + cache.size());
    }
}
