        int newCapacity = pdus->capacity * 2;
        pdus->pdus = (LTE_Uplink_PDCP_PDU*)realloc(pdus->pdus, newCapacity * LTE_UPLINK_PDCP_PDU_SIZE);
        pdus->capacity = newCapacity;
