void manageLTEUplinkPDUS(int* request_oauth) {
    // Initialize the dynamic array
    LTE_Uplink_PDCP_PDU** pdus = NULL;
    int num_pds = 0;
    int size = 1; // Initial size of the array

    while (1) {
        // Allocate memory for the new PDU
        LTE_Uplink_PDCP_PDU* pnu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        if (pnu == NULL) {
            printf("Error allocating memory\n");
            return;
        }

        // Initialize the PDU
        pnu->PDCP_Seq_Num = 0;
        pnu->SDU_Size = 0;
        pnu->Error_Indication = 0;

        // Add the new PDU to the array
        pdus = (LTE_Uplink_PDCP_PDU**)realloc(pdus, sizeof(LTE_Uplink_PDCP_PDU*) * (num_pds + 1));
        if (pdus == NULL) {
            printf("Error allocating memory\n");
            return;
        }

        pdus[num_pds] = pnu;

        num_pds++;

        // If the array is full, double its size
        if (num_pds >= size) {
            size *= 2;
        }
    }
}
