#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SN;
    size_t SDU_size;
    int error_indication;
    char payload[1024];
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t current_size;
} PDCP_Array;

void pdcps_init(PDCP_Array* array) {
    array->capacity = 10;
    array->current_size = 0;
    array->pdus = (LTE_Uplink_PDCP_PDU*)calloc(array->capacity, sizeof(LTE_Uplink_PDCP_PDU));
}

int pdcps_add(PDCP_Array* array, LTE_Uplink_PDCP_PDU* new_pdu) {
    if (array->current_size >= array->capacity) {
        array->capacity *= 2;
        void* temp = realloc(array->pdus, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
        if (!temp) return -1; // out of memory
        array->pdus = temp_cast(LTE_Uplink_PDCP_PDU*, temp);
    }
    array->pdus[array->current_size] = *new_pdu;
    return 0;
}

int pdcps_get(PDCP_Array* array, int SN, LTE_Uplink_PDCP_PDU* target_pdu) {
    for (size_t i = 0; i < array->current_size; i++) {
        if (array->pdus[i].SN == SN) {
            *target_pdu = array->pdus[i];
            return 0;
        }
    }
    return -1; // PDU not found
}

int pdcps_update_error(PDCP_Array* array, int SN, int new_error_indication) {
    for (size_t i = 0; i < array->current_size; i++) {
        if (array->pdus[i].SN == SN) {
            array->pdus[i].error_indication = new_error_indication;
            return 0;
        }
    }
    return -1; // PDU not found
}

int pdcps_get_payload(PDCP_Array* array, int SN, char* target_payload) {
    for (size_t i = 0; i < array->current_size; i++) {
        if (array->pdus[i].SN == SN) {
            memcpy(target_payload, array->pdus[i].payload, strlen(array->pdus[i].payload));
            return 0;
        }
    }
    return -1; // PDU not found
}

int pdcps_flush(PDCP_Array* array) {
    free(array->pdus);
    pdcps_init(array);
    return 0;
}
