import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class TaskManager {
    private final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private final ThreadPoolExecutor executor;

    public TaskManager(int corePoolSize, int maximumPoolSize) {
        executor = new ThreadPoolExecutor(corePoolSize, maximumPoolSize, 60L, TimeUnit.SECONDS);
    }

    public void manageAsynchronousTaskQueue() throws InterruptedException {
        for (Runnable task : queue.toArray(new Runnable[0])) {
            try {
                Future<?> future = executor.submit(task);
                if (!future.isDone()) {
                    // Handle timeouts or failures
                    future.get();
                }
            } catch (ExecutionException e) {
                // Log and handle exceptions
            } finally {
                executor.shutdown();
            }
        }
    }

    public void scheduleTask(Runnable task) {
        queue.add(task);
    }

    public void shutdown() {
        executor.shutdown();
    }
}
