Metadata processImageMetadata(char* filePath) {
    Metadata metadata;
    char filename[256];
    strcpy(filename, filePath);

    // Extract file extension
    const char* ext = strrchr(filename, '.');
    if (ext != NULL) {
        // Determine format type based on file extension
        if (strcmp(ext, ".jpg") == 0 || strcmp(ext, ".jpeg") == 0) {
            metadata.format[0] = '\0';
        } else if (strcmp(ext, ".png") == 0) {
            strcpy(metadata.format, "PNG");
        } else if (strcmp(ext, ".gif") == 0) {
            strcpy(metadata.format, "GIF");
        } else {
            // Default format
            strcpy(metadata.format, "Unknown");
        }
    }

    // Read file metadata
    FILE* file = fopen(filePath, "rb");
    if (file != NULL) {
        fseek(file, 6, SEEK_SET); // Seek to the start of EXIF data
        int width, height;
        fread(&width, sizeof(int), 1, file);
        fread(&height, sizeof(int), 1, file);
        metadata.width = width;
        metadata.height = height;

        fclose(file);
    } else {
        // Handle file not found or error reading file
        strcpy(metadata.format, "Error");
    }

    return metadata;
}
