typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    int size;
    int capacity;
    int successfulTransmissions;
    int errors;
} PDCP_Array;

void pdcP_array_init(PDCP_Array* array) {
    array->size = 0;
    array->capacity = 4; // Initial capacity
    array->pdus = (LTE_Uplink_PDCP_PDU*)malloc(array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    array->successfulTransmissions = 0;
    array->errors = 0;
}

void pdcP_array_add(PDCP_Array* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->size == array->capacity) {
        // Increase capacity and reallocate memory
        array->capacity *= 2;
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    }
    array->pdus[array->size] = pdu;
    array->size++;
}

LTE_Uplink_PDCP_PDU* pdcP_array_get(PDCP_Array* array, int sequenceNumber) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

void pdcP_array_update_error(PDCP_Array* array, int sequenceNumber, int errorIndication) {
    LTE_Uplink_PDCP_PDU* pdu = pdcP_array_get(array, sequenceNumber);
    if (pdu != NULL) {
        pdu->errorIndication = errorIndication;
        if (errorIndication > 0) array->errors++;
        else array->successfulTransmissions++;
    }
}

void pdcP_array_free(PDCP_Array* array) {
    free(array->pdus);
}
