// ImageLoader.js
import { URL } from 'url';
import { Promise } from 'bluebird';

class ImageLoader {
  constructor(options = {}) {
    this.options = options;
    this.cache = {};
    this.queue = [];
  }

  async load(url, priority) {
    if (!this.queue.includes(url)) this.queue.push(url);
    const cachedImage = this.cache[url];
    if (cachedImage) return cachedImage;

    const request = new URL(url);

    try {
      const response = await fetch(request.href, {
        method: 'GET',
        headers: {
          Accept: 'image/*',
        },
      });
      const imageBuffer = await response.arrayBuffer();
      this.cache[url] = Buffer.from(imageBuffer);
    } catch (error) {
      if (this.options.fallback) {
        try {
          const fallbackResponse = await fetch(this.options.fallback, {
            method: 'GET',
            headers: {
              Accept: 'image/*',
            },
          });
          const fallbackImageBuffer = await fallbackResponse.arrayBuffer();
          this.cache[url] = Buffer.from(fallbackImageBuffer);
        } catch (fallbackError) {
          console.error(`Fallback error for ${url}:`, fallbackError);
        }
      }
    }

    return this.cache[url];
  }

  async loadQueue() {
    while (this.queue.length > 0) {
      const url = this.queue.shift();
      await this.load(url, 1);
    }
  }
}

export default ImageLoader;
