const axios = require('axios');
const { performance } = require('perf_hooks');
const { Cache } = require('./cache');

class API {
  constructor({ apiUrl, cacheDuration }) {
    this.apiUrl = apiUrl;
    this.cache = new Cache(cacheDuration);
    this.requests = [];
    this.parsers = {};
  }

  async fetchUser(id) {
    const cachedResponse = await this.cache.get(`user:${id}`);
    if (cachedResponse) return cachedResponse;

    const requestStart = performance.now();
    try {
      const response = await axios.get(`${this.apiUrl}/users/${id}`);
      this.requests.push({ id, time: performance.now() - requestStart });
      await this.parseAndCache(response.data);
      return response.data;
    } catch (error) {
      this.requests.push({ id, time: performance.now() - requestStart, error });
      throw error;
    }
  }

  async parseAndCache(data) {
    if (!this.parsers[data.__type]) {
      try {
        const Parser = require(`./parsers/${data.__type}`);
        this.parsers[data.__type] = new Parser();
      } catch (error) {
        console.error('Failed to load parser:', error);
        return;
      }
    }

    const parsedData = await this.parsers[data.__type].parse(data);
    await this.cache.set(`user:${parsedData.id}`, parsedData, this.cacheDuration);
  }

  async resetCache() {
    await this.cache.clear();
  }

  async logRequests() {
    console.log('Successful Requests:');
    for (const request of this.requests) {
      if (!request.error) {
        console.log(`User ${request.id} (${request.time}ms)`);
      } else {
        console.log(`Failed to fetch User ${request.id} (${request.time}ms):`, request.error);
      }
    }
  }
