// loader.js
import { debounce } from 'lodash';
import { getComputedStyle } from 'dom-helpers';

class ImageLoader {
  constructor(options = {}) {
    this.options = options;
    this.cache = {};
    this.requests = [];
    this.dependencies = new Map();
  }

  async load(url, dependencies = []) {
    const cacheKey = url;
    if (this.cache[cacheKey]) return this.cache[cacheKey];

    // Handle broken URLs gracefully
    try {
      const response = await fetch(url);
      if (!response.ok) throw new Error('Image not found');
    } catch (error) {
      // Fallback to placeholder image or notification
      return Promise.resolve(null);
    }

    // Optimize image size and quality based on device capabilities and network conditions
    const { width, height } = getComputedStyle(url).thumbnail;
    const resizedUrl = `${url}?width=${width}&height=${height}`;
    this.cache[cacheKey] = await fetch(resizedUrl);

    // Resolve dependencies and load images in correct order
    if (dependencies.length) {
      const deps = [...new Set(dependencies)];
      for (const dep of deps) {
        if (!this.dependencies.has(dep)) {
          this.dependencies.set(dep, new Promise((resolve) => {
            this.load(dep).then(() => resolve()).catch((error) => {
              // Handle dependency errors gracefully
              return Promise.resolve(null);
            });
          }));
        }
      }
    }

    return this.cache[cacheKey];
  }

  async prefetch(url, dependencies = []) {
    // Prioritize essential images and optimize cache usage
    if (this.options.priority && !this.options.priority.includes(url)) return;

    const cacheKey = url;
    if (this.cache[cacheKey]) return this.cache[cacheKey];

    try {
      await fetch(url);
    } catch (error) {
      // Handle image unavailability gracefully
      return Promise.resolve(null);
    }

    // Load images in correct order based on dependencies and priority
    if (dependencies.length) {
      const deps = [...new Set(dependencies)];
      for (const dep of deps) {
        await this.load(dep);
      }
    }
  }

  // Interactive features
  async previewImage(url, modal = false) {
    const image = await this.load(url);
    return Promise.resolve(image);
  }

  async lazyLoadImages() {
    const images = [...document.querySelectorAll('img')];
    for (const img of images) {
      if (!img.src) continue;
      const url = img.src;
      const viewport = getComputedStyle(img).getBoundingClientRect();
      if (viewport.top > window.innerHeight || viewport.bottom < 0) continue;

      // Load image before it enters the viewport
      await this.load(url);
    }
  }

  static debounce(fn, delay) {
    let timeout;
    return function(...args) {
      const context = this;
      clearTimeout(timeout);
      timeout = setTimeout(() => fn.apply(context, args), delay);
    };
  }
}

// usage example:
const loader = new ImageLoader({
  priority: ['essential-image-1', 'essential-image-2'],
});

loader.load('image-url-1');
loader.load('image-url-2');

loader.previewImage('image-url-3', true);

loader.lazyLoadImages();

// Polyfills and fallbacks for unsupported features
if (!window.Promise) {
  window.Promise = Promise;
}

if (!window.fetch) {
  window.fetch = (url, options = {}) => {
    // Implement XHR or other fallback methods here
  };
}
