        usage_records[num_records].disk_io = disk;
        usage_records[num_records].network_throughput = network;
        num_records++;

        // Periodically clean up outdated records
        if (num_records > time_window) {
            int i;
            for (i = 0; i < time_window; i++) {
                free(&usage_records[i]);
            }
            num_records = time_window;
        }
    }

