            usage();
        }
}

void append_separator(char **str, int *size_limit, char **separator, FILE **output_file) {
    size_t len = strlen(*str);
    if (len < *size_limit) {
        char *new_str = realloc(*str, (*size_limit + strlen(*separator)) * sizeof(char));
        if (new_str == NULL) {
            // handle memory allocation error
        } else {
            strcpy(new_str + len, *separator);
            *str = new_str;
        }
    } else {
        char *err_msg = malloc(strlen("Error: string too long.\n") + 1);
        if (err_msg != NULL) {
            strcpy(err_msg, "Error: string too long.\n");
            fprintf(*output_file, "%s", err_msg);
            free(err_msg);
        }
    }
}

void usage() {
    printf("Usage: program [options] input_file\n");
    printf("  --manpage   Show man page information\n");
    printf("  -cs         Set character set\n");
    printf("  -o output_file   Specify output file\n");
    exit(1);
}

int main(int argc, char *argv[]) {
