    parse_args(argc, argv, &output_file);

    if (argc < 2) {
        usage();
    }

    FILE *input_file = fopen(argv[argc - 1], "r");
    if (input_file == NULL) {
        fprintf(stderr, "Error opening input file\n");
        exit(1);
