    char *line = NULL;
    size_t line_size = 0;
    while (getline(&line, &line_size, input_file) != -1) {
        // process the line
        printf("Number of lines: %zu\n", ++line_size);
    }
    free(line);

    if (output_file != NULL) {
        fclose(output_file);
    }

    return 0;
}
