typedef struct {
    uint16_t sn;
    size_t sdu_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
} PDCP_Array;

void pdcps_init(PDCP_Array* array, size_t initial_capacity) {
    array->pdus = malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->size = 0;
}

LTE_Uplink_PDCP_PDU* pdcps_add(PDCP_Array* array, uint16_t sn, size_t sdu_size, int error_indication) {
    if (array->size == array->capacity) {
        array->capacity *= 2; // Double the capacity
        array->pdus = realloc(array->pdus, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    }

    LTE_Uplink_PDCP_PDU* pdu = &array->pdus[array->size++];
    pdu->sn = sn;
    pdu->sdu_size = sdu_size;
    pdu->error_indication = error_indication;

    return pdu;
}

LTE_Uplink_PDCP_PDU* pdcps_get(PDCP_Array* array, uint16_t sn) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].sn == sn) {
            return &array->pdus[i];
        }
    }

    return NULL;
}

void pdcps_update_error(PDCP_Array* array, uint16_t sn, int error_indication) {
    for (size_t i = 0; i < array->size; i++) {
        if (array->pdus[i].sn == sn) {
            array->pdus[i].error_indication = error_indication;
            return;
        }
    }
}

void pdcps_merge_consecutive(PDCP_Array* array, uint16_t sn) {
    for (size_t i = 0; i < array->size - 1; i++) {
        if (array->pdus[i].sn == sn && array->pdus[i + 1].sn == sn) {
            LTE_Uplink_PDCP_PDU pdu;
            pdu.sn = sn;
            pdu.sdu_size = array->pdus[i].sdu_size + array->pdus[i + 1].sdu_size;
            pdu.error_indication = array->pdus[i].error_indication; // Assume error indication is the same for consecutive PDUs

            // Shift all subsequent PDUs to the left
            memmove(&array->pdus[i], &array->pdus[i + 1], (array->size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));

            array->size--;
            pdcps_add(array, sn, pdu.sdu_size, pdu.error_indication); // Re-add the merged PDU
        }
    }
}

void pdcps_compact(PDCP_Array* array) {
    size_t new_capacity = array->size * 2; // Double the capacity for compaction
    LTE_Uplink_PDCP_PDU* new_pdsus = malloc(new_capacity * sizeof(LTE_Uplink_PDCP_PDU));

    size_t j = 0;
    for (size_t i = 0; i < array->size; i++) {
        if (i % 2 == 0) {
            // Keep the PDU
            new_pdsus[j++] = array->pdus[i];
        }
    }

    free(array->pdus);
    array->pdus = new_pdsus;
    array->capacity = new_capacity;
}

void pdcps_free(PDCP_Array* array) {
    free(array->pdus);
}
