// Define the TCP Segment structure
typedef struct {
    uint32_t seq_num;
    uint32_t ack_num;
    uint16_t size;
    uint8_t flags;
    uint8_t error_indication;
} TCP_Segment;

// Custom memory allocator structure
typedef struct {
    void** blocks; // Array of allocated block pointers
    int num_blocks; // Number of allocated blocks
    int total_size; // Total size of all allocated blocks
    int max_alloc_size; // Maximum allocation size allowed
} MemoryAllocator;

// Function to create a new TCP segment
TCP_Segment* tcp_segment_create(int seq_num, int ack_num, int size) {
    // Create a new memory block for the segment
    MemoryAllocator* allocator = get_allocator();
    void* block = allocator->blocks[0];
    TCP_Segment* segment = block;

    // Initialize the segment with given values
    segment->seq_num = seq_num;
    segment->ack_num = ack_num;
    segment->size = size;
    segment->flags = 0;
    segment->error_indication = 0;

    return segment;
}

// Function to add a new TCP segment to the dynamic array
void tcp_segment_add(TCP_Segment** segments, int seq_num) {
    // Allocate memory for the new segment
    MemoryAllocator* allocator = get_allocator();
    void* block = malloc(allocator->max_alloc_size);

    // Initialize the new segment with given sequence number
    TCP_Segment* segment = block;
    segment->seq_num = seq_num;

    // Add the new segment to the array and update the array size
    *segments = realloc(*segments, (sizeof(TCP_Segment*) * (++((*segments)->size)));
    (*segments)[(*segments)-1] = segment;
}

// Function to retrieve a TCP segment by its sequence number
TCP_Segment* tcp_segment_get(TCP_Segment** segments, int seq_num) {
    // Iterate through the segments array to find the requested segment
    for (int i = 0; i < (*segments)->size; i++) {
        if ((*segments)[i]->seq_num == seq_num) {
            return (*segments)[i];
        }
    }

    // Return NULL if the segment is not found
    return NULL;
}

// Function to update the error indication for a given sequence number
void tcp_segment_update_error(TCP_Segment** segments, int seq_num, uint8_t error_indication) {
    // Iterate through the segments array to find the requested segment
    for (int i = 0; i < (*segments)->size; i++) {
        if ((*segments)[i]->seq_num == seq_num) {
            (*segments)[i]->error_indication = error_indication;
            return;
        }
    }

    // Return if the segment is not found
    return;
}

// Get the custom memory allocator instance
MemoryAllocator* get_allocator() {
    // Initialize the memory allocator with default values
    MemoryAllocator* allocator = malloc(sizeof(MemoryAllocator));
    allocator->blocks = NULL;
    allocator->num_blocks = 0;
    allocator->total_size = 0;
    allocator->max_alloc_size = 1024; // Default allocation size

    // Return the allocated memory allocator instance
    return allocator;
}

// Free the custom memory allocator instance and all its blocks
void free_allocator(MemoryAllocator* allocator) {
    // Iterate through the blocks array to free each block
    for (int i = 0; i < allocator->num_blocks; i++) {
        free(allocator->blocks[i]);
    }

    // Free the allocator itself
    free(allocator);
}
