import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class DynamicTaskManager {
    private final int threadCount = Runtime.getRuntime().availableProcessors();
    private final int queueSize = 10000; // adjust as needed
    private BlockingQueue<Runnable> taskQueue;
    private ThreadPoolExecutor executor;
    private LRUResultCache resultCache;

    public DynamicTaskManager(int threadPoolSize) {
        taskQueue = new LinkedBlockingQueue<>();
        executor = new ThreadPoolExecutor(threadCount, threadPoolSize, 0L, TimeUnit.MILLISECONDS);
        resultCache = new LRUResultCache(100); // adjust as needed
    }

    public void scheduleTask(Runnable task) {
        taskQueue.add(task);
    }

    public Object getTaskResult(Runnable task) {
        return resultCache.getTaskResult(task);
    }

    public void shutdown() {
        executor.shutdown();
        resultCache.clear();
    }

    // LRU Cache implementation
    private class LRUResultCache {
        private final int cacheSize;
        private final java.util.concurrent.ConcurrentHashMap<Runnable, Object> cacheMap;

        public LRUResultCache(int cacheSize) {
            this.cacheSize = cacheSize;
            cacheMap = new java.util.concurrent.ConcurrentHashMap<>();
        }

        public void clear() {
            cacheMap.clear();
        }

        public Object getTaskResult(Runnable task) {
            return cacheMap.get(task);
        }
    }
}

