#define MAX_THREADS 10

typedef struct {
    char* separator;
    int size_limit_multiplier;
} TransformationOptions;

void parse_args(int argc, char** argv, TransformationOptions* options) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // handle --manpage option
        } else if (strcmp(argv[i], "-cs") == 0) {
            // handle -cs option
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            options->output_file = argv[i+1];
            i++;
        } else if (sscanf(argv[i], "-s%s", options->separator) != 1) {
            printf("Error: invalid option %s\n", argv[i]);
            exit(1);
        }
    }
}

void transform_line(char* line, TransformationOptions* options, FILE* output_file) {
    int line_length = strlen(line);
    if (line_length > options->size_limit_multiplier * average_line_length()) {
        fprintf(output_file, "Warning: line too long\n");
    } else {
        strcat(line, options->separator);
    }
}

void* transform_thread(void* arg) {
    TransformationOptions* options = arg;
    // read input file line by line
    FILE* input_file = fopen("input.txt", "r");
    if (input_file == NULL) {
        printf("Error: cannot open input file\n");
        return NULL;
    }

    int num_transformed_lines = 0;
    while (fgets(line, sizeof(line), input_file)) {
        transform_line(line, options, output_file);
        num_transformed_lines++;
    }

    // log transformation outcome
    pthread_log_info("Transformed %d lines", num_transformed_lines);

    fclose(input_file);
    return NULL;
}

int main(int argc, char** argv) {
    TransformationOptions options = {0};
    parse_args(argc, argv, &options);

    if (argc <= 1 || strcmp(argv[1], "-h") == 0) {
        printf("Usage: %s [-cs] [-o output_file] [input_file]\n", argv[0]);
        return 1;
    }

    // determine average line length
    FILE* input_file = fopen("input.txt", "r");
    int total_line_length = 0;
    int num_lines = 0;
    while (fgets(line, sizeof(line), input_file)) {
        total_line_length += strlen(line);
        num_lines++;
    }
    fclose(input_file);

    options.size_limit_multiplier = total_line_length / num_lines;

    // create and start threads
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, transform_thread, &options) != 0) {
            printf("Error: cannot create thread\n");
            return 1;
        }
    }

    // wait for threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            printf("Error: cannot join thread\n");
            return 1;
        }
    }

    return 0;
}
