NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_entries, int max_size_constraint) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int created_count = 0;

    for (int i = 0; i < num_entries && i <= max_size_constraint; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            log_error("Memory allocation failure");
            continue;
        }

        pdu->RNTI = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;

        // validate RNTI value
        if (pdu->RNTI < RNTI_MIN || pdu->RNTI > RNTI_MAX) {
            log_error("Invalid RNTI value");
            free(pdu);
            continue;
        }

        pdu->CRCFLAG = malloc(strlen("CRCFLAG") + 1); // allocate space for CRCFLAG string
        if (pdu->CRCFLAG == NULL) {
            log_error("Memory allocation failure");
            free(pdu);
            continue;
        }
        strcpy(pdu->CRCFLAG, "CRCFLAG");

        list = realloc(list, (created_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (list == NULL) {
            log_error("Memory allocation failure");
            for (int j = 0; j < created_count; j++) {
                free(&list[j]);
            }
            free(list);
            return NULL;
        }

        list[created_count] = pdu;
        created_count++;

        // check if maximum size constraint is exceeded
        if (created_count >= max_size_constraint) {
            log_error("Maximum size constraint exceeded");
            for (int j = 0; j < created_count - 1; j++) {
                free(&list[j]);
            }
            free(list);
            return NULL;
        }
    }

    // log total number of successfully created structures
    printf("Total number of structures created: %d\n", created_count);

    return list;
}
