    int sn_range_start, sn_range_end;
    if (scanf("%d %d", &sn_range_start, &sn_range_end) != 2) return -1; // Invalid SN range input
    if ((sn_range_start < SN_RANGE_MIN || sn_range_start > SN_RANGE_MAX) ||
        (sn_range_end < SN_RANGE_MIN || sn_range_end > SN_RANGE_MAX)) {
        printf("Invalid SN range: %d-%d\n", sn_range_start, sn_range_end);
        return -1; // Invalid SN range
    }

    new_frame->pdc_context = PDCP_CONTEXT_INITIALIZER;
    new_frame->pdc_context->sn_range.start = sn_range_start;
    new_frame->pdc_context->sn_range.end = sn_range_end;

    (*size)++;

    if (LOGGING_ENABLED)
        printf("Initialized frame %d with SN range: %d-%d\n", *size, sn_range_start, sn_range_end);

    return 0; // Successful initialization
}

void dl_frame_header_prune(DL_FRAME_HEADER_T** list, int* size) {
    int i;
    for (i = 0; i < *size - 1; i++)
        (*list)[i] = (*list)[i + 1];

    (*list) = realloc(*list, --(*size) * sizeof(DL_FRAME_HEADER_T));
}

int main() {
    int list_size = 0;
    DL_FRAME_HEADER_T* frame_list = NULL;

    while (dl_frame_header_init(&frame_list, &list_size, MAX_LIST_SIZE) == 0)
        ; // Continue initializing frames until the list exceeds max size

    dl_frame_header_prune(&frame_list, &list_size);

    return 0;
}
