typedef struct TCP_Segment {
    int sequenceNumber;
    int payloadSize;
    double timestamp;
} TCP_Segment;

TCP_Segment* networkSegmentManager(int* bandwidthLimit, int* currentBandwidthUsage, TCP_Segment** segments, int size) {
    // Add new segment
    if (size < *currentBandwidthUsage + sizeof(TCP_Segment)) {
        printf("Warning: Bandwidth limit exceeded. Further additions will not be possible without discarding older segments.\n");
    } else {
        TCP_Segment* newSegment = (TCP_Segment*)malloc(sizeof(TCP_Segment));
        newSegment->sequenceNumber = *currentBandwidthUsage + 1;
        newSegment->payloadSize = sizeof(TCP_Segment);
        newSegment->timestamp = time(NULL);
        *segments = (TCP_Segment**)realloc(*segments, (*size + 1) * sizeof(TCP_Segment*));
        (*segments)[size] = newSegment;
        (*currentBandwidthUsage)++;
    }

    // Retrieve segment by sequence number
    TCP_Segment* foundSegment = NULL;
    for (int i = 0; i < size; i++) {
        if ((*segments)[i]->sequenceNumber == sequenceNumber) {
            foundSegment = (*segments)[i];
            break;
        }
    }

    // Update timestamp for a given sequence number
    for (int i = 0; i < size; i++) {
        if ((*segments)[i]->sequenceNumber == sequenceNumber) {
            (*segments)[i]->timestamp = time(NULL);
            break;
        }
    }

    // Prune old segments based on their transmission timestamps
    int pruneIndex = 0;
    for (int i = 0; i < size; i++) {
        if ((*segments)[i]->timestamp + *bandwidthLimit <= time(NULL)) {
            free((*segments)[i]);
            (*segments)[i] = NULL;
        } else {
            (*segments)[pruneIndex++] = (*segments)[i];
        }
    }
    *size = pruneIndex;

    return *segments;
}
