char* modifyFileName(char* filename) {
    int len = strlen(filename);
    char* extStart = NULL;
    int digitCount = 0;

    // Analyze the characters of the original filename to determine the number of digits and file type for the new extension
    for (int i = len - 1; i >= 0 && i--; ) {
        if (isdigit(filename[i])) {
            digitCount++;
            extStart = &filename[i + 1];
            break;
        }
    }

    char* newFileName = (char*)malloc(len + strlen(extStart) + 2);
    sprintf(newFileName, "%.*s%s", len - (extStart - filename), filename, ".new");

    return newFileName;
}
