    int width;
    int height;
};

// Function to process image files
void processImageFiles(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& images, const std::string& output_file) {
    // Calculate total images and average resolution
    int total_images = 0;
    int sum_width = 0;
    int sum_height = 0;
    for (const auto& image : images) {
        total_images++;
        sum_width += image.width;
        sum_height += image.height;
    }
    double avg_resolution = static_cast<double>(sum_width + sum_height) / (total_images * 2);

    // Generate histogram data
    std::vector<int> histogram(256, 0);
    for (const auto& image : images) {
        for (int i = 0; i < image.height; ++i) {
            for (int j = 0; j < image.width; ++j) {
                int pixel_value = ((image.filename[i * image.width + j] - '0') % 256);
                histogram[pixel_value]++;
            }
        }
    }

    // Write output to file
    std::ofstream output(output_file);
    if (output) {
        output << "Total Images: " << total_images << "\n";
        output << "Average Resolution: " << avg_resolution << "\n";
        for (int i = 0; i < histogram.size(); ++i) {
            output << "Histogram[" << i << "]: " << histogram[i] << "\n";
        }
    } else {
        std::cerr << "Error writing to file: " << output_file << '\n';
    }
}

