ResourceUsage* resourceMonitor(ResourceUsage** records, int* capacity, int* currentSize) {
    // Initialize or update the record with latest metrics
    ResourceUsage* newRecord = (ResourceUsage*)malloc(sizeof(ResourceUsage));
    newRecord->cpuUtilization = 0.8; // Update CPU utilization metric
    newRecord->memoryUsage = 0.5; // Update memory usage metric
    newRecord->diskIO = 0.3; // Update disk I/O metric
    newRecord->networkThroughput = 1.2; // Update network throughput metric
    time_t currentTimestamp = time(NULL);
    newRecord->timestamp = currentTimestamp;

    if (*currentSize >= *capacity) {
        // Realloc the array and update capacity
        *records = (ResourceUsage*)realloc(*records, (*capacity + 1) * sizeof(ResourceUsage));
        *capacity += 1;
    }

    // Add new record to the array
    *records[*currentSize] = *newRecord;

    *currentSize += 1;

    return *records;
}

int main() {
    ResourceUsage* records = NULL;
    int capacity = 5;
    int currentSize = 0;

    resourceMonitor(&records, &capacity, &currentSize);

    // Cleanup outdated records
    for (int i = 0; i < currentSize; i++) {
        if ((time(NULL) - records[i].timestamp) > 3600) { // Clean up after 1 hour
            free(records[i]);
            for (int j = i + 1; j < currentSize; j++) {
                *records++ = *records++;
            }
            currentSize--;
        }
    }

    return 0;
}

