import java.io.*;
import java.net.*;
import java.util.*;

public class DatabaseConnector {
    public static DataTableReader connectToDatabase(byte[] data) throws Exception {
        SocketChannel channel = null;
        try {
            channel = new SocketChannel();
            channel.connect(new InetSocketAddress("localhost", 8080));
            channel.configureBlocking(true);

            // Initialize arrays
            long[] offsets = new long[100];
            int[] keys = new int[100];
            double[] values = new double[100];
            Record[] records = new Record[100];

            // Initialize linked list
            LinkedList<Record> recordList = new LinkedList<>();

            // Read data from channel and deserialize into arrays and records
            DataInputStream input = new DataInputStream(channel.socket().getInputStream());
            int i = 0;
            while (input.available() > 0) {
                long offset = input.readLong();
                int key = input.readInt();
                double value = input.readDouble();

                // Create new record and add to linked list
                Record record = new Record(i, "Record " + i, value);
                records[i] = record;
                recordList.add(record);
                i++;
            }

            // Close channel
            channel.close();

            // Serialize arrays and records into byte array
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(bos);
            for (int j = 0; j < i; j++) {
                dos.writeLong(offsets[j]);
                dos.writeInt(keys[j]);
                dos.writeDouble(values[j]);
            }

            // Send serialized data to database server
            channel = new SocketChannel();
            channel.connect(new InetSocketAddress("localhost", 8080));
            channel.configureBlocking(true);
            DataOutputStream dos2 = new DataOutputStream(channel.socket().getOutputStream());
            dos2.writeInt(bos.size());
            bos.writeTo(dos2);

            // Read result from database server
            DataTableReader reader = new DataTableReader();
            DataInputStream input2 = new DataInputStream(channel.socket().getInputStream());
            int size = input2.readInt();
            byte[] buffer = new byte[size];
            input2.readFully(buffer);
            reader.setData(buffer);

            return reader;
        } catch (Exception e) {
            // Handle connection failure
            throw new Exception("Failed to connect to database");
        } finally {
            if (channel != null) {
                try {
                    channel.close();
                } catch (IOException ignored) {}
            }
        }
    }

    public static class Record {
        int id;
        String name;
        double value;

        public Record(int id, String name, double value) {
            this.id = id;
            this.name = name;
            this.value = value;
        }
    }

    public static class DataTableReader {
        private byte[] data;

        public void setData(byte[] data) {
            this.data = data;
        }

