// Structure to represent UE context
typedef struct {
    uint32_t ue_id;
    SRS_CONFIG srs_config;
    CHANNEL_ESTIMATE channel_estimate;
} NRUE_CONTEXT;

// Function to manage dynamic collection of UE contexts
NRUE_CONTEXT* ue_context_manager(int num_ue_contexts) {
    // Hash table for efficient memory management and access
    int* hash_table = (int*)malloc((num_ue_contexts + 1) * sizeof(int));
    for (int i = 0; i <= num_ue_contexts; i++) {
        hash_table[i] = -1;
    }

    NRUE_CONTEXT* ue_contexts = (NRUE_CONTEXT*)calloc(num_ue_contexts, sizeof(NRUE_CONTEXT));

    return ue_contexts;
}

// Function to add a new UE context
void add_ue_context(int ue_id, SRS_CONFIG srs_config, CHANNEL_ESTIMATE channel_estimate) {
    // Calculate hash value for efficient memory management and access
    int hash_value = ue_id % (num_ue_contexts + 1);

    // Allocate memory for the UE context structure
    NRUE_CONTEXT* new_ue_context = (NRUE_CONTEXT*)malloc(sizeof(NRUE_CONTEXT));

    // Set UE context parameters
    new_ue_context->ue_id = ue_id;
    new_ue_context->srs_config = srs_config;
    new_ue_context->channel_estimate = channel_estimate;

    // Update hash table and memory allocation for the new UE context
    hash_table[hash_value] = (int)new_ue_context - (int)ue_contexts;
}

// Function to retrieve a specific UE context by its unique identifier
NRUE_CONTEXT* get_ue_context(int ue_id) {
    int hash_value = ue_id % (num_ue_contexts + 1);

    return (NRUE_CONTEXT*) ((void*)ue_contexts + hash_table[hash_value] * sizeof(NRUE_CONTEXT));
}

// Function to update context parameters like bandwidth and modulation scheme
void update_ue_context(int ue_id, SRS_CONFIG srs_config, CHANNEL_ESTIMATE channel_estimate) {
    NRUE_CONTEXT* ue_context = get_ue_context(ue_id);

