import java.util.concurrent.LinkedBlockingDeque;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class DynamicTaskManager {
    private static final int DEFAULT_MAX_THREADS = 10;
    private static final int DEFAULT_KEEP_ALIVE_TIME = 60; // seconds
    private static final long DEFAULT_CACHE_SIZE = (long) (1024 * 1024 * 100); // 100 MB

    private ExecutorService threadPool;
    private Map<String, Future<?>> taskResults;
    private LRU Cache;

    public DynamicTaskManager(int maxThreads, int keepAliveTime) {
        this.threadPool = new ThreadPoolExecutor(maxThreads, maxThreads, TimeUnit.SECONDS.toMillis(keepAliveTime), TimeUnit.MILLISECONDS, new LinkedBlockingDeque<Runnable>());
        this.taskResults = new HashMap<>();
        this.cache = new LRU(DEFAULT_CACHE_SIZE);
    }

    public <T> Future<T> submitTask(Callable<T> task) {
        return threadPool.submit(task);
    }

    public T getTaskResult(String taskId) throws InterruptedException, ExecutionException {
        return (T) taskResults.get(taskId).get();
    }

    public Map<String, T> getTaskResults() {
        return new HashMap<>(taskResults);
    }

    // Other methods...
}

public class LRU {
    private final int capacity;
    private final Map<String, byte[]> cache;

    public LRU(int capacity) {
        this.capacity = capacity;
        this.cache = new LinkedHashMap<String, byte[]>(capacity, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry<String, byte[]> eldest) {
                return size() > capacity;
            }
        };
    }

    public void put(String key, byte[] value) {
        cache.put(key, value);
    }

    public byte[] get(String key) {
        return cache.get(key);
    }

    public void clear() {
        cache.clear();
    }
}

