#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_LINE_SIZE 1024
#define LOG_FILE "log.txt"

typedef struct {
    int num_lines;
} file_info_t;

void *thread_func(void *arg) {
    file_info_t *file_info = (file_info_t *) arg;
    FILE *file = fopen(file_info->filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }
    char line[MAX_LINE_SIZE];
    int num_lines = 0;
    while (fgets(line, MAX_LINE_SIZE, file)) {
        num_lines++;
    }
    fclose(file);
    printf("Number of lines in %s: %d\n", file_info->filename, num_lines);
    return NULL;
}

int main(int argc, char *argv[]) {
    int c;
    char *output_file = NULL;
    int verbose = 0;

    static struct option long_options[] = {
        {"manpage",     required_argument, 0, 'm'},
        {"cs",          no_argument,       0, 'c'},
        {"o",           required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "cm:o:", long_options, NULL)) != -1) {
        switch (c) {
            case 'm':
                printf("Man page:\n");
                break;
            case 'c':
                verbose++;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                return 1;
        }
    }

    if (argc < 2) {
        printf("Usage: %s [options] <file>\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    file_info_t files[argc - 1];

    for (int i = 1; i < argc; i++) {
        char *filename = argv[i];
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            perror("Error opening file");
            return 1;
        }
        struct stat sb;
        fstat(fd, &sb);
        close(fd);

        files[i-1].num_lines = 0;
        strcpy(files[i-1].filename, filename);

        pthread_create(&threads[i-1], NULL, thread_func, &files[i-1]);
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
