    // Add a new PDU to the array
    void addPDU(int SN, int SDU_size);

    // Retrieve a specific PDU by its sequence number
    LTE_Uplink_PDCP_PDU* getPN(int SN);

    // Update the error indication for a given SN
    void updateErrorIndication(int SN, char new_error_indication);

