// Process a media file path as a string
struct {
    int dimensions[2];
    char format[10];
    char extension[5];
} manageDynamicMediaArray(LTE_Uplink_PDCP_PDU **array, int *size, const char* filename) {
    struct {
        int dimensions[2];
        char format[10];
        char extension[5];
    } metadata;

    // Extract metadata from the file path
    if (strnlen(filename, 256) > 0) {
        int num_digits = 0;
        for (int i = 0; i < strnlen(filename, 256); i++) {
            if (isdigit(filename[i])) {
                num_digits++;
            }
        }

        // Determine the new file extension format
        if (num_digits == 0) {
            sprintf(metadata.extension, "txt");
        } else if (num_digits == 1) {
            sprintf(metadata.extension, "log");
        } else {
            sprintf(metadata.extension, "bin");
        }

        // Extract dimensions and format from the filename
        sscanf(filename, "%dx%d.%s", &metadata.dimensions[0], &metadata.dimensions[1], metadata.format);
    } else {
        // Handle edge cases where filename is too long or missing
        strcpy(metadata.extension, "unknown");
        strcpy(metadata.format, "unknown");
    }

    return metadata;
}

// Add a new PDU to the array
void addPDU(LTE_Uplink_PDCP_PDU **array, int *size) {
    // Allocate memory for the new PDU and update the size
    if (*size >= 1 && (array[*size - 1] = (LTE_Uplink_PDCP_PDU *) malloc(sizeof(LTE_Uplink_PDCP_PDU))) == NULL) {
        printf("Out of memory.\n");
        return;
    }

    // Initialize the new PDU
    array[*size - 1]->SN = 0;
    array[*size - 1]->SDU_size = 0;
    array[*size - 1]->error_indication = '\0';

    (*size)++;
}

// Retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* getPN(LTE_Uplink_PDCP_PDU **array, int *size, int SN) {
    for (int i = 0; i < *size; i++) {
        if (array[i]->SN == SN) {
            return array + i;
        }
    }

    return NULL;
}

// Update the error indication for a given SN
void updateErrorIndication(LTE_Uplink_PDCP_PDU **array, int *size, int SN, char new_error_indication) {
    LTE_Uplink_PDCP_PDU* p = getPN(array, size, SN);

    if (p != NULL) {
        p->error_indication = new_error_indication;
    }
}
