void handleNetworkRequestQueue(Request** requests, int size) {
    // Handle queue operations
    for (int i = 0; i < size; i++) {
        Request* request = requests[i];
        if (request == NULL) continue;

        // Extract domain and path from URL
        char* domain = strtok(request->url, "/");
        char* path = strdup(strtok(NULL, "/"));
        if (!domain || !path) {
            printf("Error parsing URL: %s\n", request->url);
            return;
        }

        // Validate URL structure
        if (strlen(domain) > 255) {
            printf("URL is too long: %s\n", request->url);
            return;
        }

        // Parse headers and content type
        char* contentType = NULL;
        for (int j = 0; j < strlen(request->method); j++) {
            if (strncmp(request->headers[j], "Content-Type:", 14) == 0) {
                sscanf(request->headers[j + 1], "%[^;]; charset=%s", &contentType);
                break;
            }
        }

        // Determine content type based on MIME type and extension
        char* fileType = NULL;
        if (strncmp(contentType, "application/json", strlen("application/json")) == 0) {
            fileType = "json";
        } else if (strncmp(contentType, "text/xml", strlen("text/xml")) == 0) {
            fileType = "xml";
        } else if (strncmp(contentType, "application/x-www-form-urlencoded", strlen("application/x-www-form-urlencoded")) == 0) {
            fileType = "form";
        }

        // Process the request
        printf("Request ID: %s\nDomain: %s\nPath: %s\nContent Type: %s\nFile Type: %s\n\n", request->id, domain, path, contentType, fileType);
    }
}
