    // Initialize cache and its size
    int cacheSize = 1000; 
    FileMetadata* metadata = (FileMetadata*)malloc(cacheSize * sizeof(FileMetadata));

    for(int i=0; i<cacheSize; i++) {
        metadata[i].id = -1;
        metadata[i].filePath = NULL;
    }

    // Check if the file path exists and is valid
    struct stat sb;
    if(stat(newPath, &sb) == -1) {
        printf("Error: File %s does not exist or access denied.\n", newPath);
        return;
    }

    int newType = 0; // Determine type based on file extension

    const char* lastDot = strrchr(newPath, '.');
    if(lastDot != NULL) {
        // Check for valid extensions
        if(strncmp(lastDot, ".txt", 4) == 0 || strncmp(lastDot, ".jpg", 4) == 0 
            || strncmp(lastDot, ".pdf", 4) == 0) {
            newType = lastDot - newPath;
        } else {
            printf("Error: File %s has invalid extension.\n", newPath);
            return;
        }
    }

    // Update or add to cache
    for(int i=0; i<cacheSize; i++) {
        if(metadata[i].id == newId) {
            metadata[i].filePath = strcpy((char*)malloc(strlen(newPath)+1), newPath);
            metadata[i].modificationTime = newModTime;
            metadata[i].accessFrequency = newAccessFreq;
            break;
        }
    }

    // Evict outdated entries based on access frequency and age
    for(int i=0; i<cacheSize; i++) {
        if(metadata[i].id != -1) {
            if((time(NULL) - metadata[i].modificationTime) > 3600 || 
               metadata[i].accessFrequency < newAccessFreq) {
                // Remove entry from cache
                free(metadata[i].filePath);
                metadata[i].id = -1;
            }
        }
    }

    free(metadata);
}
