#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>

#define MAX_PDUs 1000
#define TIME_TO_LIVE 300 // in seconds

typedef struct {
    int pdcpsn;
    int sdu_size;
    int error_indication;
    time_t timestamp;
} LTE_Uplink_PDCP_PDU;

// Global cache of previously processed configurations
static LTE_Uplink_PDCP_PDU *pdus[MAX_PDUs];
static int num_pdus = 0;
static pthread_mutex_t pdus_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_pdus() {
    for (int i = 0; i < MAX_PDUs; i++) {
        pdus[i] = NULL;
    }
}

void add_pdu(int pdcpsn, int sdu_size, int error_indication) {
    pthread_mutex_lock(&pdus_mutex);
    LTE_Uplink_PDCP_PDU *new_pdu = (LTE_Uplink_PDCP_PDU *)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    new_pdu->pdcpsn = pdcpsn;
    new_pdu->sdu_size = sdu_size;
    new_pdu->error_indication = error_indication;
    time_t current_time = time(NULL);
    new_pdu->timestamp = current_time;

    // Add the new PDU to the array
    if (num_pdus < MAX_PDUs) {
        pdus[num_pdus] = new_pdu;
        num_pdus++;
    } else {
        printf("Array full. Cannot add more PDUs.\n");
    }

    pthread_mutex_unlock(&pdus_mutex);
}

LTE_Uplink_PDCP_PDU *get_pdu(int pdcpsn) {
    pthread_mutex_lock(&pdus_mutex);

    for (int i = 0; i < num_pdus; i++) {
        if (pdus[i]->pdcpsn == pdcpsn) {
            LTE_Uplink_PDCP_PDU *result = pdus[i];
            pthread_mutex_unlock(&pdus_mutex);
            return result;
        }
    }

    pthread_mutex_unlock(&pdus_mutex);
    return NULL;
}

void update_error_indication(int pdcpsn, int error_indication) {
    pthread_mutex_lock(&pdus_mutex);

    for (int i = 0; i < num_pdus; i++) {
        if (pdus[i]->pdcpsn == pdcpsn) {
            pdus[i]->error_indication = error_indication;
            pthread_mutex_unlock(&pdus_mutex);
            return;
        }
    }

    pthread_mutex_unlock(&pdus_mutex);
}

void remove_outdated_pdus(int age_threshold) {
    pthread_mutex_lock(&pdus_mutex);

    for (int i = 0; i < num_pdus; i++) {
        if ((time(NULL) - pdus[i]->timestamp) > age_threshold) {
            free(pdus[i]);
            pdus[i] = NULL;
        }
    }

    pthread_mutex_unlock(&pdus_mutex);
}

// Read the configuration file, parse its contents, and update resource allocation parameters
void process_configuration_file(char *config_file_path) {
    // Read the file
    int fd = open(config_file_path, O_RDONLY);
    if (fd < 0) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Parse the contents of the configuration file
    char buffer[1024];
    read(fd, buffer, 1023); // Don't include the null terminator in the read

    close(fd);
}

int main() {
    init_pdus();

    add_pdu(1, 1000, 0);
    add_pdu(2, 500, 0);

    LTE_Uplink_PDCP_PDU *pdu = get_pdu(1);
    if (pdu != NULL) {
        printf("PDU with SN 1 has error indication: %d\n", pdu->error_indication);
    }

    update_error_indication(2, 1);

    remove_outdated_pdus(TIME_TO_LIVE);

    return 0;
}
