#define FILTER_ARRAY_THRESHOLD 1000
#define LINKED_LIST_THRESHOLD 5000

typedef struct {
    int id;
    char *criteria;
} Filter;

void process_csv_file(char *input_file, char *output_file, char *transform_rules, int parallel_processing) {
    // Initialize variables and arrays
    FILE *file = fopen(input_file, "r");
    if (!file) {
        perror("Error opening input file");
        return;
    }

    Filter *filters = NULL;
    int num_filters = 0;

    char *rule_str = strtok(transform_rules, ",");
    while (rule_str) {
        // Dynamically allocate memory for filters
        Filter *new_filter = (Filter *)malloc(sizeof(Filter));
        if (!new_filter) {
            perror("Error allocating memory for filter");
            return;
        }
        new_filter->id = num_filters++;
        new_filter->criteria = strdup(rule_str);
        if (!new_filter->criteria) {
            perror("Error allocating memory for filter criteria");
            free(new_filter);
            return;
        }

        // Resize filters array if necessary
        if (num_filters > FILTER_ARRAY_THRESHOLD) {
            Filter *old_filters = filters;
            filters = (Filter *)realloc(old_filters, num_filters * sizeof(Filter));
            if (!filters) {
                perror("Error reallocating memory for filters");
                free(new_filter->criteria);
                free(new_filter);
                return;
            }
        }

        // Add new filter to the array
        if (filters) {
            Filter *last_filter = &filters[num_filters - 2];
            last_filter->id = num_filters - 1;
