void manageLTEConfigurations(LTE_PHY_FRAME_CONFIG_S **configArray, int *arraySize) {
    int i, newConfigurationCount = 0;
    LTE_PHY_FRAME_CONFIG_S *newConfiguration;

    // Check for invalid bandwidth values and overlapping configurations
    while (1) {
        printf("Enter number of new configurations to add (0 to stop): ");
        scanf("%d", &newConfigurationCount);

        if (newConfigurationCount == 0)
            break;

        for (i = 0; i < *arraySize; i++) {
            // Check for overlapping bandwidths
            if (*configArray[i]->bandwidth >= newConfigurationCount->bandwidth) {
                printf("Error: Overlapping configurations detected. Please try again.\n");
                return;
            }
        }

        // Allocate memory for the new configuration and its corresponding array
        newConfiguration = (LTE_PHY_FRAME_CONFIG_S *)malloc(sizeof(LTE_PHY_FRAME_CONFIG_S));
        *configArray = (LTE_PHY_FRAME_CONFIG_S **)realloc(*configArray, (*arraySize + 1) * sizeof(LTE_PHY_FRAME_CONFIG_S *));

        // Store the new configuration and increment the array size
        (*configArray)[*arraySize] = newConfiguration;
        (*arraySize)++;
    }
}
