// Function to generate random number based on weighted probability distribution
double generateRandomNumber(double p1, double p2) {
    return (rand() / (RAND_MAX + 1.0)) * (p2 - p1) + p1;
}

int initCRCIndicationPool(int* poolSize, int** structures, int maxStructures) {
    if (*poolSize > 0) {
        // Reset the internal state
        free(*structures);
    }
    *poolSize = CRC_INDICATION_POOL_SIZE;
    *structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(CRC_INDICATION_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*structures == NULL) {
        // Handle insufficient memory
        return -1;
    }
    return 0;
}

int createCRCIndicationStructures(int* structuresCreated, int poolSize, double p1, double p2) {
    NFAPI_CRC_INDICATION_PDU_T* tempPool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(CRC_INDICATION_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (tempPool == NULL) {
        // Handle insufficient memory
        return -1;
    }

    for (int i = 0; i < poolSize && (*structuresCreated + i) < MAX_STRUCTURES_CREATED; i++) {
        tempPool[i].CRCFLAG = generateRandomNumber(p1, p2);
    }
    free(*structures);
    *structures = tempPool;
    *structuresCreated += poolSize;

    return 0;
}

void resetCRCIndicationPool(int* structures, int poolSize) {
    free(*structures);
    *poolSize = CRC_INDICATION_POOL_SIZE;
}
