#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LTESN_MAX 65535
#define SDU_SIZE_MAX 1024
#define ERROR_INDICATION_MAX 255

typedef struct {
    int sequenceNumber;
    int sduSize;
    int errorIndication;
} LTE_Uplink_PDCP_PDU;

typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    int size;
    int capacity;
} DynamicArray;

void initDynamicArray(DynamicArray* array, int initialCapacity) {
    array->size = 0;
    array->capacity = initialCapacity;
    array->pdus = (LTE_Uplink_PDCP_PDU*)malloc(array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
}

void addPDU(DynamicArray* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    }
    array->pdus[array->size] = pdu;
    array->size++;
}

LTE_Uplink_PDCP_PDU* getPDUBySN(DynamicArray* array, int sequenceNumber) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

void updatePDU(DynamicArray* array, int sequenceNumber, int errorIndication) {
    LTE_Uplink_PDCP_PDU* pdu = getPDUBySN(array, sequenceNumber);
    if (pdu != NULL) {
        pdu->errorIndication = errorIndication;
    }
}

void compactDynamicArray(DynamicArray* array) {
    int i = 0;
    while (i < array->size - 1) {
        if (array->pdus[i].sequenceNumber == array->pdus[i + 1].sequenceNumber) {
            // Merge or discard duplicate PDUs based on configurable rules
        } else {
            array->pdus[i] = array->pdus[i + 1];
        }
        i++;
    }
    array->size--;
}

void serializeDynamicArray(DynamicArray* array, FILE* file) {
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->pdus[i], sizeof(LTE_Uplink_PDCP_PDU), 1, file);
    }
}

void deserializeDynamicArray(DynamicArray* array, FILE* file) {
    array->size = 0;
    while (fread(&array->pdus[array->size], sizeof(LTE_Uplink_PDCP_PDU), 1, file) == 1) {
        array->size++;
    }
}

int main() {
    DynamicArray array;
    initDynamicArray(&array, 10);

    addPDU(&array, (LTE_Uplink_PDCP_PDU){.sequenceNumber = 0, .sduSize = 100, .errorIndication = 0});
    addPDU(&array, (LTE_Uplink_PDCP_PDU){.sequenceNumber = 1, .sduSize = 200, .errorIndication = 0});

    LTE_Uplink_PDCP_PDU* pdu = getPDUBySN(&array, 0);
    if (pdu != NULL) {
        printf("PDU with SN %d found!\n", pdu->sequenceNumber);
    }

    updatePDU(&array, 1, 1);

    FILE* file = fopen("pdus.bin", "wb");
    serializeDynamicArray(&array, file);
    fclose(file);

    file = fopen("pdus.bin", "rb");
    deserializeDynamicArray(&array, file);
    fclose(file);

    return 0;
}
