// Define the structure LTE_Uplink_PDCP_PDU
typedef struct {
    uint32_t sn;
    uint16_t sdu_size;
    int8_t error_indication;
} LTE_Uplink_PDCP_PDU;

// Define the dynamic array management function
LTE_Uplink_PDCP_PDU **ltek_dynamic_array_init(uint16_t max_size) {
    if (max_size == 0) {
        printf("Error: Max size cannot be zero.\n");
        return NULL;
    }

    LTE_Uplink_PDCP_PDU **array = (LTE_Uplink_PDCP_PDU **)malloc(max_size * sizeof(LTE_Uplink_PDCP_PDU *));
    if (!array) {
        printf("Error: Out of memory.\n");
        return NULL;
    }
    array[0] = NULL;  // Initialize the first element to NULL

    return array;
}

// Add a new PDU to the dynamic array
int ltek_dynamic_array_add(LTE_Uplink_PDCP_PDU **array, uint32_t sn, uint16_t sdu_size) {
    int i;
    for (i = 0; i < array[0] - 1; i++) {
        if (!array[i + 1]) {
            array[i + 1] = (LTE_Uplink_PDCP_PDU *)malloc(sizeof(LTE_Uplink_PDCP_PDU));
            if (!array[i + 1]) {
                printf("Error: Out of memory.\n");
                return -1;
            }
            array[i + 1]->sn = sn;
            array[i + 1]->sdu_size = sdu_size;
            array[i + 1]->error_indication = 0; // Initialize the error indication field
            printf("PDU added with sequence number %d and size %d.\n", sn, sdu_size);
            return i + 1;
        }
    }
    printf("Array is full. Cannot add more PDUs.\n");
    return -2;
}

// Retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU *ltek_dynamic_array_get(LTE_Uplink_PDCP_PDU **array, uint32_t sn) {
    int i;
    for (i = 0; i < array[0]; i++) {
        if (array[i]->sn == sn) {
            return array[i];
        }
    }
    printf("PDU not found with sequence number %d.\n", sn);
    return NULL;
}

// Update the error indication field of a PDU
int ltek_dynamic_array_update_error(LTE_Uplink_PDCP_PDU **array, uint32_t sn) {
    int i;
    for (i = 0; i < array[0]; i++) {
        if (array[i]->sn == sn) {
            array[i]->error_indication = 1; // Update the error indication field
            printf("Error indication updated for PDU with sequence number %d.\n", sn);
            return 0;
        }
    }
    printf("PDU not found with sequence number %d.\n", sn);
    return -1;
}

// Compact the dynamic array when it becomes fragmented due to deletions
void ltek_dynamic_array_compact(LTE_Uplink_PDCP_PDU **array) {
    int i, j = 0;
    for (i = 0; i <= array[0]; i++) {
        if (array[i]) {
            array[j] = array[i];
            j++;
        }
    }
    array[0] = j; // Update the size of the dynamic array
}

// Handle out-of-memory conditions gracefully and provide a fallback strategy
void *ltek_dynamic_array_realloc(void *ptr, size_t size) {
    void *new_ptr;
    new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        printf("Error: Out of memory.\n");
    }
    return new_ptr;
}

// Implement the logging mechanism to record all operations
void ltek_dynamic_array_log_operation(char *operation) {
    printf("%s operation performed.\n", operation);
}
