            if (pdus[i]->sn == sn) {
                free(pdus[i]); // Free the memory allocated for the removed PDU
                for (int j = i + 1; j < total_pdu_count; j++) {
                    pdus[j - 1] = pdus[j]; // Shift the remaining PDUs to fill the gap
                }
                total_pdu_count--;
            }
