#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PDU 10000000 // Maximum number of PDUs (10 million)

// Define the structure for LTE_Uplink_PDCP_PDU
typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

// Define the structure to manage the dynamic array and its operations
typedef struct {
    LTE_Uplink_PDCP_PDU *pdus; // Dynamic array of PDUs
    int num_pds; // Number of PDUs in the array
    pthread_mutex_t lock; // Mutex for thread-safe operations
    FILE *log_file; // File handle for logging
} LTE_Array;

// Function to initialize and manage the dynamic array
LTE_Array* lte_array_init() {
    LTE_Array* array = (LTE_Array*)malloc(sizeof(LTE_Array));
    if (!array) {
        return NULL;
    }
    array->pdus = NULL;
    array->num_pds = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->log_file = fopen("lte_array.log", "a");
    if (!array->log_file) {
        free(array);
        return NULL;
    }
    return array;
}

// Function to add a new PDU to the array
int lte_array_add(LTE_Array* array, int SN, int SDU_size, int error_indication) {
    pthread_mutex_lock(&array->lock);

    // Allocate memory for the new PDU structure
    LTE_Uplink_PDCP_PDU* new_pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!new_pdu) {
        pthread_mutex_unlock(&array->lock);
        // Log allocation failure and retry allocation under certain conditions
        fprintf(array->log_file, "Allocation failed for SN %d. Retrying...\n", SN);
        sleep(1); // Retry after 1 second
        new_pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        if (!new_pdu) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Failed to allocate memory
        }
    }

    // Initialize the new PDU structure
    new_pdu->SN = SN;
    new_pdu->SDU_size = SDU_size;
    new_pdu->error_indication = error_indication;

    // Add the new PDU to the array
    array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, (array->num_pds + 1) * sizeof(LTE_Uplink_PDCP_PDU));
    if (!array->pdus) {
        free(new_pdu);
        pthread_mutex_unlock(&array->lock);
        return -1; // Failed to reallocate memory
    }
    array->pdus[array->num_pds] = new_pdu;
    array->num_pds++;

    pthread_mutex_unlock(&array->lock);

    return 0; // Successful addition of PDU
}

// Function to retrieve a specific PDU by its sequence number (SN)
LTE_Uplink_PDCP_PDU* lte_array_get(LTE_Array* array, int SN) {
    for (int i = 0; i < array->num_pds; i++) {
        if (array->pdus[i]->SN == SN) {
            return array->pdus[i];
        }
    }
    return NULL;
}

// Function to update the error indication for a given PDU by its sequence number (SN)
int lte_array_update_error(LTE_Array* array, int SN, int error_indication) {
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < array->num_pds; i++) {
        if (array->pdus[i]->SN == SN) {
            array->pdus[i]->error_indication = error_indication;
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);

    return 0; // Successful update of PDU
}

// Function to remove a specific PDU by its sequence number (SN)
int lte_array_remove(LTE_Array* array, int SN) {
