// Define a struct to hold information about each resource item
typedef struct {
    char* key;
    void* data;
} ResourceItem;

// Define a struct to hold information about the resource bundle
typedef struct {
    int size;
    ResourceItem** items;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char* path) {
    // Initialize variables
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    int num_items = 0;

    // Open the file in binary mode
    FILE* file = fopen(path, "rb");
    if (!file) {
        free(bundle);
        return NULL;
    }

    // Read the header of the resource file to determine its structure and encoding
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    // Allocate memory for the resource bundle and items
    bundle->size = (int)size;
    bundle->items = (ResourceItem**)malloc((num_items + 1) * sizeof(ResourceItem*));

    // Read the resource items from the file
    while (!feof(file)) {
        ResourceItem* item = (ResourceItem*)malloc(sizeof(ResourceItem));
        fread(&item->key, sizeof(char), strlen(item->key) + 1, file);
        item->data = malloc(100); // Assuming each item's data is 100 bytes long
        fread(item->data, sizeof(char), 100, file);
        bundle->items[num_items] = item;
        num_items++;
    }

    // Close the file and free any unused memory
    fclose(file);

    return bundle;
}
