        int nonAlphanumericCount = countNonAlphanumericCharacters(newServiceName);
        char *updatedServiceName = malloc(strlen(newServiceName) + 10);
        sprintf(updatedServiceName, "%s_%d", newServiceName, nonAlphanumericCount);
        logEventDetails(nonAlphanumericCount, updatedServiceName);

        // Calculate average latency
        int connectionTimestamps[] = { /* get connection timestamps */ };
        double averageLatency = calculateAverageLatency(connectionTimestamps);
        printf("Average latency: %.2f ms\n", averageLatency);

        // Log event details
        logEventDetails(/* event ID */, /* event details */);
    }

    free(connections);
    free(queue);
}

double calculateAverageLatency(int *timestamps) {
    int totalDuration = 0;
    for (int i = 0; i < sizeof(timestamps) / sizeof(*timestamps); i++) {
        if (timestamps[i] > 0) {
            totalDuration += timestamps[i + 1] - timestamps[i];
        } else {
            printf("Error: Invalid timestamp format!\n");
            return -1.0;
        }
    }
    if (totalDuration < 0) {
        printf("Error: Negative time difference! Average latency calculation failed.\n");
        return -1.0;
    }
    double averageLatency = (double)totalDuration / (sizeof(timestamps) / sizeof(*timestamps));
    return averageLatency;
}
