// Function to initialize and manage dynamic array of PDCP PDUs
LTE_Uplink_PDCP_PDU** lte_pdcppdu_init(int max_elements) {
    int i;
    LTE_Uplink_PDCP_PDU** pdus = (LTE_Uplink_PDCP_PDU**)malloc((max_elements+1)*sizeof(LTE_Uplink_PDCP_PDU*));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for(i=0; i<=max_elements; i++) {
        pdus[i] = NULL;
    }

    return pdus;
}

// Function to add a new PDU to the array
void lte_pdcppdu_add(LTE_Uplink_PDCP_PDU** pdus, int max_elements, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&mutex);

    if(pdus[pdu->SN] != NULL) {
        // Handle out-of-memory condition
        perror("Memory error");
        exit(1);
    }

    pdus[pdu->SN] = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    *pdus[pdu->SN] = *pdu;

    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* lte_pdcppdu_get(LTE_Uplink_PDCP_PDU** pdus, int SN) {
    LTE_Uplink_PDCP_PDU* pdu = NULL;

    pthread_mutex_lock(&mutex);

    if(pdus[SN] != NULL) {
        pdu = pdus[SN];
    }

    pthread_mutex_unlock(&mutex);

    return pdu;
}

// Function to update the error indication for a given SN
void lte_pdcppdu_update_error(LTE_Uplink_PDCP_PDU** pdus, int SN, int error) {
    pthread_mutex_lock(&mutex);

    if(pdus[SN] != NULL) {
        pdus[SN]->error_indication = error;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to free memory allocated for the dynamic array
void lte_pdcppdu_free(LTE_Uplink_PDCP_PDU** pdus, int max_elements) {
    pthread_mutex_lock(&mutex);

    for(int i=0; i<=max_elements; i++) {
        if(pdus[i] != NULL) {
            free(pdus[i]);
            pdus[i] = NULL;
        }
    }

    pthread_mutex_unlock(&mutex);
}

