#include <pthread.h>

#define LTE_UPLINK_PDCP_PDU_SIZE 1024 // Assuming size of a PDU structure is 1024 bytes

// Structure to represent an LTE uplink PDCP PDU with error indication and sequence number
typedef struct {
    int seq_num;
    char data[LTE_UPLINK_PDCP_PDU_SIZE];
    int error_indication;
} LTE_Uplink_PDCP_PDU;

// Dynamic array of LTE uplink PDCP PDUs
LTE_Uplink_PDCP_PDU **pdcps = NULL; // Initialize as null
int pdcps_size = 0; // Initialize with a default size

// Function to manage dynamic array of LTE uplink PDCP PDUs
void lte_uplink_pdcp_pdu_manager(int add_new, int sn, int error_ind) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (add_new == 1) { // Adding a new PDU
        // Find the next available index in the array
        int idx = pdcps_size;

        // Increase the size of the array dynamically if needed
        if (idx >= pdcps_size * 2) {
            pdcps = realloc(pdcps, (pdcps_size * 2 + 1) * sizeof(LTE_Uplink_PDCP_PDU *));
            pdcps_size *= 2;
        }

        // Initialize the new PDU
        LTE_Uplink_PDCP_PDU *new_pdu = malloc(sizeof(LTE_Uplink_PDCP_PDU));
        new_pdu->seq_num = sn;
        new_pdu->error_indication = error_ind;

        pthread_mutex_lock(&mutex);
        pdcps[idx] = new_pdu; // Add the new PDU to the array
        pthread_mutex_unlock(&mutex);

    } else if (add_new == 0) { // Retrieving a specific PDU by its sequence number

        pthread_mutex_lock(&mutex);
        for (int i = 0; i < pdcps_size; i++) {
            if (pdcps[i]->seq_num == sn) {
                // Return the retrieved PDU
                printf("PDU with seq num %d found: error indication is %d\n", sn, pdcps[i]->error_indication);
                return;
            }
        }

        pthread_mutex_unlock(&mutex);

        printf("PDU not found in the array.\n");

    } else if (add_new == 2) { // Updating the error indication for a given SN

        pthread_mutex_lock(&mutex);
        for (int i = 0; i < pdcps_size; i++) {
            if (pdcps[i]->seq_num == sn) {
                pdcps[i]->error_indication = error_ind;
                printf("Error indication updated for PDU with seq num %d.\n", sn);
                return;
            }
        }

        pthread_mutex_unlock(&mutex);

        printf("PDU not found in the array.\n");
    }
}

int main() {
    // Example usage
    lte_uplink_pdcp_pdu_manager(1, 10, 0); // Add a new PDU with SN 10 and error indication 0
    lte_uplink_pdcp_pdu_manager(2, 20, 1); // Update the error indication for PDU with SN 20 to 1
    lte_uplink_pdcp_pdu_manager(0, 15, 0); // Retrieve a specific PDU by its sequence number (SN 15)
    return 0;
}

