// Define the LTE_Uplink_PDCP_PDU structure
typedef struct {
    int sequence_number;
    char data[];
} LTE_Uplink_PDCP_PDU;

// Define a structure to hold the dynamic array and its metadata
typedef struct {
    LTE_Uplink_PDCP_PDU** pdus;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} LTE_Uplink_PDCP_PDU_Array;

void* lte_uplink_pdcps_new(size_t capacity) {
    void* memory = malloc(capacity * sizeof(LTE_Uplink_PDCP_PDU));
    if (!memory) return NULL; // Handle out-of-memory condition

    LTE_Uplink_PDCP_PDU_Array* array = (LTE_Uplink_PDCP_PDU_Array*)malloc(sizeof(LTE_Uplink_PDCP_PDU_Array));
    array->pdus = (LTE_Uplink_PDCP_PDU**)malloc(capacity * sizeof(void*));
    array->capacity = capacity;
    array->used = 0;

    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void lte_uplink_pdcps_free(LTE_Uplink_PDCP_PDU_Array* array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->used; i++) {
        free(array->pdus[i]->data);
        free(array->pdus[i]);
    }
    free(array->pdus);
    free(array);
    pthread_mutex_unlock(&array->mutex);
}

int lte_uplink_pdcps_add(LTE_Uplink_PDCP_PDU_Array* array, LTE_Uplink_PDCP_PDU* pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->used >= array->capacity * 0.8) {
        // Resize the array to accommodate more PDUs
        array->capacity *= 2;
        array->pdus = (LTE_Uplink_PDCP_PDU**)realloc(array->pdus, array->capacity * sizeof(void*));
    }

    array->pdus[array->used++] = pdu;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get(LTE_Uplink_PDCP_PDU_Array* array, int sequence_number) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->used; i++) {
        if (array->pdus[i]->sequence_number == sequence_number) {
            return array->pdus[i];
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

int lte_uplink_pdcps_update_error(LTE_Uplink_PDCP_PDU_Array* array, int sequence_number, int error) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->used; i++) {
        if (array->pdus[i]->sequence_number == sequence_number) {
            // Update the error indication for the given SN
            array->pdus[i]->data[1] = error;
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // PDU not found
}
