#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int validateCRCIndication(NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned char* crcTable) {
    // Validate tags within valid ranges
    if (pdu->RX_UE_INFORMATION_TAG < 0 || pdu->RX_UE_INFORMATION_TAG > 255) {
        return -1;
    }
    if (pdu->RNTI < 0 || pdu->RNTI > 65) {
        return -2;
    }

    // Validate CRC indication
    int crc = pdu->CRC_INDICATION_REL8_TAG & 0x3FFF;
    int calculatedCrc = crcTable[crc & 0x1FFF];
    if (pdu->CRCFLAG != (crc | (calculatedCrc << 1))) {
        return -3;
    }

    return 0; // Indication is valid
}

int manageNFAPI_CRC_INDICATION_PDU_T(int N, unsigned char* crcTable) {
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -4; // Allocation failure
    }

    for (int i = 0; i < N; i++) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pduArray[i].RNTI = rand() % 66;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 4096;
        pduArray[i].CRCFLAG = (pduArray[i].CRC_INDICATION_REL8_TAG & 0x3FFF) | ((rand() % 2) << 1);
    }

    // Validate CRC indication for each pdu
    for (int i = 0; i < N; i++) {
        if (validateCRCIndication(&pduArray[i], crcTable) < 0) {
            free(pduArray); // Deallocate memory to prevent leaks
            return -5; // Indication is not valid
        }
    }

    return 0; // Success
}

int main() {
    int N = 10;
    unsigned char* crcTable = (unsigned char*)malloc(4096 * sizeof(unsigned char));
    if (!crcTable) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -4;
    }

    int result = manageNFAPI_CRC_INDICATION_PDU_T(N, crcTable);
    free(crcTable); // Deallocate memory to prevent leaks

    return result;
}
