#include <stdlib.h>
#include <string.h>

typedef struct {
    // MAC_PDCP_CONTEXT* pdcpc;
    // MAC_RLC_CONTEXT* rlcc;
    TRANSPORT_LAYER_INFO tli;
} MAC_CONTEXT;

// Memory pool structure
typedef struct {
    void** memory_blocks;
    size_t capacity;
    size_t used;
} MEMORY_POOL;

MEMORY_POOL* create_memory_pool(size_t initial_capacity) {
    MEMORY_POOL* pool = (MEMORY_POOL*)malloc(sizeof(MEMORY_POOL));
    pool->memory_blocks = (void**)calloc(initial_capacity, sizeof(void*));
    pool->capacity = initial_capacity;
    pool->used = 0;
    return pool;
}

void destroy_memory_pool(MEMORY_POOL* pool) {
    for (size_t i = 0; i < pool->used; ++i) {
        free(pool->memory_blocks[i]);
    }
    free(pool->memory_blocks);
    free(pool);
}

MAC_CONTEXT* allocate_mac_context(MEMORY_POOL* pool, size_t M) {
    if (pool->used + M > pool->capacity) {
        // Reallocate memory pool
        MEMORY_POOL* new_pool = create_memory_pool(pool->capacity * 2);
        for (size_t i = 0; i < pool->used; ++i) {
            void* block = pool->memory_blocks[i];
            // Copy data from old block to new block
            memcpy(new_pool->memory_blocks[new_pool->used++], block, sizeof(MAC_CONTEXT));
            free(block);
        }
        destroy_memory_pool(pool);
        pool = new_pool;
    }

    MAC_CONTEXT* context = (MAC_CONTEXT*)pool->memory_blocks[pool->used++];
    // Initialize context with valid pointers and TRANSPORT_LAYER_INFO
    return context;
}

void deallocate_mac_context(MEMORY_POOL* pool, MAC_CONTEXT* context) {
    void** temp = pool->memory_blocks + pool->used - 1;
    *temp = NULL;  // Mark as free
    --pool->used;
}

int main() {
    MEMORY_POOL* pool = create_memory_pool(10);
    for (size_t i = 0; i < 100; ++i) {
        MAC_CONTEXT* context = allocate_mac_context(pool, 1);
        // Use the context...
        deallocate_mac_context(pool, context);
    }
    destroy_memory_pool(pool);
    return 0;
}
