            context->pdcp_config = 0;
            context->rlc_config = 0;
            for (int j = 0; j < 10; j++) {
                context->stats[j] = 0;
            }

            memory_pool[i] = context;
        }
    }

    return memory_pool;
}

void deallocate_MAC_context(int M, void* pool) {
    if (M > 0 && pool != NULL) {
        for (int i = 0; i < M; i++) {
            free(((MAC_CONTEXT*)pool)[i]);
        }
        free(pool);
    }
