    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int load_resource_bundle(const char* file_path, NFAPI_CRC_INDICATION_PDU_T** pdus) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return -1;
    }

    int num_pdus = 0;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fclose(file);
            fprintf(stderr, "Failed to allocate memory for PDU.\n");
            return -2;
        }

        fread(&pdu->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&pdu->RNTI, sizeof(int), 1, file);
        fread(&pdu->CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        pdu->CRCFLAG = rand() % 2; // Set CRCFLAG randomly

        num_pdus++;
        if (num_pdus >= MAX_ELEM) {
            break;
        }
    }

    *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!*pdus) {
        fclose(file);
        fprintf(stderr, "Failed to allocate memory for PDU array.\n");
        return -3;
    }

    int i;
    for (i = 0; i < num_pdus; i++) {
        (*pdus)[i] = pdu + i;
    }

    fclose(file);
    free(pdu);
    return num_pdus;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    int num_pds = load_resource_bundle("resource_file.bin", &pdus);
    if (num_pds < 0) {
        return -1; // Error occurred during loading
    }
    // Process the loaded PDUs
    free(pdus);
    return 0;
}
