    if (pdcp_buffer.total_pdus >= pdcp_buffer.capacity) {
        realloc_pdcp_buffer();
    }
    LTE_Uplink_PDCP_PDU* new_pdu = &pdcp_buffer.pdus[pdcp_buffer.size];
