        if (pdcp_buffer.pdus[i].SN == SN) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        memmove(&pdcp_buffer.pdus[index], &pdcp_buffer.pdus[index + 1], pdcp_buffer.size - index - 1 * sizeof(LTE_Uplink_PDCP_PDU));
        pdcp_buffer.size--;
    }
}

void realloc_pdcp_buffer() {
    pdcp_buffer.capacity *= 2;
    LTE_Uplink_PDCP_PDU* new_pdus = (LTE_Uplink_PDCP_PDU*)realloc(pdcp_buffer.pdus, pdcp_buffer.capacity * sizeof(LTE_Uplink_PDCP_PDU));
