    for (int i = 0; i < numPDUsAdded; i++) {
        if (pdulist[i]->pdcpsn == pdcpsn) {
            pdulist[i]->errorindication = errorindication;
        }
    }
}

// Remove a PDU from the array based on its sequence number
void removePDU(LTE_Uplink_PDCP_PDU** pdulist, int* numPDUsAdded, size_t* bufferBytesUsed, int pdcpsn) {
    for (int i = 0; i < *numPDUsAdded; i++) {
        if (pdulist[i]->pdcpsn == pdcpsn) {
            // Shift the remaining PDUs down
            memmove(pdulist, pdulist + i + 1, (*numPDUsAdded - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));

            // Decrement the statistics
            (*numPDUsAdded]--;
            *bufferBytesUsed -= sizeof(LTE_Uplink_PDCP_PDU);

