typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    size_t SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

typedef struct Dynamic_Array {
    LTE_Uplink_PDCP_PDU* array;
    size_t capacity;
    size_t used;
} Dynamic_Array;

Dynamic_Array* initialize_array() {
    Dynamic_Array* array = (Dynamic_Array*)malloc(sizeof(Dynamic_Array));
    if (!array) return NULL; // Handle out-of-memory condition
    array->capacity = 10; // Initial capacity of the array
    array->used = 0;
    array->array = (LTE_Uplink_PDCP_PDU*)calloc(array->capacity, sizeof(LTE_Uplink_PDCP_PDU));
    if (!array->array) return NULL; // Handle out-of-memory condition
    return array;
}

void add_pdu(Dynamic_Array* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->used == array->capacity) {
        array->capacity *= 2; // Double the capacity when it's full
        array->array = (LTE_Uplink_PDCP_PDU*)realloc(array->array, array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
    }
    array->array[array->used++] = pdu;
}

void remove_pdu(Dynamic_Array* array, int SN) {
    for (int i = 0; i < array->used; i++) {
        if (array->array[i].SN == SN) {
            for (int j = i + 1; j < array->used; j++) {
                array->array[j - 1] = array->array[j];
            }
            array->used--;
            return;
        }
    }
}

LTE_Uplink_PDCP_PDU* get_pdu(Dynamic_Array* array, int SN) {
    for (int i = 0; i < array->used; i++) {
        if (array->array[i].SN == SN) {
            return &array->array[i];
        }
    }
    return NULL;
}

void update_error_indication(Dynamic_Array* array, int SN, int error_indication) {
    LTE_Uplink_PDCP_PDU* pdu = get_pdu(array, SN);
    if (pdu) pdu->error_indication = error_indication;
}

size_t max_SN(Dynamic_Array* array) {
    size_t max = 0;
    for (int i = 0; i < array->used; i++) {
        if (array->array[i].SN > max) max = array->array[i].SN;
    }
    return max;
}

void print_all_pdu(Dynamic_Array* array) {
    for (int i = 0; i < array->used; i++) {
        printf("PDU %d: SN=%d, SDU size=%zu, error indication=%d\n", i, array->array[i].SN, array->array[i].SDU_size, array->array[i].error_indication);
    }
}

void free_array(Dynamic_Array* array) {
    free(array->array);
    free(array);
}
