#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CONNECTIONS 5000
#define MAX_FILE_ACCESS 10000
#define TTL 3600 // Time to Live in seconds (1 hour)
#define CACHESIZE 1024 * 16 // Size of the cache in bytes

typedef struct {
    int connection_id;
    int sequence_number;
    int acknowledgment_number;
    char* data_payload;
    int error_flag;
} TCP_Connection;

typedef struct {
    int operation_id;
    char* file_path;
    char* metadata;
    int status;
} File_System_Access;

TCP_Connection* connections = NULL;
int connection_count = 0;

File_System_Access* accesses = NULL;
int access_count = 0;

// Cache for file system metadata
char* cache[CACHESIZE];
int cache_size = 0;
int cache_hit = 0;
int cache_miss = 0;

void add_connection(int id, int seq_num, int ack_num, char* payload) {
    if (connection_count >= MAX_CONNECTIONS) {
        printf("Error: Maximum connections reached.\n");
        return;
    }
    TCP_Connection* conn = malloc(sizeof(TCP_Connection));
    conn->connection_id = id;
    conn->sequence_number = seq_num;
    conn->acknowledgment_number = ack_num;
    conn->data_payload = payload;
    conn->error_flag = 0;
    if (connections == NULL) {
        connections = conn;
    } else {
        TCP_Connection* temp = connections;
        while (temp != NULL && temp->connection_id < id) {
            temp = temp->next;
        }
        temp->next = conn;
    }
    connections = temp;
    connection_count++;
}

void add_access(int id, char* path, char* meta, int status) {
    if (access_count >= MAX_FILE_ACCESS) {
        printf("Error: Maximum file accesses reached.\n");
        return;
    }
    File_System_Access* access = malloc(sizeof(File_System_Access));
    access->operation_id = id;
    access->file_path = path;
    access->metadata = meta;
    access->status = status;
    if (accesses == NULL) {
        accesses = access;
    } else {
        File_System_Access* temp = accesses;
        while (temp != NULL && temp->operation_id < id) {
            temp = temp->next;
        }
        temp->next = access;
    }
    accesses = temp;
    access_count++;
}

TCP_Connection* get_connection(int id) {
    TCP_Connection* conn = connections;
    while (conn != NULL && conn->connection_id < id) {
        conn = conn->next;
    }
    if (conn == NULL || conn->connection_id != id) {
        return NULL;
    }
    return conn;
}

File_System_Access* get_access(int id) {
    File_System_Access* access = accesses;
    while (access != NULL && access->operation_id < id) {
        access = access->next;
    }
    if (access == NULL || access->operation_id != id) {
        return NULL;
    }
    return access;
}

void update_connection_error(int id, int flag) {
    TCP_Connection* conn = get_connection(id);
    if (conn != NULL) {
        conn->error_flag = flag;
    }
}

void update_access_status(int id, int status) {
    File_System_Access* access = get_access(id);
    if (access != NULL) {
        access->status = status;
    }
}

void remove_connection(int id) {
    TCP_Connection* prev = NULL;
    TCP_Connection* curr = connections;
    while (curr != NULL && curr->connection_id < id) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL || curr->connection_id != id) {
        return;
    }
    if (prev == NULL) {
        connections = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    connection_count--;
}

void remove_access(int id) {
    File_System_Access* prev = NULL;
    File_System_Access* curr = accesses;
    while (curr != NULL && curr->operation_id < id) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL || curr->operation_id != id) {
        return;
    }
    if (prev == NULL) {
        accesses = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    access_count--;
}

