            free(cache[i]);
            cache[i] = NULL;
            break;
        }
    }
    if (i >= cache_size || cache[i] != NULL) {
        for (int j = 0; j < i; j++) {
            if (cache[j] != NULL) {
                free(cache[j]);
                cache[j] = NULL;
            }
        }
        cache_size = i;
    } else {
        cache[cache_size++] = meta;
    }
}

