void add_PDU(int SN, int SDU_size, int error_indication) {
    pthread_mutex_lock(&mutex);
    LTE_Uplink_PDCP_PDU* temp = (LTE_Uplink_PDCP_PDU*)realloc(PDUs, ++total_PDUs * sizeof(LTE_Uplink_PDCP_PDU));
    if (!temp) {
        // handle out-of-memory condition
        printf("Out of memory!\n");
        return;
    }
    PDUs = temp;
    PDUs[total_PDUs - 1].SN = SN;
    PDUs[total_PDUs - 1].SDU_size = SDU_size;
    PDUs[total_PDUs - 1].error_indication = error_indication;
    pthread_mutex_unlock(&mutex);
}

LTE_Uplink_PDCP_PDU* get_PDU(int SN) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < total_PDUs; i++) {
        if (PDUs[i].SN == SN) {
            LTE_Uplink_PDCP_PDU* temp = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
            *temp = PDUs[i];
            pthread_mutex_unlock(&mutex);
            return temp;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_error(int SN, int error_indication) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < total_PDUs; i++) {
        if (PDUs[i].SN == SN) {
            PDUs[i].error_indication = error_indication;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void remove_PDU(int SN) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < total_PDUs; i++) {
        if (PDUs[i].SN == SN) {
            memmove(PDUs + i, PDUs + i + 1, (total_PDUs - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            free(PDUs[--total_PDUs]);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int get_average_SDU_size() {
    int total_SDU_size = 0;
    for (int i = 0; i < total_PDUs; i++) {
        total_SDU_size += PDUs[i].SDU_size;
    }
    return total_SDU_size / total_PDUs;
}

void get_PDUs_with_errors(LTE_Uplink_PDCP_PDU** result) {
    *result = (LTE_Uplink_PDCP_PDU*)malloc(total_PDUs * sizeof(LTE_Uplink_PDCP_PDU));
    for (int i = 0; i < total_PDUs; i++) {
        if (PDUs[i].error_indication) {
            (*result)[i] = PDUs[i];
        }
    }
}
