#include <stdio.h>
#include <stdlib.h>

typedef struct LTE_Uplink_PDCP_PDU {
    int SN;
    int SDU_size;
    int error_indication;
} PDU;

typedef struct {
    PDU* pdus;
    int capacity;
    int size;
    int last_used_index;
    int timestamp_flush;
} PDCP_Array;

void init_array(PDCP_Array* array, int initial_capacity) {
    array->pdus = (PDU*)malloc(initial_capacity * sizeof(PDU));
    array->capacity = initial_capacity;
    array->size = 0;
    array->last_used_index = -1;
    array->timestamp_flush = -1;
}

void add_pdu(PDCP_Array* array, PDU pdu) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->pdus = (PDU*)realloc(array->pdus, array->capacity * sizeof(PDU));
    }
    array->pdus[array->size] = pdu;
    array->last_used_index = array->size++;
}

PDU* get_pdu_by_sn(PDCP_Array* array, int SN) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

void update_error_indication(PDCP_Array* array, int SN, int error_indication) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN == SN) {
            array->pdus[i].error_indication = error_indication;
            return;
        }
    }
}

void flush_old_pdus(PDCP_Array* array, int timestamp) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].SN <= timestamp) {
            for (int j = i + 1; j < array->size; j++) {
                array->pdus[j - 1] = array->pdus[j];
            }
            array->size--;
            i--; // Decrement i to re-process the same index
        }
    }
}

void compact_array(PDCP_Array* array) {
    PDU* temp = (PDU*)malloc(array->size * sizeof(PDU));
    for (int i = 0; i < array->size; i++) {
        temp[i] = array->pdus[i];
    }
    free(array->pdus);
    array->pdus = temp;
}

void release_array(PDCP_Array* array) {
    free(array->pdus);
}
