['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int pi;
    int payloadSize;
    bool isError;
} LTE_Uplink_PDCP_PDU;

struct pdu_list {
    LTE_Uplink_PDCP_PDU* pdus;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
};

void initPduList(struct pdu_list* list) {
    list->pdus = NULL;
    list->size = 0;
    list->capacity = 1;
}

int addPdu(struct pdu_list* list, int pi, int payloadSize, bool isError) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->pdus = realloc(list->pdus, sizeof(LTE_Uplink_PDCP_PDU) * list->capacity);
    }

    LTE_Uplink_PDCP_PDU* pdu = &list->pdus[list->size++];
    pdu->pi = pi;
    pdu->payloadSize = payloadSize;
    pdu->isError = isError;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

LTE_Uplink_PDCP_PDU* getPdu(struct pdu_list* list, int pi) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; i++) {
        if (list->pdus[i].pi == pi) {
            LTE_Uplink_PDCP_PDU* pdu = &list->pdus[i];
            pthread_mutex_unlock(&list->mutex);
            return pdu;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return NULL;
}

int updateError(struct pdu_list* list, int pi, bool isError) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; i++) {
        if (list->pdus[i].pi == pi) {
            list->pdus[i].isError = isError;
            break;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int removePdu(struct pdu_list* list, int pi) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; i++) {
        if (list->pdus[i].pi == pi) {
            memmove(&list->pdus[i], &list->pdus[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (list->size - i));
            list->size--;
            break;
        }
    }

    if (list->size < list->capacity / 4 && list->capacity > 1) {
        list->capacity /= 2;
        list->pdus = realloc(list->pdus, sizeof(LTE_Uplink_PDCP_PDU) * list->capacity);
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int purgeOldPDUs(struct pdu_list* list, int timestamp) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; i++) {
        if (gettimeofday(NULL, NULL)) {
            printf("Error getting time: %s\n", strerror(errno));
            return -1;
        }
        struct timeval now;
        gettimeofday(&now, NULL);
        long timeDiff = (now.tv_sec * 1000L + now.tv_usec / 1000) - timestamp;

        if (timeDiff > 30000L) { // 30 seconds
            memmove(&list->pdus[i], &list->pdus[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (list->size - i));
            list->size--;
            i--;
        }
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int main() {
    struct pdu_list list;
    initPduList(&list);

    // Example usage
    addPdu(&list, 1, 100, false);
    addPdu(&list, 2, 200, true);
    addPdu(&list, 3, 300, false);

    LTE_Uplink_PDCP_PDU* pdu = getPdu(&list, 2);
    if (pdu) {
        printf("PI: %d, Payload Size: %d, Error Status: %s\n", pdu->pi, pdu->payloadSize, pdu->isError ? "Yes" : "No");
    }

    updateError(&list, 1, true);

    removePdu(&list, 2);

    purgeOldPDUs(&list, time(NULL) - 30); // Purge PDUs older than 30 seconds

    return 0;
}
