// Define the structure for MediaStreamFrames
typedef struct {
    int timestamp;
    int frame_size;
    int quality_rating;
} MediaStreamFrame;

// Define the structure for TCP_Connectors
typedef struct {
    int connection_id;
    int last_active_timestamp;
    char status[16];
} TCP_Connector;

// Define the structure for FileRecords
typedef struct {
    char file_path[256];
    int file_size;
    int last_modified_timestamp;
    int read_write_flag;
    char checksum[64];
} FileRecord;

// Function to manage dynamic array of MediaStreamFrames, TCP_Connectors, and FileRecords
void* media_stream_frame_array_manager(void* arg) {
    // Initialize the dynamic array
    MediaStreamFrame** frames = (MediaStreamFrame**)malloc(1000000 * sizeof(MediaStreamFrame*));

    // Initialize the mutex for thread-safe operations
    pthread_mutex_t frame_mutex;
    pthread_mutex_init(&frame_mutex, NULL);

    // Function to add a new frame
    void add_frame(int timestamp, int frame_size, int quality_rating) {
        // Create a new MediaStreamFrame instance
        MediaStreamFrame* new_frame = (MediaStreamFrame*)malloc(sizeof(MediaStreamFrame));

        // Set the properties of the new frame
        new_frame->timestamp = timestamp;
        new_frame->frame_size = frame_size;
        new_frame->quality_rating = quality_rating;

        // Add the new frame to the array and update the total count
        pthread_mutex_lock(&frame_mutex);
        frames[frames_count] = new_frame;
        frames_count++;
        pthread_mutex_unlock(&frame_mutex);
    }

    // Function to retrieve a specific frame by timestamp
    MediaStreamFrame* get_frame(int timestamp) {
        for (int i = 0; i < frames_count; i++) {
            if (frames[i]->timestamp == timestamp) {
                return frames[i];
            }
        }
        return NULL;
    }

    // Function to update the quality rating of a specific frame
    void update_frame_quality(int timestamp, int new_quality_rating) {
        MediaStreamFrame* frame = get_frame(timestamp);
        if (frame != NULL) {
            pthread_mutex_lock(&frame_mutex);
            frame->quality_rating = new_quality_rating;
            pthread_mutex_unlock(&frame_mutex);
        }
    }

    // Function to add a new TCP connector
    void add_tcp_connector(int connection_id, int last_active_timestamp, char status[16]) {
        // Create a new TCP_Connector instance
        TCP_Connector* new_connector = (TCP_Connector*)malloc(sizeof(TCP_Connector));

        // Set the properties of the new connector
        new_connector->connection_id = connection_id;
        new_connector->last_active_timestamp = last_active_timestamp;
        strcpy(new_connector->status, status);

        // Add the new connector to the array and update the total count
        pthread_mutex_lock(&frame_mutex);
        tcp_connectors[tcp_connectors_count] = new_connector;
        tcp_connectors_count++;
        pthread_mutex_unlock(&frame_mutex);
    }

    // Function to retrieve a specific TCP connector by connection ID
    TCP_Connector* get_tcp_connector(int connection_id) {
        for (int i = 0; i < tcp_connectors_count; i++) {
            if (tcp_connectors[i]->connection_id == connection_id) {
                return tcp_connectors[i];
            }
        }
        return NULL;
    }

    // Function to update the status of a specific TCP connector
    void update_tcp_connector_status(int connection_id, char new_status[16]) {
        TCP_Connector* connector = get_tcp_connector(connection_id);
        if (connector != NULL) {
            pthread_mutex_lock(&frame_mutex);
            strcpy(connector->status, new_status);
            pthread_mutex_unlock(&frame_mutex);
        }
    }

    // Function to add a new file record
    void add_file_record(char file_path[256], int file_size, int last_modified_timestamp, int read_write_flag, char checksum[64]) {
        // Create a new FileRecord instance
        FileRecord* new_record = (FileRecord*)malloc(sizeof(FileRecord));

        // Set the properties of the new record
        strcpy(new_record->file_path, file_path);
        new_record->file_size = file_size;
        new_record->last_modified_timestamp = last_modified_timestamp;
        new_record->read_write_flag = read_write_flag;
        strcpy(new_record->checksum, checksum);

        // Add the new record to the array and update the total count
        pthread_mutex_lock(&frame_mutex);
        file_records[file_records_count] = new_record;
        file_records_count++;
        pthread_mutex_unlock(&frame_mutex);
    }

    // Function to retrieve a specific file record by path
    FileRecord* get_file_record(char file_path[256]) {
        for (int i = 0; i < file_records_count; i++) {
            if (strcmp(file_records[i]->file_path, file_path) == 0) {
                return file_records[i];
            }
        }
        return NULL;
    }

    // Function to update the read/write flag of a specific file record
    void update_file_record_read_write_flag(char file_path[256], int new_flag) {
        FileRecord* record = get_file_record(file_path);
        if (record != NULL) {
            pthread_mutex_lock(&frame_mutex);
            record->read_write_flag = new_flag;
            pthread_mutex_unlock(&frame_mutex);
        }
    }

    // Function to verify array integrity and log operations
    void verify_array_integrity() {
        int total_entries = frames_count + tcp_connectors_count + file_records_count;

        if (total_entries != 1000000) {
            printf("Array integrity issue: Total entries mismatched.\n");
        } else {
            printf("Array integrity verified.\n");
        }
    }

    // Function to export the current state in a standardized format
    void export_state() {
        FILE* file = fopen("media_stream_frame_array_manager_state.txt", "w");

        if (file != NULL) {
            fprintf(file, "MediaStreamFrames:\n");
            for (int i = 0; i < frames_count; i++) {
                MediaStreamFrame* frame = frames[i];
                fprintf(file, "Timestamp: %d, Frame Size: %d, Quality Rating: %d\n", frame->timestamp, frame->frame_size, frame->quality_rating);
            }

