// Define a memory pool manager
typedef struct {
    void **pool;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t mutex;
} MemoryPoolManager;

MemoryPoolManager* memory_pool_manager = NULL;

// Initialize the memory pool manager
void init_memory_pool_manager(size_t initial_capacity) {
    if (!memory_pool_manager) {
        memory_pool_manager = (MemoryPoolManager*)malloc(sizeof(MemoryPoolManager));
        memory_pool_manager->pool = (void**)calloc(initial_capacity, sizeof(void*));
        memory_pool_manager->capacity = initial_capacity;
        memory_pool_manager->allocated = 0;
        pthread_mutex_init(&memory_pool_manager->mutex, NULL);
    }
}

// Resize the memory pool manager
void resize_memory_pool(size_t new_capacity) {
    MemoryPoolManager* mp = memory_pool_manager;
    void** old_pool = mp->pool;
    size_t old_allocated = mp->allocated;

    mp->pool = (void**)realloc(mp->pool, new_capacity * sizeof(void*));
    mp->capacity = new_capacity;
    mp->allocated = 0;

    // Re-allocate memory for the existing objects
    for (size_t i = 0; i < old_allocated; i++) {
        void* obj = *(old_pool + i);
        size_t new_index = i % mp->capacity;
        *(mp->pool + new_index) = obj;
    }

    free(old_pool);
}

// Define a function to compress SDU sizes
uint16_t compress_sdu_size(uint16_t size) {
    // Implement compression algorithm here
    return size;
}

// Define a function to decompress compressed SDU sizes
uint16_t decompress_sdu_size(uint16_t compressed_size) {
    // Implement decompression algorithm here
    return compressed_size;
}

// Initialize and manage the dynamic array of PDCP PDUs
void* lte_uplink_pdcp_pdu_manager(void** pdus, size_t size, int (*process_pdu)(LTE_Uplink_PDCP_PDU*)) {
    pthread_mutex_lock(&memory_pool_manager->mutex);

    // Check if memory is available in the pool before allocating
    if (size > memory_pool_manager->capacity) {
        resize_memory_pool(size);
    }

    for (size_t i = 0; i < size; i++) {
        LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        pdu->SN = compress_sdu_size((uint16_t)(i + 1)); // Initialize SN with compressed SDU size
        pdu->SDU_size = decompress_sdu_size(pdus[i]->SDU_size); // Decompress and store in PDU
        pdu->error_indication = pdus[i]->error_indication;

        memory_pool_manager->pool[memory_pool_manager->allocated] = pdu;
        memory_pool_manager->allocated++;

        process_pdu(*pdu);
    }

    pthread_mutex_unlock(&memory_pool_manager->mutex);

    return NULL;
}

// Define a function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* get_pdu_by_sn(uint32_t sn) {
    for (size_t i = 0; i < memory_pool_manager->allocated; i++) {
        LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)memory_pool_manager->pool[i];
        if (pdu->SN == sn) {
            return pdu;
        }
    }

    return NULL;
}

// Define a function to update the error indication for a given SN
void update_error_indication(uint32_t sn, int8_t new_error_indication) {
