    TCP_Flow_Control_Record* new_record;
    int bytes_needed = sizeof(TCP_Flow_Control_Record);

    pthread_mutex_lock(&records_lock);

    if (mem_pool == NULL || record_count >= mem_pool_size / bytes_needed) {
        // Out of memory or pool too small, resize it
        mem_pool_size *= 2;
        mem_pool = realloc(mem_pool, mem_pool_size);
        mem_pool_threshold /= 2;
