typedef struct {
    char srcIP[16];
    char dstIP[16];
    int protocol;
    int size;
    time_t timestamp;
} packet;

typedef struct {
    packet* packets;
    int numPackets;
    int capacity;
} packetList;

packetList* createPacketList(int initialCapacity) {
    packetList* list = (packetList*)malloc(sizeof(packetList));
    list->packets = (packet*)malloc(initialCapacity * sizeof(packet));
    list->numPackets = 0;
    list->capacity = initialCapacity;
    return list;
}

void addPacket(packetList* list, packet newPacket) {
    if (list->numPackets == list->capacity) {
        // Resize the list
        list->capacity *= 2;
        list->packets = (packet*)realloc(list->packets, list->capacity * sizeof(packet));
    }
    list->packets[list->numPackets] = newPacket;
    list->numPackets++;
}

packet* getPacketByID(packetList* list, int packetID) {
    for (int i = 0; i < list->numPackets; i++) {
        if (list->packets[i].timestamp == packetID) {
            return &list->packets[i];
        }
    }
    return NULL;
}

void updatePacketStatus(packetList* list, int packetID, char status) {
    for (int i = 0; i < list->numPackets; i++) {
        if (list->packets[i].timestamp == packetID) {
            // Update the status
            strcpy(list->packets[i].status, status);
            return;
        }
    }
}

void removeOldPackets(packetList* list, time_t threshold) {
    for (int i = 0; i < list->numPackets; i++) {
        if (list->packets[i].timestamp < threshold) {
            // Remove the packet
            memmove(&list->packets[i], &list->packets[i+1], (list->numPackets - i - 1) * sizeof(packet));
            list->numPackets--;
            i--; // Decrement i to re-check the same index
        }
    }
}

void sortPacketsByTimestamp(packetList* list) {
    qsort(list->packets, list->numPackets, sizeof(packet), packetComparator);
}

int packetComparator(const void* a, const void* b) {
    const packet* pa = (const packet*)a;
    const packet* pb = (const packet*)b;
    if (pa->timestamp < pb->timestamp) return -1;
    if (pa->timestamp > pb->timestamp) return 1;
    return 0;
}

void freePacketList(packetList* list) {
    free(list->packets);
    free(list);
}
