void* operator new(size_t size) {
    return malloc(size);
}

void operator delete(void* ptr) {
    free(ptr);
}

struct PDCP_array {
    LTE_Uplink_PDCP_PDU** PDUs;
    int num_PDUs;
    int capacity;
};

PDCP_array* pdcps_init(int initial_capacity) {
    PDCP_array* array = new PDCP_array();
    array->PDUs = new LTE_Uplink_PDCP_PDU*[initial_capacity];
    array->num_PDUs = 0;
    array->capacity = initial_capacity;
    return array;
}

void pdcps_free(PDCP_array* array) {
    delete[] array->PDUs;
    delete array;
}

int pdcps_add_pdu(PDCP_array* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->num_PDUs >= array->capacity) {
        int new_capacity = array->capacity * 2;
        LTE_Uplink_PDCP_PDU** new_PDUs = new LTE_Uplink_PDCP_PDU*[new_capacity];
        for (int i = 0; i < array->capacity; i++) {
            new_PDUs[i] = array->PDUs[i];
        }
        delete[] array->PDUs;
        array->PDUs = new_PDUs;
        array->capacity = new_capacity;
    }
    array->PDUs[array->num_PDUs++] = &pdu;
    return 0;
}

LTE_Uplink_PDCP_PDU* pdcps_get_pdu(PDCP_array* array, int SN) {
    for (int i = 0; i < array->num_PDUs; i++) {
        if (array->PDUs[i]->SN == SN) {
            return array->PDUs[i];
        }
    }
    return NULL;
}

void pdcps_update_error(PDCP_array* array, int SN, int error_indication) {
    for (int i = 0; i < array->num_PDUs; i++) {
        if (array->PDUs[i]->SN == SN) {
            array->PDUs[i]->error_indication = error_indication;
            return;
        }
    }
}

void pdcps_process(PDCP_array* array, int (*callback)(int progress)) {
    for (int i = 0; i < array->num_PDUs; i++) {
        try {
            // Processing code here
            callback(i / (array->num_PDUs * 1.0) * 100);
        } catch (...) {
            printf("Error occurred during processing: %s\n", __FUNCTION__);
            pdcps_free(array);
            return;
        }
    }
}

int main() {
    // Example usage:
    PDCP_array* array = pdcps_init(10);
    LTE_Uplink_PDCP_PDU pdu1 = {0, 128, 0};
    LTE_Uplink_PDCP_PDU pdu2 = {1, 256, 0};
    pdcps_add_pdu(array, pdu1);
    pdcps_add_pdu(array, pdu2);
    LTE_Uplink_PDCP_PDU* pdu = pdcps_get_pdu(array, 1);
    if (pdu) {
        printf("PDU with SN %d found: SDU size - %d\n", pdu->SN, pdu->SDU_size);
    } else {
        printf("PDU not found.\n");
    }
    pdcps_update_error(array, 0, 1);
    // Simulate processing:
    for (int i = 0; i <= 100; i++) {
        pdcps_process(array, (progress) {
            printf("Processing progress: %d%%\n", progress);
            return 0;
        });
    }
    pdcps_free(array);
    return 0;
}

