} LTE_Uplink_PDCP_PDU;

void managePDUFilenameUpdateAndSend(LTE_Uplink_PDCP_PDU** pdus, int* numPdus, int* totalPdusAdded, int* numErrorsEncountered, int* bufferTotalBytes, char* filename) {
    // Initialize variables
    *numPdus = 0;
    *totalPdusAdded = 0;
    *numErrorsEncountered = 0;
    *bufferTotalBytes = 0;

    // Check if the filename is valid
    if (strlen(filename) > FILENAME_MAX_LENGTH || !isalnum(filename[0])) {
        printf("Invalid filename. Please check your input.\n");
        return;
    }

    // Create a new dynamic array for PDUs if it doesn't exist
    LTE_Uplink_PDCP_PDU* tempPDus = *pdus;
    *pdus = (LTE_Uplink_PDCP_PDU*)malloc(MAX_PDUS * sizeof(LTE_Uplink_PDCP_PDU));
    free(tempPDus);

    // Calculate the new filename
    char newFilename[FILENAME_MAX_LENGTH + BUFFER_SIZE];
    int numDigits = filename[0] ? 1 : (strlen(filename) > 0 ? 0 : -1);
    if (numDigits < 0) {
        printf("Invalid filename. Please check your input.\n");
        return;
    }
    else {
        // Ensure the new filename is within the allowed length
        sprintf(newFilename, "%.*s", BUFFER_SIZE - numDigits - 4, filename);

        // Calculate the number of digits to append based on the filename's length
        int numNewDigits = (FILENAME_MAX_LENGTH + BUFFER_SIZE) - strlen(newFilename);
        if (numNewDigits > 0) {
            char* numStr = malloc((numNewDigits + 1) * sizeof(char));
