typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* create_list(int n) {
    if (n <= 0) return NULL;

    Node* head = NULL;
    for (int i = 0; i < n; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed\n");
            exit(1);
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand();
        new_node->data.CRC_INDICATION_REL8_TAG = rand();
        new_node->data.CRCFLAG = rand() % 2;

        if (!head) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    return head;
}

void print_list(Node* list) {
    Node* current = list;
    int count = 0;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n", 
               current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, 
               current->data.CRC_INDICATION_REL8_TAG, current->data.CRCFLAG);
        current = current->next;
        ++count;
    }
    printf("Total elements: %d\n", count);
}

int main() {
    int n = 10000;

    Node* list = create_list(n);

    print_list(list);

