int process_pipeline(const char* log_file_path) {
    FILE* file = fopen(log_file_path, "rb");
    if (!file) {
        printf("Error opening file: %s\n", log_file_path);
        return -1;
    }

    // Initialize counters and buffers
    int record_count = 0;
    unsigned char buffer[BUFFER_SIZE];
    z_stream strm;

    // Initialize the compression stream
    memset(&strm, 0, sizeof(z_stream));
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int compressed_records = 0;
    while (fread(buffer, 1, BUFFER_SIZE, file) > 0) {
        // Decompress the data
        strm.avail_in = BUFFER_SIZE;
        strm.next_in = buffer;
        do {
            strm.avail_out = BUFFER_SIZE;
            strm.next_out = buffer;
            deflate(&strm, Z_FINISH);
            compressed_records++;
        } while (strm.avail_in == 0 && !ferror(file));

        // Process the decompressed data
        record_count += process_decompressed_data(buffer, BUFFER_SIZE);
    }

    fclose(file);

    return record_count + compressed_records;
}

