                // Limit rate of processed events
                time_t current_time = time(NULL);
                if (current_time - last_process_time >= 1) {
                    last_process_time = current_time;
                    count = 0;
                }
                else if (++count > RATE_LIMIT / 1000) {
                    printf("Rate limit exceeded! Dropped event.\n");
                    continue;
                }

                // Handle connection requests, data packets, and disconnection notifications
