// Dynamic array of PDUs
LTE_Uplink_PDCP_PDU** pdus;
int pdu_count = 0;

// Mutex for concurrency control
pthread_mutex_t pdus_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_pdu(int sequence_number, int error_indication) {
    LTE_Uplink_PDCP_PDU* new_pdu = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!new_pdu) {
        printf("Out of memory!\n");
        return;
    }
    new_pdu->sequence_number = sequence_number;
    new_pdu->error_indication = error_indication;

    // Check if we've reached the maximum capacity
    if (pdu_count >= 10000) {
        printf("PDU array is full. Cannot add more PDUs.\n");
        free(new_pdu);
        return;
    }

    pdus[pdu_count] = new_pdu;
    pdu_count++;
}

LTE_Uplink_PDCP_PDU* get_pdu(int sequence_number) {
    for (int i = 0; i < pdu_count; i++) {
        if (pdus[i]->sequence_number == sequence_number) {
            return pdus[i];
        }
    }
    return NULL;
}

void update_error_indication(int sequence_number, int error_indication) {
    pthread_mutex_lock(&pdus_mutex);

    for (int i = 0; i < pdu_count; i++) {
        if (pdus[i]->sequence_number == sequence_number) {
            pdus[i]->error_indication = error_indication;
            break;
        }
    }

    pthread_mutex_unlock(&pdus_mutex);
}

void free_pdus() {
    for (int i = 0; i < pdu_count; i++) {
        free(pdus[i]);
