typedef struct LTE_Uplink_PDCP_PDU {
    int sequenceNumber;
    int size;
    int errorIndication;
} PDU;

// Function to initialize the dynamic array
void initPDUArray(PDU **array, int *size) {
    *array = (PDU *)malloc(sizeof(PDU));
    *size = 1;
}

// Function to add a new PDU to the array
int addPDU(PDU **array, int *size, int sequenceNumber, int size, int errorIndication) {
    if (*size == 0) {
        // Initialize the dynamic array
        initPDUArray(array, size);
    }

    if ((*size) <= (strlen((char*)array) + 1)) {
        // Double the current size of the array
        *array = (PDU *)realloc(*array, sizeof(PDU) * (*size) * 2);
        *size *= 2;
    }

    PDU *newArray = (PDU *)malloc(sizeof(PDU));
    newArray->sequenceNumber = sequenceNumber;
    newArray->size = size;
    newArray->errorIndication = errorIndication;

    // Add the new PDU to the array
    memcpy(&array[(*size) - 1], newArray, sizeof(PDU));

    return (*size) - 1;
}

// Function to retrieve a specific PDU by its sequence number
PDU* getPDUBySequenceNumber(PDU **array, int size, int sequenceNumber) {
    for (int i = 0; i < size; i++) {
        if ((array)[i]->sequenceNumber == sequenceNumber) {
            return &(array)[i];
        }
    }

    return NULL;
}

// Function to update the error indication for a given SN
void updateErrorIndication(PDU **array, int size, int sequenceNumber, int errorIndication) {
    PDU *pdu = getPDUBySequenceNumber(array, size, sequenceNumber);
    if (pdu != NULL) {
        pdu->errorIndication = errorIndication;
    }
}

// Function to remove outdated PDUs based on a configurable expiration time
void removeOutdatedPDU(PDU **array, int *size, int expirationTime) {
    for (int i = 0; i < *size; i++) {
        if ((array)[i]->sequenceNumber <= expirationTime) {
            // Remove the outdated PDU from the array
            free((array));
            *size -= 1;
            array = realloc(array, sizeof(PDU) * (*size));
        }
    }
}

// Function to serialize the entire PDU array to a file
void serializePDUArray(PDU **array, int size, FILE *file) {
    for (int i = 0; i < size; i++) {
        fwrite(&((array)[i]), sizeof(PDU), 1, file);
    }
}

// Function to handle potential out-of-memory conditions gracefully
void handleMemoryError() {
    printf("Out of memory! Terminating the program.\n");
    exit(1);
}
