use std::thread;
use std::time::{Duration, Instant};
use log::{info, error};

struct HealthChecker {
    services: Vec<String>,
    threshold: u16,
}

impl HealthChecker {
    fn new(services: Vec<String>, threshold: u16) -> Self {
        HealthChecker { services, threshold }
    }

    fn start(&self) {
        thread::spawn(move || {
            loop {
                for service in &self.services {
                    if !is_service_up(service) {
                        error!("Service {} is down", service);
                        send_alert(service);
                    }
                }
                thread::sleep(Duration::from_secs(60 * 60)); // check every hour
            }
        });
    }
}

fn main() {
    let services = vec!["service1".to_string(), "service2".to_string()];
    let threshold = 1500;
    let health_checker = HealthChecker::new(services, threshold);
    health_checker.start();
}
```

