    pthread_mutex_lock(&pdcp_pdu_lock);
    for (int i = 0; i < pdcp_pdu_pool_count; i++) {
        if (pdcp_pdu_pool[i].sn == sn) {
            pdu = &pdcp_pdu_pool[i];
            break;
        }
    }
    pthread_mutex_unlock(&pdcp_pdu_lock);
    return pdu;
}

