    LTE_Uplink_PDCP_PDU* pdu = get_pdu(sn);
    if (pdu != NULL) {
        pdu->error_indication = error_indication;
        return 0;
    }
    return -1; // PDU not found
}

int remove_stale_pdus(int expiration_time) {
