void add_request(HashTable* table, int id, const char* method, const char* url, char* headers, size_t body_len) {
    // implement lock mechanism
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->capacity; i++) {
        if (table->requests[i] == NULL) {
            table->requests[i] = (HTTP_Request*)malloc(sizeof(HTTP_Request));
            table->requests[i]->id = id;
            strcpy(table->requests[i]->method, method);
            strcpy(table->requests[i]->url, url);
            table->requests[i]->headers = headers;
            table->requests[i]->body_len = body_len;
            table->size++;
            break;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

