// Structure definition
typedef struct {
    uint32_t sequence_number;
    uint16_t sdu_size;
    uint8_t error_indication;
} LTE_Uplink_PDCP_PDU;

// Dynamic array management function
void manage_pdu_array(LTE_Uplink_PDCP_PDU **pdu_array, size_t *array_size, size_t max_size, size_t expiration_time) {
    // Initialize variables
    size_t i;
    uint32_t sn = 0; // Current sequence number

    // Add new PDUs
    for (i = 0; i < *array_size; i++) {
        if (pdu_array[i]->sequence_number == sn + 1) {
            // New PDU with incremented sequence number
            pdu_array[i] = realloc(pdu_array[i], sizeof(LTE_Uplink_PDCP_PDU));
            pdu_array[i]->sequence_number = sn + 1;
            pdu_array[i]->sdu_size = 0; // Initialize SDU size to zero
            pdu_array[i]->error_indication = 0; // Initialize error indication to zero
        }
    }

    // Remove outdated PDUs based on expiration time
    for (i = 0; i < *array_size; i++) {
        if (pdu_array[i]->sequence_number <= sn - expiration_time) {
            free(pdu_array[i]);
            memmove(pdu_array + i, pdu_array + i + 1, (*array_size - i - 1) * sizeof(LTE_Uplink_PDCP_PDU));
            (*array_size)--;
        }
    }

    // Update error indication for a given SN
    for (i = 0; i < *array_size; i++) {
        if (pdu_array[i]->sequence_number == sn) {
            pdu_array[i]->error_indication = 1; // Set error indication to one
        }
    }

    // Log changes (configurable)
    if (logging_enabled()) {
        printf("Added new PDU with sequence number %u\n", sn);
        for (i = 0; i < *array_size; i++) {
            printf("PDU at index %zu: SN=%u, SDU size=%u, Error indication=%u\n", i, pdu_array[i]->sequence_number, pdu_array[i]->sdu_size, pdu_array[i]->error_indication);
