#include <stdlib.h>
#include <stdio.h>

typedef enum {
    CONNECTED,
    DISCONNECTED,
} ConnectionState;

typedef struct TCP_Connection {
    int cid;
    int timeout;
    ConnectionState state;
    bool isError;
} TCP_Connection;

void init_TCP_Connection_list(TCP_Connection **connections) {
    *connections = NULL;
}

int addTCP_Connection(TCP_Connection **connections, int cid, int timeout, ConnectionState state, bool isError) {
    TCP_Connection *new_connection = malloc(sizeof(TCP_Connection));
    new_connection->cid = cid;
    new_connection->timeout = timeout;
    new_connection->state = state;
    new_connection->isError = isError;

    if (*connections == NULL || (*connections)->cid != cid) {
        if (*connections) {
            TCP_Connection *tmp = *connections;
            *connections = new_connection;
            new_connection = tmp;
        } else {
            new_connection->next = NULL;
            *connections = new_connection;
        }
    } else {
        TCP_Connection *cur = *connections;
        while (cur && cur->cid != cid) {
            cur = cur->next;
        }
        if (cur) {
            cur->next = new_connection;
            new_connection = cur;
        } else {
            new_connection->next = NULL;
            *connections = new_connection;
        }
    }

    return new_connection ? 0 : -1; // Return 0 on success, -1 on failure
}

TCP_Connection* getTCP_Connection(TCP_Connection **connections, int cid) {
    TCP_Connection *cur = *connections;
    while (cur && cur->cid != cid) {
        cur = cur->next;
    }
    return cur ? cur : NULL; // Return the connection if found, else NULL
}

int updateTCP_Connection(TCP_Connection **connections, int cid, int timeout, ConnectionState state, bool isError) {
    TCP_Connection *conn = getTCP_Connection(connections, cid);
    if (conn) {
        conn->timeout = timeout;
        conn->state = state;
        conn->isError = isError;
        return 0; // Return 0 on success
    } else {
        return -1; // Return -1 on failure
    }
}

int purgeIdleConnections(TCP_Connection **connections, int timeout) {
    TCP_Connection *cur = *connections;
    TCP_Connection *prev = NULL;
    while (cur) {
        if (cur->timeout <= 0) { // Check for idle connections
            prev = cur;
            cur = cur->next; // Move to next connection in the list
        } else {
            int time_left = cur->timeout - timeout; // Calculate remaining timeout
            if (time_left > 0) { // Connection is not idle yet
                prev = cur; // Update previous pointer
                cur = cur->next;
            } else {
                TCP_Connection *tmp = cur;
                if (prev) {
                    prev->next = cur->next;
                } else {
                    *connections = cur->next;
                }
                free(tmp);
                return 0; // Return the count of purged connections
            }
        }
    }
    return 0; // No idle connections found
}

void cleanupTCP_Connection_list(TCP_Connection **connections) {
    TCP_Connection *cur = *connections;
    while (cur) {
        TCP_Connection *next = cur->next;
        free(cur);
        cur = next;
    }
    *connections = NULL;
}
