typedef struct {
    int SN;
    int size;
    int error;
} LTE_Uplink_PDCP_PDU;

int pdus_count = 0;
LTE_Uplink_PDCP_PDU* pdus = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void init_pdus() {
    pdus = (LTE_Uplink_PDCP_PDU*)malloc(MAX_PDUS * sizeof(LTE_Uplink_PDCP_PDU));
}

int add_pdu(int SN, int size) {
    pthread_mutex_lock(&lock);
    if (pdus_count >= MAX_PDUS - 1) {
        free_unused_pdus();
    }
    pdus[pdus_count].SN = SN;
    pdus[pdus_count].size = size;
    pdus[pdus_count].error = 0;
    pdus_count++;
    pthread_mutex_unlock(&lock);
    return pdus_count - 1;
}

LTE_Uplink_PDCP_PDU* get_pdu(int SN) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < pdus_count; i++) {
        if (pdus[i].SN == SN) {
            LTE_Uplink_PDCP_PDU* pdu = &pdus[i];
            pthread_mutex_unlock(&lock);
            return pdu;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int update_pdu_error(int SN, int error) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < pdus_count; i++) {
        if (pdus[i].SN == SN) {
            pdus[i].error = error;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return 1;
}

void free_unused_pdus() {
    int freed_count = 0;
    for (int i = 0; i < MAX_PDUS; i++) {
        if (i >= pdus_count) {
            free(&pdus[i]);
            freed_count++;
        }
    }
    printf("Freed %d PDUs\n", freed_count);
}

void save_state() {
