    for (int i = 0; i < strlen(site_path); i++) {
        if (site_path[i] != '/' && site_path[i] != '\\') {
            is_valid_path = false;
            break;
        }
    }

    if (!is_valid_path) {
        // Log a warning and attempt to correct the path format
        printf("Warning: Invalid website path '%s'. Attempting correction.\n", site_path);
        char* corrected_path = malloc((strlen(site_path)+1)*sizeof(char));
        strcpy(corrected_path, site_path);
        size_t i;
        for (i = 0; i < strlen(corrected_path); i++) {
            if (corrected_path[i] == '\\') {
                corrected_path[i] = '/';
            }
        }
        free(corrected_path);
    }

    // Fetch and apply the latest version of the web.config file
