#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int SN;
    int size;
    int error;
} LTE_Uplink_PDCP_PDU;

typedef struct Node {
    char interfaceID[20];
    int status;
    struct Node* next;
} NetworkInterfaceStatus;

void initLTEData(LTE_Uplink_PDCP_PDU** pdus, int* size, NetworkInterfaceStatus** networkInterfaces, int* numNetworkInterfaces) {
    *size = 0;
    *numNetworkInterfaces = 0;
    *pdus = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
    *networkInterfaces = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
}

void addPDU(LTE_Uplink_PDCP_PDU** pdus, int size, LTE_Uplink_PDCP_PDU pdu) {
    (*pdus) = (LTE_Uplink_PDCP_PDU*)realloc((*pdus), (size + 1) * sizeof(LTE_Uplink_PDCP_PDU));
    (*pdus)[size] = pdu;
    size++;
}

void addNetworkInterface(NetworkInterfaceStatus** networkInterfaces, int* numNetworkInterfaces, char interfaceID[20], int status) {
    NetworkInterfaceStatus* newNode = (NetworkInterfaceStatus*)malloc(sizeof(NetworkInterfaceStatus));
    strcpy(newNode->interfaceID, interfaceID);
    newNode->status = status;
    newNode->next = (*networkInterfaces);
    (*networkInterfaces) = newNode;
    (*numNetworkInterfaces)++;
}

LTE_Uplink_PDCP_PDU* getSpecificPDU(LTE_Uplink_PDCP_PDU** pdus, int size, int SN) {
    for (int i = 0; i < size; i++) {
        if ((*pdus)[i].SN == SN)
            return &(*pdus)[i];
    }
    return NULL;
}

void updatePDU(LTE_Uplink_PDCP_PDU** pdus, int size, LTE_Uplink_PDCP_PDU pdu) {
    for (int i = 0; i < size; i++) {
        if ((*pdus)[i].SN == pdu.SN)
            (*pdus)[i] = pdu;
    }
}

void removeNetworkInterface(NetworkInterfaceStatus** networkInterfaces, int* numNetworkInterfaces, char interfaceID[20]) {
    NetworkInterfaceStatus* current = *networkInterfaces;
    NetworkInterfaceStatus* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->interfaceID, interfaceID) == 0) {
            if (previous == NULL)
                (*networkInterfaces) = current->next;
            else
                previous->next = current->next;
            free(current);
            (*numNetworkInterfaces)--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

void displayData(LTE_Uplink_PDCP_PDU** pdus, int size, NetworkInterfaceStatus** networkInterfaces, int numNetworkInterfaces) {
    printf("PDUs:\n");
    for (int i = 0; i < size; i++) {
        printf("SN: %d, Size: %d, Error: %d\n", (*pdus)[i].SN, (*pdus)[i].size, (*pdus)[i].error);
    }
    printf("\nNetwork Interfaces:\n");
    NetworkInterfaceStatus* current = *networkInterfaces;
    for (int i = 0; i < numNetworkInterfaces; i++) {
        printf("Interface ID: %s, Status: %d\n", current->interfaceID, current->status);
        current = current->next;
    }
}

void freeData(LTE_Uplink_PDCP_PDU** pdus, int size, NetworkInterfaceStatus** networkInterfaces, int numNetworkInterfaces) {
    for (int i = 0; i < size; i++) {
        free((*pdus + i));
    }
    for (int i = 0; i < numNetworkInterfaces; i++) {
        free((*networkInterfaces + i));
    }
}

int main() {
    LTE_Uplink_PDCP_PDU* pdus;
    int pdusSize = 0;
    NetworkInterfaceStatus* networkInterfaces;
    int numNetworkInterfaces = 0;

    initLTEData(&pdus, &pdusSize, &networkInterfaces, &numNetworkInterfaces);

    addPDU(&pdus, pdusSize, (LTE_Uplink_PDCP_PDU){1, 100, 0});
    addPDU(&pdus, pdusSize, (LTE_Uplink_PDCP_PDU){2, 200, 1});
    addNetworkInterface(&networkInterfaces, &numNetworkInterfaces, "eth0", 1);
    addNetworkInterface(&networkInterfaces, &numNetworkInterfaces, "wlan0", 2);

    LTE_Uplink_PDCP_PDU* pdu = getSpecificPDU(&pdus, pdusSize, 2);
    if (pdu != NULL)
        printf("Found PDU with SN %d\n", pdu->SN);

    updatePDU(&pdus, pdusSize, (LTE_Uplink_PDCP_PDU){2, 200, 0});

    removeNetworkInterface(&networkInterfaces, &numNetworkInterfaces, "wlan0");

    displayData(&pdus, pdusSize, &networkInterfaces, numNetworkInterfaces);

    freeData(&pdus, pdusSize, &networkInterfaces, numNetworkInterfaces);

    return 0;
}
