#include <json-c/json.h>

int validate_json_config(json_object *config) {
    if (!config || json_object_get_type(config) != json_type_object)
        return 0;

    const char *host_ip = json_object_get_string(json_object_object_get_value(config, "host_ip"));
    int port = json_object_get_int(json_object_object_get_value(config, "port"));
    int max_connections = json_object_get_int(json_object_object_get_value(config, "max_connections"));
    bool ssl_enabled = json_object_get_boolean(json_object_object_get_value(config, "ssl_enabled"));

    if (!isValidIPv4(host_ip) || port < 1 || port > 65535 ||
        max_connections < 1 || max_connections > 1000 || !ssl_enabled)
        return 0;

    json_object *timeout_obj = json_object_object_get_value(config, "timeout");
    if (timeout_obj && json_object_get_type(timeout_obj) == json_type_int &&
        json_object_get_int(timeout_obj) < 1) {
        // timeout is optional and can be omitted
    } else if (timeout_obj)
        return 0;

    int sockfd = -1;
    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    inet_pton(AF_INET, host_ip, &serv_addr.sin_addr);
    serv_addr.sin_port = htons(port);

    // Simulate network connection
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) >= 0) {
        if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) == 0) {
            printf("Network connection successful!\n");
            close(sockfd);
        } else {
            printf("Network connection failed.\n");
            return 0;
        }
    }

    // Clean up
    if (sockfd >= 0)
        close(sockfd);

    return 1;
}

int isValidIPv4(const char *ip) {
    struct in_addr addr;
    return inet_pton(AF_INET, ip, &addr) == 1;
}
