int validate_config(json_object *config) {
    if (!json_object_object_get_ex(config, "host_ip", &json_object)) return 0;
    if (!json_object_is_string(json_object)) return 0;
    if (strlen(json_object->value.string) > sizeof(Config::host_ip)-1) return 0;

    if (!json_object_object_get_ex(config, "port", &json_object)) return 0;
    if (!json_object_is_int(json_object)) return 0;
    int port = json_object_get_int(json_object);
    if (port < 1 || port > 65535) return 0;

    if (!json_object_object_get_ex(config, "max_connections", &json_object)) return 0;
    if (!json_object_is_int(json_object)) return 0;
    int max_connections = json_object_get_int(json_object);
    if (max_connections < 1 || max_connections > MAX_CONNECTIONS) return 0;

    if (!json_object_object_get_ex(config, "ssl_enabled", &json_object)) return 0;
    if (!json_object_is_boolean(json_object)) return 0;
    bool ssl_enabled = json_object_get_bool(json_object);

    if (json_object_object_get_ex(config, "timeout", &json_object)) {
        if (!json_object_is_int(json_object)) return 0;
        int timeout = json_object_get_int(json_object);
        if (timeout < 1) return 0;
    }

    if (json_object_object_get_ex(config, "backlog", &json_object)) {
        if (!json_object_is_int(json_object)) return 0;
        int backlog = json_object_get_int(json_object);
        if (backlog < 1) return 0;
    }

    if (json_object_object_get_ex(config, "keepalive_interval", &json_object)) {
        if (!json_object_is_int(json_object)) return 0;
        int keepalive_interval = json_object_get_int(json_object);
        if (keepalive_interval < 1) return 0;
    }

    // Additional optional fields
    if (json_object_object_get_ex(config, "retry_count", &json_object)) {
        if (!json_object_is_int(json_object)) return 0;
        int retry_count = json_object_get_int(json_object);
        if (retry_count < 1) return 0;
    }

    // Validate JSON structure
    if (json_object_get_type(config) != json_type_object) return 0;

    // Perform basic performance check
    // Simulate a network connection attempt using the validated parameters
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(port);
    inet_pton(AF_INET, json_object->value.string, &server.sin_addr);

    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        // Log failure message and return false
        printf("Failed to connect.\n");
        close(sock);
        return 0;
    }

    // Log confirmation message and return true
    printf("Connected successfully.\n");
    close(sock);
    return 1;
}

void log_message(int level, const char *message) {
    if (level <= LOG_LEVEL)
        printf("%s\n", message);
}

int main() {
    json_object *config = json_object_from_file("config.json");
    int result = validate_config(config);
    json_object_free(config);

    return result;
}
