#define CACHE_SIZE 10000

typedef struct {
    uint32_t id;
    char type[16];
    int64_t metadata[10]; // assuming at most 10 metadata fields
} MediaRequest;

typedef struct {
    void* payload;
    int size;
    uint32_t timestamp;
    uint8_t quality;
} Frame;

typedef struct {
    MediaRequest request;
    Frame frames[];
} MediaStream;

pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
HashTable* cache;

void handleStreamingMediaRequests() {
    // Initialize the cache
    cache = hashTableCreate(CACHE_SIZE);

    while (1) {
        pthread_mutex_lock(&cache_mutex);
        // Process incoming media requests
        MediaRequest request;
        // Parse the request and create a new MediaStream entry
        MediaStream* stream = malloc(sizeof(MediaStream));
        stream->request.id = 0; // Initialize the request ID
        // Add frames to the stream
        int frame_count = 10; // Assuming up to 10 frames per media stream
        for (int i = 0; i < frame_count; i++) {
            Frame* frame = malloc(sizeof(Frame));
            frame->payload = malloc(1024); // Assuming a maximum payload size of 1024 bytes
            frame->size = rand() % 1024;
            frame->timestamp = time(NULL);
            frame->quality = rand() % 255; // assuming quality scores range from 0 to 254
            stream->frames[i] = frame;
        }
        // Add the media stream to the cache
        hashTablePut(cache, &stream->request.id, stream);

        pthread_mutex_unlock(&cache_mutex);
    }
}

void freeMediaStream(MediaStream* stream) {
    for (int i = 0; i < frame_count; i++) {
        Frame* frame = &stream->frames[i];
        free(frame->payload);
        free(frame);
    }
    free(stream);
}
