typedef struct {
    long timestamp;
    int stream_id;
    int sender_id;
    char codec[16];
    char quality[16];
} media_stream_t;

media_stream_manager(media_stream_manager_t *manager) {
    manager->stream_queue = NULL;
    manager->concurrency_limit = 1000;
    manager->pruning_frequency = 500;
}

void enqueue_stream(media_stream_manager_t *manager, media_stream_t *stream) {
    // implement priority queue logic
    pthread_mutex_lock(&manager->mutex);
    if (manager->stream_queue == NULL || 
        pthread_cmp(manager->stream_queue->stream_id < stream->stream_id)) {
        // add to end of queue
        manager->stream_queue = realloc(manager->stream_queue, sizeof(media_stream_t*) * (manager->stream_queue_len + 1));
        manager->stream_queue[manager->stream_queue_len++] = stream;
    } else {
        // insert at correct position
        int i;
        for (i = 0; i < manager->stream_queue_len; i++) {
            if (pthread_cmp(manager->stream_queue[i]->stream_id == stream->stream_id)) {
                break;
            }
        }
        memmove(&manager->stream_queue[i], &manager->stream_queue[i + 1], sizeof(media_stream_t*) * (manager->stream_queue_len - i));
        manager->stream_queue[i] = stream;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void dequeue_stream(media_stream_manager_t *manager, int stream_id) {
    // implement priority queue logic
    pthread_mutex_lock(&manager->mutex);
    int i;
    for (i = 0; i < manager->stream_queue_len; i++) {
        if (pthread_cmp(manager->stream_queue[i]->stream_id == stream_id)) {
            break;
        }
    }
    if (i >= manager->stream_queue_len) {
        // stream not found
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    memmove(&manager->stream_queue[i], &manager->stream_queue[i + 1], sizeof(media_stream_t*) * (manager->stream_queue_len - i));
    manager->stream_queue_len--;
    free(manager->stream_queue[i]);
    pthread_mutex_unlock(&manager->mutex);
}

void prune_streams(media_stream_manager_t *manager) {
    // implement pruning logic
    if (manager->stream_queue_len > manager->pruning_frequency) {
        int i;
        for (i = 0; i < manager->stream_queue_len - manager->pruning_frequency; i++) {
            free(manager->stream_queue[i]);
        }
        memmove(&manager->stream_queue[0], &manager->stream_queue[manager->pruning_frequency], sizeof(media_stream_t*) * (manager->stream_queue_len - i));
        manager->stream_queue_len -= manager->pruning_frequency;
    }
}

