int array_size = 0;
LTE_Uplink_PDCP_PDU* dynamic_array[MAX_SIZE] = {NULL};

void add_pdu(int sequence_number, int timestamp) {
    pthread_mutex_lock(&lock);

    // Check if the array needs to be resized
    if (array_size >= MAX_SIZE) {
        // Handle out-of-memory condition
        printf("Array is full. Cannot add more PDU.\n");
        return;
    }

    LTE_Uplink_PDCP_PDU* new_pdu = malloc(sizeof(LTE_Uplink_PDCP_PDU));
    if (!new_pdu) {
        // Handle out-of-memory condition
        printf("Failed to allocate memory for new PDU.\n");
        return;
    }

    new_pdu->sequence_number = sequence_number;
    new_pdu->timestamp = timestamp;

    dynamic_array[array_size] = new_pdu;
    array_size++;

    pthread_mutex_unlock(&lock);
}

LTE_Uplink_PDCP_PDU* get_pdu(int sequence_number, int timestamp) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i]->sequence_number == sequence_number && dynamic_array[i]->timestamp == timestamp) {
            LTE_Uplink_PDCP_PDU* pdu = dynamic_array[i];
            pthread_mutex_unlock(&lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_pdu(int sequence_number, int timestamp, int new_sequence_number, int new_timestamp) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i]->sequence_number == sequence_number && dynamic_array[i]->timestamp == timestamp) {
            dynamic_array[i]->sequence_number = new_sequence_number;
            dynamic_array[i]->timestamp = new_timestamp;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    pthread_mutex_unlock(&lock);
}

void remove_pdu(int sequence_number, int timestamp) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        if (dynamic_array[i]->sequence_number == sequence_number && dynamic_array[i]->timestamp == timestamp) {
            free(dynamic_array[i]);
            memmove(dynamic_array + i, dynamic_array + i + 1, sizeof(LTE_Uplink_PDCP_PDU*) * (array_size - i - 1));
            array_size--;
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    pthread_mutex_unlock(&lock);
