    for (int i = 0; i < N; i++) {
        (*pList)[i].RX_UE_INFORMATION_TAG = rand() % 256;
        uint16_t rnti = rand();
        while (rnti <= 65535 && find_rnti_in_list(*pList, i)) {
            rnti = rand();
        }
        (*pList)[i].RNTI = rnti;

        do {
            (*pList)[i].CRCFLAG = rand() % 256;
        } while (find_CRCFLAG_in_list(*pList, i));

        if (!(*pList)) {
            printf("Error: Memory allocation failed.\n");
            return;
        }
    }
}

int find_rnti_in_list(NFAPI_CRC_INDICATION_PDU_T *list, int i) {
    for (int j = 0; j < i; j++) {
        if (list[j].RNTI == (*pList)[i].RNTI)
            return 1;
    }
    return 0;
}

