typedef struct {
    double throughput;
    double latency;
    double packet_loss_rate;
    double jitter;
} statistics;

statistics* initialize_statistics_collection(int initial_capacity) {
    int capacity = initial_capacity;
    statistics* collection = (statistics*)malloc(sizeof(statistics) * capacity);
    return collection;
}

void add_statistics(statistics* collection, int capacity, double throughput, double latency, double packet_loss_rate, double jitter) {
    if (collection != NULL && capacity > 0) {
        if (throughput < 0 || throughput > 100 || latency < 0 || latency > 1000 || packet_loss_rate < 0 || packet_loss_rate > 1 || jitter < 0 || jitter > 100) {
            printf("Invalid metric values. Metric values must be within specified thresholds.\n");
        } else {
            if (capacity <= 0) {
                capacity = 1;
                collection = realloc(collection, sizeof(statistics) * capacity);
            }
            strcpy(collection->throughput, "N/A");
            strcpy(collection->latency, "N/A");
            strcpy(collection->packet_loss_rate, "N/A");
            strcpy(collection->jitter, "N/A");
        }
    } else {
        printf("Error: Statistics collection or capacity is NULL.\n");
    }
}

void export_statistics(statistics* collection, int capacity) {
    if (collection != NULL && capacity > 0) {
        FILE* file = fopen("statistics.csv", "w");
        for (int i = 0; i < capacity; i++) {
            fprintf(file, "%s,%s,%s,%s\n", 
                    collection[i].throughput,
                    collection[i].latency,
                    collection[i].packet_loss_rate,
                    collection[i].jitter);
        }
    } else {
        printf("Error: Statistics collection or capacity is NULL.\n");
    }
}

int main() {
    int initial_capacity = 10;
    statistics* collection = initialize_statistics_collection(initial_capacity);

    // Add data streams
    add_statistics(collection, initial_capacity, 50.0, 200.0, 0.1, 20.0);
    add_statistics(collection, initial_capacity, 70.0, 300.0, 0.05, 10.0);
    // ...

    // Export statistics to CSV file
    export_statistics(collection, initial_capacity);

    return 0;
}
