    StreamingMediaRequest** requestsList = (StreamingMediaRequest**)malloc(10000 * sizeof(StreamingMediaRequest*));

    // Function to add a new request
    void* addRequest(void* data) {
        pthread_mutex_lock(mutex);
        int requestId = ((int*)data)[0];
        char mediaType[20] = {0};
        int clientConnectionId = ((int*)data)[1];
        int requestedBandwidth = ((int*)data)[2];
        int priorityLevel = ((int*)data)[3];

        // Allocate memory for the new request
        StreamingMediaRequest* request = (StreamingMediaRequest*)malloc(sizeof(StreamingMediaRequest));
        request->requestId = requestId;
        strcpy(request->mediaType, mediaType);
        request->clientConnectionId = clientConnectionId;
        request->requestedBandwidth = requestedBandwidth;
        request->priorityLevel = priorityLevel;

        // Add the new request to the list
        requestsList[(*requestsCount)++] = request;
        pthread_mutex_unlock(mutex);
    }

    // Function to process a request
    void* processRequest(void* data) {
        pthread_mutex_lock(mutex);
        int requestId = ((int*)data)[0];
        StreamingMediaRequest* request = NULL;

        for (int i = 0; i < *requestsCount; i++) {
            if (requestsList[i]->requestId == requestId) {
                request = requestsList[i];
                break;
            }
        }

        if (request != NULL) {
            // Process the request
            free(request);
        }

        pthread_mutex_unlock(mutex);
    }

    return NULL;
}
