}

int main(int argc, char** argv) {
    int i, event_count = 0;
    EVENT_RECORD_T *event_records = NULL;
    FILE *file_in = stdin;
    FILE *file_out = stdout;

    if (argc > 1) {
        file_in = fopen(argv[1], "r");
        if (!file_in) {
            fprintf(stderr, "Error opening input file\n");
            return -1;
        }
    }

    if (argc > 2) {
        file_out = fopen(argv[2], "w");
        if (!file_out) {
            fprintf(stderr, "Error opening output file\n");
            fclose(file_in);
            return -1;
        }
    }

    // parse command line arguments
    for (i = 0; i < argc; i++) {
        if (strcmp(argv[i], "-help") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-help] [input_file] [output_file]\n", argv[0]);
            return 0;
        }
    }

    // allocate memory for event records
    if ((event_records = (EVENT_RECORD_T*) malloc(MAX_EVENTS * sizeof(EVENT_RECORD_T))) == NULL) {
        fprintf(stderr, "Error allocating memory\n");
        fclose(file_in);
        fclose(file_out);
        return -1;
    }

    // handle events
    pthread_t thread[MAX_EVENTS];
    for (i = 0; i < MAX_EVENTS; i++) {
        if (pthread_create(&thread[i], NULL, handle_events, NULL) != 0) {
            fprintf(stderr, "Error creating thread\n");
            free(event_records);
            fclose(file_in);
            fclose(file_out);
            return -1;
        }
    }

    // wait for threads to finish
    for (i = 0; i < MAX_EVENTS; i++) {
        pthread_join(thread[i], NULL);
    }

    // release memory
    free(event_records);

    fclose(file_in);
    fclose(file_out);

    return 0;
}

