            line_count = count_lines(fp);
            fclose(fp);
        } else if (sscanf(argv[i], "-o %s", output_file) == 1) {
            strcpy(output_file, argv[i] + 2);
            has_output_file = 1;
        }
    }

    // process each input file
    for (i = 1; i < argc; i++) {
