            return 0;
        }
    }

    // write output to file or stdout
    if (has_output_file) {
        fp = fopen(output_file, "w");
        fprintf(fp, "Line count: %d\n", line_count);
        fclose(fp);
    } else {
        printf("Line count: %d\n", line_count);
    }

    return 0;
}

void display_manpage() {
    printf("Usage: program [options]\n");
    printf("-i <input_file> : Specifies an input file to be processed.\n");
    printf("--manpage : Displays detailed usage information.\n");
    printf("-cs : Checks the syntax of each line in the input file for common formatting errors and reports them.\n");
    printf("-o <output_file> : Specifies an output file to which the results of the line count and error reports should be written. If not specified, the results will be printed to the standard output.\n");
}

int count_lines(FILE *fp) {
    int line_count = 0;
    char line[1024];

    while (fgets(line, sizeof(line), fp)) {
        line_count++;
    }

    return line_count;
}
