        array[i].RNTI = rand() % 10000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000000;
        array[i].CRCFLAG = (i % 2) ? 1 : 0; // Set CRC flag to alternating pattern
    }

    if (validate_crc_flags(array, N)) {
        free(array); // Free memory in case of error
        return NULL;
    }

    return array;
}
