#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000
#define THRESHOLD 10

typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int max_inconsistencies = 0;
FILE *log_file = fopen("log.txt", "w");

void validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T **array, int n) {
    for (int i = 0; i < n; i++) {
        if ((i % 2 == 1 && array[i]->CRCFLAG == 1) || 
            (i % 2 == 0 && array[i]->CRCFLAG == 0)) {
            fprintf(log_file, "CRCFLAG inconsistency at index %d.\n", i);
            max_inconsistencies++;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T **manage_array(int *n) {
    NFAPI_CRC_INDICATION_PDU_T **array = NULL;
    int size = 0;

    while (1) {
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (size + THRESHOLD));
        if (!array) {
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        for (int i = size; i < size + THRESHOLD; i++) {
            array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            strcpy(array[i]->RX_UE_INFORMATION_TAG, "valid_tag");
            array[i]->RNTI = rand() % 100;
            strcpy(array[i]->CRC_INDICATION_REL8_TAG, "valid_tag");
            array[i]->CRCFLAG = (rand() % 2) ? 1 : 0;
        }

        size += THRESHOLD;

        if (*n <= size) {
            break;
        }
    }

    *n = size;
    return array;
}

void clear_array(NFAPI_CRC_INDICATION_PDU_T **array, int n) {
    for (int i = 0; i < n; i++) {
        free(array[i]);
    }
    free(array);
}

NFAPI_CRC_INDICATION_PDU_T **manage_array_resize(NFAPI_CRC_INDICATION_PDU_T **array, int *n, int new_size) {
    if (new_size > *n + THRESHOLD) {
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (new_size));
        if (!array) {
            fprintf(stderr, "Memory allocation failed.\n");
            return NULL;
        }

        for (int i = *n; i < new_size; i++) {
            array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            strcpy(array[i]->RX_UE_INFORMATION_TAG, "valid_tag");
            array[i]->RNTI = rand() % 100;
            strcpy(array[i]->CRC_INDICATION_REL8_TAG, "valid_tag");
            array[i]->CRCFLAG = (rand() % 2) ? 1 : 0;
        }

        *n = new_size;
    }
    return array;
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T **array = manage_array(&n);

    // Use the array...

    validate_crc_flags(array, n);
    if (max_inconsistencies > 0) {
        fprintf(log_file, "Total CRCFLAG inconsistencies: %d.\n", max_inconsistencies);
    }

    int new_size = 20;
    array = manage_array_resize(array, &n, new_size);

    // Use the resized array...

    clear_array(array, n);

    return 0;
}
