    size_t size;
    size_t capacity;
} DynamicLinkedList;

DynamicLinkedList* create_list() {
    return (DynamicLinkedList*)malloc(sizeof(DynamicLinkedList));
}

void delete_list(DynamicLinkedList* list) {
    free(list);
}

TCP_Segment* add_segment(DynamicLinkedList* list, TCP_Segment segment) {
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(TCP_Segment));
    }
    list->data[list->size++] = segment;
    return &list->data[list->size - 1];
}

TCP_Segment* get_segment(DynamicLinkedList* list, int seq_num) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].seq_num == seq_num) {
            return &list->data[i];
        }
    }
    return NULL;
}

void update_segment(DynamicLinkedList* list, int seq_num, time_t timestamp, int error_indication) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].seq_num == seq_num) {
            list->data[i].transmission_timestamp = timestamp;
            list->data[i].error_indication = error_indication;
            return;
        }
    }
}

void prune_list(DynamicLinkedList* list, time_t threshold_timestamp) {
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].transmission_timestamp < threshold_timestamp) {
            for (int j = i + 1; j < list->size; j++) {
                list->data[j - 1] = list->data[j];
            }
            list->size--;
            i--;
        }
    }
}

void check_bandwidth(DynamicLinkedList* list, size_t total_size) {
