void deviceManager() {
    // Initialize dynamic array of devices
    Device *devices = (Device *)malloc(MAX_DEVICES * sizeof(Device));
    for (int i = 0; i < MAX_DEVICES; i++) {
        strcpy(devices[i].status, "offline");
        devices[i].last_seen = 0;
        devices[i].bandwidth_usage = 0.0;
        strcpy(devices[i].metadata, "");
    }

    // Initialize priority queue
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Initialize concurrency control
    int available_devices = MAX_DEVICES;
    pthread_mutex_lock(&mutex);
    while (available_devices < CONCURRENCY_LIMIT) {
        pthread_cond_wait(&cond, &mutex);
        available_devices++;
    }
    pthread_mutex_unlock(&mutex);

    // Initialize periodic pruning mechanism
    time_t prune_time = 0;

    // Implement thread-safe periodic pruning
    pthread_mutex_lock(&mutex);
    while (1) {
        if (time(NULL) > prune_time) {
            prune_time += 60 * 10; // Prune every 10 minutes
            // Remove expired devices from the queue
            for (int i = 0; i < available_devices; i++) {
                if (devices[i].last_seen + (60 * 60 * 24 * 30) <= time(NULL)) { // 30 days
                    devices[i] = devices[--available_devices];
                }
