            // Try to reconnect devices that have failed to connect
            for (int i = 0; i < available_devices; i++) {
                if (!devices[i].status[0]) { // Device is not connected
                    // Perform exponential backoff and circuit breaker patterns
                    int attempts = 0;
                    while (attempts++ <= 3) {
                        if (connect_device(&devices[i])) {
                            break;
                        } else {
