    *logEntries = (LogEntry*)malloc(sizeof(LogEntry));
    *totalSize = sizeof(LogEntry);

    // Define some constants
    const int MAX_LOG_SIZE = 1024;
    const int MIN_METADATA_LENGTH = 10;
    const int MAX_METADATA_LENGTH = 1000;

    // Initialize counters and buffers
    int addedCount = 0;
    int updatedCount = 0;

    while (true) {
        // Add a log entry to the array if not full
        if (*totalSize + sizeof(LogEntry) <= *logCount * *totalSize) {
            LogEntry* newEntry = (LogEntry*)realloc(*logEntries, (*logCount + 1) * *totalSize);
            newEntry[*logCount].timestamp = time(NULL);
            printf("Enter log message: ");
            char input[1024];
