            processedMessage = result;

            if (strlen(processedMessage) > MAX_LOG_SIZE) {
                printf("Log message too long. Please try again.\n");
                continue;
            }

            // Store the log entry in the database and handle any connection issues
            void storeLogEntryInDB(LogEntry& entry);
            int status = storeLogEntryInDB(newEntry[*logCount]);
            if (status != 0) {
                printf("Failed to store log entry. Error code: %d\n", status);
                continue;
            }

