// Function to add a new TCP segment to the dynamic linked list
void addTCP_Segment(SegmentNode** headRef, SegmentNode* newNode) {
    if (*headRef == NULL || newNode->sequenceNumber < (*headRef)->sequenceNumber) {
        newNode->next = *headRef;
        *headRef = newNode;
    } else {
        SegmentNode* current = *headRef;
        while (current->next != NULL && current->next->sequenceNumber <= newNode->sequenceNumber) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to retrieve a TCP segment by its sequence number
SegmentNode* getTCP_Segment(SegmentNode* head, int sequenceNumber) {
    SegmentNode* current = head;
    while (current != NULL && current->sequenceNumber < sequenceNumber) {
        current = current->next;
    }
    return current == NULL || current->sequenceNumber == sequenceNumber ? current : NULL;
}

// Function to update the transmission timestamp and error indication for a given sequence number
void updateTCP_Segment(SegmentNode* head, int sequenceNumber, long newTimestamp, int newErrorIndication) {
    SegmentNode* segment = getTCP_Segment(head, sequenceNumber);
    if (segment != NULL) {
        segment->timestamp = newTimestamp;
        segment->errorIndication = newErrorIndication;
    }
}

