void pruneOldSegments(SegmentNode* head, long maxAllowedTransmissionTime) {
    SegmentNode* current = head;
    while (current != NULL) {
        if (current->timestamp + maxAllowedTransmissionTime < time(NULL)) {
            deallocate(current);
            current = current->next;
        } else {
            break;
        }
    }
