#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <vector>
#include <string>
#include <fstream>

class DynamicTaskManager {
public:
    DynamicTaskManager(size_t maxThreads) : poolSize(maxThreads), running(true) {}

    ~DynamicTaskManager() {
        stop();
    }

    void start() {
        for (size_t i = 0; i < poolSize; ++i) {
            threads.emplace_back([this] { run(); });
        }
    }

    template<typename Func, typename... Args>
    void submit(Func f, Args... args) {
        auto task = [f, args...]() {
            f(std::forward<Args>(args)...);
        };
        tasks.push(task);
    }

    void stop() {
        running = false;
        condition.notify_all();
        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

private:
    std::vector<std::thread> threads;
    std::queue<std::function<void()>> tasks;
    size_t poolSize;
    bool running;

    void run() {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !tasks.empty() || !running; });
            if (!tasks.empty()) {
                auto task = std::move(tasks.front());
                tasks.pop();
                lock.unlock();
                try {
                    task();
                } catch (...) {
                    // handle exceptions
                }
            }
        }
    }

    std::mutex mutex;
    std::condition_variable condition;
};

