        switch (action) {
            case 1:
                // Add a new log entry
                LogEntry* newEntry = (LogEntry*)malloc(sizeof(LogEntry));
                printf("Enter the timestamp: ");
                scanf("%s", newEntry->timestamp);
                printf("Enter the severity level: ");
                scanf("%d", &newEntry->severityLevel);
                printf("Enter the message: ");
