                // Log the entry's ID and the action taken (success/failure)
                printf("Log entry added successfully.\n");

                totalEntriesAdded++;
                free(newEntry);
                break;

            case 2:
                // Retrieve a specific log entry by its unique ID
                int id;
                scanf("%d", &id);

                // Check if the buffer has reached its capacity and handle this case appropriately
                if (bufferOccupancy >= bufferSize) {
                    printf("Buffer full. Please wait for available space.\n");
                    continue;
                }

                // Retrieve the log entry from the array based on its ID
                LogEntry* retrievedEntry = &buffer[id];
                printf("Timestamp: %s\n", retrievedEntry->timestamp);
                printf("Severity level: %d\n", retrievedEntry->severityLevel);
                printf("Message: %s\n", retrievedEntry->message);

                break;

            case 3:
                // Update the severity level for a given ID
                int idToUpdate;
                scanf("%d", &idToUpdate);

                if (idToUpdate < 0 || idToUpdate >= bufferOccupancy) {
                    printf("Invalid ID. Please enter a valid ID.\n");
                    continue;
                }

                LogEntry* entryToUpdate = &buffer[idToUpdate];
                printf("Enter the new severity level: ");
                int newSeverityLevel;
                scanf("%d", &newSeverityLevel);
                entryToUpdate->severityLevel = newSeverityLevel;

                updatesMade++;
                break;

            case 4:
                // Remove a log entry from the array based on its ID
                int idToRemove;
                scanf("%d", &idToRemove);

                if (idToRemove < 0 || idToRemove >= bufferOccupancy) {
                    printf("Invalid ID. Please enter a valid ID.\n");
                    continue;
                }

                // Free memory for the removed log entry
                free(&buffer[idToRemove]);
                buffer[idToRemove].timestamp[0] = '\0';
                buffer[idToRemove].message[0] = '\0';

                updatesMade++;
                break;

            default:
                printf("Invalid action. Please enter a valid action.\n");
                continue;
        }
    }

    // Free dynamically allocated memory
    for (int i = 0; i < bufferOccupancy; i++) {
        free(&buffer[i]);
