#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <random>

#define MAX_ENTRIES 1000
#define TABLE_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int hash(int key) {
    return key % TABLE_SIZE;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T **list, int *size, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (*size >= MAX_ENTRIES) {
        printf("Error: List is full.\n");
        return;
    }
    for (int i = 0; i < *size; i++) {
        if (((*list)[i]).RNTI == entry->RNTI) {
            printf("Error: Duplicate RNTI detected.\n");
            return;
        }
    }
    (*list) = realloc((*list), (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    (*list)[*size] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&((*list)[*size]), entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*size)++;
}

void remove_entry(NFAPI_CRC_INDICATION_PDU_T **list, int *size) {
    if (*size > 0) {
        free((*list)[(*size) - 1]);
    }
    (*list) = realloc((*list), (*size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    (*size]--;
}

void print_list(NFAPI_CRC_INDICATION_PDU_T **list, int size) {
    for (int i = 0; i < size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               (*list)[i]->RX_UE_INFORMATION_TAG,
               (*list)[i]->RNTI,
               (*list)[i]->CRC_INDICATION_REL8_TAG,
               (*list)[i]->CRCFLAG);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int size = 0;

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, TABLE_SIZE);

    for (int i = 0; i < 10; i++) {
        int RNTI = distribution(generator);
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        entry->RX_UE_INFORMATION_TAG = rand() % TABLE_SIZE;
        entry->RNTI = RNTI;
        entry->CRC_INDICATION_REL8_TAG = rand() % TABLE_SIZE;
        entry->CRCFLAG = rand() % 2;
        add_entry(&list, &size, entry);
    }

    print_list(&list, size);

    for (int i = 0; i < size; i++) {
        remove_entry(&list, &size);
    }

    return 0;
}

