// Define the dynamic array of PDU structures
typedef struct {
    LTE_Uplink_PDCP_PDU* PDUs;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
    int successful_PDUs;
    int failed_PDUs;
} LTE_Uplink_PDCP_PDU_Array;

// Function to initialize and manage the dynamic array of PDU structures
LTE_Uplink_PDCP_PDU_Array* lte_uplink_pdcps_init(size_t initial_capacity) {
    LTE_Uplink_PDCP_PDU_Array* array = (LTE_Uplink_PDCP_PDU_Array*)malloc(sizeof(LTE_Uplink_PDCP_PDU_Array));
    if (!array) return NULL;

    array->PDUs = (LTE_Uplink_PDCP_PDU*)calloc(initial_capacity, sizeof(LTE_Uplink_PDCP_PDU));
    array->capacity = initial_capacity;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->successful_PDUs = 0;
    array->failed_PDUs = 0;

    return array;
}

// Function to add a new PDU to the dynamic array
int lte_uplink_pdcps_add(LTE_Uplink_PDCP_PDU_Array* array, LTE_Uplink_PDCP_PDU pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->length >= array->capacity) {
        // Reallocate the array with double capacity
        array->PDUs = (LTE_Uplink_PDCP_PDU*)realloc(array->PDUs, 2 * array->capacity * sizeof(LTE_Uplink_PDCP_PDU));
        array->capacity *= 2;
    }

    array->PDUs[array->length++] = pdu;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* lte_uplink_pdcps_get(LTE_Uplink_PDCP_PDU_Array* array, int SN) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->length; i++) {
        if (array->PDUs[i].SN == SN) {
            pthread_mutex_unlock(&array->mutex);
            return &array->PDUs[i];
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return NULL;
}

// Function to update the error indication for a given sequence number
int lte_uplink_pdcps_update_error(LTE_Uplink_PDCP_PDU_Array* array, int SN) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->length; i++) {
        if (array->PDUs[i].SN == SN) {
            array->PDUs[i].error_indication = 1;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return -1;
}

