#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for LTE uplink PDCP PDUs
typedef struct {
    int sequenceNumber;
    int sdusize;
    int errorIndication;
} LTE_Uplink_PDCP_PDU;

// Define a structure to hold the dynamic array of PDU structures
typedef struct {
    LTE_Uplink_PDCP_PDU* pdus;
    int size;
    int capacity;
    clock_t maxAge;
    int ageThreshold;
    int numActivePdus;
} PdcpArray;

// Function to initialize and manage a dynamic array of PDU structures
PdcpArray* pdcpArrayCreate(int capacity, int maxAge) {
    PdcpArray* array = (PdcpArray*)malloc(sizeof(PdcpArray));
    array->pdus = (LTE_Uplink_PDCP_PDU*)calloc(capacity, sizeof(LTE_Uplink_PDCP_PDU));
    array->size = 0;
    array->capacity = capacity;
    array->maxAge = maxAge;
    array->ageThreshold = clock();
    array->numActivePdus = 0;
    return array;
}

// Function to add a new PDU to the dynamic array
int pdcpArrayAdd(PdcpArray* array, LTE_Uplink_PDCP_PDU pdu) {
    if (array->size == array->capacity) {
        // Array is full, need to reallocate and copy existing PDUs
        array->capacity *= 2;
        array->pdus = (LTE_Uplink_PDCP_PDU*)realloc(array->pdus, sizeof(LTE_Uplink_PDCP_PDU) * array->capacity);
    }
    array->pdus[array->size++] = pdu;
    return 0;
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* pdcpArrayGet(PdcpArray* array, int sequenceNumber) {
    for (int i = 0; i < array->size; i++) {
        if (array->pdus[i].sequenceNumber == sequenceNumber) {
            return &array->pdus[i];
        }
    }
    return NULL;
}

// Function to update the error indication for a given SN
int pdcpArrayUpdateError(PdcpArray* array, int sequenceNumber, int errorIndication) {
    LTE_Uplink_PDCP_PDU* pdu = pdcpArrayGet(array, sequenceNumber);
    if (pdu != NULL) {
        pdu->errorIndication = errorIndication;
        return 0;
    }
    return -1; // PDU not found
}

// Function to remove PDUs older than the maximum age threshold
int pdcpArrayRemoveOldPdus(PdcpArray* array) {
    clock_t now = clock();
    for (int i = 0; i < array->size; i++) {
        if ((now - array->pdus[i].sequenceNumber) > array->maxAge) {
            // PDU is older than max age, remove it
            free(&array->pdus[i]);
            memmove(&array->pdus[i], &array->pdus[i + 1], sizeof(LTE_Uplink_PDCP_PDU) * (array->size - i));
            array->size--;
        }
    }
    return 0;
}

// Function to retrieve the total number of active PDUs
int pdcpArrayGetNumActivePdus(PdcpArray* array) {
    int num = 0;
    for (int i = 0; i < array->size; i++) {
        if ((clock() - array->pdus[i].sequenceNumber) <= array->maxAge) {
            num++;
        }
    }
    return num;
}

// Function to serialize the PDU array to disk
void pdcpArraySerialize(PdcpArray* array, FILE* file) {
    fwrite(&array->size, sizeof(int), 1, file);
    for (int i = 0; i < array->size; i++) {
        fwrite(&array->pdus[i], sizeof(LTE_Uplink_PDCP_PDU), 1, file);
    }
}

// Function to deserialize the PDU array from disk
PdcpArray* pdcpArrayDeserialize(FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);
    PdcpArray* array = (PdcpArray*)malloc(sizeof(PdcpArray));
    array->pdus = (LTE_Uplink_PDCP_PDU*)calloc(size, sizeof(LTE_Uplink_PDCP_PDU));
    fread(array->pdus, sizeof(LTE_Uplink_PDCP_PDU), size, file);
    array->size = size;
    return array;
}

// Example usage
int main() {
    PdcpArray* array = pdcpArrayCreate(10, 300); // Create an array with capacity 10 and max age 300

    LTE_Uplink_PDCP_PDU pdu1 = {1234, 100, 0};
    pdcpArrayAdd(array, pdu1);

    LTE_Uplink_PDCP_PDU pdu2 = {5678, 200, 0};
    pdcpArrayAdd(array, pdu2);

    // ...
    return 0;
}
