#include <stdlib.h>
#include <pthread.h>

struct LTE_Uplink_PDCP_PDU {
    int SN;
    size_t SDU_size;
    int error_indication;
};

typedef struct {
    struct LTE_Uplink_PDCP_PDU* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PDCP_Array;

PDCP_Array pdcps = {
    .pdus = NULL,
    .capacity = 0,
    .size = 0,
    .mutex = PTHREAD_MUTEX_INITIALIZER,
    .cond = PTHREAD_COND_INITIALIZER
};

void* pdcp_array_init(size_t initial_capacity) {
    pdcps.capacity = initial_capacity;
    pdcps.pdus = (struct LTE_Uplink_PDCP_PDU*)malloc(pdcps.capacity * sizeof(struct LTE_Uplink_PDCP_PDU));
    return &pdcps;
}

void pdcp_array_add(PDCP_Array* pdcps, int SN, size_t SDU_size) {
    pthread_mutex_lock(&pdcps->mutex);

    if (pdcps->size == pdcps->capacity) {
        pdcps->capacity *= 2;
        pdcps->pdus = (struct LTE_Uplink_PDCP_PDU*)realloc(pdcps->pdus, pdcps->capacity * sizeof(struct LTE_Uplink_PDCP_PDU));
    }

    struct LTE_Uplink_PDCP_PDU* new_pdu = &pdcps->pdus[pdcps->size++];
    new_pdu->SN = SN;
    new_pdu->SDU_size = SDU_size;
    new_pdu->error_indication = 0;

    pthread_mutex_unlock(&pdcps->mutex);
}

struct LTE_Uplink_PDCP_PDU* pdcp_array_get(PDCP_Array* pdcps, int SN) {
    pthread_mutex_lock(&pdcps->mutex);

    for (int i = 0; i < pdcps->size; i++) {
        if (pdcps->pdus[i].SN == SN) {
            struct LTE_Uplink_PDCP_PDU* pdu = &pdcps->pdus[i];
            pthread_mutex_unlock(&pdcps->mutex);
            return pdu;
        }
    }

    pthread_mutex_unlock(&pdcps->mutex);
    return NULL;
}

void pdcp_array_update_error(PDCP_Array* pdcps, int SN) {
    pthread_mutex_lock(&pdcps->mutex);

    for (int i = 0; i < pdcps->size; i++) {
        if (pdcps->pdus[i].SN == SN) {
            pdcps->pdus[i].error_indication = 1;
            break;
        }
    }

    pthread_mutex_unlock(&pdcps->mutex);
}

int main() {
    // Example usage
    PDCP_Array* pdcps = (PDCP_Array*)pdcp_array_init(10);

    pdcp_array_add(pdcps, 1, 100);
    pdcp_array_add(pdcps, 2, 200);

    struct LTE_Uplink_PDCP_PDU* pdu = pdcp_array_get(pdcps, 2);
    if (pdu) {
        printf("SN: %d, SDU_size: %zu, error_indication: %d\n", pdu->SN, pdu->SDU_size, pdu->error_indication);
    }

    pdcp_array_update_error(pdcps, 1);

    return 0;
}
