function fetchUserData(userId) {
  const API_URL = 'https://api.example.com/users';
  const LOGGING_SERVICE_URL = 'https://logging-service.example.com/logs';

  async function getUserData() {
    try {
      const response = await fetch(`${API_URL}/${userId}`);
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      return await response.json();
    } catch (error) {
      console.error('Error fetching user data:', error);
      return null;
    }
  }

  async function logRequest Details(requestId, url, method, data) {
    try {
      const response = await fetch(LOGGING_SERVICE_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ requestId, url, method, data }),
      });
      if (!response.ok) console.error('Error logging request details:', response.status);
    } catch (error) {
      console.error('Error logging request details:', error);
    }
  }

  async function cacheUser(data, userId) {
    try {
      const cachedData = await localStorage.getItem(`user-data-${userId}`);
      if (cachedData) return JSON.parse(cachedData);
      return data;
    } catch (error) {
      console.error('Error caching user data:', error);
      return null;
    }
  }

  async function displayUserData(data, userId) {
    const cachedData = await cacheUser(data, userId);
    if (cachedData) document.getElementById(`user-data-${userId}`).innerHTML = JSON.stringify(cachedData);
  }

  async function main(userId) {
    try {
      const data = await getUserData();
      if (!data) return;
      logRequestDetails('fetch', API_URL + '/' + userId, null);
      displayUserData(data, userId);
    } catch (error) {
      console.error('Error in main:', error);
    }
  }

  main(userId);
