    pdus = (Mobile_Radio_Network_PDU**)malloc(1 * sizeof(Mobile_Radio_Network_PDU*));
    pdus[0] = NULL;
    pdus_size = 1;
}

void add_pdu(int id, time_t timestamp, time_t validity_period) {
    if (id < next_id - 1) {
        for (int i = 0; i < pdus_size; i++) {
            if (pdus[i]->id == id) {
                printf("PDU already exists\n");
                return;
            }
        }
