    new_pdu->id = id;
    new_pdu->timestamp = timestamp;
    new_pdu->validity_period = validity_period;
    new_pdu->status = 0;

    Mobile_Radio_Network_PDU** temp = (Mobile_Radio_Network_PDU**)malloc((pdus_size + 1) * sizeof(Mobile_Radio_Network_PDU*));
    for (int i = 0; i < pdus_size; i++) {
        temp[i] = pdus[i];
    }
    temp[pdus_size++] = new_pdu;
    free(pdus);
    pdus = temp;

    if (id >= next_id) {
        next_id = id + 1;
    }
}

