    } else {
        printf("PDU not found\n");
    }
}

void expire_pdus() {
    for (int i = 0; i < pdus_size; i++) {
        time_t current_time = time(NULL);
        if ((current_time - pdus[i]->timestamp) >= pdus[i]->validity_period) {
            free(pdus[i]);
            for (int j = i + 1; j < pdus_size; j++) {
                pdus[j - 1] = pdus[j];
            }
            pdus_size--;
            i--;
        }
    }
}

void purge_expired_pdus() {
    expire_pdus();
    int new_size = 0;
    for (int i = 0; i < pdus_size; i++) {
        if ((time(NULL) - pdus[i]->timestamp) < pdus[i]->validity_period) {
            new_size++;
        }
    }
    Mobile_Radio_Network_PDU** temp = (Mobile_Radio_Network_PDU**)malloc(new_size * sizeof(Mobile_Radio_Network_PDU*));
    int j = 0;
    for (int i = 0; i < pdus_size; i++) {
        if ((time(NULL) - pdus[i]->timestamp) < pdus[i]->validity_period) {
            temp[j++] = pdus[i];
        }
    }
    free(pdus);
    pdus = temp;
    pdus_size = new_size;
