Mobile_Radio_Network_PDU* pdu_array = NULL;
int pdu_count = 0;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t array_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t array_ready = PTHREAD_COND_INITIALIZER;
pthread_t expiry_thread;

void* expiry_function(void* arg) {
    while(1) {
        pthread_mutex_lock(&array_lock);
        while(pdu_count == 0 || !pthread_trylock(&array_not_empty)) {
            pthread_cond_wait(&array_ready, &array_not_empty);
        }
        for(int i = 0; i < pdu_count; i++) {
            if((time(NULL) - pdu_array[i].timestamp) > pdu_array[i].validity) {
                free(pdu_array[i].id);
                memmove(&pdu_array[i], &pdu_array[i+1], (pdu_count - i - 1) * sizeof(Mobile_Radio_Network_PDU));
                pdu_count--;
                i--;
            }
        }
        pthread_mutex_unlock(&array_lock);
        pthread_cond_broadcast(&array_not_empty);
    }
}

void add_pdu(int id, time_t timestamp, time_t validity) {
