    new_pdu->id = id;
    new_pdu->timestamp = timestamp;
    new_pdu->validity = validity;
    new_pdu->processed = 0;
    memmove(&pdu_array[pdu_count], &new_pdu, sizeof(Mobile_Radio_Network_PDU));
    pdu_count++;
    pthread_cond_signal(&array_not_empty);
    pthread_mutex_unlock(&array_lock);
}

Mobile_Radio_Network_PDU* get_pdu(int id) {
    for(int i = 0; i < pdu_count; i++) {
        if(pdu_array[i].id == id) {
            return &pdu_array[i];
        }
    }
    return NULL;
}

