        if ((new_pdu = (LTE_Uplink_PDCP_PDU *)malloc(sizeof(LTE_Uplink_PDCP_PDU))) == NULL) {
            printf("Out of memory\n");
            return;
        }

        // Initialize the new PDU with default values and track its age and removal status
