        new_pdu->SDU_Size = -1;
        new_pdu->Error_Indication = -1;
        new_pdu->Last_Accessed = time(NULL);

        // Add the new PDU to the array and update its age tracking metadata
        if (*array_size >= sizeof(LTE_Uplink_PDCP_PDU) * 100000) {
            printf("Array full. Cannot add more PDUs.\n");
            return;
        }

        for (int i = *array_size; i > 0; i--) {
            pdu_array[i - 1] = pdu_array[i - 2];
