    LTE_Uplink_PDCP_PDU *get_pdu_by_seq(LTE_Uplink_PDCP_PDU **pdu_array, int *array_size, int seq_num) {
        for (int i = 0; i < *array_size; i++) {
            if (pdu_array[i]->PDCP_SeqNum == seq_num) {
                return pdu_array[i];
            }
        }

        // Log the retrieval operation with a warning message
        log_operation("Could not find PDU with sequence number %d", seq_num);

        return NULL;
    }

