    // Function to mark PDUs for removal if they exceed the maximum age
    void remove_old_PDUs(LTE_Uplink_PDCP_PDU **pdu_array, int *array_size) {
        time_t current_time = time(NULL);

        for (int i = 0; i < *array_size; i++) {
            PDU_Meta meta;

            meta.Last_Accessed = pdu_array[i]->Last_Accessed;
            meta.Removed = pdu_array[i]->Removed;

            if ((meta.Last_Accessed + MAX_AGE) <= current_time && !meta.Removed) {
                // Mark the PDU for removal
                pdu_array[i]->Removed = 1;
