#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure to store LTE uplink PDCP PDUs
typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

// Define a global cache of previously used sequence numbers
static int* used_SNs = NULL;
static int num_used_SNs = 0;
static int max_used_SNs = 1000; // Initialize with a reasonable default size

// Function to generate a unique PDCP Sequence Number (SN)
int generate_unique_SN(int truncated_SN) {
    time_t current_time = time(NULL);
    int timestamp = (int)current_time % max_used_SNs;

    // Combine the truncated SN and timestamp
    int new_SN = truncated_SN + timestamp;

    // Check for collisions in the global cache
    for (int i = 0; i < num_used_SNs; i++) {
        if (used_SNs[i] == new_SN) {
            return generate_unique_SN(truncated_SN); // Retry allocation
        }
    }

    // If no collision is found, return the generated SN
    return new_SN;
}

// Function to initialize and manage a dynamic array of LTE uplink PDCP PDUs
LTE_Uplink_PDCP_PDU* init_and_manage_PDCPs(int initial_capacity) {
    LTE_Uplink_PDCP_PDU* pdcps = (LTE_Uplink_PDCP_PDU*)malloc(initial_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    if (!pdcps) {
        return NULL; // Handle out-of-memory condition
    }

    used_SNs = (int*)malloc(max_used_SNs * sizeof(int));
    num_used_SNs = 0;

    return pdcps;
}

// Function to add a new PDCP PDU to the array, ensuring uniqueness of the sequence number
void add_PDCP(LTE_Uplink_PDCP_PDU* pdcps, int initial_capacity, LTE_Uplink_PDCP_PDU new_pdcp) {
    int truncated_SN = new_pdcp.SN % max_used_SNs;

    // Generate a unique sequence number
    int SN = generate_unique_SN(truncated_SN);
    new_pdcp.SN = SN;

    // Add the PDU to the array, resizing if necessary
    int current_capacity = initial_capacity;
    for (int i = 0; i < current_capacity; i++) {
        if (!pdcps[i].SN) {
            pdcps[i] = new_pdcp;
            return;
        }
    }

    // Resize the array and add the PDU
    int new_capacity = current_capacity * 2 + 1;
    LTE_Uplink_PDCP_PDU* new_pdcps = (LTE_Uplink_PDCP_PDU*)realloc(pdcps, new_capacity * sizeof(LTE_Uplink_PDCP_PDU));
    if (!new_pdcps) {
        // Handle out-of-memory condition
        return;
    }

    pdcps = new_pdcps;

    // Add the PDU to the array and update the cache
    int* new_used_SNs = (int*)realloc(used_SNs, max_used_SNs * sizeof(int));
    num_used_SNs++;
    used_SNs = new_used_SNs;
}

// Function to retrieve a specific PDCP PDU by its sequence number
LTE_Uplink_PDCP_PDU* get_PDCP(LTE_Uplink_PDCP_PDU* pdcps, int capacity, int SN) {
    for (int i = 0; i < capacity; i++) {
        if (pdcps[i].SN == SN) {
            return &pdcps[i];
        }
    }

    return NULL;
}

// Function to update the error indication for a given sequence number
void update_error_indication(LTE_Uplink_PDCP_PDU* pdcps, int capacity, int SN, int new_error_indication) {
    for (int i = 0; i < capacity; i++) {
        if (pdcps[i].SN == SN) {
            pdcps[i].error_indication = new_error_indication;
            return;
        }
    }
}

// Function to update the error indication and log a message in case of collision
void update_and_log_error_indication(LTE_Uplink_PDCP_PDU* pdcps, int capacity, int SN, int new_error_indication) {
    LTE_Uplink_PDCP_PDU* pdcp = get_PDCP(pdcps, capacity, SN);
    if (!pdcp) {
        // Log a message in case of collision
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Collision detected for sequence number %d", SN);
        va_list ap;
        va_start(ap, log_message);
        vprintf(log_message, &ap);
        va_end(ap);

        // Update the error indication without logging
        update_error_indication(pdcps, capacity, SN, new_error_indication);
    } else {
        pdcp->error_indication = new_error_indication;
    }
}
