    size_t sdu_size;
    char error_indication;
} LTE_Uplink_PDCP_PDU;

// Function to manage dynamic array of LTE Uplink PDCP PDUs
void* lte_pdcp_pdu_manager(int** sn_cache, size_t max_sn_length) {
    // Initialize global SN cache and current timestamp
    *sn_cache = malloc(sizeof(int) * (max_sn_length + 1));
    int current_timestamp = time(NULL);

    while (1) {
        // Generate a new sequence number with a unique combination of timestamp and incrementing value
        int pdcp_sequence_number = ((current_timestamp << 10) | (*sn_cache)[0])++;

        // Check for collisions in the SN cache
        int i;
        for (i = 1; i <= max_sn_length && (*sn_cache)[i] < pdcp_sequence_number; i++) {
            if ((*sn_cache)[i] == pdcp_sequence_number) {
                break;
            }
        }

        // If a collision is detected, retry allocation
        if (i <= max_sn_length) {
            continue;
        }

        // Update the SN cache with the new sequence number
        for (int j = max_sn_length; j > 0; j--) {
            (*sn_cache)[j] = (*sn_cache)[j - 1];
        }
        (*sn_cache)[0] = pdcp_sequence_number;

        // Initialize a new PDU structure with the generated SN and default values
        LTE_Uplink_PDCP_PDU* pdu = malloc(sizeof(LTE_Uplink_PDCP_PDU));
        pdu->pdcp_sequence_number = pdcp_sequence_number;
        pdu->sdu_size = 0;
        pdu->error_indication = 0;

        // Return the newly allocated PDU and updated SN cache
        return (void*)pdu;
    }
}

// Function to retrieve a specific PDU by its sequence number
LTE_Uplink_PDCP_PDU* lte_pdcp_pdu_retrieve(int pdcp_sequence_number, int** sn_cache) {
    // Iterate through the SN cache and find the specified sequence number
    int i;
    for (i = 0; ; i++) {
        if ((*sn_cache)[i] == pdcp_sequence_number) {
            break;
        }
    }

    // If the sequence number is not found, return NULL
    if (i >= (*sn_cache)[max_sn_length]) {
        return NULL;
    }

    // Find and return the corresponding PDU structure
    for (int j = 0; ; j++) {
        if (((LTE_Uplink_PDCP_PDU*)j)->pdcp_sequence_number == pdcp_sequence_number) {
            return &((LTE_Uplink_PDCP_PDU*)j)[i];
        }
    }
}

// Function to update the error indication for a given sequence number
void lte_pdcp_pdu_update_error(int pdcp_sequence_number, int** sn_cache) {
    // Find the specified sequence number in the SN cache
    int i;
    for (i = 0; ; i++) {
        if ((*sn_cache)[i] == pdcp_sequence_number) {
            break;
        }
    }

    // If the sequence number is not found, return
    if (i >= (*sn_cache)[max_sn_length]) {
        return;
    }

    // Find and update the corresponding PDU structure
    for (int j = 0; ; j++) {
        if (((LTE_Uplink_PDCP_PDU*)j)->pdcp_sequence_number == pdcp_sequence_number) {
            ((LTE_Uplink_PDCP_PDU*)j)->error_indication++;
            return;
        }
    }
}

// Function to free the memory allocated for PDU structures and SN cache
void lte_pdcp_pdu_free(int** sn_cache, LTE_Uplink_PDCP_PDU* pdu) {
    // Free the PDU structure memory
    free(pdu);

    // Free the SN cache memory
    free(*sn_cache);
}

int main() {
    int* sn_cache;
    lte_pdcp_pdu_manager(&sn_cache, 1024);

    LTE_Uplink_PDCP_PDU* pdu = (LTE_Uplink_PDCP_PDU*)lte_pdcp_pdu_manager(&sn_cache, 1024);
    printf("Sequence Number: %d\nSDU Size: %zu\nError Indication: %c\n", pdu->pdcp_sequence_number, pdu->sdu_size, pdu->error_indication);

