CustomHashTable* init_hash_table() {
    CustomHashTable* hash_table = (CustomHashTable*)malloc(sizeof(CustomHashTable));
    hash_table->size = TABLE_SIZE;
    hash_table->table = (User**)malloc(TABLE_SIZE * sizeof(User*));
    for(int i=0; i<TABLE_SIZE; i++) {
        hash_table->table[i] = NULL;
    }
    return hash_table;
}

int hash_function(char* key, int size) {
    int hash = 0;
    for(int i=0; i<strlen(key); i++) {
        hash = (hash << 4) ^ (hash >> 3) ^ key[i];
    }
    return hash % size;
}

void insert_hash_table(CustomHashTable* table, char* key, User* user) {
    int index = hash_function(key, table->size);
    while(table->table[index] != NULL && strcmp(key, ((User*)table->table[index])->name) != 0) {
        index = (index + 1) % table->size;
    }
    table->table[index] = user;
}

