// Structure to hold the memory pool information
typedef struct {
    void **pool;
    size_t capacity;
    pthread_mutex_t mutex;
} MEMORY_POOL;

MEMORY_POOL *memory_pool_create(size_t initial_capacity) {
    MEMORY_POOL *pool = (MEMORY_POOL *)malloc(sizeof(MEMORY_POOL));
    if (!pool) return NULL;

    pool->pool = (void **)calloc(initial_capacity, sizeof(void *));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void memory_pool_free(MEMORY_POOL *pool) {
    if (pool) {
        for (size_t i = 0; i < pool->capacity; i++) {
            free((void *)pool->pool[i]);
        }
        free(pool->pool);
        free(pool);
        pthread_mutex_destroy(&pool->mutex);
    }
}

LTE_ENB_S1AP_PDU_T_DATA *allocate_structure(MEMORY_POOL *pool) {
    if (!pool) return NULL;

    for (size_t i = 0; i < pool->capacity; i++) {
        if (pool->pool[i] == NULL) {
            LTE_ENB_S1AP_PDU_T_DATA *new_data = (LTE_ENB_S1AP_PDU_T_DATA *)malloc(sizeof(LTE_ENB_S1AP_PDU_T_DATA));
            if (!new_data) return NULL;

            pool->pool[i] = (void *)new_data;
            return new_data;
        }
    }

    // Resize the memory pool if necessary
    size_t new_capacity = pool->capacity * 2;
    MEMORY_POOL *new_pool = memory_pool_create(new_capacity);
    if (!new_pool) return NULL;

    for (size_t i = 0; i < pool->capacity; i++) {
        new_pool->pool[i] = pool->pool[i];
    }

    memory_pool_free(pool);

    return (LTE_ENB_S1AP_PDU_T_DATA *)new_pool->pool[pool->capacity - 1];
}

void deallocate_structure(LTE_ENB_S1AP_PDU_T_DATA *data, MEMORY_POOL *pool) {
    if (!data || !pool) return;

    for (size_t i = 0; i < pool->capacity; i++) {
        if ((void *)data == pool->pool[i]) {
            free((void *)data);
            pool->pool[i] = NULL;
            return;
        }
    }

    // If the data is not found in the current memory pool, try to find it in the resized pool
    MEMORY_POOL *new_pool = (MEMORY_POOL *)malloc(sizeof(MEMORY_POOL));
    if (!new_pool) return;

    for (size_t i = 0; i < new_pool->capacity; i++) {
        if ((void *)data == new_pool->pool[i]) {
            free((void *)data);
            new_pool->pool[i] = NULL;
            memory_pool_free(new_pool);
            memory_pool_free(pool);
            return;
        }
    }

    // If the data is not found in any of the pools, it means that the deallocation failed
    if (new_pool) {
        free(new_pool);
    }
}

int main() {
    // Initialize the logging mechanism here

    // Initialize the memory pool here
    MEMORY_POOL *pool = memory_pool_create(10);

