void manageFileAndSN(LTE_Uplink_PDCP_PDU *pdu, char *filename) {
    static int global_sn = 0;
    static pthread_mutex_t sn_mutex = PTHREAD_MUTEX_INITIALIZER;
    static char *sn_cache[1024];
    int i, collision = 0;

    // Generate a new SN with timestamp component
    time_t now = time(NULL);
    int ts = (int)now % 10000; // Ensure uniqueness within the current second

    pthread_mutex_lock(&sn_mutex);
    for (i = 0; i < 1024; i++) {
        if (!sn_cache[i]) {
            global_sn++;
            pdu->PDCP_Seq_Num = global_sn;
            sn_cache[i] = malloc(strlen(filename) + 1);
            strcpy(sn_cache[i], filename);
            break;
        } else if (collision == 0 && !strcmp(filename, sn_cache[i])) {
            collision = 1; // SN collision detected
        }
    }

    pthread_mutex_unlock(&sn_mutex);

    // If a collision is detected, retry allocation until a unique SN is found
    while (collision) {
        pdu->PDCP_Seq_Num++;
        for (i = 0; i < 1024; i++) {
            if (!sn_cache[i]) {
                global_sn++;
                pdu->PDCP_Seq_Num = global_sn;
                sn_cache[i] = malloc(strlen(filename) + 1);
                strcpy(sn_cache[i], filename);
                break;
            } else if (collision == 0 && !strcmp(filename, sn_cache[i])) {
                collision = 1; // SN collision detected
            }
        }
    }

    // Update error indication field and SDU size as needed
    pdu->Error_Indication = ...;
    pdu->SDU_Size = ...;

    // Log SN allocation conflicts (optional)
    if (collision) {
        printf("SN conflict: '%s' with sequence number %d\n", filename, pdu->PDCP_Seq_Num);
    }
}

int main() {
    LTE_Uplink_PDCP_PDU pdu;
    manageFileAndSN(&pdu, "example.txt");
    return 0;
}
