import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class FileManagement {

    public static String generateMD5Hash(String filename) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = filename.getBytes();
            byte[] hashBytes = md.digest(bytes);
            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < hashBytes.length; i++) {
                String hex = Integer.toHexString(0xff & hashBytes[i]);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public static int countDigits(String filename) {
        int count = 0;
        for (char c : filename.toCharArray()) {
            if (Character.isDigit(c)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String filename = "example.txt";
        System.out.println("MD5 hash: " + generateMD5Hash(filename));
        int digitCount = countDigits(filename);
        System.out.println("Number of digits in the filename: " + digitCount);
    }
}
