// Define structures
typedef struct {
    int timestamp;
    char metadata[256];
} AudioStreamFrame;

typedef struct {
    int timestamp;
    int measurementValue;
} UeMeasurementReport;

// Function to manage the dynamic linked list and array
void* audioProcessingFunction(void* data) {
    // Initialize variables
    AudioStreamFrame* frames = NULL;
    UeMeasurementReport* reports = NULL;
    size_t frameCount = 0;
    size_t reportCount = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Function to add a new audio stream frame and measurement report
    void addFrameAndReport(int timestamp, char metadata[], int measurementValue) {
        pthread_mutex_lock(&lock);

        AudioStreamFrame* newFrame = (AudioStreamFrame*)malloc(sizeof(AudioStreamFrame));
        newFrame->timestamp = timestamp;
        strcpy(newFrame->metadata, metadata);

        UeMeasurementReport* newReport = (UeMeasurementReport*)malloc(sizeof(UeMeasurementReport));
        newReport->timestamp = timestamp;
        newReport->measurementValue = measurementValue;

        // Add the frame and report to the linked list and array
        if (frames == NULL) {
            frames = newFrame;
            reports = newReport;
        } else {
            AudioStreamFrame* current = frames;
            while (current != NULL) {
                if (current->timestamp > timestamp) {
                    break;
                }
                current = current->next;
            }

            // Add the frame and report before or after the found frame
            if (current == frames || current->timestamp < timestamp) {
                newFrame->next = frames;
                frames = newFrame;
            } else {
                current->next = newFrame;
            }
            newReport->next = reports;
            reports = newReport;
        }

        pthread_mutex_unlock(&lock);
    }

    // Function to retrieve a frame by its timestamp
    AudioStreamFrame* getFrame(int timestamp) {
        pthread_mutex_lock(&lock);

        AudioStreamFrame* current = frames;
        while (current != NULL && current->timestamp < timestamp) {
            current = current->next;
        }

        pthread_mutex_unlock(&lock);
        return current;
    }

    // Function to update metadata for a given frame
    void updateMetadata(int timestamp, char newMetadata[]) {
        pthread_mutex_lock(&lock);

        AudioStreamFrame* frame = getFrame(timestamp);
        if (frame != NULL) {
            strcpy(frame->metadata, newMetadata);
        }

        pthread_mutex_unlock(&lock);
    }

    // Function to merge consecutive frames and reports
    void mergeFramesAndReports() {
        pthread_mutex_lock(&lock);

        AudioStreamFrame* current = frames;
        while (current != NULL && current->next != NULL) {
            if (current->timestamp + 1 == current->next->timestamp) {
                // Merge the frames into a larger segment
                size_t length = current->next - current;
                char metadata[256];
                for (size_t i = 0; i < length; i++) {
                    metadata[i] = current->metadata[i];
                }
                metadata[length] = '\0';

                // Update the metadata and timestamp for the merged segment
                current->timestamp += length;
                strcpy(current->metadata, metadata);
            } else {
                break;
            }
        }

        pthread_mutex_unlock(&lock);
    }

    // Function to free allocated memory when no longer needed
    void cleanup() {
        pthread_mutex_lock(&lock);

        AudioStreamFrame* current = frames;
        while (current != NULL) {
            UeMeasurementReport* report = reports;
            while (report != NULL) {
                if (report->timestamp == current->timestamp) {
                    // Free the report and remove it from the array
                    free(report);
                    reports = (UeMeasurementReport*)malloc(sizeof(UeMeasurementReport));
                    reportCount--;
                    break;
                }
                report = report->next;
            }

            // Free the frame and remove it from the linked list
            frames = current->next;
            free(current);

            current = frames;
        }

        pthread_mutex_unlock(&lock);
    }

    return data;
}
