    int role;
    int permissions;
} UserDatabaseNode;

// Define the dynamic array of PDCP PDUs and user database
typedef struct {
    LTE_Uplink_PDCP_PDU *pdu_array;
    int pdu_array_size;
    int user_database_size;
    UserDatabaseNode *user_database;
} DynamicArray;

// Initialize a dynamic array for PDCP PDUs and user database
DynamicArray* initialize_dynamic_array(int initial_pdu_array_size, int initial_user_database_size) {
    DynamicArray* dynamic_array = (DynamicArray*)malloc(sizeof(DynamicArray));
    dynamic_array->pdu_array = (LTE_Uplink_PDCP_PDU*)malloc(initial_pdu_array_size * sizeof(LTE_Uplink_PDCP_PDU));
    dynamic_array->pdu_array_size = initial_pdu_array_size;
    dynamic_array->user_database = (UserDatabaseNode*)malloc(initial_user_database_size * sizeof(UserDatabaseNode));
    dynamic_array->user_database_size = initial_user_database_size;
    return dynamic_array;
}

// Add a user to the user database
void add_user(DynamicArray* dynamic_array, char* username, int role, int permissions) {
    // Check if the user already exists
    for(int i = 0; i < dynamic_array->user_database_size; i++) {
        if(strcmp(dynamic_array->user_database[i].username, username) == 0) {
            printf("Error: User '%s' already exists.\n", username);
            return;
        }
    }

    // Add the user to the user database
    for(int i = dynamic_array->user_database_size - 1; i >= 0; i--) {
        if(i > 0) {
            dynamic_array->user_database[i] = dynamic_array->user_database[i-1];
        } else {
            strcpy(dynamic_array->user_database[i].username, username);
            dynamic_array->user_database[i].role = role;
            dynamic_array->user_database[i].permissions = permissions;
        }
    }

    // Increase the user database size
    dynamic_array->user_database_size++;
}

// Update a user in the user database
void update_user(DynamicArray* dynamic_array, char* username, int role, int permissions) {
    // Check if the user exists
    for(int i = 0; i < dynamic_array->user_database_size; i++) {
        if(strcmp(dynamic_array->user_database[i].username, username) == 0) {
            dynamic_array->user_database[i].role = role;
            dynamic_array->user_database[i].permissions = permissions;
            printf("Updated user '%s' successfully.\n", username);
            return;
        }
    }

    printf("Error: User '%s' does not exist.\n", username);
}

// Delete a user from the user database
void delete_user(DynamicArray* dynamic_array, char* username) {
    // Check if the user exists
    for(int i = 0; i < dynamic_array->user_database_size; i++) {
        if(strcmp(dynamic_array->user_database[i].username, username) == 0) {
            // Move all subsequent users one position up
            for(int j = i + 1; j < dynamic_array->user_database_size; j++) {
                dynamic_array->user_database[j-1] = dynamic_array->user_database[j];
            }

            // Decrease the user database size
            dynamic_array->user_database_size--;
            printf("Deleted user '%s' successfully.\n", username);
            return;
        }
    }

    printf("Error: User '%s' does not exist.\n", username);
}

// List all users in the user database
void list_users(DynamicArray* dynamic_array) {
    for(int i = 0; i < dynamic_array->user_database_size; i++) {
        printf("Username: %s, Role: %d, Permissions: %d\n", dynamic_array->user_database[i].username, dynamic_array->user_database[i].role, dynamic_array->user_database[i].permissions);
    }
}

