#define MAX_PDU_COUNT 1000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
    unsigned int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pdu_count_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int global_pdu_count = 0;

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(int n, unsigned int seed) {
    if (n > MAX_PDU_COUNT) {
        return NULL; // error: resource exhaustion
    }

    pthread_mutex_lock(&pdu_count_lock);
    global_pdu_count += n;
    pthread_mutex_unlock(&pdu_count_lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = 
        (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        return NULL; // error: memory allocation failed
    }

    srand(seed);
    for (int i = 0; i < n; ++i) {
        pdu_array[i].rx_ue_info = ...;
        pdu_array[i].rnti = ...;
        pdu_array[i].crc_ind_rel8_tag = ...;
        pdu_array[i].crcflag = rand();
        log_pdu_creation(pdu_array + i);
    }

    return pdu_array;
}

void destroy_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int n) {
    free(pdu_array);

    pthread_mutex_lock(&pdu_count_lock);
    global_pdu_count -= n;
    pthread_mutex_unlock(&pdu_count_lock);
}
