#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE_Uplink_PDCP_PDU
typedef struct {
    int PDCP_Sequence_Number;
    int SDU_Size;
    char Error_Indication;
} LTE_Uplink_PDCP_PDU;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage dynamic array of LTE_Uplink_PDCP_PDU structures
void* init_pdcp_pdu_array(int n) {
    // Initialize and allocate memory for the PDCP PDUs
    LTE_Uplink_PDCP_PDU** pdcps = (LTE_Uplink_PDCP_PDU**)malloc(n * sizeof(LTE_Uplink_PDCP_PDU*));

    // Fill the array with new PDUs
    for (int i = 0; i < n; i++) {
        pdcps[i] = (LTE_Uplink_PDCP_PDU*)malloc(sizeof(LTE_Uplink_PDCP_PDU));
        // Initialize PDCP Sequence Number, SDU size and error indication field
        pdcps[i]->PDCP_Sequence_Number = i;
        pdcps[i]->SDU_Size = i * 10;
        pdcps[i]->Error_Indication = 'A' + (i % 26);
    }

    return pdcps;
}

void update_pdcp_pdu(LTE_Uplink_PDCP_PDU* pdu, int sn) {
    // Update PDU based on sequence number
    if (sn < 0 || sn >= 100) {
        printf("Invalid Sequence Number: %d\n", sn);
        return;
    }

    pdu->PDCP_Sequence_Number = sn;
}

LTE_Uplink_PDCP_PDU* get_pdcp_pdu(LTE_Uplink_PDCP_PDU** pdcps, int sn) {
    // Retrieve a specific PDU by its sequence number
    for (int i = 0; i < 100; i++) {
        if (pdcps[i]->PDCP_Sequence_Number == sn) {
            return pdcps[i];
        }
    }

    printf("PDU not found with sequence number %d\n", sn);
    return NULL;
}

int main() {
    // Initialize and manage a dynamic array of LTE_Uplink_PDCP_PDU structures
    int n = 100;
    LTE_Uplink_PDCP_PDU** pdcps = init_pdcp_pdu_array(n);

    // Perform operations on the PDCP PDUs
    for (int i = 0; i < n; i++) {
        update_pdcp_pdu(pdcps[i], i);
        printf("PDCP Sequence Number: %d, SDU Size: %d, Error Indication: %c\n", pdcps[i]->PDCP_Sequence_Number, pdcps[i]->SDU_Size, pdcps[i]->Error_Indication);
    }

    // Retrieve a specific PDU by its sequence number
    int sn = 50;
    LTE_Uplink_PDCP_PDU* pdu = get_pdcp_pdu(pdcps, sn);
    if (pdu != NULL) {
        printf("PDU with Sequence Number %d: PDCP Sequence Number: %d, SDU Size: %d, Error Indication: %c\n", sn, pdu->PDCP_Sequence_Number, pdu->SDU_Size, pdu->Error_Indication);
    }

    return 0;
}
