typedef struct {
    char* name;
    int priority;
    double estimated_completion_time;
    size_t task_id;
    struct timespec timestamp;
} Task;

typedef struct {
    uint16_t sequence_number;
    uint16_t sdu_size;
    int error_indication;
} LTE_Uplink_PDCP_PDU;

void handleDynamicTasksAndPDUs() {
    // Initialize arrays
    size_t num_tasks = 1000; 
    size_t num_pds = 5000; 

    Task* tasks = (Task*)malloc(num_tasks * sizeof(Task));
    LTE_Uplink_PDCP_PDU* pdus = (LTE_Uplink_PDCP_PDU*)malloc(num_pds * sizeof(LTE_Uplink_PDCP_PDU));

    // Initialize task properties
    for(size_t i=0; i<num_tasks; i++) {
        tasks[i].name = malloc(20);  // Name with random length
        sprintf(tasks[i].name, "Task %lu", (unsigned long)i);
        tasks[i].priority = rand() % 5 + 1;
        tasks[i].estimated_completion_time = (double)rand() / RAND_MAX * 12.0 + 8.0; // Estimated completion time in hours
        tasks[i].task_id = i;
        clock_gettime(CLOCK_REALTIME, &tasks[i].timestamp);
    }

    // Initialize PDU properties
    for(size_t i=0; i<num_pds; i++) {
        pdus[i].sequence_number = i;
        pdus[i].sdu_size = rand() % 100 + 50; // Random SDU size between 50 and 149 bytes
        pdus[i].error_indication = 0; // No error initially
    }

    // Add new PDU to the array
    void addPDU(LTE_Uplink_PDCP_PDU* p, LTE_Uplink_PDCP_PDU* pdus) {
        for(size_t i=0; i<num_pds; i++) {
            if(pdus[i].sequence_number == p->sequence_number) {
                printf("Error: Existing PDU sequence number\n");
                return;
            }
        }
        // Insert at the end of the array
        pdus = realloc(pdus, (num_pds+1) * sizeof(LTE_Uplink_PDCP_PDU));
        pdus[num_pds-1] = *p;
        num_pds++;
    }

    // Retrieve a specific PDU by its sequence number
    LTE_Uplink_PDCP_PDU* getPDU(uint16_t sn, LTE_Uplink_PDCP_PDU* pdus) {
        for(size_t i=0; i<num_pds; i++) {
            if(pdus[i].sequence_number == sn) {
                return &pdus[i];
            }
        }
        printf("Error: PDU sequence number not found\n");
        return NULL;
    }

    // Update the error indication for a given SN
    void updatePDU(uint16_t sn, int error_indication, LTE_Uplink_PDCP_PDU* pdus) {
        for(size_t i=0; i<num_pds; i++) {
            if(pdus[i].sequence_number == sn) {
                pdus[i].error_indication = error_indication;
                return;
            }
        }
        printf("Error: PDU sequence number not found\n");
    }

    // Compute the number of disjoint pairs
    int computeDisjointPairs(LTE_Uplink_PDCP_PDU* pdus) {
        size_t num_disjoint_pairs = 0;

        for(size_t i=0; i<num_pds-1; i++) {
            for(size_t j=i+1; j<num_pds; j++) {
                if(pdus[i].sequence_number != pdus[j].sequence_number) {
                    num_disjoint_pairs++;
                }
            }
        }

        return num_disjoint_pairs;
    }

    // Free allocated memory
    void freeMemory(Task* tasks, LTE_Uplink_PDCP_PDU* pdus) {
        for(size_t i=0; i<num_tasks; i++) {
            free(tasks[i].name);
        }
        free(tasks);
        free(pdus);
    }
}
