        return;
    }

    // Extract max concurrent files, timeout, and cleanup interval from config file
    json_object* maxConcurrentFilesObj = json_object_object_get(configFileJSON, "max_concurrent_files");
    if (maxConcurrentFilesObj != NULL) {
        int tempInt = atoi(json_object_get_string(maxConcurrentFilesObj));
        if (tempInt > 0) {
            maxConcurrentFiles = tempInt;
        }
    }

    json_object* timeoutSecsObj = json_object_object_get(configFileJSON, "timeout_secs");
    if (timeoutSecsObj != NULL) {
        int tempInt = atoi(json_object_get_string(timeoutSecsObj));
        if (tempInt > 0) {
            timeoutSecs = tempInt;
        }
    }

    json_object* cleanupIntervalSecsObj = json_object_object_get(configFileJSON, "cleanup_interval_secs");
    if (cleanupIntervalSecsObj != NULL) {
        int tempInt = atoi(json_object_get_string(cleanupIntervalSecsObj));
        if (tempInt > 0) {
            cleanupIntervalSecs = tempInt;
        }
    }

    json_object* filesArrayObj = json_object_object_get(configFileJSON, "files");
