            file->value = atof(json_object_get_string(json_object_object_get(fileObjs[i], "value")));
            file->timestamp = atoi(json_object_get_string(json_object_object_get(fileObjs[i], "timestamp")));
            file->id = atol(json_object_get_string(json_object_object_get(fileObjs[i], "id")));

            // Validate metric value and apply smoothing algorithm
            if (file->value < 0 || file->value > 100) {
                printf("Invalid metric value: %f\n", file->value);
                return;
            }

            files = realloc(files, (numFiles + 1) * sizeof(MetricEntry*));
            files[numFiles] = file;
            numFiles++;
        }
    }

    // Calculate average value of all metric entries
    double sum = 0;
    for (int i = 0; i < numFiles; i++) {
        sum += files[i]->value;
    }
    double avgValue = sum / numFiles;

    printf("Average value: %f\n", round(avgValue * 100.0) / 100.0);

    // Free allocated memory
    for (int i = 0; i < numFiles; i++) {
        free(files[i]->name);
        free(files[i]);
    }
    free(files);

    json_object_free(configFileJSON);
}
