// Define the structure for LTE Uplink PDCP PDU
typedef struct {
    int SN;
    int SDU_size;
    int error_indication;
    time_t timestamp;
} LTE_Uplink_PDCP_PDU;

// Function to add a new PDU
void add_pdu(LTE_Uplink_PDCP_PDU** pdus, int* size, LTE_Uplink_PDCP_PDU* pdu) {
    if (*size >= 100000) {
        // Handle memory full condition
        return;
    }

    pdus[(*size)++] = pdu;
}

// Function to retrieve a PDU by its sequence number
LTE_Uplink_PDCP_PDU* get_pdu(LTE_Uplink_PDCP_PDU** pdus, int size, int SN) {
    for (int i = 0; i < size; i++) {
        if (pdus[i]->SN == SN) {
            return pdus[i];
        }
    }

    // Handle PDU not found condition
    return NULL;
}

// Function to update the error indication for a given SN
void update_error_indication(LTE_Uplink_PDCP_PDU** pdus, int size, int SN, int new_error) {
    for (int i = 0; i < size; i++) {
        if (pdus[i]->SN == SN) {
            pdus[i]->error_indication = new_error;
        }
    }
}

// Function to mark PDUs for removal based on maximum age
void remove_old_pds(LTE_Uplink_PDCP_PDU** pdus, int size, time_t max_age) {
    for (int i = 0; i < size; i++) {
        if ((time(NULL) - pdus[i]->timestamp) > max_age) {
            // Mark PDU for removal
            pdus[i] = NULL;
        }
    }
}

// Function to serialize the array to disk
void serialize_pds(LTE_Uplink_PDCP_PDU** pdus, int size) {
    FILE* file = fopen("pdus.dat", "wb");
    if (file == NULL) {
        // Handle file open error
        return;
    }

    for (int i = 0; i < size; i++) {
        fwrite(&pdus[i]->SN, sizeof(int), 1, file);
        fwrite(&pdus[i]->SDU_size, sizeof(int), 1, file);
        fwrite(&pdus[i]->error_indication, sizeof(int), 1, file);
        fwrite(&pdus[i]->timestamp, sizeof(time_t), 1, file);
    }

    fclose(file);
}

// Function to deserialize the array from disk
void deserialize_pds(LTE_Uplink_PDCP_PDU** pdus, int size) {
    FILE* file = fopen("pdus.dat", "rb");
    if (file == NULL) {
        // Handle file open error
        return;
    }

    for (int i = 0; i < size; i++) {
        fread(&pdus[i]->SN, sizeof(int), 1, file);
        fread(&pdus[i]->SDU_size, sizeof(int), 1, file);
        fread(&pdus[i]->error_indication, sizeof(int), 1, file);
        fread(&pdus[i]->timestamp, sizeof(time_t), 1, file);
    }

    fclose(file);
}

// Function to get the total number of active PDUs
int get_active_pds(LTE_Uplink_PDCP_PDU** pdus, int size) {
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (pdus[i] != NULL) {
            count++;
        }
    }

    return count;
}

// Function to bulk delete PDUs based on age range
void bulk_delete_pds(LTE_Uplink_PDCP_PDU** pdus, int size, time_t min_age, time_t max_age) {
    for (int i = 0; i < size; i++) {
        if ((time(NULL) - pdus[i]->timestamp) > min_age && (time(NULL) - pdus[i]->timestamp) <= max_age) {
            // Delete PDU
            pdus[i] = NULL;
        }
    }
}

